// Fields that must never appear in a backup export (H-6)
const EMAIL_SETTINGS_SECRET_FIELDS = ['api_key', 'smtp_password', 'smtp_user', 'webhook_secret']

function redactEmailSettings(rows) {
  return (rows || []).map(row => {
    const safe = { ...row }
    for (const field of EMAIL_SETTINGS_SECRET_FIELDS) {
      if (field in safe) safe[field] = '[REDACTED — re-enter after restore]'
    }
    return safe
  })
}

export const backup = {
  async exportAll() {
    const [products, customers, tickets, comments, activity, users, brandingData, emailSettings, emailTemplates] = await Promise.all([
      supabase.from('products').select('*'),
      supabase.from('customers').select('*'),
      supabase.from('rma_tickets').select('*'),
      supabase.from('ticket_comments').select('*'),
      supabase.from('ticket_activity').select('*'),
      supabase.from('user_roles').select('*'),
      supabase.from('branding_settings').select('*'),
      // Select only non-secret columns — api_key / smtp_password never leave the server (H-6)
      supabase.from('email_settings').select('id, provider, from_email, from_name, smtp_host, smtp_port, smtp_secure, is_active, updated_by, updated_date'),
      supabase.from('email_templates').select('*')
    ])
    return {
      version: '1.0',
      exported_date: new Date().toISOString(),
      data: {
        products: products.data || [],
        customers: customers.data || [],
        tickets: tickets.data || [],
        comments: comments.data || [],
        activity: activity.data || [],
        users: users.data || [],
        branding: brandingData.data || [],
        // Secrets are excluded from the SELECT above; redactEmailSettings is a
        // belt-and-braces guard in case the schema grows new secret columns (H-6)
        emailSettings: redactEmailSettings(emailSettings.data),
        emailTemplates: emailTemplates.data || []
      }
    }
  },
  async importAll(backupData) {
    if (!backupData.data) throw new Error('Invalid backup file')
    const { data } = backupData
    const targets = [
      ['products', data.products, 'products'],
      ['customers', data.customers, 'customers'],
      ['tickets', data.tickets, 'rma_tickets'],
      ['comments', data.comments, 'ticket_comments'],
      ['activity', data.activity, 'ticket_activity']
    ]
    const results = await Promise.all(
      targets.map(async ([label, rows, table]) => {
        if (!rows?.length) return { label, skipped: true }
        const { error } = await supabase.from(table).upsert(rows)
        return { label, count: rows.length, error: error?.message || null }
      })
    )
    const failures = results.filter(r => r.error)
    if (failures.length) {
      const msg = failures.map(f => `${f.label}: ${f.error}`).join('; ')
      throw new Error(`Import partially failed — ${msg}`)
    }
    return { success: true, results }
  }
}

import React from 'react'
import toast from 'react-hot-toast'

const MAX_FILE_SIZE = 25 * 1024 * 1024 // 25 MB

const ClipIcon = () => (
  <svg className="w-4 h-4 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" />
  </svg>
)

const XIcon = () => (
  <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
  </svg>
)

// Shared attachment field used in both AddCustomerModal and CustomerDetails edit mode.
// savedAttachments  — array of {name, url, path, size, type} objects already in DB
// onSavedChange     — called with new savedAttachments array when user removes one
// pendingFiles      — array of File objects not yet uploaded
// onPendingChange   — called with new pendingFiles array when user adds/removes
export default function AttachmentsField({ savedAttachments = [], onSavedChange, pendingFiles = [], onPendingChange }) {
  const handleFileSelect = (e) => {
    if (!e.target.files?.length) return
    const incoming = Array.from(e.target.files)
    const oversize = incoming.filter(f => f.size > MAX_FILE_SIZE)
    const valid = incoming.filter(f => f.size <= MAX_FILE_SIZE)
    if (oversize.length) {
      toast.error(`${oversize.length} file${oversize.length !== 1 ? 's' : ''} exceeded 25 MB and were skipped`)
    }
    if (valid.length) onPendingChange([...pendingFiles, ...valid])
    e.target.value = ''
  }

  return (
    <div className="space-y-2">
      {/* Already-saved attachments */}
      {savedAttachments.map((att, i) => (
        <div key={i} className="flex items-center gap-2 px-3 py-2 bg-gray-50 rounded-lg border border-gray-200">
          <span className="text-gray-400"><ClipIcon /></span>
          <a href={att.url} target="_blank" rel="noopener noreferrer" className="text-sm text-indigo-600 hover:underline flex-1 truncate">
            {att.name}
          </a>
          {att.size && <span className="text-xs text-gray-400 flex-shrink-0">{(att.size / 1024).toFixed(0)} KB</span>}
          <button
            type="button"
            onClick={() => onSavedChange(savedAttachments.filter((_, j) => j !== i))}
            className="w-5 h-5 flex items-center justify-center rounded text-gray-400 hover:text-red-500 hover:bg-red-50 transition-colors flex-shrink-0"
          >
            <XIcon />
          </button>
        </div>
      ))}

      {/* Pending (not yet uploaded) files */}
      {pendingFiles.map((file, i) => (
        <div key={i} className="flex items-center gap-2 px-3 py-2 bg-blue-50 rounded-lg border border-blue-200">
          <span className="text-blue-400"><ClipIcon /></span>
          <span className="text-sm text-gray-700 flex-1 truncate">{file.name}</span>
          <span className="text-xs text-gray-400 flex-shrink-0">{(file.size / 1024).toFixed(0)} KB</span>
          <button
            type="button"
            onClick={() => onPendingChange(pendingFiles.filter((_, j) => j !== i))}
            className="w-5 h-5 flex items-center justify-center rounded text-gray-400 hover:text-red-500 hover:bg-red-50 transition-colors flex-shrink-0"
          >
            <XIcon />
          </button>
        </div>
      ))}

      {/* File picker */}
      <label className="flex items-center gap-3 px-4 py-3 border-2 border-dashed border-gray-300 rounded-lg cursor-pointer hover:border-indigo-400 hover:bg-indigo-50 transition-colors group">
        <svg className="w-5 h-5 text-gray-400 group-hover:text-indigo-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
        </svg>
        <span className="text-sm text-gray-500 group-hover:text-indigo-600">Attach files</span>
        <span className="text-xs text-gray-400 ml-auto">PDF, images, docs · max 25 MB each</span>
        <input type="file" multiple className="hidden" onChange={handleFileSelect} />
      </label>
    </div>
  )
}

import React, { useState, useEffect, useRef, useCallback } from 'react'
import { db } from '../api/supabaseClient'

const ICONS = {
  ticket: (
    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
    </svg>
  ),
  customer: (
    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
    </svg>
  ),
  product: (
    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" />
    </svg>
  ),
}

const TYPE_COLORS = {
  ticket: 'bg-blue-100 text-blue-700',
  customer: 'bg-green-100 text-green-700',
  product: 'bg-purple-100 text-purple-700',
}

const TYPE_LABELS = { ticket: 'Ticket', customer: 'Customer', product: 'Product' }

export default function CommandPalette({ open, onClose, onSelectTicket, onSelectCustomer, onSelectProduct }) {
  const [query, setQuery] = useState('')
  const [results, setResults] = useState([])
  const [loading, setLoading] = useState(false)
  const [activeIndex, setActiveIndex] = useState(0)
  const inputRef = useRef(null)
  const listRef = useRef(null)
  const searchTimeout = useRef(null)

  useEffect(() => {
    if (open) {
      setQuery('')
      setResults([])
      setActiveIndex(0)
      setTimeout(() => inputRef.current?.focus(), 50)
    }
  }, [open])

  const search = useCallback(async (q) => {
    if (!q.trim()) { setResults([]); setLoading(false); return }
    if (q.length > 100) { setResults([]); setLoading(false); return }
    setLoading(true)
    try {
      const safe = q.replace(/[%,()]/g, ' ').trim()
      if (!safe) { setResults([]); setLoading(false); return }
      const [tickets, customers, products] = await Promise.all([
        db.supabase.from('rma_tickets').select('id,rma_number,ticket_status,customer_name').or(`rma_number.ilike.%${safe}%,customer_name.ilike.%${safe}%`).limit(5),
        db.supabase.from('customers').select('id,company_name,contact_person,email,mobile').or(`company_name.ilike.%${safe}%,contact_person.ilike.%${safe}%,email.ilike.%${safe}%,mobile.ilike.%${safe}%`).limit(5),
        db.supabase.from('products').select('id,product_name,sku,brand:brands(brand_name)').or(`product_name.ilike.%${safe}%,sku.ilike.%${safe}%`).limit(5),
      ])
      const r = [
        ...(tickets.data || []).map(t => ({ type: 'ticket', id: t.id, primary: t.rma_number, secondary: t.customer_name || '', badge: t.ticket_status, raw: t })),
        ...(customers.data || []).map(c => ({ type: 'customer', id: c.id, primary: c.company_name || c.contact_person || '—', secondary: c.email || c.mobile || '', raw: c })),
        ...(products.data || []).map(p => ({ type: 'product', id: p.id, primary: p.product_name, secondary: `${p.brand?.brand_name || ''} ${p.sku ? '· ' + p.sku : ''}`.trim(), raw: p })),
      ]
      setResults(r)
      setActiveIndex(0)
    } catch {
      setResults([])
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    clearTimeout(searchTimeout.current)
    searchTimeout.current = setTimeout(() => search(query), 220)
    return () => clearTimeout(searchTimeout.current)
  }, [query, search])

  const select = useCallback((item) => {
    onClose()
    if (item.type === 'ticket') onSelectTicket?.(item.raw)
    else if (item.type === 'customer') onSelectCustomer?.(item.raw)
    else if (item.type === 'product') onSelectProduct?.(item.raw)
  }, [onClose, onSelectTicket, onSelectCustomer, onSelectProduct])

  useEffect(() => {
    if (!open) return
    const handler = (e) => {
      if (e.key === 'Escape') { onClose(); return }
      if (e.key === 'ArrowDown') { e.preventDefault(); setActiveIndex(i => Math.min(i + 1, results.length - 1)) }
      if (e.key === 'ArrowUp') { e.preventDefault(); setActiveIndex(i => Math.max(i - 1, 0)) }
      if (e.key === 'Enter' && results[activeIndex]) select(results[activeIndex])
    }
    document.addEventListener('keydown', handler)
    return () => document.removeEventListener('keydown', handler)
  }, [open, results, activeIndex, select, onClose])

  useEffect(() => {
    const el = listRef.current?.children[activeIndex]
    el?.scrollIntoView({ block: 'nearest' })
  }, [activeIndex])

  if (!open) return null

  return (
    <div className="fixed inset-0 z-[300] flex items-start justify-center pt-[15vh]">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose} />
      <div className="relative w-full max-w-xl mx-4 bg-white rounded-2xl shadow-2xl border border-gray-200 overflow-hidden">
        <div className="flex items-center gap-3 px-4 py-3 border-b border-gray-100">
          <svg className="w-4 h-4 text-gray-400 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
          <input
            ref={inputRef}
            value={query}
            onChange={e => setQuery(e.target.value)}
            placeholder="Search tickets, customers, products…"
            className="flex-1 text-sm outline-none bg-transparent text-gray-900 placeholder-gray-400"
          />
          {loading && (
            <svg className="w-4 h-4 text-gray-400 animate-spin flex-shrink-0" fill="none" viewBox="0 0 24 24">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8H4z" />
            </svg>
          )}
          <kbd className="hidden sm:inline-flex items-center gap-1 px-2 py-0.5 text-xs text-gray-400 bg-gray-100 rounded border border-gray-200 font-mono">Esc</kbd>
        </div>

        {results.length > 0 && (
          <ul ref={listRef} className="max-h-80 overflow-y-auto py-2">
            {results.map((item, idx) => (
              <li
                key={`${item.type}-${item.id}`}
                onMouseEnter={() => setActiveIndex(idx)}
                onClick={() => select(item)}
                className={`flex items-center gap-3 px-4 py-2.5 cursor-pointer transition-colors ${idx === activeIndex ? 'bg-gray-50' : ''}`}
              >
                <span className={`w-7 h-7 rounded-lg flex items-center justify-center flex-shrink-0 ${TYPE_COLORS[item.type]}`}>
                  {ICONS[item.type]}
                </span>
                <div className="flex-1 min-w-0">
                  <span className="text-sm font-medium text-gray-900 truncate block">{item.primary}</span>
                  {item.secondary && <span className="text-xs text-gray-500 truncate block">{item.secondary}</span>}
                </div>
                <span className={`text-xs px-2 py-0.5 rounded-full font-medium flex-shrink-0 ${TYPE_COLORS[item.type]}`}>
                  {TYPE_LABELS[item.type]}
                </span>
              </li>
            ))}
          </ul>
        )}

        {query.trim() && !loading && results.length === 0 && (
          <div className="py-10 text-center">
            <p className="text-sm text-gray-500">No results for <span className="font-medium text-gray-700">"{query}"</span></p>
          </div>
        )}

        {!query.trim() && (
          <div className="px-4 py-3 flex items-center gap-4 text-xs text-gray-400">
            <span className="flex items-center gap-1"><kbd className="px-1.5 py-0.5 bg-gray-100 rounded border border-gray-200 font-mono">↑↓</kbd> navigate</span>
            <span className="flex items-center gap-1"><kbd className="px-1.5 py-0.5 bg-gray-100 rounded border border-gray-200 font-mono">↵</kbd> select</span>
            <span className="flex items-center gap-1"><kbd className="px-1.5 py-0.5 bg-gray-100 rounded border border-gray-200 font-mono">Esc</kbd> close</span>
          </div>
        )}
      </div>
    </div>
  )
}

import React, { useEffect } from 'react'

export default function ConfirmDialog({
  open, title, message,
  confirmLabel = 'Delete',
  confirmClass = 'bg-red-600 hover:bg-red-700 text-white',
