export default function ControlPanel({ currentUserRole, currentUserEmail }) {
  const [section, setSection] = useURLTab('section', null, true)

  if (currentUserRole !== 'admin' && currentUserRole !== 'super_admin') {
    return (
      <div className="flex items-center justify-center h-96">
        <div className="text-center">
          <svg className="w-16 h-16 text-gray-300 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
          </svg>
          <h2 className="text-xl font-semibold text-gray-700">Access Restricted</h2>
          <p className="text-gray-500 mt-1">This area is for administrators only.</p>
        </div>
      </div>
    )
  }

  const activeFeature = section ? ALL_FEATURES.find(f => f.id === section) : null

  return (
    <div className="space-y-6">
      {/* Header */}
      {section ? (
        <div className="flex items-center gap-3">
          <button onClick={() => setSection(null)}
            className="flex items-center gap-1.5 text-sm text-indigo-600 hover:text-indigo-800 font-medium">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
            Control Panel
          </button>
          <svg className="w-4 h-4 text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
          <span className="text-sm font-semibold text-gray-900">{activeFeature?.label}</span>
        </div>
      ) : (
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Control Panel</h1>
          <p className="text-sm text-gray-500 mt-0.5">System administration and configuration</p>
        </div>
      )}

      {/* Home view */}
      {!section && <HomeView onNavigate={setSection} currentUserEmail={currentUserEmail} />}

      {/* Feature content */}
      {section === 'users'       && <UserManagement currentUserRole={currentUserRole} currentUserEmail={currentUserEmail} />}
      {section === 'appearance'  && <BrandingSettings key="appearance" currentUserRole={currentUserRole} currentUserEmail={currentUserEmail} initialTab="branding" visibleTabs={['branding']} />}
      {section === 'email'       && <BrandingSettings key="email" currentUserRole={currentUserRole} currentUserEmail={currentUserEmail} initialTab="email-settings" visibleTabs={['email-settings', 'notifications', 'templates']} />}
      {section === 'backup'      && <BackupRestore currentUserRole={currentUserRole} currentUserEmail={currentUserEmail} />}
      {section === 'announcements' && <Announcements currentUserEmail={currentUserEmail} />}
      {section === 'broadcast'     && <SendAlert currentUserEmail={currentUserEmail} />}
      {section === 'audit'       && <AuditLog />}
      {section === 'rmaconfig'   && <RMAConfig currentUserEmail={currentUserEmail} />}
      {section === 'cleanup'     && <DataCleanup />}
      {section === 'integrations' && <Integrations currentUserEmail={currentUserEmail} />}
      {section === 'customfields' && <CustomFields currentUserEmail={currentUserEmail} />}
      {section === 'pdflayout'   && <PDFLayout currentUserEmail={currentUserEmail} />}
      {section === 'sla'         && <SLAPolicies currentUserEmail={currentUserEmail} />}
      {section === 'automation'  && <AutomationRules currentUserEmail={currentUserEmail} />}
      {section === 'webhooks'    && <WebhooksConfig currentUserEmail={currentUserEmail} />}
    </div>
  )
}

// ─── SEND ALERT ─────────────────────────────────────────────────────────────

const ALERT_TYPES = [
  { value: 'system_announcement', label: 'Announcement', icon: '📢', desc: 'General system message' },
  { value: 'custom_alert',        label: 'Warning',       icon: '⚠️', desc: 'Important action required' },
]

const ALERT_TARGETS = [
  { value: 'all',          label: 'Everyone',        icon: '👥', roles: ['super_admin', 'admin', 'technician'] },
  { value: 'admins',       label: 'Admins only',     icon: '🔑', roles: ['super_admin', 'admin'] },
  { value: 'technicians',  label: 'Technicians',     icon: '🔧', roles: ['technician'] },
  { value: 'email',        label: 'Specific email',  icon: '✉️', roles: [] },
]

function SendAlert({ currentUserEmail }) {
  const [type, setType]               = useState('system_announcement')
  const [title, setTitle]             = useState('')
  const [message, setMessage]         = useState('')
  const [target, setTarget]           = useState('all')
  const [specificEmail, setSpecificEmail] = useState('')
  const [sending, setSending]         = useState(false)
  const [sent, setSent]               = useState(false)

  const handleSend = async () => {
    if (!title.trim() || !message.trim()) { toast.error('Title and message are required'); return }
    if (target === 'email' && !specificEmail.trim()) { toast.error('Enter a recipient email address'); return }
    setSending(true)
    try {
      const targetConfig = ALERT_TARGETS.find(t => t.value === target)
      await db.notifications.create({
        type,
        title: title.trim(),
        message: message.trim(),
        createdBy: currentUserEmail,
        targetRoles: targetConfig.roles,
        targetEmails: target === 'email' ? [specificEmail.trim()] : [],
      })
      toast.success('Alert sent')
      db.auditLog.log(currentUserEmail, 'alert_sent', `Sent alert "${title.trim()}" to ${target}`).catch(() => {})
      setSent(true)
      setTitle(''); setMessage(''); setSpecificEmail('')
      setTimeout(() => setSent(false), 3000)
    } catch (err) {
      toast.error(`Failed to send: ${err.message}`)
    } finally {
      setSending(false)
    }
  }

  return (
    <div className="max-w-2xl space-y-5">
      <div className="bg-white rounded-xl border border-gray-200 p-6 space-y-6">

        {/* Type */}
        <div>
          <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Alert Type</p>
          <div className="grid grid-cols-2 gap-3">
            {ALERT_TYPES.map(t => (
              <button key={t.value} onClick={() => setType(t.value)}
                className={`flex items-center gap-3 p-3.5 rounded-xl border-2 text-left transition-colors ${type === t.value ? 'border-indigo-500 bg-indigo-50' : 'border-gray-200 hover:border-gray-300 bg-white'}`}>
                <span className="text-2xl">{t.icon}</span>
                <div>
                  <p className="text-sm font-semibold text-gray-800">{t.label}</p>
                  <p className="text-xs text-gray-500">{t.desc}</p>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Title */}
        <div>
          <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1.5">
            Title <span className="text-red-500">*</span>
          </label>
          <input
            value={title} onChange={e => setTitle(e.target.value)} maxLength={100}
            className="w-full px-3 py-2.5 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600 focus:border-transparent"
            placeholder="e.g. System maintenance tonight at 11pm"
          />
        </div>

        {/* Message */}
        <div>
          <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1.5">
            Message <span className="text-red-500">*</span>
          </label>
          <textarea
            value={message} onChange={e => setMessage(e.target.value)} rows={4} maxLength={500}
            className="w-full px-3 py-2.5 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600 focus:border-transparent resize-none"
            placeholder="Describe the alert in detail..."
          />
          <p className="text-xs text-gray-400 text-right mt-1">{message.length}/500</p>
        </div>

        {/* Target */}
        <div>
          <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Send To</p>
          <div className="grid grid-cols-2 gap-2">
            {ALERT_TARGETS.map(t => (
              <button key={t.value} onClick={() => setTarget(t.value)}
                className={`flex items-center gap-2 px-4 py-2.5 rounded-lg border-2 text-sm font-medium transition-colors ${target === t.value ? 'border-indigo-500 bg-indigo-50 text-indigo-700' : 'border-gray-200 text-gray-600 hover:border-gray-300 bg-white'}`}>
                <span>{t.icon}</span>{t.label}
              </button>
            ))}
          </div>
          {target === 'email' && (
            <input
              value={specificEmail} onChange={e => setSpecificEmail(e.target.value)} type="email"
              className="w-full mt-3 px-3 py-2.5 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600 focus:border-transparent"
              placeholder="recipient@example.com"
            />
          )}
        </div>

        {/* Send */}
        <div className="pt-2 border-t border-gray-100">
          <button
            onClick={handleSend}
            disabled={sending || !title.trim() || !message.trim()}
            className={`px-6 py-2.5 text-white text-sm font-medium rounded-lg disabled:opacity-50 transition-all flex items-center gap-2 ${sent ? 'bg-green-600 hover:bg-green-700' : 'bg-indigo-600 hover:bg-indigo-700'}`}
          >
            {sending ? (
              <><Spinner size="sm" color="white" />Sending...</>
            ) : sent ? (
              <><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" /></svg>Alert Sent!</>
            ) : (
              <><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>Send Alert</>
            )}
          </button>
        </div>
      </div>
    </div>
  )
}

// ─── HOME VIEW ─────────────────────────────────────────────────────────────

function HomeView({ onNavigate, currentUserEmail }) {
  const [stats, setStats] = useState(null)

  useEffect(() => {
    Promise.all([db.rmaTickets.list(), db.customers.list(), db.products.list(), db.userRoles.listAllRoles()])
      .then(([tickets, customers, products, users]) => {
        const byStatus = tickets.reduce((a, t) => { a[t.ticket_status] = (a[t.ticket_status] || 0) + 1; return a }, {})
        const open = (byStatus['New'] || 0) + (byStatus['In Progress'] || 0) + (byStatus['On Hold'] || 0)
        const overdue = tickets.filter(t => t.due_date && new Date(t.due_date) < new Date() && t.ticket_status !== 'Completed' && t.ticket_status !== 'Cancelled').length
        setStats({ total: tickets.length, open, overdue, completed: byStatus['Completed'] || 0, customers: customers.length, products: products.length, users: users.length, byStatus })
      }).catch(() => {})
  }, [])

  const statCards = stats ? [
    { label: 'Total Tickets', value: stats.total, sub: `${stats.open} open`, color: 'indigo' },
    { label: 'Overdue', value: stats.overdue, sub: 'past due date', color: stats.overdue > 0 ? 'red' : 'green' },
    { label: 'Customers', value: stats.customers, sub: 'in database', color: 'emerald' },
    { label: 'System Users', value: stats.users, sub: 'with access', color: 'purple' },
  ] : []

  const colorStat = { indigo: 'bg-indigo-50 text-indigo-600', red: 'bg-red-50 text-red-600', green: 'bg-green-50 text-green-600', emerald: 'bg-emerald-50 text-emerald-600', purple: 'bg-purple-50 text-purple-600' }

  return (
    <div className="space-y-8">
      {/* Quick stats */}
      {stats && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {statCards.map(c => (
            <div key={c.label} className="bg-white rounded-xl border border-gray-200 p-4 shadow-sm">
              <div className={`text-2xl font-bold ${colorStat[c.color].split(' ')[1]}`}>{c.value}</div>
              <div className="text-sm font-medium text-gray-700 mt-0.5">{c.label}</div>
              <div className="text-xs text-gray-400">{c.sub}</div>
            </div>
          ))}
        </div>
      )}

      {/* Ticket status row */}
      {stats && (
        <div className="flex flex-wrap gap-3">
          {[
            { label: 'New', color: 'bg-pink-100 text-pink-800' },
            { label: 'In Progress', color: 'bg-blue-100 text-blue-800' },
            { label: 'On Hold', color: 'bg-yellow-100 text-yellow-800' },
            { label: 'Completed', color: 'bg-green-100 text-green-800' },
            { label: 'Cancelled', color: 'bg-gray-100 text-gray-700' },
          ].map(({ label, color }) => (
            <div key={label} className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm ${color}`}>
              <span className="font-medium">{label}</span>
              <span className="font-bold">{stats.byStatus[label] || 0}</span>
            </div>
          ))}
        </div>
      )}

      {/* Feature groups */}
      {GROUPS.map(group => {
        const c = COLOR_MAP[group.color]
        return (
          <div key={group.id}>
            <h2 className="text-base font-semibold text-gray-900 mb-3">{group.label}</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
              {group.features.map(f => (
                <button key={f.id} onClick={() => onNavigate(f.id)}
                  className={`group bg-white border border-gray-200 rounded-xl p-4 text-left transition-all hover:shadow-md ${c.hover}`}>
                  <div className={`w-9 h-9 rounded-lg flex items-center justify-center mb-3 ${c.icon}`}>
                    {f.icon}
                  </div>
                  <div className="font-semibold text-gray-900 text-sm group-hover:text-indigo-700">{f.label}</div>
                  <div className="text-xs text-gray-500 mt-1 leading-relaxed">{f.desc}</div>
                  <div className="mt-3 flex items-center gap-1 text-xs font-medium text-indigo-600 opacity-0 group-hover:opacity-100 transition-opacity">
                    Open
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
                  </div>
                </button>
              ))}
            </div>
          </div>
        )
      })}
    </div>
  )
}

// ─── SLA POLICIES ───────────────────────────────────────────────────────────

const PRIORITIES = ['Critical', 'High', 'Medium', 'Low']

function SLAPolicies({ currentUserEmail }) {
  const [config, setConfig] = useState(null)
  const [saving, setSaving] = useState(false)

  useEffect(() => { db.slaConfig.get().then(setConfig) }, [])

  const updatePolicy = (priority, hours) => {
    setConfig(prev => ({
      ...prev,
      policies: prev.policies.map(p => p.priority === priority ? { ...p, hours: Number(hours) } : p)
    }))
  }

  const handleSave = async () => {
    setSaving(true)
    try {
      await db.slaConfig.save(config, currentUserEmail)
      toast.success('SLA policies saved')
      db.auditLog.log(currentUserEmail, 'sla_updated', 'Updated SLA policy configuration').catch(() => {})
    } catch (e) { toast.error('Failed to save: ' + e.message) }
    finally { setSaving(false) }
  }

  if (!config) return <div className="flex justify-center py-10"><Spinner /></div>

  return (
    <div className="max-w-2xl space-y-6">
      <div className="bg-white rounded-xl border border-gray-200 p-6 space-y-5">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="text-sm font-semibold text-gray-900">SLA Policies</h3>
            <p className="text-xs text-gray-500 mt-0.5">Auto-set ticket due dates based on priority when a new ticket is created.</p>
          </div>
          <label className="flex items-center gap-2 cursor-pointer select-none">
            <span className="text-sm text-gray-600 font-medium">Enabled</span>
            <button
              onClick={() => setConfig(c => ({ ...c, enabled: !c.enabled }))}
              className={`relative inline-flex h-5 w-9 rounded-full transition-colors ${config.enabled ? 'bg-indigo-600' : 'bg-gray-300'}`}
            >
              <span className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white shadow transition-transform ${config.enabled ? 'translate-x-4' : 'translate-x-0'}`} />
            </button>
          </label>
        </div>

        <div className={`space-y-3 ${!config.enabled ? 'opacity-50 pointer-events-none' : ''}`}>
          {PRIORITIES.map(p => {
            const policy = config.policies?.find(pl => pl.priority === p) || { priority: p, hours: 72 }
            const colors = { Critical: 'text-red-600', High: 'text-orange-600', Medium: 'text-yellow-600', Low: 'text-green-600' }
            return (
              <div key={p} className="flex items-center gap-4 p-3 bg-gray-50 rounded-lg">
                <span className={`w-20 text-sm font-semibold ${colors[p]}`}>{p}</span>
                <div className="flex items-center gap-2 flex-1">
                  <input
                    type="number" min={1} max={8760}
                    value={policy.hours}
                    onChange={e => updatePolicy(p, e.target.value)}
                    className="w-24 px-3 py-1.5 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600"
                  />
                  <span className="text-sm text-gray-500">hours</span>
                  <span className="text-xs text-gray-400 ml-2">({policy.hours >= 24 ? `${(policy.hours / 24).toFixed(1)}d` : `${policy.hours}h`})</span>
                </div>
              </div>
            )
          })}

          <div className="flex items-center gap-3 pt-2">
            <label className="flex items-center gap-2 cursor-pointer select-none">
              <button
                onClick={() => setConfig(c => ({ ...c, pauseOnHold: !c.pauseOnHold }))}
                className={`relative inline-flex h-5 w-9 rounded-full transition-colors ${config.pauseOnHold ? 'bg-indigo-600' : 'bg-gray-300'}`}
              >
                <span className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white shadow transition-transform ${config.pauseOnHold ? 'translate-x-4' : 'translate-x-0'}`} />
              </button>
              <span className="text-sm text-gray-600">Pause SLA clock when ticket is "On Hold"</span>
            </label>
          </div>
        </div>

        <div className="pt-3 border-t border-gray-100">
          <button onClick={handleSave} disabled={saving} className="px-5 py-2 bg-indigo-600 text-white text-sm font-medium rounded-lg hover:bg-indigo-700 disabled:opacity-50 flex items-center gap-2">
            {saving ? <Spinner size="sm" color="white" /> : null} Save Policies
          </button>
        </div>
      </div>

      <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 text-sm text-blue-700">
        <strong>How it works:</strong> When SLA is enabled, creating a new ticket will automatically set its due date based on the priority selected. The due date can always be overridden manually in the ticket form.
      </div>
    </div>
  )
}

// ─── AUTOMATION RULES ───────────────────────────────────────────────────────

const TRIGGER_OPTIONS = [
  { value: 'ticket_created',        label: 'Ticket Created' },
  { value: 'ticket_updated',        label: 'Ticket Updated' },
  { value: 'ticket_status_changed', label: 'Status Changed' },
  { value: 'ticket_assigned',       label: 'Ticket Assigned' },
  { value: 'ticket_overdue',        label: 'Ticket Overdue' },
]
const FIELD_OPTIONS = [
  { value: 'ticket_status',       label: 'Status' },
  { value: 'priority',            label: 'Priority' },
  { value: 'assigned_technician', label: 'Technician' },
  { value: 'customer_name',       label: 'Customer Name' },
]
const OP_OPTIONS = [
  { value: 'equals',      label: 'equals' },
  { value: 'not_equals',  label: 'does not equal' },
  { value: 'contains',    label: 'contains' },
  { value: 'starts_with', label: 'starts with' },
]
const ACTION_TYPES = [
  { value: 'change_status',       label: 'Change Status' },
  { value: 'change_priority',     label: 'Change Priority' },
  { value: 'assign_technician',   label: 'Assign Technician' },
  { value: 'create_notification', label: 'Send Notification' },
]
const STATUS_OPTIONS   = ['New', 'In Progress', 'On Hold', 'Completed', 'Cancelled']
const PRIORITY_OPTIONS = ['Critical', 'High', 'Medium', 'Low']

const EMPTY_RULE = () => ({ id: Date.now(), name: 'New Rule', enabled: true, trigger: 'ticket_created', conditions: [], actions: [{ type: 'change_status', value: 'In Progress' }] })

function AutomationRules({ currentUserEmail }) {
  const [rules, setRules] = useState(null)
  const [editing, setEditing] = useState(null)
  const [saving, setSaving] = useState(false)

  useEffect(() => { db.automationRules.list().then(r => setRules(r || [])) }, [])

  const saveAll = async (newRules) => {
    setSaving(true)
    try {
      await db.automationRules.save(newRules, currentUserEmail)
      setRules(newRules)
      toast.success('Automation rules saved')
    } catch (e) { toast.error(e.message) }
    finally { setSaving(false) }
  }

  const deleteRule = (id) => saveAll(rules.filter(r => r.id !== id))
  const toggleRule = (id) => saveAll(rules.map(r => r.id === id ? { ...r, enabled: !r.enabled } : r))
  const saveEdit = () => {
    if (!editing.name.trim()) { toast.error('Rule name is required'); return }
    const exists = rules.find(r => r.id === editing.id)
    const updated = exists ? rules.map(r => r.id === editing.id ? editing : r) : [...rules, editing]
    saveAll(updated).then(() => setEditing(null))
  }

  if (!rules) return <div className="flex justify-center py-10"><Spinner /></div>

  if (editing) {
    return (
      <div className="max-w-2xl space-y-4">
        <div className="flex items-center gap-3 mb-2">
          <button onClick={() => setEditing(null)} className="text-sm text-indigo-600 hover:text-indigo-800 font-medium flex items-center gap-1">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>Back
          </button>
          <span className="text-sm font-semibold text-gray-900">{editing.name || 'New Rule'}</span>
        </div>

        <div className="bg-white rounded-xl border border-gray-200 p-5 space-y-5">
          <div>
            <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1.5">Rule Name</label>
            <input value={editing.name} onChange={e => setEditing(r => ({ ...r, name: e.target.value }))}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600" placeholder="e.g. Auto-escalate critical tickets" />
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1.5">Trigger Event</label>
            <select value={editing.trigger} onChange={e => setEditing(r => ({ ...r, trigger: e.target.value }))}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600 bg-white">
              {TRIGGER_OPTIONS.map(t => <option key={t.value} value={t.value}>{t.label}</option>)}
            </select>
          </div>

          {/* Conditions */}
          <div>
            <div className="flex items-center justify-between mb-2">
              <label className="text-xs font-semibold text-gray-500 uppercase tracking-wider">Conditions <span className="font-normal text-gray-400">(all must match)</span></label>
              <button onClick={() => setEditing(r => ({ ...r, conditions: [...r.conditions, { field: 'priority', op: 'equals', value: 'Critical' }] }))}
                className="text-xs text-indigo-600 hover:text-indigo-800 font-medium">+ Add Condition</button>
            </div>
            {editing.conditions.length === 0 && <p className="text-xs text-gray-400 italic">No conditions — rule runs on all tickets</p>}
            {editing.conditions.map((c, i) => (
              <div key={i} className="flex gap-2 items-center mb-2">
                <select value={c.field} onChange={e => setEditing(r => { const conds = [...r.conditions]; conds[i] = { ...conds[i], field: e.target.value }; return { ...r, conditions: conds } })}
                  className="flex-1 px-2 py-1.5 border border-gray-300 rounded text-sm bg-white">
                  {FIELD_OPTIONS.map(f => <option key={f.value} value={f.value}>{f.label}</option>)}
                </select>
                <select value={c.op} onChange={e => setEditing(r => { const conds = [...r.conditions]; conds[i] = { ...conds[i], op: e.target.value }; return { ...r, conditions: conds } })}
                  className="flex-1 px-2 py-1.5 border border-gray-300 rounded text-sm bg-white">
                  {OP_OPTIONS.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
                </select>
                <input value={c.value} onChange={e => setEditing(r => { const conds = [...r.conditions]; conds[i] = { ...conds[i], value: e.target.value }; return { ...r, conditions: conds } })}
                  className="flex-1 px-2 py-1.5 border border-gray-300 rounded text-sm" placeholder="value" />
                <button onClick={() => setEditing(r => ({ ...r, conditions: r.conditions.filter((_, j) => j !== i) }))} className="text-red-400 hover:text-red-600">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))}
          </div>

          {/* Actions */}
          <div>
            <div className="flex items-center justify-between mb-2">
              <label className="text-xs font-semibold text-gray-500 uppercase tracking-wider">Actions <span className="font-normal text-gray-400">(executed in order)</span></label>
              <button onClick={() => setEditing(r => ({ ...r, actions: [...r.actions, { type: 'create_notification', title: 'Alert', value: '' }] }))}
                className="text-xs text-indigo-600 hover:text-indigo-800 font-medium">+ Add Action</button>
            </div>
            {editing.actions.map((a, i) => (
              <div key={i} className="flex gap-2 items-center mb-2">
                <select value={a.type} onChange={e => setEditing(r => { const acts = [...r.actions]; acts[i] = { ...acts[i], type: e.target.value }; return { ...r, actions: acts } })}
                  className="flex-1 px-2 py-1.5 border border-gray-300 rounded text-sm bg-white">
                  {ACTION_TYPES.map(at => <option key={at.value} value={at.value}>{at.label}</option>)}
                </select>
                {(a.type === 'change_status') && (
                  <select value={a.value} onChange={e => setEditing(r => { const acts = [...r.actions]; acts[i] = { ...acts[i], value: e.target.value }; return { ...r, actions: acts } })}
                    className="flex-1 px-2 py-1.5 border border-gray-300 rounded text-sm bg-white">
                    {STATUS_OPTIONS.map(s => <option key={s}>{s}</option>)}
                  </select>
                )}
                {(a.type === 'change_priority') && (
                  <select value={a.value} onChange={e => setEditing(r => { const acts = [...r.actions]; acts[i] = { ...acts[i], value: e.target.value }; return { ...r, actions: acts } })}
                    className="flex-1 px-2 py-1.5 border border-gray-300 rounded text-sm bg-white">
                    {PRIORITY_OPTIONS.map(p => <option key={p}>{p}</option>)}
                  </select>
                )}
                {(a.type === 'assign_technician' || a.type === 'create_notification') && (
                  <input value={a.value} onChange={e => setEditing(r => { const acts = [...r.actions]; acts[i] = { ...acts[i], value: e.target.value }; return { ...r, actions: acts } })}
                    className="flex-1 px-2 py-1.5 border border-gray-300 rounded text-sm"
                    placeholder={a.type === 'assign_technician' ? 'email@example.com' : 'Notification message'} />
                )}
                <button onClick={() => setEditing(r => ({ ...r, actions: r.actions.filter((_, j) => j !== i) }))} className="text-red-400 hover:text-red-600">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))}
          </div>

          <div className="flex gap-3 pt-2 border-t border-gray-100">
            <button onClick={saveEdit} disabled={saving} className="px-5 py-2 bg-indigo-600 text-white text-sm font-medium rounded-lg hover:bg-indigo-700 disabled:opacity-50 flex items-center gap-2">
              {saving ? <Spinner size="sm" color="white" /> : null} Save Rule
            </button>
            <button onClick={() => setEditing(null)} className="px-5 py-2 bg-gray-100 text-gray-700 text-sm font-medium rounded-lg hover:bg-gray-200">Cancel</button>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="max-w-2xl space-y-4">
      <div className="flex items-center justify-between">
        <p className="text-sm text-gray-500">{rules.length} rule{rules.length !== 1 ? 's' : ''} configured</p>
        <button onClick={() => setEditing(EMPTY_RULE())} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white text-sm font-medium rounded-lg hover:bg-indigo-700">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
          New Rule
        </button>
      </div>

      {rules.length === 0 ? (
        <div className="bg-white rounded-xl border border-dashed border-gray-300 p-10 text-center">
          <svg className="w-10 h-10 text-gray-300 mx-auto mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
          <p className="text-sm text-gray-500">No automation rules yet</p>
          <p className="text-xs text-gray-400 mt-1">Rules automatically act on tickets when events occur</p>
        </div>
      ) : (
        <div className="space-y-3">
          {rules.map(rule => (
            <div key={rule.id} className="bg-white rounded-xl border border-gray-200 p-4">
              <div className="flex items-start justify-between gap-3">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <span className="font-semibold text-sm text-gray-900">{rule.name}</span>
                    <span className={`px-2 py-0.5 text-xs rounded-full font-medium ${rule.enabled ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'}`}>{rule.enabled ? 'Active' : 'Disabled'}</span>
                  </div>
                  <div className="text-xs text-gray-500 mt-1">
                    Trigger: <span className="font-medium text-gray-700">{TRIGGER_OPTIONS.find(t => t.value === rule.trigger)?.label}</span>
                    {rule.conditions.length > 0 && <> · {rule.conditions.length} condition{rule.conditions.length !== 1 ? 's' : ''}</>}
                    · {rule.actions.length} action{rule.actions.length !== 1 ? 's' : ''}
                  </div>
                </div>
                <div className="flex gap-2 flex-shrink-0">
                  <button onClick={() => toggleRule(rule.id)} className={`text-xs px-3 py-1 rounded-lg font-medium ${rule.enabled ? 'bg-yellow-50 text-yellow-700 hover:bg-yellow-100' : 'bg-green-50 text-green-700 hover:bg-green-100'}`}>
                    {rule.enabled ? 'Disable' : 'Enable'}
                  </button>
                  <button onClick={() => setEditing({ ...rule })} className="text-xs px-3 py-1 rounded-lg font-medium bg-gray-50 text-gray-700 hover:bg-gray-100">Edit</button>
                  <button onClick={() => deleteRule(rule.id)} className="text-xs px-3 py-1 rounded-lg font-medium bg-red-50 text-red-600 hover:bg-red-100">Delete</button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

// ─── OUTBOUND WEBHOOKS ──────────────────────────────────────────────────────

const WEBHOOK_EVENTS = [
  'ticket_created', 'ticket_updated', 'ticket_status_changed', 'ticket_assigned',
  'ticket_overdue', 'customer_created', 'customer_deleted', 'invoice_created', 'invoice_paid'
]

const EMPTY_HOOK = () => ({ id: Date.now(), name: '', url: '', secret: '', enabled: true, events: [] })

function WebhooksConfig({ currentUserEmail }) {
  const [hooks, setHooks] = useState(null)
  const [editing, setEditing] = useState(null)
  const [saving, setSaving] = useState(false)
  const [testing, setTesting] = useState(null)

  useEffect(() => { db.webhooks.list().then(h => setHooks(h || [])) }, [])

  const saveAll = async (newHooks) => {
    setSaving(true)
    try {
      await db.webhooks.save(newHooks, currentUserEmail)
      setHooks(newHooks)
      toast.success('Webhooks saved')
    } catch (e) { toast.error(e.message) }
    finally { setSaving(false) }
  }

  const saveEdit = () => {
    if (!editing.name.trim() || !editing.url.trim()) { toast.error('Name and URL are required'); return }
    try { new URL(editing.url) } catch { toast.error('Invalid URL'); return }
    const exists = hooks.find(h => h.id === editing.id)
    const updated = exists ? hooks.map(h => h.id === editing.id ? editing : h) : [...hooks, editing]
    saveAll(updated).then(() => setEditing(null))
  }

  const testHook = async (hook) => {
    setTesting(hook.id)
    try {
      const res = await fetch(hook.url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...(hook.secret ? { 'X-myRMA-Secret': hook.secret } : {}) },
        body: JSON.stringify({ event: 'test', timestamp: new Date().toISOString(), data: { message: 'Test from myRMA' } })
      })
      res.ok ? toast.success(`Webhook responded: ${res.status}`) : toast.error(`Webhook returned ${res.status}`)
    } catch { toast.error('Failed to reach webhook URL') }
    finally { setTesting(null) }
  }

  if (!hooks) return <div className="flex justify-center py-10"><Spinner /></div>

  if (editing) return (
    <div className="max-w-lg space-y-4">
      <div className="flex items-center gap-3 mb-2">
        <button onClick={() => setEditing(null)} className="text-sm text-indigo-600 hover:text-indigo-800 font-medium flex items-center gap-1">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>Back
        </button>
        <span className="text-sm font-semibold text-gray-900">{editing.name || 'New Webhook'}</span>
      </div>
      <div className="bg-white rounded-xl border border-gray-200 p-5 space-y-4">
        {[{ label: 'Name', key: 'name', placeholder: 'e.g. Notify Slack', type: 'text' },
          { label: 'Endpoint URL', key: 'url', placeholder: 'https://hooks.slack.com/...', type: 'url' },
          { label: 'Secret Header (optional)', key: 'secret', placeholder: 'Sent as X-myRMA-Secret', type: 'text' },
        ].map(f => (
          <div key={f.key}>
            <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1.5">{f.label}</label>
            <input type={f.type} value={editing[f.key]} onChange={e => setEditing(h => ({ ...h, [f.key]: e.target.value }))}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600" placeholder={f.placeholder} />
          </div>
        ))}

        <div>
          <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">Events to Send <span className="font-normal">(leave empty = all events)</span></label>
          <div className="flex flex-wrap gap-2">
            {WEBHOOK_EVENTS.map(ev => (
              <button key={ev} onClick={() => setEditing(h => ({ ...h, events: h.events.includes(ev) ? h.events.filter(e => e !== ev) : [...h.events, ev] }))}
                className={`px-2.5 py-1 text-xs rounded-full font-medium border transition-colors ${editing.events.includes(ev) ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-600 border-gray-300 hover:border-indigo-400'}`}>
                {ev}
              </button>
            ))}
          </div>
        </div>

        <div className="flex gap-3 pt-2 border-t border-gray-100">
          <button onClick={saveEdit} disabled={saving} className="px-5 py-2 bg-indigo-600 text-white text-sm font-medium rounded-lg hover:bg-indigo-700 disabled:opacity-50 flex items-center gap-2">
            {saving ? <Spinner size="sm" color="white" /> : null} Save Webhook
          </button>
          <button onClick={() => setEditing(null)} className="px-5 py-2 bg-gray-100 text-gray-700 text-sm font-medium rounded-lg hover:bg-gray-200">Cancel</button>
        </div>
      </div>
    </div>
  )

  return (
    <div className="max-w-2xl space-y-4">
      <div className="flex items-center justify-between">
        <p className="text-sm text-gray-500">{hooks.length} webhook{hooks.length !== 1 ? 's' : ''} configured</p>
        <button onClick={() => setEditing(EMPTY_HOOK())} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white text-sm font-medium rounded-lg hover:bg-indigo-700">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
          Add Webhook
        </button>
      </div>

      <div className="bg-blue-50 border border-blue-200 rounded-xl p-3 text-xs text-blue-700">
        Webhooks send a POST request with JSON payload <code className="bg-blue-100 px-1 rounded">{'{ event, timestamp, data }'}</code> to your URL on selected events.
      </div>

      {hooks.length === 0 ? (
        <div className="bg-white rounded-xl border border-dashed border-gray-300 p-10 text-center">
          <p className="text-sm text-gray-500">No webhooks configured</p>
          <p className="text-xs text-gray-400 mt-1">Push ticket events to Slack, QuickBooks, Zapier, and more</p>
        </div>
      ) : (
        <div className="space-y-3">
          {hooks.map(h => (
            <div key={h.id} className="bg-white rounded-xl border border-gray-200 p-4">
              <div className="flex items-start justify-between gap-3">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <span className="font-semibold text-sm text-gray-900">{h.name}</span>
                    <span className={`px-2 py-0.5 text-xs rounded-full font-medium ${h.enabled ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'}`}>{h.enabled ? 'Active' : 'Disabled'}</span>
                  </div>
                  <div className="text-xs text-gray-400 font-mono mt-0.5 truncate">{h.url}</div>
                  {h.events.length > 0 && <div className="flex flex-wrap gap-1 mt-1.5">{h.events.map(e => <span key={e} className="px-1.5 py-0.5 bg-gray-100 text-gray-600 text-xs rounded">{e}</span>)}</div>}
                </div>
                <div className="flex gap-2 flex-shrink-0">
                  <button onClick={() => testHook(h)} disabled={testing === h.id} className="text-xs px-3 py-1 rounded-lg font-medium bg-indigo-50 text-indigo-700 hover:bg-indigo-100 disabled:opacity-50">
                    {testing === h.id ? '…' : 'Test'}
                  </button>
                  <button onClick={() => setEditing({ ...h })} className="text-xs px-3 py-1 rounded-lg font-medium bg-gray-50 text-gray-700 hover:bg-gray-100">Edit</button>
                  <button onClick={() => saveAll(hooks.filter(wh => wh.id !== h.id))} className="text-xs px-3 py-1 rounded-lg font-medium bg-red-50 text-red-600 hover:bg-red-100">Delete</button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { db, storage } from '../api/supabaseClient'
import toast from 'react-hot-toast'
import ConfirmDialog from '../components/ConfirmDialog'
import { CardSkeleton } from '../components/Skeleton'
import AttachmentsField from '../components/AttachmentsField'
import { Button, Spinner } from '../components/ui'
import { useURLTab } from '../hooks/useURLTab'

export default function CustomerDetails({ customerId, currentUserRole, currentUserEmail, currentUserPermissions, onBack, onNavigateToTicket }) {
  const [customer, setCustomer] = useState(null)
  const [tickets, setTickets] = useState([])
  const [notes, setNotes] = useState([])
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useURLTab('tab', 'profile')
  const [isEditing, setIsEditing] = useState(false)
  const [editForm, setEditForm] = useState({})
  const [pendingFiles, setPendingFiles] = useState([])
  const [newNote, setNewNote] = useState('')
  const [editingNote, setEditingNote] = useState(null)
  const [editNoteText, setEditNoteText] = useState('')
  const [savingNote, setSavingNote] = useState(false)

  const isSuperAdmin = currentUserRole === 'super_admin'
  const canDo = (action) => {
    if (isSuperAdmin) return true
    if (currentUserPermissions?.customers?.[action] === true) return true
    if (currentUserRole === 'admin') return true
    return false
  }

  const [confirmDialog, setConfirmDialog] = useState({ open: false, title: '', message: '', onConfirm: null })
  const openConfirm = (title, message, onConfirm) => setConfirmDialog({ open: true, title, message, onConfirm })
  const closeConfirm = () => setConfirmDialog(d => ({ ...d, open: false }))

  useEffect(() => { loadAll() }, [customerId])

  const loadAll = async () => {
    setLoading(true)
    try {
      const [customerData, ticketsData, notesData] = await Promise.all([
        db.customers.get(customerId),
        db.customers.getRelatedTickets(customerId),
        db.customerNotes.list(customerId)
      ])
      setCustomer(customerData)
      setEditForm(customerData)
      setTickets(ticketsData)
      setNotes(notesData)
    } catch (error) {
      console.error('Error loading customer:', error)
      toast.error('Failed to load customer details')
    } finally {
      setLoading(false)
    }
  }

  const handleSaveEdit = async () => {
    if (!editForm.contact_person?.trim() || !editForm.mobile?.trim()) {
      toast.error('Contact person and mobile are required')
      return
    }
    if (editForm.customer_type === 'B2B' && !editForm.company_name?.trim()) {
      toast.error('Company name is required for B2B customers')
      return
    }

    // Upload any newly added files
    const uploadedAttachments = []
    if (pendingFiles.length > 0) {
      for (const file of pendingFiles) {
        try {
          const result = await storage.uploadCustomerAttachment(file, customerId)
          uploadedAttachments.push(result)
        } catch (err) {
          toast.error(`Failed to upload ${file.name}: ${err.message}`)
          return
        }
      }
    }
    const allAttachments = [...(editForm.attachments || []), ...uploadedAttachments]

    try {
      const updated = await db.customers.update(customerId, {
        customer_type: editForm.customer_type,
        customer_status: editForm.customer_status,
        company_name: editForm.company_name || null,
        contact_person: editForm.contact_person,
        account_manager: editForm.account_manager || null,
        mobile: editForm.mobile,
        landline: editForm.landline || null,
        email: editForm.email || null,
        address: editForm.address || null,
        cr_number: editForm.cr_number || null,
        tax_id: editForm.tax_id || null,
        notes: editForm.notes || null,
        attachments: allAttachments,
        updated_by: currentUserEmail,
        updated_date: new Date().toISOString()
      })
      setCustomer(updated)
      setEditForm(updated)
      setPendingFiles([])
      setIsEditing(false)
      toast.success('Customer updated successfully')
      db.auditLog.log(currentUserEmail, 'customer_updated', `Updated customer ${editForm.contact_person}${editForm.company_name ? ` (${editForm.company_name})` : ''}`).catch(err => console.error('audit log failed:', err))
    } catch (error) {
      toast.error(`Failed to update: ${error.message}`)
    }
  }

  const handleDelete = () => {
    openConfirm(
      'Delete Customer',
      `Delete ${customer.contact_person}? This cannot be undone.`,
      async () => {
        closeConfirm()
        try {
          await db.customers.delete(customerId)
          toast.success('Customer deleted')
          db.auditLog.log(currentUserEmail, 'customer_deleted', `Deleted customer ${customer.contact_person}${customer.company_name ? ` (${customer.company_name})` : ''}`).catch(err => console.error('audit log failed:', err))
          onBack()
        } catch (error) {
          toast.error('Failed to delete customer')
        }
      }
    )
  }

  const handleAddNote = async () => {
    if (!newNote.trim()) return
    setSavingNote(true)
    try {
      const created = await db.customerNotes.create({
        customer_id: customerId,
        note: newNote.trim(),
        created_by: currentUserEmail,
        created_date: new Date().toISOString(),
        updated_date: new Date().toISOString()
      })
      setNotes(prev => [created, ...prev])
      setNewNote('')
      toast.success('Note added')
      db.auditLog.log(currentUserEmail, 'customer_note_added', `Added note on customer ${customer?.contact_person}`).catch(err => console.error('audit log failed:', err))
    } catch (error) {
      toast.error('Failed to add note')
    } finally {
      setSavingNote(false)
    }
  }

  const handleUpdateNote = async (noteId) => {
    if (!editNoteText.trim()) return
    try {
      const updated = await db.customerNotes.update(noteId, {
        note: editNoteText.trim(),
        updated_date: new Date().toISOString()
      })
      setNotes(prev => prev.map(n => n.id === noteId ? updated : n))
      setEditingNote(null)
      setEditNoteText('')
      toast.success('Note updated')
      db.auditLog.log(currentUserEmail, 'customer_note_updated', `Updated note ${noteId} on customer ${customer?.contact_person}`).catch(err => console.error('audit log failed:', err))
    } catch (error) {
      toast.error('Failed to update note')
    }
  }

  const handleDeleteNote = (noteId) => {
    openConfirm(
      'Delete Note',
      'Delete this note? This cannot be undone.',
      async () => {
        closeConfirm()
        try {
          await db.customerNotes.delete(noteId)
          setNotes(prev => prev.filter(n => n.id !== noteId))
          toast.success('Note deleted')
          db.auditLog.log(currentUserEmail, 'customer_note_deleted', `Deleted note ${noteId} on customer ${customer?.contact_person}`).catch(err => console.error('audit log failed:', err))
        } catch (error) {
          toast.error('Failed to delete note')
        }
      }
    )
  }

  const getStatusBadge = (status) => {
    const style = status === 'Active'
      ? 'bg-green-100 text-green-800'
      : 'bg-gray-100 text-gray-800'
    return (
      <span className={`px-3 py-1 text-sm rounded-full font-medium ${style}`}>
        {status || 'Unknown'}
      </span>
    )
  }

  const getTypeBadge = (type) => {
    const style = type === 'B2B'
      ? 'bg-blue-100 text-blue-800'
      : 'bg-emerald-100 text-emerald-800'
    return (
      <span className={`px-2 py-1 text-xs rounded-full font-medium ${style}`}>
        {type === 'B2B' ? '🏢 B2B' : '👤 B2C'}
      </span>
    )
  }

  const getTicketStatusBadge = (status) => {
    const styles = {
      'New': 'bg-blue-100 text-blue-800',
      'In Progress': 'bg-yellow-100 text-yellow-800',
      'On Hold': 'bg-orange-100 text-orange-800',
      'Completed': 'bg-green-100 text-green-800',
      'Cancelled': 'bg-gray-100 text-gray-800'
    }
    return (
      <span className={`px-2 py-1 text-xs rounded-full font-medium ${styles[status] || 'bg-gray-100 text-gray-800'}`}>
        {status || 'Unknown'}
      </span>
    )
  }

  const formatDate = (dateStr) => {
    if (!dateStr) return '—'
    return new Date(dateStr).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' })
  }

  const formatDateTime = (dateStr) => {
    if (!dateStr) return '—'
    return new Date(dateStr).toLocaleString('en-US', {
      year: 'numeric', month: 'short', day: 'numeric',
      hour: '2-digit', minute: '2-digit'
    })
  }

  const inputClass = 'w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent'
  const labelClass = 'block text-sm font-medium text-gray-700 mb-1'

  if (loading) {
    return (
      <div className="space-y-6">
        <div className="h-8 w-48 animate-pulse bg-gray-200 rounded-lg" />
        <CardSkeleton lines={5} />
        <CardSkeleton lines={4} />
      </div>
    )
  }

  if (!customer) {
    return (
      <div className="text-center py-12">
        <p className="text-gray-500">Customer not found.</p>
        <Button className="mt-4" onClick={onBack}>Go Back</Button>
      </div>
    )
  }

  const displayName = customer.customer_type === 'B2B' && customer.company_name
    ? customer.company_name
    : customer.contact_person

  return (
    <div className="space-y-6">

      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-4">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="flex items-center gap-1.5 text-sm text-gray-500 hover:text-gray-900 transition-colors">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
            Back to Customers
          </button>
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-700 font-bold text-lg">
              {displayName?.[0]?.toUpperCase() || '?'}
            </div>
            <div>
              <h1 className="text-2xl font-bold text-gray-900">{displayName}</h1>
              {customer.customer_type === 'B2B' && customer.contact_person && (
                <p className="text-sm text-gray-500">Contact: {customer.contact_person}</p>
              )}
              <div className="flex items-center gap-2 mt-1">
                {getStatusBadge(customer.customer_status)}
                {getTypeBadge(customer.customer_type)}
                {customer.customer_code && (
                  <span className="font-mono text-xs text-gray-500 bg-gray-100 px-2 py-1 rounded">
                    {customer.customer_code}
                  </span>
                )}
              </div>
            </div>
          </div>
        </div>

        {canDo('edit') && !isEditing && (
          <div className="flex items-center gap-2">
            <Button onClick={() => { setIsEditing(true); setEditForm(customer); setPendingFiles([]) }}>
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
              </svg>
              Edit
            </Button>
            <Button variant="danger" onClick={handleDelete}>
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
              Delete
            </Button>
          </div>
        )}

        {isEditing && (
          <div className="flex items-center gap-2">
            <Button variant="secondary" onClick={() => { setIsEditing(false); setEditForm(customer); setPendingFiles([]) }}>
              Cancel
            </Button>
            <Button variant="success" onClick={handleSaveEdit}>Save Changes</Button>
          </div>
        )}
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        {[
          { label: 'Total RMAs', value: tickets.length, icon: '🎫', color: 'bg-blue-50 text-blue-700' },
          { label: 'Open Tickets', value: tickets.filter(t => t.ticket_status === 'New' || t.ticket_status === 'In Progress' || t.ticket_status === 'On Hold').length, icon: '🔓', color: 'bg-yellow-50 text-yellow-700' },
          { label: 'Notes', value: notes.length, icon: '📝', color: 'bg-purple-50 text-purple-700' },
          { label: 'Customer Since', value: formatDate(customer.created_date), icon: '📅', color: 'bg-green-50 text-green-700' }
        ].map(stat => (
          <div key={stat.label} className={`rounded-xl p-4 ${stat.color}`}>
            <div className="text-2xl mb-1">{stat.icon}</div>
            <div className="text-xl font-bold">{stat.value}</div>
            <div className="text-sm font-medium">{stat.label}</div>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200">
        <div className="border-b border-gray-200">
          <nav className="flex gap-6 px-6">
            {[
              { key: 'profile', label: 'Profile', icon: '👤' },
              { key: 'rma', label: `RMA History (${tickets.length})`, icon: '🎫' },
              { key: 'notes', label: `Notes (${notes.length})`, icon: '📝' },
              { key: 'activity', label: 'Activity Log', icon: '📋' }
            ].map(tab => (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key)}
                className={`py-4 border-b-2 font-medium transition-colors flex items-center gap-2 ${
                  activeTab === tab.key
                    ? 'border-indigo-600 text-indigo-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700'
                }`}
              >
                <span>{tab.icon}</span>
                {tab.label}
              </button>
            ))}
          </nav>
        </div>

        <div className="p-6">

          {/* ==================== PROFILE TAB ==================== */}
          {activeTab === 'profile' && (
            <div className="space-y-8">
              {isEditing ? (
                <div className="space-y-6">
                  {/* Customer Type + Status */}
                  <div>
                    <h3 className="text-sm font-semibold text-gray-700 uppercase tracking-wider mb-3">Customer Type & Status</h3>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className={labelClass}>Customer Type <span className="text-red-500">*</span></label>
                        <select
                          value={editForm.customer_type || 'B2B'}
                          onChange={(e) => setEditForm({ ...editForm, customer_type: e.target.value })}
                          className={inputClass}
                        >
                          <option value="B2B">B2B — Business</option>
                          <option value="B2C">B2C — Individual</option>
                        </select>
                      </div>
                      <div>
                        <label className={labelClass}>Status <span className="text-red-500">*</span></label>
                        <select
                          value={editForm.customer_status || 'Active'}
                          onChange={(e) => setEditForm({ ...editForm, customer_status: e.target.value })}
                          className={inputClass}
                        >
                          <option value="Active">Active</option>
                          <option value="Inactive">Inactive</option>
                        </select>
                      </div>
                    </div>
                  </div>

                  {/* B2B fields */}
                  {editForm.customer_type === 'B2B' && (
                    <div>
                      <h3 className="text-sm font-semibold text-gray-700 uppercase tracking-wider mb-3">Company Information</h3>
                      <div className="grid grid-cols-2 gap-4">
                        <div>
                          <label className={labelClass}>Company Name <span className="text-red-500">*</span></label>
                          <input
                            type="text"
                            value={editForm.company_name || ''}
                            onChange={(e) => setEditForm({ ...editForm, company_name: e.target.value })}
                            className={inputClass}
                          />
                        </div>
                        <div>
                          <label className={labelClass}>CR Number</label>
                          <input
                            type="text"
                            value={editForm.cr_number || ''}
                            onChange={(e) => setEditForm({ ...editForm, cr_number: e.target.value })}
                            className={inputClass}
                          />
                        </div>
                        <div>
                          <label className={labelClass}>Tax ID</label>
                          <input
                            type="text"
                            value={editForm.tax_id || ''}
                            onChange={(e) => setEditForm({ ...editForm, tax_id: e.target.value })}
                            className={inputClass}
                          />
                        </div>
                      </div>
                    </div>
                  )}

                  {/* Contact */}
                  <div>
                    <h3 className="text-sm font-semibold text-gray-700 uppercase tracking-wider mb-3">Contact Information</h3>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className={labelClass}>Contact Person <span className="text-red-500">*</span></label>
                        <input
                          type="text"
                          value={editForm.contact_person || ''}
                          onChange={(e) => setEditForm({ ...editForm, contact_person: e.target.value })}
                          className={inputClass}
                        />
                      </div>
                      <div>
                        <label className={labelClass}>Mobile <span className="text-red-500">*</span></label>
                        <input
                          type="tel"
                          value={editForm.mobile || ''}
                          onChange={(e) => setEditForm({ ...editForm, mobile: e.target.value })}
                          className={inputClass}
                        />
                      </div>
                      <div>
                        <label className={labelClass}>Landline</label>
                        <input
                          type="tel"
                          value={editForm.landline || ''}
                          onChange={(e) => setEditForm({ ...editForm, landline: e.target.value })}
                          className={inputClass}
                        />
                      </div>
                      <div>
                        <label className={labelClass}>Email</label>
                        <input
                          type="email"
                          value={editForm.email || ''}
                          onChange={(e) => setEditForm({ ...editForm, email: e.target.value })}
                          className={inputClass}
                        />
                      </div>
                      <div>
                        <label className={labelClass}>Account Manager</label>
                        <input
                          type="text"
                          value={editForm.account_manager || ''}
                          onChange={(e) => setEditForm({ ...editForm, account_manager: e.target.value })}
                          className={inputClass}
                        />
                      </div>
                    </div>
                  </div>

                  {/* Address */}
                  <div>
                    <h3 className="text-sm font-semibold text-gray-700 uppercase tracking-wider mb-3">Address</h3>
                    <textarea
                      value={editForm.address || ''}
                      onChange={(e) => setEditForm({ ...editForm, address: e.target.value })}
                      rows={3}
                      placeholder="Full address..."
                      className={inputClass}
                    />
                  </div>

                  {/* Notes */}
                  <div>
                    <h3 className="text-sm font-semibold text-gray-700 uppercase tracking-wider mb-3">Internal Notes</h3>
                    <textarea
                      value={editForm.notes || ''}
                      onChange={(e) => setEditForm({ ...editForm, notes: e.target.value })}
                      rows={3}
                      placeholder="Internal notes..."
                      className={inputClass}
                    />
                  </div>

                  {/* Attachments */}
                  <div>
                    <h3 className="text-sm font-semibold text-gray-700 uppercase tracking-wider mb-3">Attachments</h3>
                    <AttachmentsField
                      savedAttachments={editForm.attachments || []}
                      onSavedChange={(val) => setEditForm({ ...editForm, attachments: val })}
                      pendingFiles={pendingFiles}
                      onPendingChange={setPendingFiles}
                    />
                  </div>
                </div>
              ) : (
                // View Mode
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  {/* Left Column */}
                  <div className="space-y-6">
                    <div>
                      <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider mb-4">Contact Information</h3>
                      <div className="space-y-3">
                        <DetailRow icon="👤" label="Contact Person" value={customer.contact_person} />
                        <DetailRow icon="📱" label="Mobile" value={customer.mobile} />
                        <DetailRow icon="📞" label="Landline" value={customer.landline} />
                        <DetailRow icon="✉️" label="Email" value={
                          customer.email
                            ? <a href={`mailto:${customer.email}`} className="text-indigo-600 hover:underline">{customer.email}</a>
                            : null
                        } />
                        <DetailRow icon="👔" label="Account Manager" value={customer.account_manager} />
                      </div>
                    </div>

                    <div>
                      <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider mb-4">System Info</h3>
                      <div className="space-y-3">
                        <DetailRow icon="🔢" label="Customer Code" value={
                          customer.customer_code
                            ? <span className="font-mono text-sm">{customer.customer_code}</span>
                            : null
                        } />
                        <DetailRow icon="📅" label="Customer Since" value={formatDate(customer.created_date)} />
                        <DetailRow icon="🔄" label="Last Updated" value={formatDateTime(customer.updated_date)} />
                        <DetailRow icon="👤" label="Created By" value={customer.created_by} />
                      </div>
                    </div>
                  </div>

                  {/* Right Column */}
                  <div className="space-y-6">
                    {customer.customer_type === 'B2B' && (
                      <div>
                        <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider mb-4">Company Information</h3>
                        <div className="space-y-3">
                          <DetailRow icon="🏢" label="Company Name" value={customer.company_name} />
                          <DetailRow icon="📄" label="CR Number" value={customer.cr_number} />
                          <DetailRow icon="🧾" label="Tax ID" value={customer.tax_id} />
                        </div>
                      </div>
                    )}

                    <div>
                      <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider mb-4">Address</h3>
                      {customer.address ? (
                        <div className="bg-gray-50 rounded-lg p-4 text-sm text-gray-700 whitespace-pre-wrap">
                          {customer.address}
                        </div>
                      ) : (
                        <p className="text-gray-400 text-sm">No address on file</p>
                      )}
                    </div>

                    {customer.notes && (
                      <div>
                        <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider mb-4">Internal Notes</h3>
                        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 text-sm text-gray-700 whitespace-pre-wrap">
                          {customer.notes}
                        </div>
                      </div>
                    )}

                    {(customer.attachments || []).length > 0 && (
                      <div>
                        <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider mb-3">Attachments</h3>
                        <div className="space-y-2">
                          {customer.attachments.map((att, i) => (
                            <a
                              key={i}
                              href={att.url}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="flex items-center gap-3 px-4 py-3 bg-gray-50 border border-gray-200 rounded-lg hover:bg-indigo-50 hover:border-indigo-300 transition-colors group"
                            >
                              <svg className="w-5 h-5 text-gray-400 group-hover:text-indigo-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" />
                              </svg>
                              <span className="text-sm text-gray-700 group-hover:text-indigo-700 flex-1 truncate">{att.name}</span>
                              {att.size && <span className="text-xs text-gray-400 flex-shrink-0">{(att.size / 1024).toFixed(0)} KB</span>}
                              <svg className="w-4 h-4 text-gray-300 group-hover:text-indigo-400 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                              </svg>
                            </a>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>
          )}

          {/* ==================== RMA HISTORY TAB ==================== */}
          {activeTab === 'rma' && (
            <div>
              {tickets.length === 0 ? (
                <div className="text-center py-12 text-gray-500">
                  <div className="text-4xl mb-3">🎫</div>
                  <p className="font-medium">No RMA tickets found</p>
                  <p className="text-sm">This customer has no RMA history yet</p>
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead className="bg-gray-50 border-y border-gray-200">
                      <tr>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">RMA Number</th>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Priority</th>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Issue</th>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Created</th>
                        <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Action</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                      {tickets.map(ticket => (
                        <tr key={ticket.id} className="hover:bg-gray-50">
                          <td className="px-4 py-3">
                            <span className="font-mono text-sm font-medium text-indigo-600">
                              {ticket.rma_number || ticket.id?.slice(0, 8)}
                            </span>
                          </td>
                          <td className="px-4 py-3">{getTicketStatusBadge(ticket.ticket_status)}</td>
                          <td className="px-4 py-3">
                            <span className={`px-2 py-1 text-xs rounded-full font-medium ${
                              ticket.priority === 'High' ? 'bg-red-100 text-red-800' :
                              ticket.priority === 'Medium' ? 'bg-yellow-100 text-yellow-800' :
                              ticket.priority === 'Critical' ? 'bg-red-200 text-red-900' :
                              'bg-gray-100 text-gray-800'
                            }`}>
                              {ticket.priority || 'Low'}
                            </span>
                          </td>
                          <td className="px-4 py-3 text-sm text-gray-600 max-w-xs truncate" title={ticket.general_description || ''}>
                            {ticket.general_description || '—'}
                          </td>
                          <td className="px-4 py-3 text-sm text-gray-500">{formatDate(ticket.created_date)}</td>
                          <td className="px-4 py-3">
                            <button
                              onClick={() => onNavigateToTicket(ticket.id)}
                              className="text-indigo-600 hover:text-indigo-900 text-sm font-medium hover:underline"
                            >
                              View →
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          )}

          {/* ==================== NOTES TAB ==================== */}
          {activeTab === 'notes' && (
            <div className="space-y-4">
              <div className="bg-gray-50 rounded-lg p-4 space-y-3">
                <h3 className="font-medium text-gray-900">Add a Note</h3>
                <textarea
                  value={newNote}
                  onChange={(e) => setNewNote(e.target.value)}
                  placeholder="Write an internal note about this customer..."
                  rows={3}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent"
                />
                <div className="flex justify-end">
                  <button
                    onClick={handleAddNote}
                    disabled={!newNote.trim() || savingNote}
                    className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 flex items-center gap-2"
                  >
                    {savingNote
                      ? <Spinner size="sm" color="white" />
                      : <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
                    }
                    Add Note
                  </button>
                </div>
              </div>

              {notes.length === 0 ? (
                <div className="text-center py-8 text-gray-500">
                  <div className="text-3xl mb-2">📝</div>
                  <p>No notes yet. Add the first note above.</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {notes.map(note => (
                    <div key={note.id} className="bg-white border border-gray-200 rounded-lg p-4">
                      {editingNote === note.id ? (
                        <div className="space-y-3">
                          <textarea
                            value={editNoteText}
                            onChange={(e) => setEditNoteText(e.target.value)}
                            rows={3}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none resize-none"
                          />
                          <div className="flex gap-2 justify-end">
                            <button
                              onClick={() => { setEditingNote(null); setEditNoteText('') }}
                              className="px-3 py-1.5 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 text-sm transition-colors"
                            >
                              Cancel
                            </button>
                            <button
                              onClick={() => handleUpdateNote(note.id)}
                              className="px-3 py-1.5 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm transition-colors"
                            >
                              Save
                            </button>
                          </div>
                        </div>
                      ) : (
                        <div>
                          <p className="text-gray-800 whitespace-pre-wrap">{note.note}</p>
                          <div className="flex items-center justify-between mt-3 pt-3 border-t border-gray-100">
                            <div className="text-xs text-gray-500">
                              <span className="font-medium">{note.created_by || 'Unknown'}</span>
                              {' · '}
                              {formatDateTime(note.created_date)}
                              {note.updated_date !== note.created_date && ' (edited)'}
                            </div>
                            <div className="flex gap-2">
                              <button
                                onClick={() => { setEditingNote(note.id); setEditNoteText(note.note) }}
                                className="text-indigo-600 hover:text-indigo-900 text-xs font-medium"
                              >
                                Edit
                              </button>
                              <button
                                onClick={() => handleDeleteNote(note.id)}
                                className="text-red-600 hover:text-red-900 text-xs font-medium"
                              >
                                Delete
                              </button>
                            </div>
                          </div>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* ==================== ACTIVITY LOG TAB ==================== */}
          {activeTab === 'activity' && (
            <div className="space-y-3">
              <p className="text-sm text-gray-500 mb-4">Timeline of all activity for this customer</p>
              {[
                ...tickets.map(t => ({
                  type: 'ticket',
                  date: t.created_date,
                  icon: '🎫',
                  color: 'bg-blue-100',
                  title: 'RMA Ticket Created',
                  detail: `${t.rma_number || t.id?.slice(0, 8)} — ${t.issue_description || t.title || 'No description'}`,
                  action: () => onNavigateToTicket(t.id)
                })),
                ...notes.map(n => ({
                  type: 'note',
                  date: n.created_date,
                  icon: '📝',
                  color: 'bg-yellow-100',
                  title: 'Note Added',
                  detail: n.note.length > 80 ? n.note.slice(0, 80) + '...' : n.note,
                  by: n.created_by
                })),
                {
                  type: 'created',
                  date: customer.created_date,
                  icon: '✅',
                  color: 'bg-green-100',
                  title: 'Customer Created',
                  detail: `Added by ${customer.created_by || 'Unknown'}`
                }
              ]
                .filter(e => e.date)
                .sort((a, b) => new Date(b.date) - new Date(a.date))
                .map((event, idx) => (
                  <div key={idx} className="flex gap-4 items-start">
                    <div className={`w-10 h-10 rounded-full ${event.color} flex items-center justify-center flex-shrink-0 text-lg`}>
                      {event.icon}
                    </div>
                    <div className="flex-1 pb-4 border-b border-gray-100 last:border-0">
                      <div className="flex items-center justify-between">
                        <p className="font-medium text-gray-900">{event.title}</p>
                        <span className="text-xs text-gray-500">{formatDateTime(event.date)}</span>
                      </div>
                      <p className="text-sm text-gray-600 mt-1">{event.detail}</p>
                      {event.action && (
                        <button onClick={event.action} className="text-xs text-indigo-600 hover:underline mt-1">
                          View ticket →
                        </button>
                      )}
                    </div>
                  </div>
                ))
              }
              {tickets.length === 0 && notes.length === 0 && (
                <div className="text-center py-8 text-gray-500">
                  <div className="text-3xl mb-2">📋</div>
                  <p>No activity yet for this customer</p>
                </div>
              )}
            </div>
          )}

        </div>
      </div>

      <ConfirmDialog
        open={confirmDialog.open}
        title={confirmDialog.title}
        message={confirmDialog.message}
        onConfirm={confirmDialog.onConfirm}
        onCancel={closeConfirm}
      />
    </div>
  )
}

function DetailRow({ icon, label, value }) {
  return (
    <div className="flex items-start gap-3">
      <span className="text-lg flex-shrink-0">{icon}</span>
      <div>
        <p className="text-xs font-medium text-gray-500">{label}</p>
        <div className="text-sm text-gray-900">{value || <span className="text-gray-400">—</span>}</div>
      </div>
    </div>
  )
}

