import React, { useState, useEffect, useRef } from 'react'
import { supabase, db, storage } from '../api/supabaseClient'
import toast from 'react-hot-toast'
import ConfirmDialog from '../components/ConfirmDialog'
import { PageSkeleton } from '../components/Skeleton'
import AttachmentsField from '../components/AttachmentsField'
import { Button, Spinner, PageHeader } from '../components/ui'

const EMPTY_FORM = {
  customer_type: 'B2B',
  customer_status: 'Active',
  company_name: '',
  contact_person: '',
  account_manager: '',
  mobile: '',
  landline: '',
  email: '',
  address: '',
  cr_number: '',
  tax_id: '',
  notes: '',
  attachments: [],
}

const generateCustomerCode = () => `CB-${Math.floor(10000000 + Math.random() * 90000000)}`

export default function Customers({ currentUserRole, currentUserEmail, currentUserPermissions, onNavigateToCustomer }) {
  const searchRef = useRef(null)
  const [customers, setCustomers] = useState([])
  const [filteredCustomers, setFilteredCustomers] = useState([])
  const [customersTotalCount, setCustomersTotalCount] = useState(null)
  const [loading, setLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedCustomers, setSelectedCustomers] = useState([])
  const [showAddCustomer, setShowAddCustomer] = useState(false)
  const [editingCustomer, setEditingCustomer] = useState(null)
  const [openMenuId, setOpenMenuId] = useState(null)
  const [filterStatus, setFilterStatus] = useState('')
  const [filterType, setFilterType] = useState('')
  const [filterCompany, setFilterCompany] = useState('')
  const [showFilters, setShowFilters] = useState(false)
  const [usersList, setUsersList] = useState([])
  const [customerForm, setCustomerForm] = useState(EMPTY_FORM)
  const [pendingFiles, setPendingFiles] = useState([])
  const [showBulkUpload, setShowBulkUpload] = useState(false)
  const [showAddDropdown, setShowAddDropdown] = useState(false)

  // Pagination
  const [currentPage, setCurrentPage] = useState(1)
  const [itemsPerPage, setItemsPerPage] = useState(() => parseInt(localStorage.getItem('customersPerPage')) || 25)
  const [jumpToPage, setJumpToPage] = useState('')

  // Sorting
  const [sortConfig, setSortConfig] = useState(() => {
    try {
      const saved = localStorage.getItem('customersSortConfig')
      return saved ? JSON.parse(saved) : { key: 'created_date', direction: 'desc' }
    } catch {
      return { key: 'created_date', direction: 'desc' }
    }
  })

  const [confirmDialog, setConfirmDialog] = useState({ open: false, title: '', message: '', onConfirm: null })
  const openConfirm = (title, message, onConfirm) => setConfirmDialog({ open: true, title, message, onConfirm })
  const closeConfirm = () => setConfirmDialog(d => ({ ...d, open: false }))

  const canDo = (action) => {
    if (currentUserRole === 'super_admin' || currentUserRole === 'admin') return true
    return currentUserPermissions?.customers?.[action] === true
  }

  useEffect(() => { loadAll() }, [])
  useEffect(() => {
    const handler = (e) => { if (!e.target.closest('.action-menu')) setOpenMenuId(null) }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])
  useEffect(() => { handleSearchAndSort() }, [searchQuery, customers, sortConfig, filterStatus, filterType, filterCompany])
  useEffect(() => { localStorage.setItem('customersPerPage', itemsPerPage.toString()) }, [itemsPerPage])
  useEffect(() => { localStorage.setItem('customersSortConfig', JSON.stringify(sortConfig)) }, [sortConfig])
  useEffect(() => { setCurrentPage(1) }, [searchQuery, itemsPerPage, filterStatus, filterType, filterCompany])

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (showAddDropdown && !e.target.closest('.add-customer-dropdown')) setShowAddDropdown(false)
    }
    document.addEventListener('click', handleClickOutside)
    return () => document.removeEventListener('click', handleClickOutside)
  }, [showAddDropdown])

  // Real-time: refresh when customers table changes
  useEffect(() => {
    const channel = supabase.channel('customers_realtime')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'customers' }, () => loadAll())
      .subscribe()
    return () => { supabase.removeChannel(channel) }
  }, [])

  // Keyboard shortcuts: / = focus search, N = add customer, Esc = close modal
  useEffect(() => {
    const handler = (e) => {
      const tag = e.target.tagName
      const typing = tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || e.target.isContentEditable
      if (e.key === 'Escape') { setShowAddCustomer(false); setEditingCustomer(null); return }
      if (typing) return
      if (e.key === '/') { e.preventDefault(); searchRef.current?.focus() }
      if (e.key === 'n' || e.key === 'N') { e.preventDefault(); if (canDo('create')) setShowAddCustomer(true) }
    }
    document.addEventListener('keydown', handler)
    return () => document.removeEventListener('keydown', handler)
  }, [showAddCustomer])

  const loadAll = async () => {
    setLoading(true)
    try {
      const [customersData, usersData] = await Promise.all([
        db.customers.list(),
        db.userRoles.listAllRoles()
      ])
      db.customers.listPaged(0, 1).then(r => setCustomersTotalCount(r.count)).catch(() => {})
      setCustomers(customersData)
      setUsersList(usersData)
    } catch (error) {
      toast.error('Failed to load customers')
    } finally {
      setLoading(false)
    }
  }

  const handleSearchAndSort = () => {
    let filtered = [...customers]
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase()
      filtered = filtered.filter(c =>
        c.contact_person?.toLowerCase().includes(q) ||
        c.company_name?.toLowerCase().includes(q) ||
        c.email?.toLowerCase().includes(q) ||
        c.mobile?.toLowerCase().includes(q) ||
        c.customer_code?.toLowerCase().includes(q) ||
        c.landline?.toLowerCase().includes(q)
      )
    }
    if (filterStatus)  filtered = filtered.filter(c => c.customer_status === filterStatus)
    if (filterType)    filtered = filtered.filter(c => c.customer_type === filterType)
    if (filterCompany) {
      const q = filterCompany.toLowerCase()
      filtered = filtered.filter(c => c.company_name?.toLowerCase().includes(q) || c.contact_person?.toLowerCase().includes(q))
    }

    filtered.sort((a, b) => {
      let av = '', bv = ''
      if (sortConfig.key === 'contact_person') { av = a.contact_person || ''; bv = b.contact_person || '' }
      else if (sortConfig.key === 'company_name') { av = a.company_name || ''; bv = b.company_name || '' }
      else if (sortConfig.key === 'created_date') { av = new Date(a.created_date || 0).getTime(); bv = new Date(b.created_date || 0).getTime() }
      else { av = a[sortConfig.key] || ''; bv = b[sortConfig.key] || '' }
      if (typeof av === 'string') { av = av.toLowerCase(); bv = bv.toLowerCase() }
      if (av < bv) return sortConfig.direction === 'asc' ? -1 : 1
      if (av > bv) return sortConfig.direction === 'asc' ? 1 : -1
      return 0
    })
    setFilteredCustomers(filtered)
  }

  const handleSort = (key) => setSortConfig(prev => ({ key, direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc' }))

  const totalPages = Math.ceil(filteredCustomers.length / itemsPerPage)
  const startIndex = (currentPage - 1) * itemsPerPage
  const endIndex = Math.min(startIndex + itemsPerPage, filteredCustomers.length)
  const paginatedCustomers = filteredCustomers.slice(startIndex, endIndex)

  const handlePageChange = (page) => {
    if (page >= 1 && page <= totalPages) { setCurrentPage(page); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  }

  const handleJumpToPage = () => {
    const pageNum = parseInt(jumpToPage)
    if (pageNum >= 1 && pageNum <= totalPages) { handlePageChange(pageNum); setJumpToPage('') }
    else toast.error(`Page must be between 1 and ${totalPages}`)
  }

  const handleSelectCustomer = (id) => setSelectedCustomers(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id])
  const handleSelectAll = () => setSelectedCustomers(selectedCustomers.length === paginatedCustomers.length ? [] : paginatedCustomers.map(c => c.id))

  const handleBulkDelete = () => {
    openConfirm(
      'Delete Customers',
      `Delete ${selectedCustomers.length} selected customer${selectedCustomers.length !== 1 ? 's' : ''}? This cannot be undone.`,
      async () => {
        closeConfirm()
        try {
          await db.customers.bulkDelete(selectedCustomers)
          toast.success(`Deleted ${selectedCustomers.length} customers`)
          db.auditLog.log(currentUserEmail, 'customer_bulk_deleted', `Deleted ${selectedCustomers.length} customers`).catch(() => {})
          setSelectedCustomers([])
          loadAll()
        } catch { toast.error('Failed to delete customers') }
      }
    )
  }

  const handleBulkStatusChange = async (status) => {
    try {
      await db.customers.bulkUpdateStatus(selectedCustomers, status)
      toast.success(`Updated ${selectedCustomers.length} customers`)
      db.auditLog.log(currentUserEmail, 'customer_bulk_status_changed', `Changed status to "${status}" for ${selectedCustomers.length} customers`).catch(() => {})
      setSelectedCustomers([])
      loadAll()
    } catch { toast.error('Failed to update status') }
  }

  const handleSaveCustomer = async () => {
    if (!customerForm.contact_person.trim()) { toast.error('Contact person is required'); return }
    if (!customerForm.mobile.trim()) { toast.error('Mobile number is required'); return }
    if (customerForm.customer_type === 'B2B' && !customerForm.company_name.trim()) {
      toast.error('Company name is required for B2B customers'); return
    }

    // Upload pending files
    const uploadedAttachments = []
    if (pendingFiles.length > 0) {
      const folderId = editingCustomer?.id?.toString() || `new_${Date.now()}`
      for (const file of pendingFiles) {
        try {
          const result = await storage.uploadCustomerAttachment(file, folderId)
          uploadedAttachments.push(result)
        } catch (err) {
          toast.error(`Failed to upload ${file.name}: ${err.message}`)
          return
        }
      }
    }
    const allAttachments = [...(customerForm.attachments || []), ...uploadedAttachments]

    const payload = {
      customer_type:   customerForm.customer_type,
      customer_status: customerForm.customer_status,
      company_name:    customerForm.company_name || null,
      contact_person:  customerForm.contact_person,
      account_manager: customerForm.account_manager || null,
      mobile:          customerForm.mobile,
      landline:        customerForm.landline || null,
      email:           customerForm.email || null,
      address:         customerForm.address || null,
      cr_number:       customerForm.cr_number || null,
      tax_id:          customerForm.tax_id || null,
      notes:           customerForm.notes || null,
      attachments:     allAttachments,
      updated_by:      currentUserEmail,
      updated_date:    new Date().toISOString(),
    }

    try {
      if (editingCustomer) {
        await db.customers.update(editingCustomer.id, payload)
        db.userActivity.create(currentUserEmail, 'customer_updated', `Updated customer ${payload.contact_person}${payload.company_name ? ` (${payload.company_name})` : ''}`).catch(() => {})
        db.notifications.create({
          type: 'customer_updated', title: 'Customer Updated',
          message: `${payload.contact_person}${payload.company_name ? ` (${payload.company_name})` : ''} was updated`,
          entityType: 'customer', entityId: editingCustomer.id,
          createdBy: currentUserEmail, targetRoles: ['admin', 'super_admin'], targetEmails: []
        }).catch(() => {})
        toast.success('Customer updated')
        db.auditLog.log(currentUserEmail, 'customer_updated', `Updated customer ${payload.contact_person}${payload.company_name ? ` (${payload.company_name})` : ''}`).catch(() => {})
      } else {
        const newCustomer = await db.customers.create({
          ...payload,
          customer_code: generateCustomerCode(),
          created_by:    currentUserEmail,
          created_date:  new Date().toISOString(),
        })
        db.userActivity.create(currentUserEmail, 'customer_created', `Created customer ${payload.contact_person}${payload.company_name ? ` (${payload.company_name})` : ''}`).catch(() => {})
        db.notifications.create({
          type: 'customer_created', title: 'New Customer Added',
          message: `${payload.contact_person}${payload.company_name ? ` (${payload.company_name})` : ''} was added as a ${payload.customer_type} customer`,
          entityType: 'customer', entityId: newCustomer?.id,
          createdBy: currentUserEmail, targetRoles: ['admin', 'super_admin'], targetEmails: []
        }).catch(() => {})
        toast.success('Customer created')
        db.auditLog.log(currentUserEmail, 'customer_created', `Created customer ${payload.contact_person}${payload.company_name ? ` (${payload.company_name})` : ''}`).catch(() => {})
      }
      setShowAddCustomer(false)
      resetForm()
      loadAll()
    } catch (error) {
      toast.error(`Failed to save: ${error.message}`)
    }
  }

  const handleEditCustomer = (customer) => {
    setEditingCustomer(customer)
    setCustomerForm({
      customer_type:   customer.customer_type   || 'B2B',
      customer_status: customer.customer_status || 'Active',
      company_name:    customer.company_name    || '',
      contact_person:  customer.contact_person  || '',
      account_manager: customer.account_manager || '',
      mobile:          customer.mobile          || '',
      landline:        customer.landline         || '',
      email:           customer.email           || '',
      address:         customer.address         || '',
      cr_number:       customer.cr_number       || '',
      tax_id:          customer.tax_id          || '',
      notes:           customer.notes           || '',
      attachments:     customer.attachments     || [],
    })
    setPendingFiles([])
    setShowAddCustomer(true)
  }

  const handleDeleteCustomer = (customer) => {
    openConfirm(
      'Delete Customer',
      `Delete ${customer.contact_person}? This action cannot be undone.`,
      async () => {
        closeConfirm()
        try {
          await db.customers.delete(customer.id)
          db.userActivity.create(currentUserEmail, 'customer_deleted', `Deleted customer ${customer.contact_person}${customer.company_name ? ` (${customer.company_name})` : ''}`).catch(() => {})
          db.notifications.create({
            type: 'customer_deleted', title: 'Customer Deleted',
            message: `${customer.contact_person}${customer.company_name ? ` (${customer.company_name})` : ''} was removed`,
            entityType: 'customer', entityId: customer.id,
            createdBy: currentUserEmail, targetRoles: ['admin', 'super_admin'], targetEmails: []
          }).catch(() => {})
          toast.success('Customer deleted')
          db.auditLog.log(currentUserEmail, 'customer_deleted', `Deleted customer ${customer.contact_person}${customer.company_name ? ` (${customer.company_name})` : ''}`).catch(() => {})
          loadAll()
        } catch { toast.error('Failed to delete customer') }
      }
    )
  }

  const resetForm = () => { setCustomerForm(EMPTY_FORM); setEditingCustomer(null); setPendingFiles([]) }

  const handleExportCSV = () => {
    const csv = [
      ['Code', 'Type', 'Status', 'Company', 'Contact Person', 'Mobile', 'Landline', 'Email', 'Address', 'Account Manager', 'Created'].join(','),
      ...filteredCustomers.map(c => [
        c.customer_code || '', c.customer_type || '', c.customer_status || '',
        c.company_name || '', c.contact_person || '', c.mobile || '',
        c.landline || '', c.email || '', `"${(c.address || '').replace(/"/g, '""')}"`,
        c.account_manager || '', c.created_date ? new Date(c.created_date).toLocaleDateString() : ''
      ].join(','))
    ].join('\n')
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url; a.download = `customers-${new Date().toISOString().split('T')[0]}.csv`
    document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url)
    toast.success(`Exported ${filteredCustomers.length} customers`)
    db.auditLog.log(currentUserEmail, 'customers_exported', `Exported ${filteredCustomers.length} customers to CSV`).catch(() => {})
  }

  const handleDownloadTemplate = () => {
    const csv = [
      ['customer_type', 'customer_status', 'company_name', 'contact_person', 'account_manager', 'mobile', 'landline', 'email', 'address', 'cr_number', 'tax_id', 'notes'].join(','),
      ['B2B', 'Active', 'Maximum Hardware', 'Hany Tolba', '', '01000121589', '0223456789', 'hany@maximum.com', '5 Nasr St Cairo', 'CR-12345', 'TAX-67890', ''].join(','),
      ['B2C', 'Active', '', 'Ahmed Saeed', '', '01012345678', '', 'ahmed@gmail.com', '', '', '', ''].join(','),
    ].join('\n')
    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url; a.download = 'customers-template.csv'
    document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url)
    toast.success('Template downloaded')
  }

  const parseCSVLine = (line) => {
    const result = []
    let current = ''
    let inQuotes = false
    for (let i = 0; i < line.length; i++) {
      const char = line[i]
      if (char === '"') {
        if (inQuotes && line[i + 1] === '"') { current += '"'; i++ }
        else { inQuotes = !inQuotes }
      } else if (char === ',' && !inQuotes) {
        result.push(current.trim())
        current = ''
      } else {
        current += char
      }
    }
    result.push(current.trim())
    return result
  }

  const handleBulkUploadCustomers = async (file) => {
    try {
      const text = (await file.text()).replace(/^﻿/, '')
      const lines = text.split('\n').filter(line => line.trim())
      if (lines.length < 2) { toast.error('CSV file is empty or invalid'); return }

      const headers = parseCSVLine(lines[0]).map(h => h.toLowerCase())
      const requiredColumns = ['company_name', 'contact_person']
      const missing = requiredColumns.filter(f => !headers.includes(f))
      if (missing.length > 0) { toast.error(`Missing required columns: ${missing.join(', ')}`); return }

      const existingMobiles = new Set(customers.map(c => c.mobile?.trim().toLowerCase()).filter(Boolean))
      const existingCompanies = new Set(customers.map(c => c.company_name?.trim().toLowerCase()).filter(Boolean))
      const existingContacts = new Set(customers.map(c => c.contact_person?.trim().toLowerCase()).filter(Boolean))

      const toImport = []
      const errors = []
      let skippedCount = 0

      for (let i = 1; i < lines.length; i++) {
        const values = parseCSVLine(lines[i])
        const row = {}
        headers.forEach((h, idx) => { row[h] = values[idx] || '' })

        const type = ['B2B', 'B2C'].includes((row.customer_type || '').toUpperCase())
          ? row.customer_type.toUpperCase() : 'B2C'

        if (type === 'B2B' && !row.company_name) {
          errors.push(`Row ${i + 1}: company_name is required for B2B`)
          continue
        }
        if (type === 'B2C' && !row.contact_person) {
          errors.push(`Row ${i + 1}: contact_person is required for B2C`)
          continue
        }

        const mobile = row.mobile?.trim().toLowerCase()
        const company = row.company_name?.trim().toLowerCase()
        const contact = row.contact_person?.trim().toLowerCase()

        if (mobile && existingMobiles.has(mobile)) { skippedCount++; continue }
        if (!mobile && type === 'B2B' && company && existingCompanies.has(company)) { skippedCount++; continue }
        if (!mobile && type === 'B2C' && contact && existingContacts.has(contact)) { skippedCount++; continue }

        const status = ['Active', 'Inactive'].includes(row.customer_status) ? row.customer_status : 'Active'
        toImport.push({
          customer_type:   type,
          customer_status: status,
          company_name:    row.company_name    || null,
          contact_person:  row.contact_person  || null,
          account_manager: row.account_manager || null,
          mobile:          row.mobile          || null,
          landline:        row.landline         || null,
          email:           row.email            || null,
          address:         row.address          || null,
          cr_number:       row.cr_number        || null,
          tax_id:          row.tax_id           || null,
          notes:           row.notes            || null,
          customer_code:   generateCustomerCode(),
          created_by:      currentUserEmail,
          updated_by:      currentUserEmail,
          created_date:    new Date().toISOString(),
          updated_date:    new Date().toISOString(),
        })
      }

      if (toImport.length === 0) {
        if (skippedCount > 0) {
          toast.error(`All ${skippedCount} customer${skippedCount !== 1 ? 's' : ''} already exist in the system — nothing to import.`)
        } else {
          toast.error('No valid customers to import')
          if (errors.length > 0) console.error('Import errors:', errors)
        }
        return
      }

      await db.customers.bulkCreate(toImport)
      if (skippedCount > 0) {
        toast.success(`Imported ${toImport.length} new customer${toImport.length !== 1 ? 's' : ''}. Skipped ${skippedCount} duplicate${skippedCount !== 1 ? 's' : ''}.`)
      } else {
        toast.success(`Successfully imported ${toImport.length} customer${toImport.length !== 1 ? 's' : ''}`)
      }
      db.auditLog.log(currentUserEmail, 'customers_imported', `Imported ${toImport.length} customers from CSV${skippedCount ? `, skipped ${skippedCount} duplicates` : ''}`).catch(() => {})
      if (errors.length > 0) {
        toast.error(`${errors.length} rows had errors — check console`)
        console.error('Import errors:', errors)
      }
      setShowBulkUpload(false)
      loadAll()
    } catch (error) {
      toast.error(`Failed to import: ${error.message}`)
    }
  }

  const getStatusBadge = (status) => {
    const map = {
      Active:   'bg-green-100 text-green-800',
      Inactive: 'bg-gray-100 text-gray-600',
      Suspended:'bg-red-100 text-red-700',
      VIP:      'bg-purple-100 text-purple-800',
    }
    return (
      <span className={`px-2 py-0.5 text-xs rounded-full font-medium ${map[status] || 'bg-gray-100 text-gray-600'}`}>
        {status || '—'}
      </span>
    )
  }

  const SortIcon = ({ col }) => {
    if (sortConfig.key !== col) return <svg className="w-3.5 h-3.5 text-gray-300 ml-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16V4m0 0L3 8m4-4l4 4m6 0v12m0 0l4-4m-4 4l-4-4" /></svg>
    return sortConfig.direction === 'asc'
      ? <svg className="w-3.5 h-3.5 text-indigo-600 ml-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" /></svg>
      : <svg className="w-3.5 h-3.5 text-indigo-600 ml-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
  }

  const Th = ({ label, col }) => (
    <button onClick={() => handleSort(col)} className="flex items-center text-xs font-semibold text-gray-500 uppercase hover:text-gray-800">
      {label}<SortIcon col={col} />
    </button>
  )

  const renderPageNumbers = () => {
    const pages = []
    if (totalPages <= 7) { for (let i = 1; i <= totalPages; i++) pages.push(i) }
    else if (currentPage <= 4) { for (let i = 1; i <= 5; i++) pages.push(i); pages.push('...'); pages.push(totalPages) }
    else if (currentPage >= totalPages - 3) { pages.push(1); pages.push('...'); for (let i = totalPages - 4; i <= totalPages; i++) pages.push(i) }
    else { pages.push(1); pages.push('...'); for (let i = currentPage - 1; i <= currentPage + 1; i++) pages.push(i); pages.push('...'); pages.push(totalPages) }
    return pages.map((p, i) => p === '...' ? <span key={`e${i}`} className="px-2 text-gray-400">…</span> : (
      <button key={p} onClick={() => handlePageChange(p)} className={`w-8 h-8 rounded text-sm ${currentPage === p ? 'bg-indigo-600 text-white' : 'text-gray-600 hover:bg-gray-100'}`}>{p}</button>
    ))
  }

  if (loading) return <PageSkeleton cols={7} />

  return (
    <div className="space-y-6">
      {/* Header */}
      <PageHeader title="Customers" subtitle="Manage B2B and B2C customer records" />


      {/* Table Card */}
      <div className="bg-white rounded-xl border border-gray-200 shadow-sm">
        <div className="p-5 space-y-4">

          {/* Toolbar */}
          <div className="flex items-center justify-between gap-4 flex-wrap">
            <div className="flex items-center gap-3 flex-1">
              <div className="relative flex-1 max-w-md">
                <input ref={searchRef} type="text" value={searchQuery} onChange={e => setSearchQuery(e.target.value)}
                  placeholder="Search name, company, mobile, code... (Press / to focus)"
                  className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none"
                />
                <svg className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              </div>
              <button onClick={() => setShowFilters(!showFilters)}
                className={`flex items-center gap-2 px-4 py-2 border rounded-lg text-sm transition-colors ${showFilters || filterStatus || filterType || filterCompany ? 'border-indigo-500 text-indigo-600 bg-indigo-50' : 'border-gray-300 text-gray-700 hover:bg-gray-50'}`}
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2a1 1 0 01-.293.707L13 13.414V19a1 1 0 01-.553.894l-4 2A1 1 0 017 21v-7.586L3.293 6.707A1 1 0 013 6V4z" />
                </svg>
                Filters
                {(filterStatus || filterType || filterCompany) && <span className="w-4 h-4 bg-indigo-600 text-white text-xs rounded-full flex items-center justify-center">{[filterStatus, filterType, filterCompany].filter(Boolean).length}</span>}
              </button>
            </div>

            <div className="flex items-center gap-2 flex-wrap">
              {selectedCustomers.length > 0 && canDo('delete') && (
                <>
                  <button onClick={handleBulkDelete} className="flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-lg text-sm hover:bg-red-700">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                    Delete ({selectedCustomers.length})
                  </button>
                  <select onChange={e => { if (e.target.value) { handleBulkStatusChange(e.target.value); e.target.value = '' } }} defaultValue=""
                    className="px-4 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600">
                    <option value="">Change Status…</option>
                    <option value="Active">Active</option>
                    <option value="Inactive">Inactive</option>
                    <option value="Suspended">Suspended</option>
                  </select>
                </>
              )}
              {canDo('export') && (
                <button onClick={handleExportCSV} className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 flex items-center gap-2 text-sm">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                  </svg>
                  Export
                </button>
              )}
              {canDo('create') && (
                <div className="relative add-customer-dropdown">
                  <button
                    onClick={(e) => { e.stopPropagation(); setShowAddDropdown(!showAddDropdown) }}
                    className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 flex items-center gap-2 text-sm"
                  >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
                    </svg>
                    Add Customer
                    <svg className={`w-4 h-4 transition-transform ${showAddDropdown ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                    </svg>
                  </button>
                  {showAddDropdown && (
                    <div className="absolute right-0 mt-2 w-56 bg-white rounded-lg shadow-lg border border-gray-200 z-20">
                      <button
                        onClick={() => { resetForm(); setShowAddCustomer(true); setShowAddDropdown(false) }}
                        className="w-full px-4 py-3 text-left hover:bg-gray-50 flex items-center gap-3 border-b border-gray-100 rounded-t-lg"
                      >
                        <svg className="w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
                        </svg>
                        <div>
                          <div className="font-medium text-gray-900">Add Single Customer</div>
                          <div className="text-xs text-gray-500">Create one customer</div>
                        </div>
                      </button>
                      {canDo('import') && (
                        <button
                          onClick={() => { setShowBulkUpload(true); setShowAddDropdown(false) }}
                          className="w-full px-4 py-3 text-left hover:bg-gray-50 flex items-center gap-3 rounded-b-lg"
                        >
                          <svg className="w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                          </svg>
                          <div>
                            <div className="font-medium text-gray-900">Bulk Add / Upload</div>
                            <div className="text-xs text-gray-500">Upload CSV file</div>
                          </div>
                        </button>
                      )}
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>

          {/* Filters */}
          {showFilters && (
            <div className="flex items-center gap-4 p-4 bg-gray-50 rounded-lg flex-wrap">
              <div className="flex items-center gap-2">
                <label className="text-sm font-medium text-gray-700">Status:</label>
                <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className="px-3 py-1.5 border border-gray-300 rounded-lg text-sm">
                  <option value="">All</option>
                  <option value="Active">Active</option>
                  <option value="Inactive">Inactive</option>
                  <option value="Suspended">Suspended</option>
                </select>
              </div>
              <div className="flex items-center gap-2">
                <label className="text-sm font-medium text-gray-700">Type:</label>
                <select value={filterType} onChange={e => setFilterType(e.target.value)} className="px-3 py-1.5 border border-gray-300 rounded-lg text-sm">
                  <option value="">All</option>
                  <option value="B2B">B2B</option>
                  <option value="B2C">B2C</option>
                </select>
              </div>
              <div className="flex items-center gap-2">
                <label className="text-sm font-medium text-gray-700">Company / Contact:</label>
                <input
                  type="text"
                  value={filterCompany}
                  onChange={e => setFilterCompany(e.target.value)}
                  placeholder="Type to filter…"
                  className="px-3 py-1.5 border border-gray-300 rounded-lg text-sm w-44 focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
                />
              </div>
              {(filterStatus || filterType || filterCompany) && (
                <button onClick={() => { setFilterStatus(''); setFilterType(''); setFilterCompany('') }} className="text-sm text-red-600 hover:underline">Clear</button>
              )}
            </div>
          )}

          {/* Cap warning banner (H-4) */}
          {customersTotalCount !== null && customersTotalCount > customers.length && (
            <div className="mb-2 px-3 py-2 bg-amber-50 border border-amber-200 rounded-lg text-amber-800 text-sm flex items-center gap-2">
              <span>⚠️</span>
              <span>Showing first <strong>{customers.length}</strong> of <strong>{customersTotalCount}</strong> customers. Use filters or search to find specific records.</span>
            </div>
          )}

          {/* Count + per-page */}
          <div className="flex items-center justify-between text-sm text-gray-600">
            <span>Showing {filteredCustomers.length === 0 ? 0 : startIndex + 1}–{endIndex} of {filteredCustomers.length} customers</span>
            <div className="flex items-center gap-2">
              <label className="text-sm text-gray-600">Items per page:</label>
              <select value={itemsPerPage} onChange={e => setItemsPerPage(parseInt(e.target.value))} className="px-3 py-1 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600">
                <option value={10}>10</option><option value={25}>25</option><option value={50}>50</option><option value={100}>100</option>
              </select>
            </div>
          </div>

          {/* Table */}
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-50 border-y border-gray-200">
                <tr>
                  <th className="px-4 py-3 text-left w-10">
                    <input type="checkbox" checked={paginatedCustomers.length > 0 && selectedCustomers.length === paginatedCustomers.length} onChange={handleSelectAll} className="w-4 h-4 text-indigo-600 rounded" />
                  </th>
                  <th className="px-3 py-3 text-left text-xs font-medium text-gray-400 uppercase w-10">#</th>
                  <th className="px-4 py-3 text-left"><Th label="Code" col="customer_code" /></th>
                  <th className="px-4 py-3 text-left"><Th label="Contact / Company" col="contact_person" /></th>
                  <th className="px-4 py-3 text-left"><Th label="Type" col="customer_type" /></th>
                  <th className="px-4 py-3 text-left"><Th label="Mobile" col="mobile" /></th>
                  <th className="px-4 py-3 text-left"><Th label="Email" col="email" /></th>
                  <th className="px-4 py-3 text-left"><Th label="Status" col="customer_status" /></th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {paginatedCustomers.length === 0 ? (
                  <tr><td colSpan="9" className="px-4 py-20 text-center">
                    <div className="flex flex-col items-center gap-3">
                      <div className="w-14 h-14 bg-gray-100 rounded-2xl flex items-center justify-center">
                        <svg className="w-7 h-7 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                      </div>
                      <div>
                        <p className="font-semibold text-gray-700">No customers found</p>
                        <p className="text-sm text-gray-400 mt-0.5">
                          {customers.length > 0 ? 'Try adjusting your filters or search term' : 'Add your first customer to get started'}
                        </p>
                      </div>
                      {canDo('create') && customers.length === 0 && (
                        <button onClick={() => setShowAddCustomer(true)} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm font-medium hover:bg-indigo-700 transition-colors">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                          Add First Customer
                        </button>
                      )}
                    </div>
                  </td></tr>
                ) : paginatedCustomers.map((c, idx) => (
                  <tr key={c.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-4 py-3">
                      <input type="checkbox" checked={selectedCustomers.includes(c.id)} onChange={() => handleSelectCustomer(c.id)} className="w-4 h-4 text-indigo-600 rounded" />
                    </td>
                    <td className="px-3 py-3 text-xs text-gray-400 tabular-nums">{(currentPage - 1) * itemsPerPage + idx + 1}</td>
                    <td className="px-4 py-3">
                      <span className="text-xs font-mono text-gray-500">{c.customer_code || '—'}</span>
                    </td>
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center flex-shrink-0">
                          <span className="text-indigo-600 font-semibold text-xs">
                            {(c.contact_person || c.company_name || '?')[0].toUpperCase()}
                          </span>
                        </div>
                        <div>
                          <button onClick={() => onNavigateToCustomer(c.id)} className="font-medium text-gray-900 hover:text-indigo-600 text-sm text-left">
                            {c.contact_person || '—'}
                          </button>
                          {c.company_name && <div className="text-xs text-gray-400">{c.company_name}</div>}
                        </div>
                      </div>
                    </td>
                    <td className="px-4 py-3">
                      <span className={`px-2 py-0.5 text-xs rounded font-medium ${c.customer_type === 'B2B' ? 'bg-blue-100 text-blue-700' : 'bg-emerald-100 text-emerald-700'}`}>
                        {c.customer_type}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-sm text-gray-600">{c.mobile || '—'}</td>
                    <td className="px-4 py-3 text-sm">
                      {c.email ? <a href={`mailto:${c.email}`} className="text-indigo-600 hover:underline">{c.email}</a> : <span className="text-gray-400">—</span>}
                    </td>
                    <td className="px-4 py-3">{getStatusBadge(c.customer_status)}</td>
                    <td className="px-4 py-3 relative action-menu">
                      <button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === c.id ? null : c.id) }}
                        className="p-1.5 rounded-lg text-gray-400 hover:text-gray-700 hover:bg-gray-100 transition-colors">
                        <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><circle cx="12" cy="5" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="12" cy="19" r="1.5"/></svg>
                      </button>
                      {openMenuId === c.id && (
                        <div className="absolute right-0 top-9 z-30 w-44 bg-white rounded-xl shadow-lg border border-gray-200 py-1 overflow-hidden">
                          <button onClick={() => { onNavigateToCustomer(c.id); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2.5">
                            <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
                            View
                          </button>
                            {canDo('edit') && (
                            <button onClick={() => { handleEditCustomer(c); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2.5">
                              <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                              Edit
                            </button>
                          )}
                          {canDo('delete') && (
                            <button onClick={() => { handleDeleteCustomer(c); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50 flex items-center gap-2.5">
                              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                              Delete
                            </button>
                          )}
                        </div>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between pt-4 border-t border-gray-200">
              <div className="flex items-center gap-2">
                <button onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1} className="px-3 py-2 border border-gray-300 rounded text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed text-sm">Previous</button>
                <div className="flex items-center gap-1">{renderPageNumbers()}</div>
                <button onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages} className="px-3 py-2 border border-gray-300 rounded text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed text-sm">Next</button>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-sm text-gray-600">Jump to page:</span>
                <input
                  type="number" min="1" max={totalPages}
                  value={jumpToPage} onChange={e => setJumpToPage(e.target.value)}
                  onKeyDown={e => e.key === 'Enter' && handleJumpToPage()}
                  placeholder={currentPage.toString()}
                  className="w-20 px-3 py-1 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600"
                />
                <button onClick={handleJumpToPage} className="px-3 py-1 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm">Go</button>
              </div>
            </div>
          )}
        </div>
      </div>

      {showAddCustomer && (
        <AddCustomerModal
          form={customerForm}
          setForm={setCustomerForm}
          editing={editingCustomer}
          usersList={usersList}
          pendingFiles={pendingFiles}
          setPendingFiles={setPendingFiles}
          onSave={handleSaveCustomer}
          onClose={() => { setShowAddCustomer(false); resetForm() }}
        />
      )}

      {showBulkUpload && (
        <BulkUploadCustomersModal
          onClose={() => setShowBulkUpload(false)}
          onUpload={handleBulkUploadCustomers}
          onDownloadTemplate={handleDownloadTemplate}
        />
      )}

      <ConfirmDialog
        open={confirmDialog.open}
        title={confirmDialog.title}
        message={confirmDialog.message}
        onConfirm={confirmDialog.onConfirm}
        onCancel={closeConfirm}
      />
    </div>
  )
}

// ─── ADD / EDIT CUSTOMER MODAL ──────────────────────────────────────────────

const Req = () => <span className="text-red-500 ml-0.5">*</span>
const inp = "w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none"
const sel = "w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none bg-white"

function Field({ label, required, children }) {
  return (
    <div>
      <label className="block text-sm font-medium text-gray-700 mb-1.5">
        {label}{required && <Req />}
      </label>
      {children}
    </div>
  )
}

function AddCustomerModal({ form, setForm, editing, usersList, pendingFiles, setPendingFiles, onSave, onClose }) {
  const isB2B = form.customer_type === 'B2B'
  const set = (key, val) => setForm(prev => ({ ...prev, [key]: val }))

  return (
    <div className="modal-overlay-bg fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 overflow-y-auto overscroll-contain">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl my-8">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-5 border-b border-gray-200">
          <div>
            <h2 className="text-xl font-bold text-gray-900">{editing ? 'Edit Customer' : 'Add New Customer'}</h2>
            <p className="text-xs text-gray-400 mt-0.5"><span className="text-red-500">*</span> Required fields</p>
          </div>
          <button onClick={onClose} className="w-8 h-8 flex items-center justify-center rounded-full text-gray-400 hover:bg-gray-100 transition-colors">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="px-6 py-5 space-y-5 max-h-[70vh] overflow-y-auto">

          {/* Type + Status */}
          <div className="grid grid-cols-2 gap-4">
            <Field label="Customer Type" required>
              <select value={form.customer_type} onChange={e => set('customer_type', e.target.value)} className={sel}>
                <option value="B2B">B2B — Company</option>
                <option value="B2C">B2C — Individual</option>
              </select>
            </Field>
            <Field label="Status">
              <select value={form.customer_status} onChange={e => set('customer_status', e.target.value)} className={sel}>
                <option value="Active">Active</option>
                <option value="Inactive">Inactive</option>
                <option value="Suspended">Suspended</option>
                <option value="VIP">VIP</option>
              </select>
            </Field>
          </div>

          {/* Company Name — B2B only */}
          {isB2B && (
            <Field label="Company Name" required>
              <input type="text" value={form.company_name} onChange={e => set('company_name', e.target.value)} className={inp} placeholder="e.g. Maximum Hardware" />
            </Field>
          )}

          {/* Contact Person + Account Manager */}
          <div className="grid grid-cols-2 gap-4">
            <Field label="Contact Person" required>
              <input type="text" value={form.contact_person} onChange={e => set('contact_person', e.target.value)} className={inp} placeholder="Full name" />
            </Field>
            <Field label="Account Manager">
              <select value={form.account_manager} onChange={e => set('account_manager', e.target.value)} className={sel}>
                <option value="">— Select manager —</option>
                {usersList.map(u => (
                  <option key={u.user_email} value={u.user_email}>{u.user_email}</option>
                ))}
              </select>
            </Field>
          </div>

          {/* Mobile + Landline */}
          <div className="grid grid-cols-2 gap-4">
            <Field label="Mobile" required>
              <input type="tel" value={form.mobile} onChange={e => set('mobile', e.target.value)} className={inp} placeholder="+20 XXX XXX XXXX" />
            </Field>
            <Field label="Landline">
              <input type="tel" value={form.landline} onChange={e => set('landline', e.target.value)} className={inp} placeholder="+2 0X XXXX XXXX" />
            </Field>
          </div>

          {/* Email */}
          <Field label="Email">
            <input type="email" value={form.email} onChange={e => set('email', e.target.value)} className={inp} placeholder="email@example.com" />
          </Field>

          {/* Address */}
          <Field label="Address">
            <textarea value={form.address} onChange={e => set('address', e.target.value)} rows={3} className={inp} placeholder="Street, city, governorate..." />
          </Field>

          {/* CR Number + Tax ID — B2B only */}
          {isB2B && (
            <div className="grid grid-cols-2 gap-4">
              <Field label="CR Number">
                <input type="text" value={form.cr_number} onChange={e => set('cr_number', e.target.value)} className={inp} placeholder="Commercial registration" />
              </Field>
              <Field label="Tax ID">
                <input type="text" value={form.tax_id} onChange={e => set('tax_id', e.target.value)} className={inp} placeholder="Tax identification number" />
              </Field>
            </div>
          )}

          {/* Notes */}
          <Field label="Notes">
            <textarea value={form.notes} onChange={e => set('notes', e.target.value)} rows={3} className={inp} placeholder="Internal notes..." />
          </Field>

          {/* Attachments */}
          <div>
            <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Attachments</label>
            <AttachmentsField
              savedAttachments={form.attachments || []}
              onSavedChange={(val) => set('attachments', val)}
              pendingFiles={pendingFiles}
              onPendingChange={setPendingFiles}
            />
          </div>

        </div>

        {/* Footer */}
        <div className="flex gap-3 px-6 py-4 border-t border-gray-200 bg-gray-50 rounded-b-2xl">
          <Button variant="secondary" className="flex-1 justify-center" onClick={onClose}>Cancel</Button>
          <Button className="flex-1 justify-center" onClick={onSave}>
            {editing ? 'Update Customer' : 'Create Customer'}
          </Button>
        </div>
      </div>
    </div>
  )
}

// ─── BULK UPLOAD CUSTOMERS MODAL ────────────────────────────────────────────

function BulkUploadCustomersModal({ onClose, onUpload, onDownloadTemplate }) {
  const [file, setFile] = useState(null)
  const [uploading, setUploading] = useState(false)

  const handleFileChange = (e) => {
    const selected = e.target.files[0]
    if (selected) {
      if (!selected.name.endsWith('.csv')) { toast.error('Please select a CSV file'); return }
      setFile(selected)
    }
  }

  const handleUpload = async () => {
    if (!file) { toast.error('Please select a file first'); return }
    setUploading(true)
    try { await onUpload(file) } finally { setUploading(false) }
  }

  return (
    <div className="modal-overlay-bg fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 overscroll-contain">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-2xl">

        <div className="flex items-center justify-between p-6 border-b border-gray-200">
          <h2 className="text-xl font-bold text-gray-900">Bulk Upload Customers</h2>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="p-6 space-y-4">
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
            <h3 className="font-medium text-blue-900 mb-2">📋 Instructions:</h3>
            <ul className="text-sm text-blue-800 space-y-1 list-disc list-inside">
              <li>Download the CSV template first</li>
              <li>Fill in your customer data following the template format</li>
              <li>Required fields: <strong>company_name</strong> (B2B) or <strong>contact_person</strong> (B2C) — mobile is optional</li>
              <li><strong>company_name</strong> is required when customer_type is B2B</li>
              <li>Valid customer_type values: <strong>B2B</strong>, <strong>B2C</strong></li>
              <li>Valid customer_status values: <strong>Active</strong>, <strong>Inactive</strong></li>
              <li>Avoid commas inside the address field — use a dash instead</li>
            </ul>
          </div>

          <button
            onClick={onDownloadTemplate}
            className="w-full px-4 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 flex items-center justify-center gap-2"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
            Download CSV Template
          </button>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Upload CSV File</label>
            <label className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center cursor-pointer hover:border-indigo-500 transition-colors block">
              {file ? (
                <div className="space-y-2">
                  <svg className="w-12 h-12 text-green-500 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                  <p className="font-medium text-gray-900">{file.name}</p>
                  <p className="text-sm text-gray-500">{(file.size / 1024).toFixed(2)} KB</p>
                  <p className="text-xs text-indigo-600">Click to change file</p>
                </div>
              ) : (
                <div className="space-y-2">
                  <svg className="w-12 h-12 text-gray-400 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                  </svg>
                  <p className="text-gray-600">Click to upload CSV file</p>
                  <p className="text-sm text-gray-500">or drag and drop</p>
                </div>
              )}
              <input type="file" accept=".csv" onChange={handleFileChange} className="hidden" />
            </label>
          </div>

          {file && (
            <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-3 text-sm text-yellow-800">
              ⚠️ Each imported customer will get a unique CB-XXXXXXXX code generated automatically.
            </div>
          )}
        </div>

        <div className="flex gap-3 p-6 border-t border-gray-200">
          <Button variant="secondary" className="flex-1 justify-center" onClick={onClose}>Cancel</Button>
          <Button
            className="flex-1 justify-center"
            onClick={handleUpload}
            disabled={!file}
            loading={uploading}
          >
            {!uploading && (
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
            )}
            {uploading ? 'Uploading...' : 'Import Customers'}
          </Button>
        </div>
      </div>
    </div>
  )
}

import React, { useState, useEffect, useCallback } from 'react'
import { db, supabase } from '../api/supabaseClient'
import { useAppearance } from '../contexts/AppearanceContext'
import { Spinner, PageHeader } from '../components/ui'
import {
  BarChart, Bar, LineChart, Line, PieChart, Pie, Cell,
  XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
} from 'recharts'

export const WIDGET_CATALOG = [
  { id: 'stat_tickets',           label: 'Ticket KPIs',            desc: '4 stat cards: Total, Open, Closed, Overdue',  size: 'full' },
  { id: 'stat_inventory',         label: 'Inventory Snapshot',     desc: '4 inventory status counts',                   size: 'full' },
  { id: 'sla_health',             label: 'SLA Health',             desc: 'On-time ticket completion rate gauge',         size: 'half' },
  { id: 'resolution_rate',        label: 'Resolution Rate',        desc: 'Percentage of closed tickets gauge',           size: 'half' },
  { id: 'recent_tickets',         label: 'Recent Tickets',         desc: 'Last 10 RMA tickets with status',             size: 'half' },
  { id: 'overdue_tickets',        label: 'Overdue Tickets',        desc: 'All tickets past their due date',              size: 'half' },
  { id: 'weekly_trend',           label: 'Weekly Trend',           desc: '7-day ticket creation line chart',             size: 'half' },
  { id: 'monthly_trend',          label: 'Monthly Trend (30d)',    desc: '30-day ticket creation bar chart',             size: 'half' },
  { id: 'status_distribution',    label: 'Status Distribution',    desc: 'Pie chart of ticket statuses',                 size: 'half' },
  { id: 'priority_distribution',  label: 'Priority Distribution',  desc: 'Pie chart of ticket priorities',               size: 'half' },
  { id: 'technician_performance', label: 'Technician Performance', desc: 'Bar chart of top 5 technicians by close rate', size: 'full' },
  { id: 'top_issues',             label: 'Top Issues',             desc: 'Ranked list of most common product issues',    size: 'full' },
]

const COLORS = ['#6366f1', '#8b5cf6', '#ec4899', '#f59e0b', '#10b981', '#3b82f6', '#ef4444', '#14b8a6']
const PRIORITY_COLORS = ['#ef4444', '#f97316', '#f59e0b', '#10b981']

function WidgetCard({ title, icon, onClick, children, className = '' }) {
  return (
    <div
      onClick={onClick}
      className={`bg-white rounded-xl shadow-sm border border-gray-200 p-6 ${onClick ? 'cursor-pointer hover:shadow-md hover:border-indigo-200 transition-all' : ''} ${className}`}
    >
      {title && (
        <h2 className="text-base font-semibold text-gray-900 mb-4 flex items-center gap-2">
          {icon && <span className="text-indigo-600">{icon}</span>}
          {title}
          {onClick && (
            <svg className="w-3.5 h-3.5 text-gray-400 ml-auto flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
            </svg>
          )}
        </h2>
      )}
      {children}
    </div>
  )
}

function CircularGauge({ percent, color, label, sublabel }) {
  const r = 45
  const circ = 2 * Math.PI * r
  const dash = (Math.max(0, Math.min(percent, 100)) / 100) * circ
  return (
    <div className="flex flex-col items-center py-2">
      <svg width="140" height="140" viewBox="0 0 120 120">
        <circle cx="60" cy="60" r={r} fill="none" stroke="currentColor" strokeWidth="10" className="text-gray-200" />
        <circle
          cx="60" cy="60" r={r}
          fill="none" stroke={color} strokeWidth="10"
          strokeDasharray={`${dash} ${circ}`}
          strokeLinecap="round"
          transform="rotate(-90 60 60)"
          style={{ transition: 'stroke-dasharray 0.6s ease' }}
        />
        <text x="60" y="56" textAnchor="middle" style={{ fontSize: 22, fontWeight: 700 }} fill="currentColor">{percent}%</text>
        <text x="60" y="74" textAnchor="middle" style={{ fontSize: 10 }} fill="currentColor" opacity="0.5">{sublabel}</text>
      </svg>
      <p className="text-sm font-medium text-gray-700 mt-1 text-center">{label}</p>
    </div>
  )
}

function StatusBadge({ status }) {
  const colors = {
    'Open': 'bg-blue-100 text-blue-700',
    'In Progress': 'bg-amber-100 text-amber-700',
    'Pending': 'bg-purple-100 text-purple-700',
    'Resolved': 'bg-green-100 text-green-700',
    'Closed': 'bg-gray-100 text-gray-700',
    'Cancelled': 'bg-red-100 text-red-700',
  }
  return (
    <span className={`px-2 py-0.5 rounded-full text-xs font-medium whitespace-nowrap ${colors[status] || 'bg-gray-100 text-gray-700'}`}>
      {status}
    </span>
  )
}

export default function Dashboard({ currentUserEmail, onNavigate }) {
  const { dashboardWidgets } = useAppearance()
  const storageKey = `dashboard_widgets_${currentUserEmail}`

  const [enabledWidgets, setEnabledWidgets] = useState(() => {
    try {
      const stored = localStorage.getItem(storageKey)
      return stored ? JSON.parse(stored) : (dashboardWidgets || WIDGET_CATALOG.map(w => w.id))
    } catch { return dashboardWidgets || WIDGET_CATALOG.map(w => w.id) }
  })

  const [tickets, setTickets] = useState([])
  const [invStats, setInvStats] = useState(null)
  const [loading, setLoading] = useState(true)

  const loadData = useCallback(async () => {
    try {
      const [ticketsData, inv] = await Promise.all([
        db.rmaTickets.list(),
        db.inventory.getStats().catch(() => null),
      ])
      setTickets(ticketsData)
      setInvStats(inv)
    } catch {}
    finally { setLoading(false) }
  }, [])

  useEffect(() => { loadData() }, [loadData])

  useEffect(() => {
    const channel = supabase.channel('dashboard-rt')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'rma_tickets' }, () => loadData())
      .subscribe()
    return () => supabase.removeChannel(channel)
  }, [loadData])

  // Re-read widget prefs when returning to this page (storageKey may differ per user)
  useEffect(() => {
    try {
      const stored = localStorage.getItem(storageKey)
      if (stored) setEnabledWidgets(JSON.parse(stored))
    } catch {}
  }, [storageKey])

  // Listen for storage events from AccountSettings (same-tab custom event)
  useEffect(() => {
    const handler = () => {
      try {
        const stored = localStorage.getItem(storageKey)
        if (stored) setEnabledWidgets(JSON.parse(stored))
      } catch {}
    }
    window.addEventListener('dashboard-widgets-changed', handler)
    return () => window.removeEventListener('dashboard-widgets-changed', handler)
  }, [storageKey])

  const on = (id) => enabledWidgets.includes(id)
  const nav = (page) => () => onNavigate?.(page)

  // ── Computed stats ──
  const totalTickets = tickets.length
  const openTickets = tickets.filter(t => !['Closed', 'Resolved', 'Cancelled'].includes(t.ticket_status)).length
  const closedTickets = tickets.filter(t => ['Closed', 'Resolved'].includes(t.ticket_status)).length

  const overdueList = tickets.filter(t => {
    if (!t.due_date || ['Closed', 'Resolved', 'Cancelled'].includes(t.ticket_status)) return false
    return new Date(t.due_date) < new Date()
  })

  const ticketsWithDue = tickets.filter(t => t.due_date && t.ticket_status !== 'Cancelled')
  const overdueActive = ticketsWithDue.filter(t =>
    !['Closed', 'Resolved'].includes(t.ticket_status) && new Date(t.due_date) < new Date()
  ).length
  const slaPercent = ticketsWithDue.length > 0
    ? Math.round(((ticketsWithDue.length - overdueActive) / ticketsWithDue.length) * 100)
    : 100
  const resolutionPercent = totalTickets > 0 ? Math.round((closedTickets / totalTickets) * 100) : 0

  // ── Chart data ──
  const getWeeklyTrend = () => {
    const days = []
    for (let i = 6; i >= 0; i--) {
      const d = new Date(); d.setDate(d.getDate() - i)
      const ds = d.toISOString().split('T')[0]
      days.push({
        date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
        tickets: tickets.filter(t => t.created_date?.startsWith(ds)).length,
      })
    }
    return days
  }

  const getMonthlyTrend = () => {
    const days = []
    for (let i = 29; i >= 0; i--) {
      const d = new Date(); d.setDate(d.getDate() - i)
      const ds = d.toISOString().split('T')[0]
      days.push({
        date: i % 6 === 0 ? d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : '',
        fullDate: ds,
        tickets: tickets.filter(t => t.created_date?.startsWith(ds)).length,
      })
    }
    return days
  }

  const getStatusDist = () => {
    const counts = {}
    tickets.forEach(t => { counts[t.ticket_status] = (counts[t.ticket_status] || 0) + 1 })
    return Object.entries(counts).map(([name, value]) => ({ name, value }))
  }

  const getPriorityDist = () => {
    const order = ['Critical', 'High', 'Medium', 'Low']
    const counts = {}
    tickets.forEach(t => { if (t.priority) counts[t.priority] = (counts[t.priority] || 0) + 1 })
    return order.filter(p => counts[p]).map(name => ({ name, value: counts[name] }))
  }

  const getTechnicianPerformance = () => {
    const stats = {}
    tickets.forEach(t => {
      const tech = t.assigned_technician || 'Unassigned'
      if (!stats[tech]) stats[tech] = { total: 0, closed: 0 }
      stats[tech].total++
      if (['Closed', 'Resolved'].includes(t.ticket_status)) stats[tech].closed++
    })
    return Object.entries(stats)
      .map(([name, s]) => ({
        name, total: s.total, closed: s.closed,
        closeRate: s.total > 0 ? Math.round((s.closed / s.total) * 100) : 0,
      }))
      .sort((a, b) => b.closeRate - a.closeRate)
      .slice(0, 5)
  }

  const getTopIssues = () => {
    const counts = {}
    tickets.forEach(t => {
      if (!Array.isArray(t.products)) return
      t.products.forEach(p => {
        const issue = p.issue_description?.trim()
        if (issue) counts[issue] = (counts[issue] || 0) + 1
      })
    })
    return Object.entries(counts)
      .map(([issue, count]) => ({ issue, count }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 5)
  }

  const recentTickets = [...tickets]
    .sort((a, b) => new Date(b.created_date || 0) - new Date(a.created_date || 0))
    .slice(0, 10)

  const daysBetween = (a) => Math.ceil((new Date() - new Date(a)) / 86400000)

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <Spinner size="lg" />
      </div>
    )
  }

  const hasWidgets = WIDGET_CATALOG.some(w => on(w.id))

  return (
    <div className="space-y-6">
      <PageHeader title="Dashboard" subtitle="RMA system overview and analytics" />

      {!hasWidgets && (
        <div className="bg-white rounded-xl border-2 border-dashed border-gray-200 p-14 text-center">
          <svg className="w-12 h-12 text-gray-300 mx-auto mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 5a1 1 0 011-1h4a1 1 0 011 1v4a1 1 0 01-1 1H5a1 1 0 01-1-1V5zm10 0a1 1 0 011-1h4a1 1 0 011 1v4a1 1 0 01-1 1h-4a1 1 0 01-1-1V5zM4 15a1 1 0 011-1h4a1 1 0 011 1v4a1 1 0 01-1 1H5a1 1 0 01-1-1v-4zm10 0a1 1 0 011-1h4a1 1 0 011 1v4a1 1 0 01-1 1h-4a1 1 0 01-1-1v-4z" />
          </svg>
          <p className="text-gray-600 font-medium">No widgets enabled</p>
          <p className="text-gray-400 text-sm mt-1">Go to Account Settings → Appearance to enable widgets</p>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* ── Ticket KPIs ── */}
        {on('stat_tickets') && (
          <div className="lg:col-span-2 grid grid-cols-2 sm:grid-cols-4 gap-4">
            {[
              { title: 'Total Tickets', value: totalTickets,       color: 'indigo', icon: 'M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z' },
              { title: 'Open',          value: openTickets,        color: 'blue',   icon: 'M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z' },
              { title: 'Closed',        value: closedTickets,      color: 'green',  icon: 'M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z' },
              { title: 'Overdue',       value: overdueList.length, color: 'red',    icon: 'M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z' },
            ].map(({ title, value, color, icon }) => {
              const bg = { indigo: 'bg-indigo-100 text-indigo-600', blue: 'bg-blue-100 text-blue-600', green: 'bg-green-100 text-green-600', red: 'bg-red-100 text-red-600' }[color]
              return (
                <div key={title} onClick={nav('rma-tickets')}
                  className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 cursor-pointer hover:shadow-md hover:border-indigo-200 transition-all">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm text-gray-500">{title}</p>
                      <p className="text-3xl font-bold text-gray-900 mt-1">{value}</p>
                    </div>
                    <div className={`w-12 h-12 rounded-lg flex items-center justify-center ${bg}`}>
                      <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={icon} />
                      </svg>
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
        )}

        {/* ── Inventory Snapshot ── */}
        {on('stat_inventory') && invStats && (
          <WidgetCard className="lg:col-span-2" title="Inventory Snapshot" onClick={nav('inventory')}
            icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"/></svg>}
          >
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              {[
                { label: 'Active RMA',          value: invStats.active_rma ?? 0,           cls: 'bg-blue-50',   tc: 'text-blue-700' },
                { label: 'Company Stock',        value: invStats.company_stock ?? 0,         cls: 'bg-amber-50',  tc: 'text-amber-700' },
                { label: 'Sent to Manufacturer', value: invStats.sent_to_manufacturer ?? 0, cls: 'bg-purple-50', tc: 'text-purple-700' },
                { label: 'Total Units',          value: invStats.total ?? 0,                cls: 'bg-gray-50',   tc: 'text-gray-700' },
              ].map(c => (
                <div key={c.label} className={`rounded-lg p-4 ${c.cls}`}>
                  <div className={`text-2xl font-bold ${c.tc}`}>{c.value}</div>
                  <div className={`text-xs font-medium mt-0.5 opacity-70 ${c.tc}`}>{c.label}</div>
                </div>
              ))}
            </div>
          </WidgetCard>
        )}

        {/* ── SLA Health ── */}
        {on('sla_health') && (
          <WidgetCard title="SLA Health" onClick={nav('rma-tickets')}
            icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"/></svg>}
          >
            <div className="flex justify-center">
              <CircularGauge
                percent={slaPercent}
                color={slaPercent >= 80 ? '#10b981' : slaPercent >= 60 ? '#f59e0b' : '#ef4444'}
                label="On-time Delivery Rate"
                sublabel="of tickets"
              />
            </div>
            <p className="text-center text-xs text-gray-400 mt-1">
              {ticketsWithDue.length - overdueActive} of {ticketsWithDue.length} tracked tickets on schedule
            </p>
          </WidgetCard>
        )}

        {/* ── Resolution Rate ── */}
        {on('resolution_rate') && (
          <WidgetCard title="Resolution Rate" onClick={nav('rma-tickets')}
            icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4M7.835 4.697a3.42 3.42 0 001.946-.806 3.42 3.42 0 014.438 0 3.42 3.42 0 001.946.806 3.42 3.42 0 013.138 3.138 3.42 3.42 0 00.806 1.946 3.42 3.42 0 010 4.438 3.42 3.42 0 00-.806 1.946 3.42 3.42 0 01-3.138 3.138 3.42 3.42 0 00-1.946.806 3.42 3.42 0 01-4.438 0 3.42 3.42 0 00-1.946-.806 3.42 3.42 0 01-3.138-3.138 3.42 3.42 0 00-.806-1.946 3.42 3.42 0 010-4.438 3.42 3.42 0 00.806-1.946 3.42 3.42 0 013.138-3.138z"/></svg>}
          >
            <div className="flex justify-center">
              <CircularGauge
                percent={resolutionPercent}
                color={resolutionPercent >= 70 ? '#10b981' : resolutionPercent >= 40 ? '#f59e0b' : '#6366f1'}
                label="Ticket Resolution Rate"
                sublabel="resolved"
              />
            </div>
            <p className="text-center text-xs text-gray-400 mt-1">
              {closedTickets} of {totalTickets} tickets resolved or closed
            </p>
          </WidgetCard>
        )}

        {/* ── Recent Tickets ── */}
        {on('recent_tickets') && (
          <WidgetCard title="Recent Tickets" onClick={nav('rma-tickets')}
            icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"/></svg>}
          >
            {recentTickets.length === 0 ? (
              <p className="text-center text-gray-400 py-8 text-sm">No tickets yet</p>
            ) : (
              <div className="divide-y divide-gray-100 -mx-2">
                {recentTickets.map(t => (
                  <div key={t.id} className="flex items-center justify-between py-2.5 px-2 hover:bg-gray-50 rounded-lg">
                    <div className="min-w-0 flex-1">
                      <p className="text-sm font-medium text-gray-900 truncate">{t.ticket_number || `#${String(t.id).slice(0, 8)}`}</p>
                      <p className="text-xs text-gray-400 truncate">{t.customer_name || '—'}</p>
                    </div>
                    <div className="ml-3 flex-shrink-0">
                      <StatusBadge status={t.ticket_status} />
                    </div>
                  </div>
                ))}
              </div>
            )}
          </WidgetCard>
        )}

        {/* ── Overdue Tickets ── */}
        {on('overdue_tickets') && (
          <WidgetCard title="Overdue Tickets" onClick={nav('rma-tickets')}
            icon={<svg className="w-5 h-5 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>}
          >
            {overdueList.length === 0 ? (
              <div className="text-center py-8">
                <svg className="w-10 h-10 text-green-400 mx-auto mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/>
                </svg>
                <p className="text-sm text-green-600 font-medium">No overdue tickets!</p>
              </div>
            ) : (
              <div className="divide-y divide-gray-100 -mx-2">
                {overdueList.slice(0, 10).map(t => (
                  <div key={t.id} className="flex items-center justify-between py-2.5 px-2 hover:bg-red-50 rounded-lg">
                    <div className="min-w-0 flex-1">
                      <p className="text-sm font-medium text-gray-900 truncate">{t.ticket_number || `#${String(t.id).slice(0, 8)}`}</p>
                      <p className="text-xs text-gray-400 truncate">{t.customer_name || '—'}</p>
                    </div>
                    <span className="ml-3 flex-shrink-0 px-2 py-0.5 bg-red-100 text-red-700 rounded-full text-xs font-medium">
                      {daysBetween(t.due_date)}d overdue
                    </span>
                  </div>
                ))}
              </div>
            )}
          </WidgetCard>
        )}

        {/* ── Weekly Trend ── */}
        {on('weekly_trend') && (
          <WidgetCard title="Weekly Trend" onClick={nav('rma-tickets')}
            icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 12l3-3 3 3 4-4M8 21l4-4 4 4M3 4h18M4 4h16v12a1 1 0 01-1 1H5a1 1 0 01-1-1V4z"/></svg>}
          >
            <ResponsiveContainer width="100%" height={220}>
              <LineChart data={getWeeklyTrend()}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />
