          >
            {getTopIssues().length === 0 ? (
              <p className="text-center text-gray-400 py-8 text-sm">No issues recorded yet</p>
            ) : (
              <div className="space-y-4">
                {getTopIssues().map((item, idx) => {
                  const max = getTopIssues()[0]?.count || 1
                  return (
                    <div key={idx} className="flex items-center gap-3">
                      <div className="w-7 h-7 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center font-semibold text-sm flex-shrink-0">
                        {idx + 1}
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center justify-between mb-1">
                          <p className="text-sm text-gray-800 truncate">{item.issue}</p>
                          <span className="ml-3 text-sm font-semibold text-gray-600 flex-shrink-0">{item.count}</span>
                        </div>
                        <div className="h-1.5 bg-gray-100 rounded-full overflow-hidden">
                          <div className="h-full bg-indigo-500 rounded-full transition-all duration-500" style={{ width: `${(item.count / max) * 100}%` }} />
                        </div>
                      </div>
                    </div>
                  )
                })}
              </div>
            )}
          </WidgetCard>
        )}

      </div>
    </div>
  )
}

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react'
