                        <td className="px-4 py-2.5" onClick={e => e.stopPropagation()}>
                          <div className="flex items-center gap-1 justify-center">
                            <button onClick={() => setEditingWh(wh)} className="p-1 text-gray-400 hover:text-indigo-600 rounded hover:bg-indigo-50 transition-colors">
                              <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                            </button>
                            <button onClick={() => handleDelete(wh)} disabled={deleting === wh.id} className="p-1 text-gray-400 hover:text-red-600 rounded hover:bg-red-50 transition-colors disabled:opacity-40">
                              <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                            </button>
                          </div>
                        </td>
                      )}
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        )}

      {selectedWh && (
        <WarehouseDetailModal
          wh={selectedWh}
          units={selectedWh.isSystem
            ? units.filter(u => u.status === selectedWh.status && !u.warehouse_id)
            : units.filter(u => u.warehouse_id === selectedWh.id)}
          warehouses={warehouses}
          brandMap={brandMap}
          canTransfer={canTransfer}
          userEmail={userEmail}
          onClose={() => setSelectedWh(null)}
          onReload={() => { setSelectedWh(null); onReload() }}
        />
      )}
      {showCreate && (
        <CreateWarehouseModal
          warehouses={warehouses}
          onSave={async d => { await db.warehouses.create({ ...d, created_by: userEmail, created_date: new Date().toISOString() }); toast.success('Warehouse created!'); db.auditLog.log(userEmail, 'warehouse_created', `Created warehouse ${d.name}`).catch(() => {}); setShowCreate(false); onReload() }}
          onClose={() => setShowCreate(false)}
        />
      )}
      {editingWh && (
        <CreateWarehouseModal
          initialData={editingWh}
          warehouses={warehouses}
          onSave={async d => { await db.warehouses.update(editingWh.id, d); toast.success('Warehouse updated!'); db.auditLog.log(userEmail, 'warehouse_updated', `Updated warehouse ${d.name || editingWh.name}`).catch(() => {}); setEditingWh(null); onReload() }}
          onClose={() => setEditingWh(null)}
        />
      )}
      <ConfirmDialog open={confirmDialog.open} title={confirmDialog.title} message={confirmDialog.message} onConfirm={confirmDialog.onConfirm} onCancel={closeConfirm} />
    </div>
  )
}

// ─── Warehouse Detail Modal ────────────────────────────────────────────────────
function WarehouseDetailModal({ wh, units, warehouses, brandMap, canTransfer, userEmail, onClose, onReload }) {
  const [selected, setSelected]       = useState([])
  const [showTransfer, setShowTransfer] = useState(false)
  const [search, setSearch]           = useState('')
  const [ticketMap, setTicketMap]     = useState({})

  useEffect(() => {
    const nums = [...new Set(units.map(u => u.rma_number).filter(Boolean))]
    if (!nums.length) return
    supabase.from('rma_tickets').select('rma_number,customer_name,ticket_status')
      .in('rma_number', nums)
      .then(({ data }) => {
        const m = {}
        for (const t of data || []) m[t.rma_number] = t
        setTicketMap(m)
      })
  }, [units])

  const filtered = useMemo(() => {
    if (!search.trim()) return units
    const q = search.toLowerCase()
    return units.filter(u =>
      (u.product_name || '').toLowerCase().includes(q) ||
      (u.serial_number || '').toLowerCase().includes(q) ||
      (u.rma_number || '').toLowerCase().includes(q) ||
      (brandMap[u.product_name] || '').toLowerCase().includes(q) ||
      (ticketMap[u.rma_number]?.customer_name || '').toLowerCase().includes(q)
    )
  }, [units, search, brandMap, ticketMap])

  const toggle    = id => setSelected(p => p.includes(id) ? p.filter(x => x !== id) : [...p, id])
  const toggleAll = () => setSelected(selected.length === filtered.length ? [] : filtered.map(u => u.id))

  const handleTransfer = async (warehouseId) => {
    const ids = selected.length > 0 ? selected : filtered.map(u => u.id)
    try {
      await db.inventory.transferUnits(ids, warehouseId)
      toast.success(`${ids.length} unit(s) transferred`)
      db.auditLog.log(userEmail, 'inventory_units_transferred', `Transferred ${ids.length} unit(s) from ${wh.name} to warehouse ${warehouseId}`).catch(() => {})
      setSelected([]); setShowTransfer(false); onReload()
    }
    catch { toast.error('Transfer failed') }
  }

  const fmtDate = d => d ? new Date(d).toLocaleDateString() : '—'

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-6xl flex flex-col" style={{ maxHeight: '90vh' }}>

        {/* Header */}
        <div className="flex items-start justify-between px-6 py-4 border-b border-gray-100 flex-shrink-0">
          <div>
            <div className="flex items-center gap-2">
              {wh.code && <span className="font-mono text-xs font-bold text-indigo-700 bg-indigo-50 px-2 py-0.5 rounded">{wh.code}</span>}
              <h3 className="text-lg font-bold text-gray-900">{wh.name}</h3>
              {!wh.isSystem && wh.is_active === false && <span className="px-2 py-0.5 rounded text-[10px] font-medium bg-gray-100 text-gray-500">Inactive</span>}
            </div>
            <p className="text-xs text-gray-400 mt-1">
              {units.length} unit{units.length !== 1 ? 's' : ''}
              {wh.location ? ` · ${wh.location}` : ''}
              {wh.description ? ` · ${wh.description}` : ''}
            </p>
          </div>
          <div className="flex items-center gap-2 flex-shrink-0">
            {units.length > 0 && <>
              <button onClick={() => exportWarehouseExcel(wh, filtered, brandMap, ticketMap)}
                className="flex items-center gap-1.5 px-3 py-1.5 border border-green-300 text-green-700 rounded-lg text-xs font-medium hover:bg-green-50">
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"/></svg>
                Excel
              </button>
              <button onClick={() => exportWarehousePDF(wh, filtered, brandMap, ticketMap)}
                className="flex items-center gap-1.5 px-3 py-1.5 border border-red-300 text-red-700 rounded-lg text-xs font-medium hover:bg-red-50">
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z"/></svg>
                PDF
              </button>
            </>}
            {canTransfer && units.length > 0 && (
              <button onClick={() => setShowTransfer(true)}
                className="flex items-center gap-1.5 px-3 py-1.5 border border-indigo-300 text-indigo-700 rounded-lg text-xs font-medium hover:bg-indigo-50">
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4"/></svg>
                Transfer{selected.length > 0 ? ` (${selected.length})` : ''}
              </button>
            )}
            <button onClick={onClose} className="p-1.5 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12"/></svg>
            </button>
          </div>
        </div>

        {/* Search */}
        <div className="px-6 py-3 border-b border-gray-100 flex-shrink-0">
          <div className="relative max-w-sm">
            <input value={search} onChange={e => setSearch(e.target.value)}
              placeholder="Search product, serial, RMA#, customer…"
              className="w-full pl-8 pr-3 py-1.5 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent"/>
            <svg className="w-4 h-4 text-gray-400 absolute left-2.5 top-1/2 -translate-y-1/2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
          </div>
        </div>

        {/* Table */}
        <div className="flex-1 overflow-auto">
          {filtered.length === 0 ? (
            <div className="text-center py-16 text-gray-400 text-sm">{search ? 'No units match your search' : 'No units in this warehouse'}</div>
          ) : (
            <table className="w-full text-xs border-collapse">
              <thead className="bg-gray-100 sticky top-0 z-10">
                <tr>
                  {canTransfer && (
                    <th className="w-9 px-3 py-2.5 border-b border-r border-gray-200 text-center">
                      <input type="checkbox" checked={filtered.length > 0 && selected.length === filtered.length} onChange={toggleAll} className="rounded border-gray-300 text-indigo-600 cursor-pointer"/>
                    </th>
                  )}
                  <th className="w-8 px-2 py-2.5 border-b border-r border-gray-200 text-center text-gray-400 font-semibold">#</th>
                  <th className="px-3 py-2.5 text-left font-semibold text-gray-600 border-b border-r border-gray-200 min-w-[140px]">Product</th>
                  <th className="px-3 py-2.5 text-left font-semibold text-gray-600 border-b border-r border-gray-200 w-24">Brand</th>
                  <th className="px-3 py-2.5 text-left font-semibold text-gray-600 border-b border-r border-gray-200 w-28">Serial #</th>
                  <th className="px-3 py-2.5 text-center font-semibold text-gray-600 border-b border-r border-gray-200 w-28">Warranty</th>
                  <th className="px-3 py-2.5 text-center font-semibold text-gray-600 border-b border-r border-gray-200 w-28">Status</th>
                  <th className="px-3 py-2.5 text-center font-semibold text-gray-600 border-b border-r border-gray-200 w-28">Resolution</th>
                  <th className="px-3 py-2.5 text-left font-semibold text-gray-600 border-b border-r border-gray-200 w-32">RMA #</th>
                  <th className="px-3 py-2.5 text-left font-semibold text-gray-600 border-b border-r border-gray-200 min-w-[120px]">Customer</th>
                  <th className="px-3 py-2.5 text-center font-semibold text-gray-600 border-b border-r border-gray-200 w-24">RMA Status</th>
                  <th className="px-3 py-2.5 text-left font-semibold text-gray-600 border-b border-r border-gray-200 w-28">Date Added</th>
                  <th className="px-3 py-2.5 text-center font-semibold text-gray-600 border-b border-gray-200 w-16">Days</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((u, idx) => {
                  const isSelected = selected.includes(u.id)
                  const age = daysSince(u.created_date)
                  const tk  = ticketMap[u.rma_number]
                  return (
                    <tr key={u.id}
                      onClick={() => canTransfer && toggle(u.id)}
                      className={`border-b border-gray-100 transition-colors ${isSelected ? 'bg-indigo-50' : idx % 2 === 0 ? 'bg-white' : 'bg-gray-50/50'} ${canTransfer ? 'cursor-pointer hover:bg-indigo-50/40' : ''}`}>
                      {canTransfer && (
                        <td className="px-3 py-1.5 text-center border-r border-gray-100">
                          <input type="checkbox" checked={isSelected} onChange={() => {}} className="rounded border-gray-300 text-indigo-600 cursor-pointer"/>
                        </td>
                      )}
                      <td className="px-2 py-1.5 text-center text-gray-400 tabular-nums border-r border-gray-100">{idx + 1}</td>
                      <td className="px-3 py-1.5 font-medium text-gray-900 border-r border-gray-100 max-w-[160px] truncate" title={u.product_name || ''}>{u.product_name || '—'}</td>
                      <td className="px-3 py-1.5 text-gray-500 border-r border-gray-100">{brandMap[u.product_name] || '—'}</td>
                      <td className="px-3 py-1.5 font-mono text-gray-600 border-r border-gray-100">{u.serial_number || '—'}</td>
                      <td className="px-3 py-1.5 text-center border-r border-gray-100"><WarrantyBadge status={u.warranty_status}/></td>
                      <td className="px-3 py-1.5 text-center border-r border-gray-100"><StatusBadge status={u.status}/></td>
                      <td className="px-3 py-1.5 text-center border-r border-gray-100"><ResolutionBadge type={u.resolution_type}/></td>
                      <td className="px-3 py-1.5 font-mono text-indigo-600 border-r border-gray-100">{u.rma_number || '—'}</td>
                      <td className="px-3 py-1.5 text-gray-700 border-r border-gray-100">{tk?.customer_name || '—'}</td>
                      <td className="px-3 py-1.5 text-center border-r border-gray-100">
                        {tk?.ticket_status
                          ? <span className={`px-1.5 py-0.5 rounded text-[10px] font-medium ${TICKET_STATUS_CLS[tk.ticket_status] || 'bg-gray-100 text-gray-500'}`}>{tk.ticket_status}</span>
                          : <span className="text-gray-300">—</span>}
                      </td>
                      <td className="px-3 py-1.5 text-gray-400 border-r border-gray-100">{fmtDate(u.created_date)}</td>
                      <td className="px-3 py-1.5 text-center">
                        <span className={`text-xs font-semibold ${age > 30 ? 'text-red-600' : age > 14 ? 'text-amber-600' : 'text-gray-500'}`}>{age}d</span>
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          )}
        </div>

        {/* Footer */}
        <div className="px-6 py-3 border-t border-gray-100 flex items-center justify-between flex-shrink-0">
          <span className="text-xs text-gray-400">
            {search ? `${filtered.length} of ${units.length} units` : `${units.length} unit${units.length !== 1 ? 's' : ''} total`}
            {selected.length > 0 && <span className="ml-2 text-indigo-600 font-medium">{selected.length} selected</span>}
          </span>
          <button onClick={onClose} className="px-4 py-1.5 border border-gray-300 text-gray-700 rounded-lg text-sm hover:bg-gray-50">Close</button>
        </div>
      </div>
      {showTransfer && (
        <TransferModal
          units={selected.length > 0 ? selected : filtered.map(u => u.id)}
          warehouses={warehouses}
          currentWarehouseId={wh.isSystem ? null : wh.id}
          onConfirm={handleTransfer}
          onClose={() => setShowTransfer(false)}
        />
      )}
    </div>
  )
}

// ─── Create / Edit Warehouse Modal ─────────────────────────────────────────────
function CreateWarehouseModal({ initialData, warehouses = [], onSave, onClose }) {
  const isEdit = !!initialData?.id

  const autoCode = useMemo(() => {
    if (isEdit) return initialData?.code || ''
    const nums = warehouses.map(w => {
      const m = (w.code || '').match(/^WH-(\d+)$/)
      return m ? parseInt(m[1]) : 0
    }).filter(n => n > 0)
    const max = nums.length ? Math.max(...nums) : 0
    return `WH-${String(max + 1).padStart(3, '0')}`
  }, [isEdit, warehouses, initialData])

  const [name, setName]         = useState(initialData?.name || '')
  const [code, setCode]         = useState(autoCode)
  const [location, setLocation] = useState(initialData?.location || '')
  const [desc, setDesc]         = useState(initialData?.description || '')
  const [active, setActive]     = useState(initialData?.is_active ?? true)
  const [saving, setSaving]     = useState(false)

  const handleSave = async () => {
    if (!name.trim()) return
    setSaving(true)
    try { await onSave({ name: name.trim(), code: code.trim() || null, location: location.trim() || null, description: desc.trim() || null, is_active: active }) }
    catch { toast.error('Failed to save warehouse') }
    finally { setSaving(false) }
  }

  return (
    <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm">
        <div className="p-6 border-b border-gray-100">
          <h3 className="text-lg font-semibold text-gray-900">{isEdit ? 'Edit Warehouse' : 'New Warehouse'}</h3>
          {!isEdit && <p className="text-xs text-gray-400 mt-0.5">Auto-assigned code: <span className="font-mono font-semibold text-indigo-600">{autoCode}</span></p>}
        </div>
        <div className="p-6 space-y-4">
          <div>
            <label className="block text-xs font-semibold text-gray-700 mb-1.5">Warehouse Name <span className="text-red-500">*</span></label>
            <input value={name} onChange={e => setName(e.target.value)} placeholder="e.g. Dubai Main Warehouse"
              className="w-full px-3 py-2 border border-gray-300 rounded-xl text-sm focus:ring-2 focus:ring-indigo-600 focus:border-transparent" autoFocus/>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-1.5">Code</label>
              <input value={code} onChange={e => setCode(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-xl text-sm focus:ring-2 focus:ring-indigo-600 focus:border-transparent font-mono"/>
            </div>
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-1.5">Location</label>
              <input value={location} onChange={e => setLocation(e.target.value)} placeholder="City, Area"
                className="w-full px-3 py-2 border border-gray-300 rounded-xl text-sm focus:ring-2 focus:ring-indigo-600 focus:border-transparent"/>
            </div>
          </div>
          <div>
            <label className="block text-xs font-semibold text-gray-700 mb-1.5">Description</label>
            <textarea value={desc} onChange={e => setDesc(e.target.value)} rows={2} placeholder="Optional notes…"
              className="w-full px-3 py-2 border border-gray-300 rounded-xl text-sm resize-none focus:ring-2 focus:ring-indigo-600 focus:border-transparent"/>
          </div>
          {isEdit && (
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="checkbox" checked={active} onChange={e => setActive(e.target.checked)} className="rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"/>
              <span className="text-sm text-gray-700">Active</span>
            </label>
          )}
        </div>
        <div className="px-6 py-4 border-t border-gray-100 flex justify-end gap-3">
          <button onClick={onClose} className="px-4 py-2 border border-gray-300 text-gray-700 rounded-xl text-sm hover:bg-gray-50">Cancel</button>
          <button onClick={handleSave} disabled={!name.trim()||saving}
            className="px-5 py-2 bg-indigo-600 text-white rounded-xl text-sm font-medium hover:bg-indigo-700 disabled:opacity-50 min-w-[100px] text-center">
            {saving ? <Spinner size="sm" color="white" /> : isEdit ? 'Save Changes' : 'Create'}
          </button>
        </div>
      </div>
    </div>
  )
}

// ─── Transfer Modal ────────────────────────────────────────────────────────────
function TransferModal({ units: unitIds, warehouses, currentWarehouseId, onConfirm, onClose }) {
  const [dest, setDest]   = useState('')
  const [saving, setSaving] = useState(false)
  const handleConfirm = async () => {
    if (!dest && dest !== '__system') return
    setSaving(true)
    await onConfirm(dest === '__system' ? null : dest)
    setSaving(false)
  }
  return (
    <div className="fixed inset-0 bg-black/50 z-[70] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm">
        <div className="p-6 border-b border-gray-100">
          <h3 className="text-lg font-semibold text-gray-900">Transfer Units</h3>
          <p className="text-sm text-gray-500 mt-1">{unitIds.length} unit{unitIds.length!==1?'s':''} selected</p>
        </div>
        <div className="p-6 space-y-2">
          <label className="block text-xs font-semibold text-gray-700 mb-2">Select Destination Warehouse</label>
          <label className={`flex items-center gap-3 p-3 border-2 rounded-xl cursor-pointer transition-all ${dest==='__system'?'border-gray-400 bg-gray-50':'border-gray-200 hover:border-gray-300'}`}>
            <input type="radio" name="dest" value="__system" checked={dest==='__system'} onChange={()=>setDest('__system')} className="text-indigo-600"/>
            <div>
              <div className="font-medium text-sm text-gray-900">System Pool</div>
              <div className="text-xs text-gray-500">Remove from custom warehouse, return to status-based tracking</div>
            </div>
          </label>
          {warehouses.filter(w => w.is_active && w.id !== currentWarehouseId).map(wh => (
            <label key={wh.id} className={`flex items-center gap-3 p-3 border-2 rounded-xl cursor-pointer transition-all ${dest===wh.id?'border-indigo-400 bg-indigo-50':'border-gray-200 hover:border-indigo-200'}`}>
              <input type="radio" name="dest" value={wh.id} checked={dest===wh.id} onChange={()=>setDest(wh.id)} className="text-indigo-600"/>
              <div>
                <div className="font-medium text-sm text-gray-900">{wh.name}</div>
                {(wh.code||wh.location) && <div className="text-xs text-gray-500">{[wh.code,wh.location].filter(Boolean).join(' · ')}</div>}
              </div>
            </label>
          ))}
          {warehouses.filter(w => w.is_active && w.id !== currentWarehouseId).length === 0 && warehouses.length === 0 && (
            <p className="text-sm text-gray-400 text-center py-4">No custom warehouses available. Create one in the Warehouses tab.</p>
          )}
        </div>
        <div className="px-6 py-4 border-t border-gray-100 flex justify-end gap-3">
          <button onClick={onClose} className="px-4 py-2 border border-gray-300 text-gray-700 rounded-xl text-sm hover:bg-gray-50">Cancel</button>
          <button onClick={handleConfirm} disabled={!dest||saving}
            className="px-5 py-2 bg-indigo-600 text-white rounded-xl text-sm font-medium hover:bg-indigo-700 disabled:opacity-50 min-w-[120px] text-center">
            {saving ? <Spinner size="sm" color="white" /> : 'Confirm Transfer'}
          </button>
        </div>
      </div>
    </div>
  )
}

// ─── Manufacturer Returns ──────────────────────────────────────────────────────
function ManufacturerTab({ batches, units, brands, userEmail, canManageBatches, onReload }) {
  const [selectedBrand, setSelectedBrand] = useState(null)
  const [selectedBatch, setSelectedBatch] = useState(null)
  const getBatchUnits  = batchId => units.filter(u => u.manufacturer_batch_id === batchId)
  const getBrandBatches = name => batches.filter(b => b.manufacturer_name?.toLowerCase() === name?.toLowerCase())
  const getBrandStats = name => {
    const bb = getBrandBatches(name)
    return { total: bb.length, draft: bb.filter(b=>b.status==='draft').length, sent: bb.filter(b=>b.status==='sent').length, resolved: bb.filter(b=>b.status==='resolved').length, units: bb.reduce((s,b) => s+(getBatchUnits(b.id).length||b.unit_count||0),0) }
  }
  const knownNames = brands.map(b => b.brand_name?.toLowerCase())
  const otherBatches = batches.filter(b => !knownNames.includes(b.manufacturer_name?.toLowerCase()))
  const displayBatches = selectedBrand==='__other' ? otherBatches : selectedBrand ? getBrandBatches(selectedBrand) : batches

  return (
    <div className="space-y-6">
      <div>
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-sm font-semibold text-gray-700">Brand Warehouses</h3>
          {selectedBrand && <button onClick={()=>setSelectedBrand(null)} className="text-xs text-indigo-600 hover:underline">Clear filter</button>}
        </div>
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-3">
          {brands.map(brand => {
            const s = getBrandStats(brand.brand_name); const isA = selectedBrand===brand.brand_name
            return (
              <button key={brand.id} onClick={()=>setSelectedBrand(isA?null:brand.brand_name)}
                className={`rounded-2xl border p-4 text-left transition-all ${isA?'border-indigo-400 bg-indigo-50 ring-2 ring-indigo-300':'border-gray-200 bg-white hover:border-indigo-200 hover:bg-indigo-50/40'}`}>
                <BrandAvatar name={brand.brand_name} size="md"/>
                <div className="mt-3"><div className="font-semibold text-sm text-gray-900 truncate">{brand.brand_name}</div><div className="text-xs text-gray-400 mt-0.5">{s.total} batch{s.total!==1?'es':''} · {s.units} unit{s.units!==1?'s':''}</div></div>
                {s.total>0 ? (
                  <div className="flex gap-1 mt-2 flex-wrap">
                    {s.draft>0    && <span className="px-1.5 py-0.5 rounded text-[10px] font-medium bg-gray-100 text-gray-600">{s.draft} draft</span>}
                    {s.sent>0     && <span className="px-1.5 py-0.5 rounded text-[10px] font-medium bg-blue-100 text-blue-700">{s.sent} sent</span>}
                    {s.resolved>0 && <span className="px-1.5 py-0.5 rounded text-[10px] font-medium bg-green-100 text-green-700">{s.resolved} done</span>}
                  </div>
                ) : <div className="mt-2 text-[10px] text-gray-300 font-medium">No batches yet</div>}
              </button>
            )
          })}
          {otherBatches.length>0 && (
            <button onClick={()=>setSelectedBrand(selectedBrand==='__other'?null:'__other')}
              className={`rounded-2xl border p-4 text-left transition-all ${selectedBrand==='__other'?'border-gray-400 bg-gray-50 ring-2 ring-gray-300':'border-dashed border-gray-300 bg-white hover:border-gray-400'}`}>
              <div className="w-9 h-9 bg-gray-200 rounded-xl flex items-center justify-center text-gray-500 text-base font-bold">?</div>
              <div className="mt-3"><div className="font-semibold text-sm text-gray-900">Other</div><div className="text-xs text-gray-400 mt-0.5">{otherBatches.length} batch{otherBatches.length!==1?'es':''}</div></div>
            </button>
          )}
        </div>
      </div>

      {displayBatches.length===0 ? (
        <div className="text-center py-16 bg-white rounded-2xl border border-gray-200 space-y-3">
          <div className="w-14 h-14 bg-purple-100 rounded-2xl flex items-center justify-center mx-auto"><svg className="w-7 h-7 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 8h14M5 8a2 2 0 110-4h14a2 2 0 110 4M5 8v10a2 2 0 002 2h10a2 2 0 002-2V8m-9 4h4"/></svg></div>
          <p className="text-gray-600 font-medium">{selectedBrand?`No batches for ${selectedBrand} yet`:'No manufacturer batches yet'}</p>
          <p className="text-gray-400 text-sm">Go to Company Stock, open a product, and select units to create a batch.</p>
        </div>
      ) : (
        <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden">
          {selectedBrand && selectedBrand!=='__other' && (
            <div className="flex items-center gap-3 px-5 py-4 border-b border-gray-100 bg-indigo-50/60">
              <BrandAvatar name={selectedBrand} size="md"/>
              <div><div className="font-semibold text-gray-900">{selectedBrand} — Return Batches</div><div className="text-xs text-gray-500">{displayBatches.length} batch{displayBatches.length!==1?'es':''}</div></div>
            </div>
          )}
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b border-gray-200">
                <tr>{['Batch #','Manufacturer','Units','Status','Sent Date','Tracking #','Resolution','Created'].map(h=><th key={h} className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider">{h}</th>)}<th className="px-4 py-3 w-16"/></tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {displayBatches.map(b => {
                  const sm=BATCH_STATUS_META[b.status]||{label:b.status,cls:'bg-gray-100 text-gray-600'}
                  const resLabel = b.resolution_type==='replacement_received'?{label:'Replacement Rcvd',cls:'bg-green-100 text-green-700'}:b.resolution_type==='credit_note_received'?{label:'Credit Note Rcvd',cls:'bg-blue-100 text-blue-700'}:null
                  return (
                    <tr key={b.id} className="hover:bg-gray-50 cursor-pointer" onClick={()=>setSelectedBatch(b)}>
                      <td className="px-4 py-3 font-mono text-xs font-bold text-indigo-600">{b.batch_number}</td>
                      <td className="px-4 py-3"><div className="flex items-center gap-2"><BrandAvatar name={b.manufacturer_name} size="xs"/><span className="text-gray-900 font-medium text-sm">{b.manufacturer_name}</span></div></td>
                      <td className="px-4 py-3 text-gray-600">{getBatchUnits(b.id).length||b.unit_count||0}</td>
                      <td className="px-4 py-3"><span className={`px-2 py-0.5 rounded-full text-xs font-medium ${sm.cls}`}>{sm.label}</span></td>
                      <td className="px-4 py-3 text-gray-500 whitespace-nowrap">{fmt(b.sent_date)}</td>
                      <td className="px-4 py-3 font-mono text-xs text-gray-500">{b.tracking_number||'—'}</td>
                      <td className="px-4 py-3">{resLabel?<span className={`px-2 py-0.5 rounded-full text-xs font-medium ${resLabel.cls}`}>{resLabel.label}</span>:<span className="text-gray-400 text-xs">—</span>}</td>
                      <td className="px-4 py-3 text-gray-400 text-xs whitespace-nowrap">{fmt(b.created_date)}</td>
                      <td className="px-4 py-3 text-right"><span className="text-xs text-indigo-600 hover:underline">View</span></td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
      {selectedBatch && <BatchDetailModal batch={selectedBatch} batchUnits={getBatchUnits(selectedBatch.id)} canEdit={canManageBatches} onClose={()=>setSelectedBatch(null)} onReload={()=>{setSelectedBatch(null);onReload()}} />}
    </div>
  )
}

// ─── Resolve Modal ─────────────────────────────────────────────────────────────
function ResolveModal({ count, onConfirm, onClose }) {
  const [resolution, setResolution] = useState('')
  const [notes, setNotes]           = useState('')
  const [saving, setSaving]         = useState(false)
  const options = [
    {value:'return_to_customer',label:'Return to Customer', desc:'Unit returned — exits inventory.',          active:'border-green-400 bg-green-50'},
    {value:'credit_note',       label:'Credit Note Issued',desc:'Credit note — moves to Company Stock.',     active:'border-orange-400 bg-orange-50'},
    {value:'replacement',       label:'Replacement Issued', desc:'Replacement sent — moves to Company Stock.',active:'border-indigo-400 bg-indigo-50'},
  ]
  const handleConfirm = async () => { if(!resolution)return; setSaving(true); await onConfirm(resolution,notes); setSaving(false) }
  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md">
        <div className="p-6 border-b border-gray-100"><h3 className="text-lg font-semibold text-gray-900">Set Resolution</h3><p className="text-sm text-gray-500 mt-1">{count} unit{count!==1?'s':''} selected</p></div>
        <div className="p-6 space-y-3">
          {options.map(o => (<label key={o.value} className={`flex items-start gap-3 p-4 border-2 rounded-xl cursor-pointer transition-all ${resolution===o.value?o.active:'border-gray-200 hover:border-gray-300 bg-white'}`}><input type="radio" name="resolution" value={o.value} checked={resolution===o.value} onChange={()=>setResolution(o.value)} className="mt-0.5 text-indigo-600"/><div><div className="font-medium text-sm text-gray-900">{o.label}</div><div className="text-xs text-gray-500 mt-0.5">{o.desc}</div></div></label>))}
          <textarea value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Notes (optional)" rows={2} className="w-full px-3 py-2 border border-gray-300 rounded-xl text-sm resize-none focus:ring-2 focus:ring-indigo-600 focus:border-transparent"/>
        </div>
        <div className="px-6 py-4 border-t border-gray-100 flex justify-end gap-3">
          <button onClick={onClose} className="px-4 py-2 border border-gray-300 text-gray-700 rounded-xl text-sm hover:bg-gray-50">Cancel</button>
          <button onClick={handleConfirm} disabled={!resolution||saving} className="px-5 py-2 bg-indigo-600 text-white rounded-xl text-sm font-medium hover:bg-indigo-700 disabled:opacity-50 min-w-[140px] text-center">{saving?<Spinner size="sm" color="white" />:'Confirm Resolution'}</button>
        </div>
      </div>
    </div>
  )
}

// ─── Create Batch Modal ────────────────────────────────────────────────────────
function CreateBatchModal({ count, brands, onConfirm, onClose }) {
  const [brandName, setBrandName]   = useState('')
  const [customName, setCustomName] = useState('')
  const [saving, setSaving]         = useState(false)
  const effectiveName = brandName==='__custom' ? customName.trim() : brandName
  const handleConfirm = async () => { if(!effectiveName)return; setSaving(true); await onConfirm(effectiveName); setSaving(false) }
  return (
    <div className="fixed inset-0 bg-black/50 z-[60] flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm">
        <div className="p-6 border-b border-gray-100"><h3 className="text-lg font-semibold text-gray-900">Create Manufacturer Batch</h3><p className="text-sm text-gray-500 mt-1">{count} unit{count!==1?'s':''} will be added</p></div>
        <div className="p-6 space-y-4">
          <label className="block text-sm font-medium text-gray-700 mb-2">Manufacturer Name</label>
          {brands.length > 0 ? (
            <div className="grid grid-cols-2 gap-2">
              {brands.map(b => (<button key={b.id||b.brand_name} type="button" onClick={()=>setBrandName(b.brand_name||b)} className={`flex items-center gap-2 px-3 py-2.5 rounded-xl border text-sm font-medium transition-all text-left ${brandName===(b.brand_name||b)?'border-indigo-400 bg-indigo-50 text-indigo-700':'border-gray-200 hover:border-indigo-200 text-gray-700'}`}><BrandAvatar name={b.brand_name||b} size="xs"/>{b.brand_name||b}</button>))}
              <button type="button" onClick={()=>setBrandName('__custom')} className={`flex items-center gap-2 px-3 py-2.5 rounded-xl border text-sm font-medium transition-all ${brandName==='__custom'?'border-gray-400 bg-gray-50':'border-dashed border-gray-300 hover:border-gray-400 text-gray-500'}`}><div className="w-5 h-5 bg-gray-200 rounded flex items-center justify-center text-xs font-bold">+</div>Other</button>
            </div>
          ) : null}
          {(brands.length === 0 || brandName === '__custom') && (
            <input value={customName} onChange={e=>setCustomName(e.target.value)} placeholder="Manufacturer name..." autoFocus
              className="w-full px-4 py-2.5 border border-gray-300 rounded-xl text-sm focus:ring-2 focus:ring-indigo-600"
              onKeyDown={e=>e.key==='Enter'&&handleConfirm()} />
          )}
        </div>
        <div className="px-6 py-4 border-t border-gray-100 flex justify-end gap-3">
          <button onClick={onClose} className="px-4 py-2 border border-gray-300 text-gray-700 rounded-xl text-sm hover:bg-gray-50">Cancel</button>
          <button onClick={handleConfirm} disabled={!effectiveName||saving} className="px-5 py-2 bg-indigo-600 text-white rounded-xl text-sm font-medium hover:bg-indigo-700 disabled:opacity-50 min-w-[120px] text-center">{saving?<Spinner size="sm" color="white" />:'Create Batch'}</button>
        </div>
      </div>
    </div>
  )
}

// ─── Batch Detail Modal ────────────────────────────────────────────────────────
function BatchDetailModal({ batch, batchUnits, canEdit, onClose, onReload }) {
  const [sentDate, setSentDate] = useState(batch.sent_date||new Date().toISOString().split('T')[0])
  const [tracking, setTracking] = useState(batch.tracking_number||'')
  const [resType, setResType]   = useState(batch.resolution_type||'')
  const [resDate, setResDate]   = useState(batch.resolution_date||new Date().toISOString().split('T')[0])
  const [resNotes, setResNotes] = useState(batch.resolution_notes||'')
  const [saving, setSaving]     = useState(false)
  const sm = BATCH_STATUS_META[batch.status]||{label:batch.status,cls:'bg-gray-100 text-gray-600'}

  const handleMarkSent = async () => { setSaving(true); try { await db.inventory.markBatchSent(batch.id,sentDate,tracking); toast.success('Batch marked as sent'); onReload() } catch { toast.error('Failed') } finally { setSaving(false) } }
  const handleMarkResolved = async () => { if(!resType)return; setSaving(true); try { await db.inventory.markBatchResolved(batch.id,resType,resDate,resNotes); toast.success('Batch resolved!'); onReload() } catch { toast.error('Failed') } finally { setSaving(false) } }

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 overflow-y-auto">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl my-4">
        <div className="flex items-center justify-between p-6 border-b border-gray-100">
          <div className="flex items-center gap-3">
            <BrandAvatar name={batch.manufacturer_name} size="lg"/>
            <div><h3 className="text-lg font-bold text-gray-900 font-mono">{batch.batch_number}</h3><div className="flex items-center gap-3 mt-0.5"><span className="text-sm text-gray-600 font-medium">{batch.manufacturer_name}</span><span className={`px-2 py-0.5 rounded-full text-xs font-medium ${sm.cls}`}>{sm.label}</span></div></div>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12"/></svg></button>
        </div>
        {(batch.sent_date||batch.tracking_number) && (
          <div className="px-6 py-3 bg-gray-50 border-b border-gray-100 flex gap-6 text-sm">
            {batch.sent_date && <div><span className="text-gray-400 text-xs">Sent:</span> <span className="font-medium text-gray-700">{fmt(batch.sent_date)}</span></div>}
            {batch.tracking_number && <div><span className="text-gray-400 text-xs">Tracking:</span> <span className="font-mono font-medium text-gray-700">{batch.tracking_number}</span></div>}
          </div>
        )}
        <div className="p-6 border-b border-gray-100">
          <h4 className="text-sm font-semibold text-gray-700 mb-3">Units in Batch ({batchUnits.length})</h4>
          {batchUnits.length===0 ? <p className="text-sm text-gray-400">No units.</p> : (
            <div className="rounded-xl border border-gray-100 overflow-hidden">
              <table className="w-full text-sm"><thead className="bg-gray-50"><tr>{['Product','Serial #','Warranty','RMA Source','Resolution'].map(h=><th key={h} className="px-3 py-2.5 text-left text-xs font-semibold text-gray-500">{h}</th>)}</tr></thead>
                <tbody className="divide-y divide-gray-50">{batchUnits.map(u=><tr key={u.id} className="hover:bg-gray-50"><td className="px-3 py-2.5 text-gray-900 font-medium">{u.product_name||'—'}</td><td className="px-3 py-2.5 font-mono text-xs text-gray-500">{u.serial_number||'—'}</td><td className="px-3 py-2.5"><WarrantyBadge status={u.warranty_status}/></td><td className="px-3 py-2.5 font-mono text-xs text-indigo-600">{u.rma_number||'—'}</td><td className="px-3 py-2.5"><ResolutionBadge type={u.resolution_type}/></td></tr>)}</tbody>
              </table>
            </div>
          )}
        </div>
        {canEdit && batch.status==='draft' && (
          <div className="p-6 border-b border-gray-100">
            <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 space-y-3">
              <h4 className="text-sm font-semibold text-blue-900">Mark as Sent to Manufacturer</h4>
              <div className="grid grid-cols-2 gap-3">
                <div><label className="block text-xs font-medium text-blue-700 mb-1">Sent Date</label><input type="date" value={sentDate} onChange={e=>setSentDate(e.target.value)} className="w-full px-3 py-2 border border-blue-200 rounded-lg text-sm bg-white focus:ring-2 focus:ring-blue-500"/></div>
                <div><label className="block text-xs font-medium text-blue-700 mb-1">Tracking Number</label><input value={tracking} onChange={e=>setTracking(e.target.value)} placeholder="AWB / courier tracking..." className="w-full px-3 py-2 border border-blue-200 rounded-lg text-sm bg-white focus:ring-2 focus:ring-blue-500"/></div>
              </div>
              <button onClick={handleMarkSent} disabled={saving} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl text-sm font-medium hover:bg-blue-700 disabled:opacity-50">{saving?<div className="animate-spin w-4 h-4 border-2 border-white border-t-transparent rounded-full"/>:<svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7"/></svg>}Mark as Sent</button>
            </div>
          </div>
        )}
        {canEdit && batch.status==='sent' && (
          <div className="p-6 border-b border-gray-100">
            <div className="bg-green-50 border border-green-200 rounded-xl p-4 space-y-3">
              <h4 className="text-sm font-semibold text-green-900">Mark Batch as Resolved</h4>
              <div className="grid grid-cols-2 gap-3">
                <div><label className="block text-xs font-medium text-green-700 mb-1">Resolution Type</label><select value={resType} onChange={e=>setResType(e.target.value)} className="w-full px-3 py-2 border border-green-200 rounded-lg text-sm bg-white focus:ring-2 focus:ring-green-500"><option value="">Select...</option><option value="replacement_received">Replacement Units Received</option><option value="credit_note_received">Credit Note Received</option></select></div>
                <div><label className="block text-xs font-medium text-green-700 mb-1">Resolution Date</label><input type="date" value={resDate} onChange={e=>setResDate(e.target.value)} className="w-full px-3 py-2 border border-green-200 rounded-lg text-sm bg-white focus:ring-2 focus:ring-green-500"/></div>
              </div>
              <textarea value={resNotes} onChange={e=>setResNotes(e.target.value)} placeholder="Notes..." rows={2} className="w-full px-3 py-2 border border-green-200 rounded-lg text-sm bg-white resize-none focus:ring-2 focus:ring-green-500"/>
              <button onClick={handleMarkResolved} disabled={!resType||saving} className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-xl text-sm font-medium hover:bg-green-700 disabled:opacity-50">{saving?<div className="animate-spin w-4 h-4 border-2 border-white border-t-transparent rounded-full"/>:<svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>}Mark as Resolved</button>
            </div>
          </div>
        )}
        {batch.status==='resolved' && (
          <div className="p-6 border-b border-gray-100">
            <div className="bg-green-50 border border-green-200 rounded-xl p-4 space-y-1.5">
              <div className="flex items-center gap-2 mb-2"><svg className="w-5 h-5 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg><span className="font-semibold text-green-900">Batch Resolved</span></div>
              <p className="text-sm text-green-800">Resolution: <strong>{batch.resolution_type==='replacement_received'?'Replacement Units Received':'Credit Note Received'}</strong></p>
              {batch.resolution_date && <p className="text-sm text-green-800">Date: <strong>{fmt(batch.resolution_date)}</strong></p>}
              {batch.resolution_notes && <p className="text-sm text-green-800">Notes: <strong>{batch.resolution_notes}</strong></p>}
            </div>
          </div>
        )}
        <div className="px-6 py-4 flex justify-end">
          <button onClick={onClose} className="px-4 py-2 border border-gray-300 text-gray-700 rounded-xl text-sm hover:bg-gray-50">Close</button>
        </div>
      </div>
    </div>
  )
}

import React, { useState, useEffect, useMemo, useCallback } from 'react'
import { db } from '../api/supabaseClient'
import toast from 'react-hot-toast'
import { Button, Spinner, PageHeader } from '../components/ui'
import EmptyState from '../components/EmptyState'
import ConfirmDialog from '../components/ConfirmDialog'
import { useAppearance } from '../contexts/AppearanceContext'

// ─── Constants ────────────────────────────────────────────────────────────────

const STATUS_TABS = ['All', 'Draft', 'Sent', 'Paid', 'Void', 'Quotes']

const STATUS_CLS = {
  draft: 'bg-gray-100 text-gray-600',
  sent:  'bg-blue-100 text-blue-700',
  paid:  'bg-green-100 text-green-700',
  void:  'bg-red-100 text-red-700',
}

const TYPE_CLS = {
  invoice: 'bg-indigo-100 text-indigo-700',
  quote:   'bg-purple-100 text-purple-700',
}

const EMPTY_LINE = () => ({ description: '', qty: 1, unitPrice: 0 })

const EMPTY_FORM = {
  type: 'invoice',
  invoice_number: '',
  rma_number_ref: '',
  ticket_id: '',
  customer_name: '',
  customer_email: '',
  lineItems: [EMPTY_LINE()],
  labour_hours: 0,
  labour_rate: 0,
  discount_pct: 0,
  tax_pct: 0,
  notes: '',
  due_date: '',
  status: 'draft',
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function calcTotals(form) {
  const partsSubtotal = form.lineItems.reduce((sum, li) => sum + (parseFloat(li.qty) || 0) * (parseFloat(li.unitPrice) || 0), 0)
  const labourTotal   = (parseFloat(form.labour_hours) || 0) * (parseFloat(form.labour_rate) || 0)
  const subtotal      = partsSubtotal + labourTotal
  const discountAmt   = subtotal * ((parseFloat(form.discount_pct) || 0) / 100)
  const taxAmt        = (subtotal - discountAmt) * ((parseFloat(form.tax_pct) || 0) / 100)
  const total         = subtotal - discountAmt + taxAmt
  return { partsSubtotal, labourTotal, subtotal, discountAmt, taxAmt, total }
}

function fmt(n) {
  return Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
}

function generateInvoiceNumber(existing = []) {
  const now = new Date()
  const yyyy = now.getFullYear()
  const mm   = String(now.getMonth() + 1).padStart(2, '0')
  const prefix = `INV-${yyyy}${mm}-`
  const serials = existing
    .map(inv => inv.invoice_number)
    .filter(n => n?.startsWith(prefix))
    .map(n => parseInt(n.replace(prefix, ''), 10))
    .filter(n => !isNaN(n))
  const next = serials.length > 0 ? Math.max(...serials) + 1 : 1
  return `${prefix}${String(next).padStart(4, '0')}`
}

// ─── PDF Export ───────────────────────────────────────────────────────────────

function exportPDF(invoice) {
  const totals = calcTotals({
    lineItems: invoice.line_items || [],
    labour_hours: invoice.labour_hours || 0,
    labour_rate: invoice.labour_rate || 0,
    discount_pct: invoice.discount_pct || 0,
    tax_pct: invoice.tax_pct || 0,
  })

  const lineRows = (invoice.line_items || []).map(li => `
    <tr style="border-bottom:1px solid #e5e7eb">
      <td style="padding:8px 12px">${li.description || ''}</td>
      <td style="padding:8px 12px;text-align:right">${li.qty}</td>
      <td style="padding:8px 12px;text-align:right">$${fmt(li.unitPrice)}</td>
      <td style="padding:8px 12px;text-align:right">$${fmt((parseFloat(li.qty)||0)*(parseFloat(li.unitPrice)||0))}</td>
    </tr>`).join('')

  const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8"/>
  <title>${invoice.invoice_number}</title>
  <style>
    body{font-family:sans-serif;color:#111;margin:0;padding:32px}
    h1{font-size:28px;font-weight:700;color:#4f46e5;margin:0}
    .meta{display:flex;justify-content:space-between;margin:24px 0 32px}
    .meta-block p{margin:2px 0;font-size:13px;color:#374151}
    .meta-block .label{font-size:11px;font-weight:600;text-transform:uppercase;color:#9ca3af;letter-spacing:.05em}
    table{width:100%;border-collapse:collapse;font-size:13px}
    thead{background:#f9fafb}
    th{padding:10px 12px;text-align:left;font-size:11px;font-weight:600;text-transform:uppercase;color:#6b7280}
    th:not(:first-child){text-align:right}
    .totals{margin-top:16px;display:flex;justify-content:flex-end}
    .totals table{width:260px}
    .totals td{padding:5px 8px;font-size:13px}
    .totals .total-row td{font-weight:700;font-size:15px;border-top:2px solid #e5e7eb;padding-top:10px}
    .notes{margin-top:32px;font-size:12px;color:#6b7280}
    @media print{body{padding:0}}
  </style>
</head>
<body>
  <h1>${invoice.invoice_number}</h1>
  <div class="meta">
    <div class="meta-block">
      <p class="label">Bill To</p>
      <p><strong>${invoice.customer_name || '—'}</strong></p>
      ${invoice.customer_email ? `<p>${invoice.customer_email}</p>` : ''}
      ${invoice.rma_number_ref ? `<p>RMA: ${invoice.rma_number_ref}</p>` : ''}
    </div>
    <div class="meta-block" style="text-align:right">
      <p class="label">Details</p>
      <p>Type: <strong>${invoice.type === 'quote' ? 'Quote' : 'Invoice'}</strong></p>
      <p>Status: ${invoice.status || 'draft'}</p>
      ${invoice.due_date ? `<p>Due: ${invoice.due_date}</p>` : ''}
    </div>
  </div>
  <table>
    <thead>
      <tr>
        <th>Description</th>
        <th style="text-align:right">Qty</th>
        <th style="text-align:right">Unit Price</th>
        <th style="text-align:right">Total</th>
      </tr>
    </thead>
    <tbody>
      ${lineRows}
      ${totals.labourTotal > 0 ? `<tr style="border-bottom:1px solid #e5e7eb">
        <td style="padding:8px 12px">Labour (${invoice.labour_hours}h @ $${fmt(invoice.labour_rate)}/h)</td>
        <td style="padding:8px 12px;text-align:right">—</td>
        <td style="padding:8px 12px;text-align:right">—</td>
        <td style="padding:8px 12px;text-align:right">$${fmt(totals.labourTotal)}</td>
      </tr>` : ''}
    </tbody>
  </table>
  <div class="totals">
    <table>
      <tr><td>Subtotal</td><td style="text-align:right">$${fmt(totals.subtotal)}</td></tr>
      ${totals.discountAmt > 0 ? `<tr><td>Discount (${invoice.discount_pct}%)</td><td style="text-align:right">−$${fmt(totals.discountAmt)}</td></tr>` : ''}
      ${totals.taxAmt > 0 ? `<tr><td>Tax (${invoice.tax_pct}%)</td><td style="text-align:right">$${fmt(totals.taxAmt)}</td></tr>` : ''}
      <tr class="total-row"><td>Total</td><td style="text-align:right">$${fmt(totals.total)}</td></tr>
    </table>
  </div>
  ${invoice.notes ? `<div class="notes"><strong>Notes:</strong> ${invoice.notes}</div>` : ''}
</body>
</html>`

  const win = window.open('', '_blank')
  if (!win) { toast.error('Pop-up blocked — allow pop-ups and try again'); return }
  win.document.write(html)
  win.document.close()
  win.focus()
  setTimeout(() => win.print(), 400)
}

// ─── Panel Form ───────────────────────────────────────────────────────────────

function InvoicePanel({ form, setForm, onSave, onClose, saving, tickets, invoices, isEdit }) {
  const totals = calcTotals(form)

  const handleRmaLookup = (rmaNum) => {
    setForm(f => ({ ...f, rma_number_ref: rmaNum }))
    if (!rmaNum) return
    const match = tickets.find(t => t.rma_number?.toLowerCase() === rmaNum.toLowerCase())
    if (match) {
      setForm(f => ({
        ...f,
        ticket_id: match.id,
        customer_name: match.customer_name || f.customer_name,
        customer_email: match.customer_email || f.customer_email,
      }))
    }
  }

  const updateLine = (idx, field, value) => {
    setForm(f => {
      const items = [...f.lineItems]
      items[idx] = { ...items[idx], [field]: value }
      return { ...f, lineItems: items }
    })
  }

  const addLine = () => setForm(f => ({ ...f, lineItems: [...f.lineItems, EMPTY_LINE()] }))
  const removeLine = (idx) => setForm(f => ({ ...f, lineItems: f.lineItems.filter((_, i) => i !== idx) }))

  return (
    <div className="fixed inset-0 z-50 flex">
      {/* Backdrop */}
      <div className="flex-1 bg-black/30 backdrop-blur-sm" onClick={onClose} />

      {/* Panel */}
      <div className="w-full max-w-xl bg-white shadow-2xl flex flex-col h-full overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200 flex-shrink-0">
          <h2 className="text-base font-semibold text-gray-900">
            {isEdit ? 'Edit Invoice / Quote' : 'New Invoice / Quote'}
          </h2>
          <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-gray-100 transition-colors">
            <svg className="w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        {/* Scrollable body */}
        <div className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
          {/* Type */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Type</label>
            <select
              value={form.type}
              onChange={e => setForm(f => ({ ...f, type: e.target.value }))}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm bg-white focus:outline-none focus:ring-2 focus:ring-indigo-500"
            >
              <option value="invoice">Invoice</option>
              <option value="quote">Quote</option>
            </select>
          </div>

          {/* Invoice Number */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Invoice / Quote Number</label>
            <input
              type="text"
              value={form.invoice_number}
              onChange={e => setForm(f => ({ ...f, invoice_number: e.target.value }))}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
          </div>

          {/* RMA Link */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Link to RMA Number (optional)</label>
            <input
              type="text"
              placeholder="e.g. RMA-01012025-0001"
              value={form.rma_number_ref}
              onChange={e => handleRmaLookup(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
            {form.ticket_id && (
              <p className="text-xs text-green-600 mt-1">Ticket found — customer details auto-filled.</p>
            )}
          </div>

          {/* Customer */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Customer Name</label>
              <input
                type="text"
                value={form.customer_name}
                onChange={e => setForm(f => ({ ...f, customer_name: e.target.value }))}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Customer Email</label>
              <input
                type="email"
                value={form.customer_email}
                onChange={e => setForm(f => ({ ...f, customer_email: e.target.value }))}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>
          </div>

          {/* Line Items */}
          <div>
            <div className="flex items-center justify-between mb-2">
              <label className="text-sm font-medium text-gray-700">Line Items</label>
              <button onClick={addLine} className="text-xs text-indigo-600 hover:text-indigo-800 font-medium">+ Add Row</button>
            </div>
            <div className="border border-gray-200 rounded-lg overflow-hidden">
              <table className="w-full text-xs">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-2 py-2 text-left text-gray-500 font-medium">Description</th>
                    <th className="px-2 py-2 text-right text-gray-500 font-medium w-14">Qty</th>
                    <th className="px-2 py-2 text-right text-gray-500 font-medium w-20">Unit $</th>
                    <th className="px-2 py-2 text-right text-gray-500 font-medium w-20">Total</th>
                    <th className="w-8" />
                  </tr>
                </thead>
                <tbody>
                  {form.lineItems.map((li, idx) => (
                    <tr key={idx} className="border-t border-gray-100">
                      <td className="px-2 py-1.5">
                        <input
                          type="text"
                          value={li.description}
                          onChange={e => updateLine(idx, 'description', e.target.value)}
                          placeholder="Item description"
                          className="w-full bg-transparent focus:outline-none focus:ring-1 focus:ring-indigo-400 rounded px-1 py-0.5"
                        />
                      </td>
                      <td className="px-2 py-1.5">
                        <input
                          type="number"
                          min="0"
                          value={li.qty}
                          onChange={e => updateLine(idx, 'qty', e.target.value)}
                          className="w-full bg-transparent text-right focus:outline-none focus:ring-1 focus:ring-indigo-400 rounded px-1 py-0.5"
                        />
                      </td>
                      <td className="px-2 py-1.5">
                        <input
                          type="number"
                          min="0"
                          step="0.01"
                          value={li.unitPrice}
                          onChange={e => updateLine(idx, 'unitPrice', e.target.value)}
                          className="w-full bg-transparent text-right focus:outline-none focus:ring-1 focus:ring-indigo-400 rounded px-1 py-0.5"
                        />
                      </td>
                      <td className="px-2 py-1.5 text-right text-gray-600">
                        ${fmt((parseFloat(li.qty)||0) * (parseFloat(li.unitPrice)||0))}
                      </td>
                      <td className="px-1 py-1.5">
                        {form.lineItems.length > 1 && (
                          <button
                            onClick={() => removeLine(idx)}
                            className="text-gray-300 hover:text-red-500 transition-colors"
                          >
                            <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                            </svg>
                          </button>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Labour */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Labour Hours</label>
              <input
                type="number"
                min="0"
                step="0.25"
                value={form.labour_hours}
                onChange={e => setForm(f => ({ ...f, labour_hours: e.target.value }))}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Labour Rate ($/h)</label>
              <input
                type="number"
                min="0"
                step="0.01"
                value={form.labour_rate}
                onChange={e => setForm(f => ({ ...f, labour_rate: e.target.value }))}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>
          </div>

          {/* Discount + Tax */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Discount %</label>
              <input
                type="number"
                min="0"
                max="100"
                step="0.1"
                value={form.discount_pct}
                onChange={e => setForm(f => ({ ...f, discount_pct: e.target.value }))}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Tax %</label>
              <input
                type="number"
                min="0"
                max="100"
                step="0.1"
                value={form.tax_pct}
                onChange={e => setForm(f => ({ ...f, tax_pct: e.target.value }))}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
              />
            </div>
          </div>

          {/* Totals summary */}
          <div className="bg-gray-50 rounded-lg p-4 text-sm space-y-1.5">
            <div className="flex justify-between text-gray-600">
              <span>Parts Subtotal</span><span>${fmt(totals.partsSubtotal)}</span>
            </div>
            {totals.labourTotal > 0 && (
              <div className="flex justify-between text-gray-600">
                <span>Labour</span><span>${fmt(totals.labourTotal)}</span>
              </div>
            )}
            <div className="flex justify-between text-gray-600 border-t border-gray-200 pt-1.5">
              <span>Subtotal</span><span>${fmt(totals.subtotal)}</span>
            </div>
            {totals.discountAmt > 0 && (
              <div className="flex justify-between text-gray-500">
                <span>Discount ({form.discount_pct}%)</span><span>−${fmt(totals.discountAmt)}</span>
              </div>
            )}
            {totals.taxAmt > 0 && (
              <div className="flex justify-between text-gray-500">
                <span>Tax ({form.tax_pct}%)</span><span>${fmt(totals.taxAmt)}</span>
              </div>
            )}
            <div className="flex justify-between font-bold text-gray-900 text-base border-t border-gray-300 pt-2 mt-1">
              <span>Total</span><span>${fmt(totals.total)}</span>
            </div>
          </div>

          {/* Notes */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Notes</label>
            <textarea
              rows={3}
              value={form.notes}
              onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
              placeholder="Additional notes or payment terms..."
              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm resize-none focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
          </div>

          {/* Due Date */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Due Date</label>
            <input
              type="date"
              value={form.due_date}
              onChange={e => setForm(f => ({ ...f, due_date: e.target.value }))}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
          </div>
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-gray-200 flex items-center justify-end gap-3 flex-shrink-0">
          <Button variant="secondary" onClick={onClose} disabled={saving}>Cancel</Button>
          <Button onClick={onSave} loading={saving}>
            {isEdit ? 'Save Changes' : 'Create'}
          </Button>
        </div>
      </div>
    </div>
  )
}

// ─── Main Component ───────────────────────────────────────────────────────────

export default function Invoices({ currentUserRole, currentUserEmail, currentUserPermissions }) {
  const { formatDate } = useAppearance()

  const canDo = (s, a) =>
    ['super_admin', 'admin'].includes(currentUserRole) ||
    currentUserPermissions?.[s]?.[a]

  const isAdmin    = ['super_admin', 'admin'].includes(currentUserRole)
  const isManager  = currentUserRole === 'manager' || isAdmin
  const isTech     = currentUserRole === 'technician'
  const isViewer   = currentUserRole === 'viewer'

  const [invoices, setInvoices]       = useState([])
  const [tickets, setTickets]         = useState([])
  const [loading, setLoading]         = useState(true)
  const [tableMissing, setTableMissing] = useState(false)
  const [activeTab, setActiveTab]     = useState('All')
  const [panelOpen, setPanelOpen]     = useState(false)
  const [editingId, setEditingId]     = useState(null)
  const [form, setForm]               = useState(EMPTY_FORM)
  const [saving, setSaving]           = useState(false)
  const [confirmDialog, setConfirmDialog] = useState({ open: false, title: '', message: '', onConfirm: null })

  const openConfirm = (title, message, onConfirm) =>
    setConfirmDialog({ open: true, title, message, onConfirm })
  const closeConfirm = () =>
    setConfirmDialog(d => ({ ...d, open: false, onConfirm: null }))

  // ─── Load data ──────────────────────────────────────────────────────────────
  const load = useCallback(async () => {
    setLoading(true)
    try {
      const [invRes, tickRes] = await Promise.all([
        db.invoices.list(),
        db.rmaTickets.list(),
      ])
      if (invRes?.missing) {
        setTableMissing(true)
        setInvoices([])
      } else {
        setTableMissing(false)
        setInvoices(invRes?.data ?? invRes ?? [])
      }
      setTickets(tickRes)
    } catch (err) {
      console.error(err)
      toast.error('Failed to load invoices')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => { load() }, [load])

  // ─── Filtered list ───────────────────────────────────────────────────────────
  const visibleInvoices = useMemo(() => {
    let list = invoices

    // Technicians only see invoices linked to their assigned tickets
    if (isTech) {
      const myTicketIds = new Set(tickets.filter(t => t.assigned_technician === currentUserEmail).map(t => t.id))
      list = list.filter(inv => inv.ticket_id && myTicketIds.has(inv.ticket_id))
    }

    if (activeTab === 'All') return list
    if (activeTab === 'Quotes') return list.filter(inv => inv.type === 'quote')
    return list.filter(inv => inv.status === activeTab.toLowerCase())
  }, [invoices, tickets, activeTab, isTech, currentUserEmail])

  // ─── Open panel ──────────────────────────────────────────────────────────────
  const openCreate = () => {
    const newNumber = generateInvoiceNumber(invoices)
    setForm({ ...EMPTY_FORM, invoice_number: newNumber })
    setEditingId(null)
    setPanelOpen(true)
  }

  const openEdit = (inv) => {
    setForm({
      type: inv.type || 'invoice',
      invoice_number: inv.invoice_number || '',
      rma_number_ref: inv.rma_number_ref || '',
      ticket_id: inv.ticket_id || '',
      customer_name: inv.customer_name || '',
      customer_email: inv.customer_email || '',
      lineItems: inv.line_items?.length ? inv.line_items : [EMPTY_LINE()],
      labour_hours: inv.labour_hours || 0,
      labour_rate: inv.labour_rate || 0,
      discount_pct: inv.discount_pct || 0,
      tax_pct: inv.tax_pct || 0,
      notes: inv.notes || '',
      due_date: inv.due_date ? inv.due_date.split('T')[0] : '',
      status: inv.status || 'draft',
    })
    setEditingId(inv.id)
    setPanelOpen(true)
  }

  // ─── Save ─────────────────────────────────────────────────────────────────
  const handleSave = async () => {
    if (!form.invoice_number.trim()) { toast.error('Invoice number is required'); return }
    if (!form.customer_name.trim())  { toast.error('Customer name is required'); return }

    setSaving(true)
    const totals = calcTotals(form)
    const payload = {
      type: form.type,
      invoice_number: form.invoice_number.trim(),
      rma_number_ref: form.rma_number_ref || null,
      ticket_id: form.ticket_id || null,
      customer_name: form.customer_name.trim(),
      customer_email: form.customer_email.trim() || null,
      line_items: form.lineItems,
      labour_hours: parseFloat(form.labour_hours) || 0,
      labour_rate: parseFloat(form.labour_rate) || 0,
      discount_pct: parseFloat(form.discount_pct) || 0,
      tax_pct: parseFloat(form.tax_pct) || 0,
      notes: form.notes || null,
      due_date: form.due_date || null,
      status: form.status,
      total: totals.total,
      created_by: currentUserEmail,
    }

    try {
      if (editingId) {
        const res = await db.invoices.update(editingId, payload)
        if (res?.missing) { setTableMissing(true); toast.error('Invoices table not found'); return }
        setInvoices(prev => prev.map(inv => inv.id === editingId ? { ...inv, ...payload } : inv))
        toast.success('Invoice updated')
      } else {
        const res = await db.invoices.create(payload)
        if (res?.missing) { setTableMissing(true); toast.error('Invoices table not found'); return }
        setInvoices(prev => [res, ...prev])
        toast.success(`${form.type === 'quote' ? 'Quote' : 'Invoice'} created`)
      }
      setPanelOpen(false)
    } catch (err) {
      console.error(err)
      toast.error(err.message || 'Save failed')
    } finally {
      setSaving(false)
    }
  }

  // ─── Status changes ──────────────────────────────────────────────────────────
  const updateStatus = async (inv, newStatus) => {
    try {
      await db.invoices.update(inv.id, { status: newStatus })
      setInvoices(prev => prev.map(i => i.id === inv.id ? { ...i, status: newStatus } : i))
      toast.success(`Marked as ${newStatus}`)
    } catch (err) {
      toast.error(err.message || 'Failed to update status')
    }
  }

  // ─── Delete ──────────────────────────────────────────────────────────────────
  const handleDelete = (inv) => {
    openConfirm(
      'Delete Invoice',
      `Delete ${inv.invoice_number}? This cannot be undone.`,
      async () => {
        closeConfirm()
        try {
          await db.invoices.delete(inv.id)
          setInvoices(prev => prev.filter(i => i.id !== inv.id))
          toast.success('Invoice deleted')
        } catch (err) {
          toast.error(err.message || 'Delete failed')
        }
      }
    )
  }

  // ─── Render ──────────────────────────────────────────────────────────────────
  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[320px]">
        <Spinner size="lg" />
      </div>
    )
  }

  return (
    <div className="p-6">
      {/* Migration banner */}
      {tableMissing && (
        <div className="mb-6 flex items-start gap-3 bg-amber-50 border border-amber-200 rounded-xl p-4 text-sm">
          <svg className="w-5 h-5 text-amber-500 flex-shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
          </svg>
          <div>
            <p className="font-semibold text-amber-800">Invoices table not found</p>
            <p className="text-amber-700 mt-0.5">
              Run the invoices migration in your Supabase SQL editor to enable this feature.
              Create the <code className="font-mono bg-amber-100 px-1 rounded">invoices</code> table with the columns used by this page.
            </p>
          </div>
        </div>
      )}

      {/* Header */}
      <PageHeader
        title="Invoices & Quotes"
        subtitle="Manage invoices and quotes for RMA jobs"
        className="mb-6"
      >
        {!isViewer && !tableMissing && (
          <Button onClick={openCreate}>
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
            </svg>
            New Invoice / Quote
          </Button>
        )}
      </PageHeader>

      {/* Status filter tabs */}
      <div className="flex gap-1 mb-6 bg-gray-100 rounded-xl p-1 w-fit">
        {STATUS_TABS.map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
              activeTab === tab
                ? 'bg-white text-gray-900 shadow-sm'
                : 'text-gray-500 hover:text-gray-700'
            }`}
          >
            {tab}
            {tab !== 'All' && (
              <span className="ml-1.5 text-xs text-gray-400">
                ({tab === 'Quotes'
                  ? invoices.filter(i => i.type === 'quote').length
                  : invoices.filter(i => i.status === tab.toLowerCase()).length})
              </span>
            )}
          </button>
        ))}
      </div>

      {/* Table */}
      {visibleInvoices.length === 0 ? (
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm">
          <EmptyState
            title={tableMissing ? 'Invoices table not set up' : 'No invoices found'}
            description={tableMissing ? 'Run the migration to get started.' : 'Try a different filter or create a new invoice.'}
            action={!isViewer && !tableMissing ? openCreate : undefined}
            actionLabel="New Invoice / Quote"
          />
        </div>
      ) : (
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b border-gray-200">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Invoice #</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Type</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Customer</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Ticket</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Status</th>
                  <th className="px-4 py-3 text-right text-xs font-semibold text-gray-500 uppercase tracking-wide">Total</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Due Date</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wide">Created</th>
                  <th className="px-4 py-3" />
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {visibleInvoices.map(inv => (
                  <InvoiceRow
                    key={inv.id}
                    inv={inv}
                    isAdmin={isAdmin}
                    isManager={isManager}
                    isTech={isTech}
                    formatDate={formatDate}
                    onEdit={() => openEdit(inv)}
                    onExportPDF={() => exportPDF(inv)}
                    onMarkSent={() => openConfirm('Mark as Sent', `Mark ${inv.invoice_number} as Sent?`, () => { closeConfirm(); updateStatus(inv, 'sent') })}
                    onMarkPaid={() => openConfirm('Mark as Paid', `Mark ${inv.invoice_number} as Paid?`, () => { closeConfirm(); updateStatus(inv, 'paid') })}
                    onVoid={()    => openConfirm('Void Invoice', `Void ${inv.invoice_number}?`, () => { closeConfirm(); updateStatus(inv, 'void') })}
                    onDelete={isAdmin ? () => handleDelete(inv) : undefined}
                  />
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Slide-over panel */}
      {panelOpen && (
        <InvoicePanel
          form={form}
          setForm={setForm}
          onSave={handleSave}
          onClose={() => setPanelOpen(false)}
          saving={saving}
          tickets={tickets}
          invoices={invoices}
          isEdit={!!editingId}
        />
      )}

      {/* Confirm dialog */}
      <ConfirmDialog
        open={confirmDialog.open}
        title={confirmDialog.title}
        message={confirmDialog.message}
        confirmLabel="Confirm"
        confirmClass="bg-indigo-600 hover:bg-indigo-700 text-white"
        onConfirm={confirmDialog.onConfirm}
        onCancel={closeConfirm}
      />
    </div>
  )
}

// ─── Invoice Row ─────────────────────────────────────────────────────────────

function InvoiceRow({ inv, isAdmin, isManager, isTech, formatDate, onEdit, onExportPDF, onMarkSent, onMarkPaid, onVoid, onDelete }) {
  const [menuOpen, setMenuOpen] = useState(false)

  const canChangeStatus = isManager
  const canEdit = isManager
  const canDelete = isAdmin

  return (
    <tr className="hover:bg-gray-50 transition-colors">
      <td className="px-4 py-3 font-mono text-xs font-semibold text-indigo-700">{inv.invoice_number}</td>
      <td className="px-4 py-3">
        <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${TYPE_CLS[inv.type] || 'bg-gray-100 text-gray-600'}`}>
          {inv.type === 'quote' ? 'Quote' : 'Invoice'}
        </span>
      </td>
      <td className="px-4 py-3">
        <p className="font-medium text-gray-800 truncate max-w-[160px]">{inv.customer_name || '—'}</p>
        {inv.customer_email && <p className="text-xs text-gray-400 truncate max-w-[160px]">{inv.customer_email}</p>}
      </td>
      <td className="px-4 py-3 font-mono text-xs text-gray-500">{inv.rma_number_ref || '—'}</td>
      <td className="px-4 py-3">
        <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${STATUS_CLS[inv.status] || 'bg-gray-100 text-gray-600'}`}>
          {inv.status ? inv.status.charAt(0).toUpperCase() + inv.status.slice(1) : 'Draft'}
        </span>
      </td>
      <td className="px-4 py-3 text-right font-semibold text-gray-800">${fmt(inv.total)}</td>
      <td className="px-4 py-3 text-gray-500 text-xs">{inv.due_date ? formatDate(inv.due_date) : '—'}</td>
      <td className="px-4 py-3 text-gray-400 text-xs">{inv.created_at ? formatDate(inv.created_at) : '—'}</td>
      <td className="px-4 py-3">
        <div className="flex items-center justify-end gap-2 relative">
          <button
            onClick={onExportPDF}
            title="Export PDF"
            className="p-1.5 rounded-lg text-gray-400 hover:text-indigo-600 hover:bg-indigo-50 transition-colors"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
          </button>

          {(canEdit || canChangeStatus || canDelete) && (
            <div className="relative">
              <button
                onClick={() => setMenuOpen(o => !o)}
                className="p-1.5 rounded-lg text-gray-400 hover:text-gray-700 hover:bg-gray-100 transition-colors"
              >
                <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                  <path d="M10 6a2 2 0 110-4 2 2 0 010 4zM10 12a2 2 0 110-4 2 2 0 010 4zM10 18a2 2 0 110-4 2 2 0 010 4z" />
                </svg>
              </button>
              {menuOpen && (
                <>
                  <div className="fixed inset-0 z-30" onClick={() => setMenuOpen(false)} />
                  <div className="absolute right-0 mt-1 w-44 bg-white border border-gray-200 rounded-xl shadow-xl z-40 py-1 text-sm">
                    {canEdit && (
                      <button onClick={() => { setMenuOpen(false); onEdit() }}
                        className="w-full text-left px-4 py-2 hover:bg-gray-50 text-gray-700">Edit</button>
                    )}
                    {canChangeStatus && inv.status === 'draft' && (
                      <button onClick={() => { setMenuOpen(false); onMarkSent() }}
                        className="w-full text-left px-4 py-2 hover:bg-gray-50 text-gray-700">Mark Sent</button>
                    )}
                    {canChangeStatus && inv.status === 'sent' && (
                      <button onClick={() => { setMenuOpen(false); onMarkPaid() }}
                        className="w-full text-left px-4 py-2 hover:bg-gray-50 text-gray-700">Mark Paid</button>
                    )}
                    {canChangeStatus && inv.status !== 'void' && inv.status !== 'paid' && (
                      <button onClick={() => { setMenuOpen(false); onVoid() }}
                        className="w-full text-left px-4 py-2 hover:bg-red-50 text-red-600">Void</button>
                    )}
                    {canDelete && (
                      <button onClick={() => { setMenuOpen(false); onDelete() }}
                        className="w-full text-left px-4 py-2 hover:bg-red-50 text-red-600 border-t border-gray-100">Delete</button>
                    )}
                  </div>
                </>
              )}
            </div>
          )}
        </div>
      </td>
    </tr>
  )
}

import React, { useState } from 'react'
import { auth } from '../api/supabaseClient'
import { useAppearance } from '../contexts/AppearanceContext'

export default function Login({ onLogin }) {
  const { loginBg } = useAppearance()
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)

  const [forgotMode, setForgotMode] = useState(false)
  const [forgotEmail, setForgotEmail] = useState('')
  const [forgotSent, setForgotSent] = useState(false)
  const [forgotError, setForgotError] = useState('')
  const [forgotLoading, setForgotLoading] = useState(false)

  const handleSubmit = async (e) => {
    e.preventDefault()
    setError('')
    setLoading(true)
    try {
      await onLogin(email, password)
    } catch (err) {
      setError(err.message || 'Login failed')
    } finally {
      setLoading(false)
    }
  }

  const handleForgotSubmit = async (e) => {
    e.preventDefault()
    setForgotError('')
    setForgotLoading(true)
    try {
      await auth.resetPassword(forgotEmail)
      setForgotSent(true)
    } catch (err) {
      setForgotError(err.message || 'Failed to send reset email')
    } finally {
      setForgotLoading(false)
    }
  }

  const backToLogin = () => {
    setForgotMode(false)
    setForgotSent(false)
    setForgotEmail('')
    setForgotError('')
  }

  return (
    <div className="min-h-screen flex items-center justify-center p-4" style={{ background: loginBg || '#eef2ff' }}>
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-8">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-indigo-600 rounded-xl flex items-center justify-center mx-auto mb-4">
            <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
          </div>
          <h1 className="text-3xl font-bold text-gray-900">myRMA</h1>
          <p className="text-gray-600 mt-2">
            {forgotMode ? 'Reset your password' : 'RMA Management System'}
          </p>
        </div>

        {!forgotMode ? (
          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Email</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent"
                placeholder="admin@example.com"
                required
              />
            </div>

            <div>
              <div className="flex items-center justify-between mb-2">
                <label className="block text-sm font-medium text-gray-700">Password</label>
                <button
                  type="button"
                  onClick={() => { setForgotMode(true); setForgotEmail(email) }}
                  className="text-sm text-indigo-600 hover:text-indigo-800 font-medium"
                >
                  Forgot password?
                </button>
              </div>
              <div className="relative">
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full px-4 py-3 pr-12 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent"
                  placeholder="••••••••"
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(v => !v)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                  tabIndex={-1}
                >
                  {showPassword ? (
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268 2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21" />
                    </svg>
                  ) : (
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                    </svg>
                  )}
                </button>
              </div>
            </div>

            {error && (
              <div className="bg-red-50 text-red-600 px-4 py-3 rounded-lg text-sm">
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-indigo-600 text-white py-3 rounded-lg font-medium hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              {loading ? 'Signing in...' : 'Sign In'}
            </button>
          </form>
        ) : (
          <div className="space-y-6">
            {!forgotSent ? (
              <form onSubmit={handleForgotSubmit} className="space-y-6">
                <p className="text-sm text-gray-600">
                  Enter your email address and we'll send you a link to reset your password.
                </p>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Email</label>
                  <input
                    type="email"
                    value={forgotEmail}
                    onChange={(e) => setForgotEmail(e.target.value)}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent"
                    placeholder="your@email.com"
                    required
                    autoFocus
                  />
                </div>

                {forgotError && (
                  <div className="bg-red-50 text-red-600 px-4 py-3 rounded-lg text-sm">
                    {forgotError}
                  </div>
                )}

                <button
                  type="submit"
                  disabled={forgotLoading}
                  className="w-full bg-indigo-600 text-white py-3 rounded-lg font-medium hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  {forgotLoading ? 'Sending...' : 'Send Reset Link'}
                </button>

                <button
                  type="button"
                  onClick={backToLogin}
                  className="w-full text-sm text-gray-500 hover:text-gray-700 text-center"
                >
                  ← Back to login
                </button>
              </form>
            ) : (
              <div className="space-y-6 text-center">
                <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto">
                  <svg className="w-8 h-8 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                  </svg>
                </div>
                <div>
                  <p className="text-gray-800 font-medium">Check your inbox</p>
                  <p className="text-sm text-gray-500 mt-1">
                    A password reset link has been sent to <span className="font-medium">{forgotEmail}</span>
                  </p>
                </div>
                <button
                  type="button"
                  onClick={backToLogin}
                  className="w-full text-sm text-indigo-600 hover:text-indigo-800 font-medium"
                >
                  ← Back to login
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

import React, { useState, useEffect, useCallback, useMemo } from 'react'
import { db } from '../api/supabaseClient'
import toast from 'react-hot-toast'
import ConfirmDialog from '../components/ConfirmDialog'
import { Button, Spinner, PageHeader } from '../components/ui'
import { useAppearance } from '../contexts/AppearanceContext'

// ─── Utility ──────────────────────────────────────────────────────────────────
function downloadCSV(rows, columns, filename) {
  if (!rows.length) { toast('No data to export'); return }
  const headers = columns.map(c => c.label)
  const escape = v => { const s = String(v ?? '').replace(/"/g, '""'); return s.includes(',') || s.includes('\n') || s.includes('"') ? `"${s}"` : s }
  const csv = [headers.join(','), ...rows.map(r => columns.map(c => escape(r[c.key] ?? '')).join(','))].join('\r\n')
  const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' })
  const url = URL.createObjectURL(blob)
  const a = Object.assign(document.createElement('a'), { href: url, download: filename })
  document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url)
  toast.success(`Exported ${rows.length} rows`)
}

const MIGRATION_SQL = `-- Run in Supabase SQL Editor to enable parts inventory:

CREATE TABLE IF NOT EXISTS parts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  part_name TEXT NOT NULL,
  part_number TEXT,
  quantity INT NOT NULL DEFAULT 0,
  unit_cost NUMERIC(10,2) DEFAULT 0,
  supplier TEXT,
  reorder_level INT NOT NULL DEFAULT 5,
  location TEXT,
  notes TEXT,
  created_date TIMESTAMPTZ DEFAULT now(),
  updated_date TIMESTAMPTZ DEFAULT now()
);`

const EMPTY_FORM = {
  part_name: '',
  part_number: '',
  quantity: '',
  unit_cost: '',
  supplier: '',
  reorder_level: '',
  location: '',
  notes: '',
}

// ─── Sort Button ──────────────────────────────────────────────────────────────
function SortBtn({ label, sortKey, activeSortKey, activeSortDir, onSort }) {
  const isActive = activeSortKey === sortKey
  return (
    <button onClick={() => onSort(sortKey)} className="flex items-center gap-1 hover:text-gray-900 transition-colors">
      {label}
      {isActive
        ? activeSortDir === 'asc'
          ? <svg className="w-3 h-3 text-indigo-600 ml-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7"/></svg>
          : <svg className="w-3 h-3 text-indigo-600 ml-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7"/></svg>
        : <svg className="w-3 h-3 text-gray-300 ml-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16V4m0 0L3 8m4-4l4 4m6 0v12m0 0l4-4m-4 4l-4-4"/></svg>
      }
    </button>
  )
}

// ─── Part Form Modal ──────────────────────────────────────────────────────────
function PartModal({ part, onSave, onClose, saving }) {
  const [form, setForm] = useState(part ? {
    part_name: part.part_name || '',
    part_number: part.part_number || '',
    quantity: String(part.quantity ?? ''),
    unit_cost: String(part.unit_cost ?? ''),
    supplier: part.supplier || '',
    reorder_level: String(part.reorder_level ?? ''),
    location: part.location || '',
    notes: part.notes || '',
  } : EMPTY_FORM)

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }))

  const handleSubmit = (e) => {
    e.preventDefault()
    if (!form.part_name.trim()) { toast.error('Part name is required'); return }
    if (form.quantity === '' || isNaN(Number(form.quantity))) { toast.error('Quantity is required'); return }
    if (form.unit_cost === '' || isNaN(Number(form.unit_cost))) { toast.error('Unit cost is required'); return }
    if (form.reorder_level === '' || isNaN(Number(form.reorder_level))) { toast.error('Reorder level is required'); return }
    onSave({
      part_name: form.part_name.trim(),
      part_number: form.part_number.trim() || null,
      quantity: parseInt(form.quantity, 10),
      unit_cost: parseFloat(form.unit_cost),
      supplier: form.supplier.trim() || null,
      reorder_level: parseInt(form.reorder_level, 10),
      location: form.location.trim() || null,
      notes: form.notes.trim() || null,
    })
  }

  const field = 'w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent'
  const label = 'block text-sm font-medium text-gray-700 mb-1'

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-lg mx-4 max-h-[90vh] overflow-y-auto">
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100">
          <h2 className="text-base font-semibold text-gray-900">{part ? 'Edit Part' : 'Add Part'}</h2>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12"/></svg>
          </button>
        </div>
        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-2">
              <label className={label}>Part Name <span className="text-red-500">*</span></label>
              <input value={form.part_name} onChange={e => set('part_name', e.target.value)} className={field} placeholder="e.g. Capacitor 100µF" required />
            </div>
            <div>
              <label className={label}>Part Number</label>
              <input value={form.part_number} onChange={e => set('part_number', e.target.value)} className={field} placeholder="e.g. CAP-100UF-25V" />
            </div>
            <div>
              <label className={label}>Location</label>
              <input value={form.location} onChange={e => set('location', e.target.value)} className={field} placeholder="e.g. Shelf A-3" />
            </div>
            <div>
              <label className={label}>Quantity <span className="text-red-500">*</span></label>
              <input type="number" min="0" value={form.quantity} onChange={e => set('quantity', e.target.value)} className={field} placeholder="0" required />
            </div>
            <div>
              <label className={label}>Reorder Level <span className="text-red-500">*</span></label>
              <input type="number" min="0" value={form.reorder_level} onChange={e => set('reorder_level', e.target.value)} className={field} placeholder="5" required />
            </div>
            <div>
              <label className={label}>Unit Cost ($) <span className="text-red-500">*</span></label>
              <input type="number" min="0" step="0.01" value={form.unit_cost} onChange={e => set('unit_cost', e.target.value)} className={field} placeholder="0.00" required />
            </div>
            <div>
              <label className={label}>Supplier</label>
              <input value={form.supplier} onChange={e => set('supplier', e.target.value)} className={field} placeholder="Supplier name" />
            </div>
            <div className="col-span-2">
              <label className={label}>Notes</label>
              <textarea value={form.notes} onChange={e => set('notes', e.target.value)} rows={2} className={`${field} resize-none`} placeholder="Optional notes…" />
            </div>
          </div>
          <div className="flex justify-end gap-3 pt-2">
            <button type="button" onClick={onClose} className="px-4 py-2 text-sm font-medium text-gray-700 border border-gray-200 rounded-xl hover:bg-gray-50 transition-colors">Cancel</button>
            <Button type="submit" loading={saving}>{part ? 'Save Changes' : 'Add Part'}</Button>
          </div>
        </form>
      </div>
    </div>
  )
}

// ─── Main Component ───────────────────────────────────────────────────────────
export default function PartsInventory({ currentUserRole, currentUserEmail, currentUserPermissions }) {
  const { formatDate } = useAppearance()

  const canDo = (action) => {
    if (currentUserRole === 'super_admin' || currentUserRole === 'admin') return true
    return currentUserPermissions?.parts?.[action] === true
  }
  const canAdd    = canDo('create') || currentUserRole === 'manager'
  const canEdit   = canDo('edit') || currentUserRole === 'manager'
  const canDelete = currentUserRole === 'super_admin' || currentUserRole === 'admin'
  const canAdjust = canAdd || currentUserRole === 'technician' || canDo('adjust_stock')
  const canExport = canAdd || canDo('export')

  const [parts, setParts]               = useState([])
  const [loading, setLoading]           = useState(true)
  const [tableMissing, setTableMissing] = useState(false)
  const [search, setSearch]             = useState('')
  const [sortKey, setSortKey]           = useState('part_name')
  const [sortDir, setSortDir]           = useState('asc')
  const [showLowOnly, setShowLowOnly]   = useState(false)
  const [showModal, setShowModal]       = useState(false)
  const [editingPart, setEditingPart]   = useState(null)
  const [saving, setSaving]             = useState(false)
  const [adjusting, setAdjusting]       = useState({})
  const [confirmDialog, setConfirmDialog] = useState({ open: false, title: '', message: '', onConfirm: null })

  const openConfirm = (title, message, onConfirm) => setConfirmDialog({ open: true, title, message, onConfirm })
  const closeConfirm = () => setConfirmDialog(d => ({ ...d, open: false }))

  const load = useCallback(async () => {
    setLoading(true)
    try {
      const res = await db.parts.list()
      if (res.missing) { setTableMissing(true); setLoading(false); return }
      setTableMissing(false)
      setParts(res.data || [])
    } catch { toast.error('Failed to load parts') }
    finally { setLoading(false) }
  }, [])

  useEffect(() => { load() }, [load])

  const handleSort = (key) => {
    if (sortKey === key) setSortDir(d => d === 'asc' ? 'desc' : 'asc')
    else { setSortKey(key); setSortDir('asc') }
  }

  const lowStockParts = useMemo(() => parts.filter(p => p.quantity <= p.reorder_level), [parts])

  const filtered = useMemo(() => {
    let list = [...parts]
    if (showLowOnly) list = list.filter(p => p.quantity <= p.reorder_level)
    if (search.trim()) {
      const q = search.toLowerCase()
      list = list.filter(p =>
        p.part_name?.toLowerCase().includes(q) ||
        p.part_number?.toLowerCase().includes(q)
      )
    }
    return list.sort((a, b) => {
      let av, bv
      if (sortKey === 'quantity') { av = a.quantity ?? 0; bv = b.quantity ?? 0 }
      else { av = (a.part_name || '').toLowerCase(); bv = (b.part_name || '').toLowerCase() }
      if (av < bv) return sortDir === 'asc' ? -1 : 1
      if (av > bv) return sortDir === 'asc' ? 1 : -1
      return 0
    })
  }, [parts, search, showLowOnly, sortKey, sortDir])

  const handleSave = async (data) => {
    setSaving(true)
    try {
      if (editingPart) {
        await db.parts.update(editingPart.id, data)
        toast.success('Part updated')
      } else {
        await db.parts.create(data)
        toast.success('Part added')
      }
      setShowModal(false)
      setEditingPart(null)
      await load()
    } catch (err) {
      toast.error(err.message || 'Failed to save part')
    } finally { setSaving(false) }
  }

  const handleDelete = (part) => {
    openConfirm(
      'Delete Part',
      `Are you sure you want to delete "${part.part_name}"? This cannot be undone.`,
      async () => {
        closeConfirm()
        try {
          await db.parts.delete(part.id)
          toast.success('Part deleted')
          await load()
        } catch { toast.error('Failed to delete part') }
      }
    )
  }

  const handleAdjust = async (part, delta) => {
    if (adjusting[part.id]) return
    setAdjusting(a => ({ ...a, [part.id]: true }))
    try {
      const updated = await db.parts.adjustQuantity(part.id, delta)
      setParts(prev => prev.map(p => p.id === part.id ? { ...p, quantity: updated.quantity } : p))
      if (delta > 0) toast.success(`+${delta} added to ${part.part_name}`)
      else toast.success(`${delta} removed from ${part.part_name}`)
    } catch { toast.error('Failed to adjust quantity') }
    finally { setAdjusting(a => ({ ...a, [part.id]: false })) }
  }

  const handleExport = () => {
    const rows = filtered.map(p => ({
      part_name: p.part_name || '',
      part_number: p.part_number || '',
      quantity: p.quantity ?? 0,
      unit_cost: p.unit_cost ?? 0,
      supplier: p.supplier || '',
      reorder_level: p.reorder_level ?? 0,
      location: p.location || '',
      notes: p.notes || '',
    }))
    const columns = [
      { key: 'part_name', label: 'Part Name' },
      { key: 'part_number', label: 'Part #' },
      { key: 'quantity', label: 'Quantity' },
      { key: 'unit_cost', label: 'Unit Cost' },
      { key: 'supplier', label: 'Supplier' },
      { key: 'reorder_level', label: 'Reorder Level' },
      { key: 'location', label: 'Location' },
      { key: 'notes', label: 'Notes' },
    ]
    downloadCSV(rows, columns, `parts-inventory-${new Date().toISOString().split('T')[0]}.csv`)
  }

  // ─── Loading ────────────────────────────────────────────────────────────────
  if (loading) return (
    <div className="space-y-6">
      <div className="space-y-2">
        <div className="h-8 w-40 animate-pulse bg-gray-200 rounded-lg" />
        <div className="h-4 w-64 animate-pulse bg-gray-200 rounded-lg" />
      </div>
      <div className="h-64 animate-pulse bg-gray-100 rounded-xl" />
    </div>
  )

  // ─── Migration Banner ────────────────────────────────────────────────────────
  if (tableMissing) return (
    <div className="max-w-3xl mx-auto mt-10 bg-amber-50 border border-amber-200 rounded-2xl p-6 space-y-4">
      <div className="flex items-start gap-3">
        <div className="w-10 h-10 bg-amber-200 rounded-xl flex items-center justify-center flex-shrink-0">
          <svg className="w-5 h-5 text-amber-700" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
        </div>
        <div>
          <h2 className="text-base font-semibold text-amber-900">Database Setup Required</h2>
          <p className="text-sm text-amber-800 mt-0.5">The <code className="font-mono bg-amber-100 px-1 rounded">parts</code> table is not set up yet. Run the SQL below in your Supabase SQL Editor, then click Retry.</p>
        </div>
      </div>
      <pre className="bg-amber-100 border border-amber-200 rounded-xl p-4 text-xs text-amber-900 overflow-x-auto whitespace-pre">{MIGRATION_SQL}</pre>
      <button onClick={load} className="px-5 py-2 bg-amber-600 text-white rounded-xl text-sm font-medium hover:bg-amber-700 transition-colors">Retry</button>
    </div>
  )

  return (
    <div className="space-y-6">
      {/* Header */}
      <PageHeader title="Parts Inventory" subtitle="Manage parts and components stock levels">
        {canExport && (
          <button onClick={handleExport}
            className="flex items-center gap-1.5 px-3 py-2 border border-gray-200 rounded-lg text-sm text-gray-600 hover:bg-gray-50 transition-colors">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
            Export CSV
          </button>
        )}
        <button onClick={load}
          className="flex items-center gap-1.5 px-3 py-2 border border-gray-200 rounded-lg text-sm text-gray-600 hover:bg-gray-50 transition-colors">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg>
          Refresh
        </button>
        {canAdd && (
          <Button onClick={() => { setEditingPart(null); setShowModal(true) }}>
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4"/></svg>
            Add Part
          </Button>
        )}
      </PageHeader>

      {/* Low Stock Banner */}
      {lowStockParts.length > 0 && (
        <div className="flex items-center gap-3 px-4 py-3 bg-amber-50 border border-amber-200 rounded-xl">
          <svg className="w-5 h-5 text-amber-600 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
          <p className="text-sm text-amber-800 flex-1">
            <span className="font-semibold">{lowStockParts.length} part{lowStockParts.length !== 1 ? 's are' : ' is'} low on stock</span>
            {' — '}
            <button
              onClick={() => setShowLowOnly(v => !v)}
              className="underline text-amber-700 hover:text-amber-900 font-medium">
              {showLowOnly ? 'Show all parts' : 'Show low stock only'}
            </button>
          </p>
        </div>
      )}

      {/* Toolbar */}
      <div className="flex items-center gap-3 flex-wrap">
        <div className="relative flex-1 min-w-[200px] max-w-sm">
          <input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Search part name or part number…"
            className="w-full pl-9 pr-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
          />
          <svg className="w-4 h-4 text-gray-400 absolute left-2.5 top-1/2 -translate-y-1/2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
        </div>
        <button
          onClick={() => setShowLowOnly(v => !v)}
          className={`flex items-center gap-1.5 px-3 py-2 border rounded-lg text-sm transition-colors ${showLowOnly ? 'bg-amber-50 border-amber-400 text-amber-700' : 'border-gray-200 text-gray-600 hover:bg-gray-50'}`}>
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
          {showLowOnly ? 'Showing Low Stock' : 'Low Stock'}
          {!showLowOnly && lowStockParts.length > 0 && (
            <span className="w-4 h-4 bg-amber-500 text-white text-[10px] rounded-full flex items-center justify-center font-bold">{lowStockParts.length}</span>
          )}
        </button>
        <span className="text-sm text-gray-400 ml-auto">{filtered.length} part{filtered.length !== 1 ? 's' : ''}</span>
      </div>

      {/* Table */}
      {filtered.length === 0 ? (
        <div className="text-center py-16 bg-white rounded-xl border border-gray-200">
          <svg className="w-10 h-10 text-gray-300 mx-auto mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4"/></svg>
          <p className="text-sm text-gray-400">{search || showLowOnly ? 'No parts match your filters' : 'No parts in inventory yet'}</p>
          {canAdd && !search && !showLowOnly && (
            <button onClick={() => { setEditingPart(null); setShowModal(true) }}
              className="mt-3 px-4 py-2 bg-indigo-600 text-white text-sm rounded-lg hover:bg-indigo-700 transition-colors">
              Add your first part
            </button>
          )}
        </div>
      ) : (
        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b border-gray-200">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider">
                    <SortBtn label="Part Name" sortKey="part_name" activeSortKey={sortKey} activeSortDir={sortDir} onSort={handleSort} />
                  </th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider">Part #</th>
                  <th className="px-4 py-3 text-center text-xs font-semibold text-gray-500 uppercase tracking-wider">
                    <SortBtn label="Quantity" sortKey="quantity" activeSortKey={sortKey} activeSortDir={sortDir} onSort={handleSort} />
                  </th>
                  <th className="px-4 py-3 text-right text-xs font-semibold text-gray-500 uppercase tracking-wider">Unit Cost</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider">Supplier</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider">Location</th>
                  <th className="px-4 py-3 text-center text-xs font-semibold text-gray-500 uppercase tracking-wider">Reorder Level</th>
                  {canAdjust && (
                    <th className="px-4 py-3 text-center text-xs font-semibold text-gray-500 uppercase tracking-wider">Adjust</th>
                  )}
                  {(canEdit || canDelete) && (
                    <th className="px-4 py-3 text-right text-xs font-semibold text-gray-500 uppercase tracking-wider">Actions</th>
                  )}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {filtered.map(part => {
                  const isLow = part.quantity <= part.reorder_level
                  return (
                    <tr key={part.id} className={`hover:bg-gray-50 transition-colors ${isLow ? 'bg-amber-50/40' : ''}`}>
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-2">
                          {isLow && (
                            <span title="Low stock" className="w-1.5 h-1.5 rounded-full bg-amber-500 flex-shrink-0" />
                          )}
                          <span className="font-medium text-gray-900">{part.part_name}</span>
                        </div>
                        {part.notes && <p className="text-xs text-gray-400 mt-0.5 truncate max-w-[200px]">{part.notes}</p>}
                      </td>
                      <td className="px-4 py-3 text-gray-500 font-mono text-xs">{part.part_number || '—'}</td>
                      <td className="px-4 py-3 text-center">
                        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold ${isLow ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'}`}>
                          {part.quantity ?? 0}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-right text-gray-700 font-medium tabular-nums">
                        ${Number(part.unit_cost ?? 0).toFixed(2)}
                      </td>
                      <td className="px-4 py-3 text-gray-500">{part.supplier || '—'}</td>
                      <td className="px-4 py-3 text-gray-500">{part.location || '—'}</td>
                      <td className="px-4 py-3 text-center text-gray-500">{part.reorder_level ?? 0}</td>
                      {canAdjust && (
                        <td className="px-4 py-3">
                          <div className="flex items-center justify-center gap-1">
                            <button
                              onClick={() => handleAdjust(part, -1)}
                              disabled={adjusting[part.id] || part.quantity <= 0}
                              title="Remove 1"
                              className="w-7 h-7 flex items-center justify-center rounded-lg border border-gray-200 text-gray-500 hover:bg-red-50 hover:border-red-300 hover:text-red-600 disabled:opacity-40 disabled:cursor-not-allowed transition-colors">
                              <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 12H4"/></svg>
                            </button>
                            {adjusting[part.id] && <Spinner size="sm" />}
                            <button
                              onClick={() => handleAdjust(part, 1)}
                              disabled={adjusting[part.id]}
                              title="Add 1"
                              className="w-7 h-7 flex items-center justify-center rounded-lg border border-gray-200 text-gray-500 hover:bg-green-50 hover:border-green-300 hover:text-green-600 disabled:opacity-40 disabled:cursor-not-allowed transition-colors">
                              <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4"/></svg>
                            </button>
                          </div>
                        </td>
                      )}
                      {(canEdit || canDelete) && (
                        <td className="px-4 py-3">
                          <div className="flex items-center justify-end gap-1">
                            {canEdit && (
                              <button
                                onClick={() => { setEditingPart(part); setShowModal(true) }}
                                title="Edit part"
                                className="w-7 h-7 flex items-center justify-center rounded-lg text-gray-400 hover:text-indigo-600 hover:bg-indigo-50 transition-colors">
                                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                              </button>
                            )}
                            {canDelete && (
                              <button
                                onClick={() => handleDelete(part)}
                                title="Delete part"
                                className="w-7 h-7 flex items-center justify-center rounded-lg text-gray-400 hover:text-red-600 hover:bg-red-50 transition-colors">
                                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                              </button>
                            )}
                          </div>
                        </td>
                      )}
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Summary footer */}
      {filtered.length > 0 && (
        <div className="flex items-center justify-between text-xs text-gray-400 px-1">
          <span>Total parts: {filtered.length}</span>
          <span>
            Total stock value: ${filtered.reduce((s, p) => s + (p.quantity ?? 0) * (p.unit_cost ?? 0), 0).toFixed(2)}
          </span>
        </div>
      )}

      {/* Part Modal */}
      {showModal && (
        <PartModal
          part={editingPart}
          onSave={handleSave}
          onClose={() => { setShowModal(false); setEditingPart(null) }}
          saving={saving}
        />
      )}

      {/* Confirm Dialog */}
      <ConfirmDialog
        open={confirmDialog.open}
        title={confirmDialog.title}
        message={confirmDialog.message}
        confirmLabel="Delete"
        onConfirm={confirmDialog.onConfirm}
        onCancel={closeConfirm}
      />
    </div>
  )
}

