import React, { useState, useEffect, useRef } from 'react'
import { supabase, db, storage, branding as brandingAPI } from '../api/supabaseClient'
import toast from 'react-hot-toast'
import QRCode from 'qrcode'
import ConfirmDialog from '../components/ConfirmDialog'
import { PageSkeleton } from '../components/Skeleton'
import { Button, Spinner, PageHeader } from '../components/ui'

const generateRmaNumber = (existingTickets = []) => {
  const now = new Date()
  const dd = String(now.getDate()).padStart(2, '0')
  const mm = String(now.getMonth() + 1).padStart(2, '0')
  const yyyy = now.getFullYear()
  const dateStr = `${dd}${mm}${yyyy}`
  const prefix = `RMA-${dateStr}-`

  const todaySerials = existingTickets
    .map(t => t.rma_number)
    .filter(n => n?.startsWith(prefix))
    .map(n => parseInt(n.replace(prefix, ''), 10))
    .filter(n => !isNaN(n))

  const nextSerial = todaySerials.length > 0 ? Math.max(...todaySerials) + 1 : 1
  return `${prefix}${String(nextSerial).padStart(4, '0')}`
}

const DEFAULT_DUE = () => {
  const d = new Date()
  d.setDate(d.getDate() + 7)
  return d.toISOString().split('T')[0]
}

const EMPTY_PRODUCT = {
  product_name: '',
  serial_number: '',
  product_status: 'Received',
  warranty_status: 'In Warranty',
  issue_description: ''
}

const CARRIERS = ['', 'FedEx', 'UPS', 'DHL', 'USPS', 'Australia Post', 'Royal Mail', 'Other']

function SortableHeader({ label, sortKey, sortConfig, onSort }) {
  const isActive = sortConfig.key === sortKey
  return (
    <button onClick={() => onSort(sortKey)} className="flex items-center gap-1 hover:text-gray-900 transition-colors">
      <span>{label}</span>
      {isActive ? (
        sortConfig.direction === 'asc'
          ? <svg className="w-3.5 h-3.5 text-indigo-600 ml-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" /></svg>
          : <svg className="w-3.5 h-3.5 text-indigo-600 ml-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
      ) : (
        <svg className="w-3.5 h-3.5 text-gray-300 ml-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16V4m0 0L3 8m4-4l4 4m6 0v12m0 0l4-4m-4 4l-4-4" /></svg>
      )}
    </button>
  )
}

export default function RMATickets({ userRole, userEmail, userPermissions, initialTicketId }) {
  const [tickets, setTickets] = useState([])
  const [filteredTickets, setFilteredTickets] = useState([])
  const [ticketsTotalCount, setTicketsTotalCount] = useState(null)
  const [customers, setCustomers] = useState([])
  const [products, setProducts] = useState([])
  const [loading, setLoading] = useState(true)
  const [searchTerm, setSearchTerm] = useState('')

  const [currentPage, setCurrentPage] = useState(1)
  const [itemsPerPage, setItemsPerPage] = useState(() => parseInt(localStorage.getItem('rmaTicketsPerPage')) || 25)
  const [jumpToPage, setJumpToPage] = useState('')
  const [sortConfig, setSortConfig] = useState(() => {
    const saved = localStorage.getItem('rmaTicketsSortConfig')
    return saved ? JSON.parse(saved) : { key: 'created_date', direction: 'desc' }
  })

  const [showFilters, setShowFilters] = useState(false)
  const [filterStatus, setFilterStatus] = useState('')
  const [filterPriority, setFilterPriority] = useState('')
  const [filterAssigned, setFilterAssigned] = useState('')
  const [filterCustomer, setFilterCustomer] = useState('')
  const [filterCustomerSearch, setFilterCustomerSearch] = useState('')
  const [showFilterCustomerDropdown, setShowFilterCustomerDropdown] = useState(false)

  const [showModal, setShowModal] = useState(false)
  const [showDetailsModal, setShowDetailsModal] = useState(false)
  const [editingTicket, setEditingTicket] = useState(null)
  const [previewRmaNumber, setPreviewRmaNumber] = useState('')
  const [selectedTicket, setSelectedTicket] = useState(null)
  const [uploading, setUploading] = useState(false)

  const [customerSearch, setCustomerSearch] = useState('')
  const [showCustomerDropdown, setShowCustomerDropdown] = useState(false)
  const [productSearches, setProductSearches] = useState([''])
  const [showProductDropdowns, setShowProductDropdowns] = useState([false])
  const [pendingFiles, setPendingFiles] = useState([])
  const fileInputRef = useRef(null)
  const searchInputRef = useRef(null)

  const [users, setUsers] = useState([])
  const [openMenuId, setOpenMenuId] = useState(null)

  const [confirmDialog, setConfirmDialog] = useState({ open: false, title: '', message: '', onConfirm: null })
  const openConfirm = (title, message, onConfirm) => setConfirmDialog({ open: true, title, message, onConfirm })
  const closeConfirm = () => setConfirmDialog(d => ({ ...d, open: false }))

  const [selectedTickets, setSelectedTickets] = useState([])
  const [bulkTicketStatus, setBulkTicketStatus] = useState('')
  const [bulkProductStatus, setBulkProductStatus] = useState('')
  const [bulkProcessing, setBulkProcessing] = useState(false)

  const [ticketComments, setTicketComments] = useState([])
  const [commentsLoading, setCommentsLoading] = useState(false)
  const [newComment, setNewComment] = useState('')
  const [isInternalComment, setIsInternalComment] = useState(false)
  const [submittingComment, setSubmittingComment] = useState(false)
  const [replyingTo, setReplyingTo] = useState(null)
  const [commentFiles, setCommentFiles] = useState([])
  const commentFileInputRef = useRef(null)

  const [formData, setFormData] = useState({
    customer_name: '',
    priority: 'Medium',
    ticket_status: 'New',
    assigned_technician: '',
    due_date: DEFAULT_DUE(),
    general_description: '',
    accessories_received: '',
    attachments: [],
    products: [{ ...EMPTY_PRODUCT }],
    // Shipping
    carrier: '',
    tracking_number: '',
    shipping_label_url: '',
  })
  // Time-tracking state for the detail panel
  const [timeEntries, setTimeEntries]         = useState([])
  const [timeEntriesMissing, setTimeEntriesMissing] = useState(false)
  const [timerRunning, setTimerRunning]       = useState(false)
  const [timerStart, setTimerStart]           = useState(null)
  const [timerNotes, setTimerNotes]           = useState('')
  const [manualHours, setManualHours]         = useState('')
  const [manualMins, setManualMins]           = useState('')
  const [manualNotes, setManualNotes]         = useState('')
  const [addingManual, setAddingManual]       = useState(false)
  const [timeTab, setTimeTab]                 = useState('log')
  // Serial history
  const [serialHistory, setSerialHistory]     = useState([])
  const [serialHistorySerial, setSerialHistorySerial] = useState('')
  // Parts on ticket
  const [ticketParts, setTicketParts]         = useState([])
  const [ticketPartsMissing, setTicketPartsMissing] = useState(false)

  useEffect(() => { loadData() }, [])

  useEffect(() => {
    if (userEmail && !formData.assigned_technician) {
      setFormData(prev => ({ ...prev, assigned_technician: userEmail }))
    }
  }, [userEmail])
  useEffect(() => { handleSearchAndSort() }, [searchTerm, tickets, sortConfig, filterStatus, filterPriority, filterAssigned, filterCustomer])
  useEffect(() => { localStorage.setItem('rmaTicketsPerPage', itemsPerPage.toString()) }, [itemsPerPage])
  useEffect(() => { localStorage.setItem('rmaTicketsSortConfig', JSON.stringify(sortConfig)) }, [sortConfig])
  useEffect(() => { setCurrentPage(1); setSelectedTickets([]) }, [searchTerm, itemsPerPage, filterStatus, filterPriority, filterAssigned, filterCustomer, sortConfig])

  useEffect(() => {
    const handler = (e) => {
      const tag = e.target.tagName
      const typing = tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || e.target.isContentEditable
      if (e.key === 'Escape') { setShowModal(false); handleCloseDetails(); return }
      if (typing) return
      if (e.key === 'n' || e.key === 'N') { e.preventDefault(); handleAddNew() }
      if (e.key === '/') { e.preventDefault(); searchInputRef.current?.focus() }
    }
    document.addEventListener('keydown', handler)
    return () => document.removeEventListener('keydown', handler)
  }, [showModal, showDetailsModal])

  useEffect(() => {
    const handler = (e) => {
      if (!e.target.closest('.customer-dropdown')) setShowCustomerDropdown(false)
      if (!e.target.closest('.product-dropdown')) setShowProductDropdowns(prev => prev.map(() => false))
      if (!e.target.closest('.filter-customer-dropdown')) setShowFilterCustomerDropdown(false)
      if (!e.target.closest('.action-menu')) setOpenMenuId(null)
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  useEffect(() => {
    const channel = supabase.channel('rma_tickets_realtime')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'rma_tickets' }, () => {
        loadData()
      })
      .subscribe()
    return () => { supabase.removeChannel(channel) }
  }, [])

  const canDo = (action) => {
    if (userRole === 'admin' || userRole === 'super_admin') return true
    return userPermissions?.rma_tickets?.[action] === true
  }

  const loadData = async () => {
    try {
      const [ticketsData, customersData, productsData, usersData] = await Promise.all([
        db.rmaTickets.list(),
        db.customers.list(),
        db.products.list(),
        db.userRoles.listAllRoles()
      ])
      // Fetch total count alongside capped list (H-4)
      db.rmaTickets.listPaged(0, 1).then(r => setTicketsTotalCount(r.count)).catch(() => {})
      setTickets(ticketsData)
      setFilteredTickets(ticketsData)
      setCustomers(customersData)
      setProducts(productsData)
      setUsers(usersData)
    } catch (error) {
      toast.error('Failed to load data')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (!tickets.length) return
    const urlTicketId = new URLSearchParams(window.location.search).get('ticket')
    const targetId = initialTicketId || urlTicketId
    if (!targetId) return
    const t = tickets.find(tk => tk.id === targetId)
    if (t) { setSelectedTicket(t); setShowDetailsModal(true) }
  }, [initialTicketId, tickets])

  useEffect(() => {
    const onPop = () => {
      const ticketId = new URLSearchParams(window.location.search).get('ticket')
      if (!ticketId) { setShowDetailsModal(false); setSelectedTicket(null) }
    }
    window.addEventListener('popstate', onPop)
    return () => window.removeEventListener('popstate', onPop)
  }, [])

  const handleSearchAndSort = () => {
    let filtered = [...tickets]
    if (searchTerm) {
      const q = searchTerm.toLowerCase()
      filtered = filtered.filter(t =>
        t.rma_number?.toLowerCase().includes(q) ||
        t.customer_name?.toLowerCase().includes(q) ||
        t.ticket_status?.toLowerCase().includes(q) ||
        t.priority?.toLowerCase().includes(q) ||
        t.assigned_technician?.toLowerCase().includes(q)
      )
    }
    if (filterStatus)   filtered = filtered.filter(t => t.ticket_status === filterStatus)
    if (filterPriority) filtered = filtered.filter(t => t.priority === filterPriority)
    if (filterAssigned) filtered = filtered.filter(t => t.assigned_technician === filterAssigned)
    if (filterCustomer) filtered = filtered.filter(t => t.customer_name === filterCustomer)
    filtered.sort((a, b) => {
      let aVal = a[sortConfig.key] || ''
      let bVal = b[sortConfig.key] || ''
      if (sortConfig.key === 'created_date' || sortConfig.key === 'due_date' || sortConfig.key === 'updated_date') {
        aVal = new Date(aVal || 0).getTime()
        bVal = new Date(bVal || 0).getTime()
      } else {
        aVal = aVal.toString().toLowerCase()
        bVal = bVal.toString().toLowerCase()
      }
      if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1
      if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1
      return 0
    })
    setFilteredTickets(filtered)
  }

  const handleSort = (key) => {
    setSortConfig(prev => ({ key, direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc' }))
  }

  const totalPages = Math.ceil(filteredTickets.length / itemsPerPage)
  const startIndex = (currentPage - 1) * itemsPerPage
  const endIndex = Math.min(startIndex + itemsPerPage, filteredTickets.length)
  const paginatedTickets = filteredTickets.slice(startIndex, endIndex)

  const handlePageChange = (page) => {
    if (page >= 1 && page <= totalPages) { setCurrentPage(page); setSelectedTickets([]); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  }

  const handleJumpToPage = () => {
    const pageNum = parseInt(jumpToPage)
    if (pageNum >= 1 && pageNum <= totalPages) { handlePageChange(pageNum); setJumpToPage('') }
    else toast.error(`Page must be between 1 and ${totalPages}`)
  }

  const renderPageNumbers = () => {
    const pages = []
    if (totalPages <= 7) {
      for (let i = 1; i <= totalPages; i++) pages.push(i)
    } else if (currentPage <= 4) {
      for (let i = 1; i <= 5; i++) pages.push(i)
      pages.push('...'); pages.push(totalPages)
    } else if (currentPage >= totalPages - 3) {
      pages.push(1); pages.push('...')
      for (let i = totalPages - 4; i <= totalPages; i++) pages.push(i)
    } else {
      pages.push(1); pages.push('...')
      for (let i = currentPage - 1; i <= currentPage + 1; i++) pages.push(i)
      pages.push('...'); pages.push(totalPages)
    }
    return pages.map((page, idx) =>
      page === '...'
        ? <span key={`e-${idx}`} className="px-3 py-2 text-gray-400">...</span>
        : <button key={page} onClick={() => handlePageChange(page)} className={`px-3 py-2 rounded transition-colors ${currentPage === page ? 'bg-indigo-600 text-white' : 'text-gray-700 hover:bg-gray-100'}`}>{page}</button>
    )
  }

  const filteredCustomersList = customers.filter(c => {
    const q = customerSearch.toLowerCase()
    return !q || c.contact_person?.toLowerCase().includes(q) ||
      c.company_name?.toLowerCase().includes(q) || c.mobile?.includes(q)
  })

  const filteredProductsList = (search) => {
    if (!search) return products.slice(0, 8)
    const q = search.toLowerCase()
    return products.filter(p =>
      p.product_name?.toLowerCase().includes(q) || p.sku?.toLowerCase().includes(q)
    ).slice(0, 6)
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (editingTicket && !canDo('edit_all') && !canDo('edit_assigned')) {
      toast.error('You do not have permission to edit tickets'); return
    }
    if (!editingTicket && !canDo('create')) {
      toast.error('You do not have permission to create tickets'); return
    }

    setUploading(true)
    try {
      const rmaNumber = editingTicket
        ? editingTicket.rma_number
        : generateRmaNumber(tickets)

      const newAttachments = []
      for (const file of pendingFiles) {
        try {
          const uploaded = await storage.uploadFile(file, rmaNumber)
          newAttachments.push(uploaded)
        } catch (err) {
          toast.error(`Failed to upload ${file.name}`)
        }
      }

      const allAttachments = [...(formData.attachments || []), ...newAttachments]

      // Auto-set due date from SLA policy when creating a new ticket
      let computedDueDate = formData.due_date || null
      if (!editingTicket) {
        try {
          const sla = await db.slaConfig.get()
          const slaDue = db.slaConfig.computeDueDate(formData.priority, sla)
          if (slaDue) computedDueDate = slaDue
        } catch {}
      }

      const ticketData = {
        customer_name: formData.customer_name,
        priority: formData.priority,
        ticket_status: formData.ticket_status,
        assigned_technician: formData.assigned_technician,
        due_date: computedDueDate,
        general_description: formData.general_description || null,
        accessories_received: formData.accessories_received || null,
        attachments: allAttachments.length > 0 ? allAttachments : null,
        products: formData.products.map(p => ({
          ...p,
          status_date: p.status_date || new Date().toISOString(),
        })),
        // Shipping
        carrier: formData.carrier || null,
        tracking_number: formData.tracking_number || null,
        shipping_label_url: formData.shipping_label_url || null,
        rma_number: rmaNumber,
        updated_by: userEmail,
        updated_date: new Date().toISOString(),
      }

      if (editingTicket) {
        await db.rmaTickets.update(editingTicket.id, ticketData)
        db.userActivity.create(userEmail, 'ticket_updated', `Updated ticket ${editingTicket.rma_number || editingTicket.id}`).catch(() => {})
        const techEmails = ticketData.assigned_technician && ticketData.assigned_technician !== userEmail ? [ticketData.assigned_technician] : []
        db.notifications.create({
          type: 'ticket_updated', title: 'Ticket Updated',
          message: `Ticket ${editingTicket.rma_number} for ${ticketData.customer_name} was updated by ${userEmail}`,
          entityType: 'ticket', entityId: editingTicket.id, entityRef: editingTicket.rma_number,
          createdBy: userEmail, targetRoles: ['admin', 'super_admin'], targetEmails: techEmails
        }).catch(() => {})
        // Specific: technician assignment changed
        if (ticketData.assigned_technician && ticketData.assigned_technician !== editingTicket.assigned_technician) {
          db.notifications.create({
            type: 'ticket_assigned', title: 'Ticket Assigned',
            message: `Ticket ${editingTicket.rma_number} was assigned to ${ticketData.assigned_technician}`,
            entityType: 'ticket', entityId: editingTicket.id, entityRef: editingTicket.rma_number,
            createdBy: userEmail, targetRoles: ['admin', 'super_admin'], targetEmails: [ticketData.assigned_technician]
          }).catch(() => {})
        }
        // Specific: status changed
        if (ticketData.ticket_status !== editingTicket.ticket_status) {
          const assigneeEmails = editingTicket.assigned_technician && editingTicket.assigned_technician !== userEmail ? [editingTicket.assigned_technician] : []
          db.notifications.create({
            type: 'ticket_status_changed', title: 'Ticket Status Changed',
            message: `Ticket ${editingTicket.rma_number} moved from "${editingTicket.ticket_status}" to "${ticketData.ticket_status}"`,
            entityType: 'ticket', entityId: editingTicket.id, entityRef: editingTicket.rma_number,
            createdBy: userEmail, targetRoles: ['admin', 'super_admin'], targetEmails: assigneeEmails
          }).catch(() => {})
        }
        toast.success('Ticket updated successfully!')
        // Fire automation rules + webhook on update
        db.automationRules.evaluate('ticket_updated', { ...editingTicket, ...ticketData }).catch(() => {})
        db.webhooks.dispatch('ticket_updated', { id: editingTicket.id, rma_number: editingTicket.rma_number, ...ticketData }).catch(() => {})
        if (ticketData.ticket_status !== editingTicket.ticket_status) {
          db.automationRules.evaluate('ticket_status_changed', { ...editingTicket, ...ticketData }).catch(() => {})
          db.webhooks.dispatch('ticket_status_changed', { id: editingTicket.id, rma_number: editingTicket.rma_number, old_status: editingTicket.ticket_status, new_status: ticketData.ticket_status }).catch(() => {})
        }
        if (ticketData.assigned_technician !== editingTicket.assigned_technician) {
          db.automationRules.evaluate('ticket_assigned', { ...editingTicket, ...ticketData }).catch(() => {})
          db.webhooks.dispatch('ticket_assigned', { id: editingTicket.id, rma_number: editingTicket.rma_number, technician: ticketData.assigned_technician }).catch(() => {})
        }
      } else {
        const newTicket = await db.rmaTickets.create({ ...ticketData, created_by: userEmail, created_date: new Date().toISOString() })
        if (newTicket?.id) {
          db.inventory.createUnitsFromTicket(newTicket.id, newTicket.rma_number || rmaNumber, ticketData.products).catch((err) => {
            console.warn('Inventory unit creation failed:', err?.message || err)
          })
          const techEmails = ticketData.assigned_technician && ticketData.assigned_technician !== userEmail ? [ticketData.assigned_technician] : []
          db.notifications.create({
            type: 'ticket_created', title: 'New RMA Ticket',
            message: `Ticket ${rmaNumber} created for ${ticketData.customer_name}`,
            entityType: 'ticket', entityId: newTicket.id, entityRef: rmaNumber,
            createdBy: userEmail, targetRoles: ['admin', 'super_admin'], targetEmails: techEmails
          }).catch(() => {})
          // Fire automation rules + webhook on create
          db.automationRules.evaluate('ticket_created', newTicket).catch(() => {})
          db.webhooks.dispatch('ticket_created', { id: newTicket.id, rma_number: rmaNumber, customer_name: ticketData.customer_name, priority: ticketData.priority, status: ticketData.ticket_status }).catch(() => {})
        }
        db.userActivity.create(userEmail, 'ticket_created', `Created ticket ${rmaNumber} for ${ticketData.customer_name}`).catch(() => {})
        toast.success('Ticket created successfully!')
      }

      setShowModal(false)
      setEditingTicket(null)
      resetForm()
      loadData()
    } catch (error) {
      toast.error(`Failed to save ticket: ${error.message}`)
    } finally {
      setUploading(false)
    }
  }

  const handleEdit = (ticket) => {
    if (!canDo('edit_all') && !canDo('edit_assigned')) {
      toast.error('You do not have permission to edit tickets'); return
    }
    if (canDo('edit_assigned') && !canDo('edit_all') && ticket.assigned_technician !== userEmail) {
      toast.error('You can only edit tickets assigned to you'); return
    }
    setEditingTicket(ticket)
    const prods = ticket.products?.length ? ticket.products : [{ ...EMPTY_PRODUCT }]
    setFormData({
      customer_name: ticket.customer_name || '',
      priority: ticket.priority || 'Medium',
      ticket_status: ticket.ticket_status || 'New',
      assigned_technician: ticket.assigned_technician || '',
      due_date: ticket.due_date || '',
      general_description: ticket.general_description || '',
      accessories_received: ticket.accessories_received || '',
      attachments: ticket.attachments || [],
      products: prods,
      carrier: ticket.carrier || '',
      tracking_number: ticket.tracking_number || '',
      shipping_label_url: ticket.shipping_label_url || '',
    })
    setCustomerSearch(ticket.customer_name || '')
    setProductSearches(prods.map(p => p.product_name || ''))
    setShowProductDropdowns(prods.map(() => false))
    setPendingFiles([])
    setShowModal(true)
  }

  const handleDelete = (id) => {
    if (!canDo('delete')) { toast.error('You do not have permission to delete tickets'); return }
    openConfirm(
      'Delete Ticket',
      'Delete this ticket? This cannot be undone.',
      async () => {
        closeConfirm()
        try {
          await db.rmaTickets.delete(id)
          db.userActivity.create(userEmail, 'ticket_deleted', `Deleted ticket ID ${id}`).catch(() => {})
          db.notifications.create({
            type: 'ticket_deleted', title: 'Ticket Deleted',
            message: `A ticket was deleted by ${userEmail}`,
            entityType: 'ticket', entityId: id, entityRef: null,
            createdBy: userEmail, targetRoles: ['admin', 'super_admin'], targetEmails: []
          }).catch(() => {})
          toast.success('Ticket deleted!')
          loadData()
        } catch { toast.error('Failed to delete ticket') }
      }
    )
  }

  const handleBulkDelete = () => {
    if (!canDo('delete')) { toast.error('You do not have permission to delete tickets'); return }
    openConfirm(
      'Delete Tickets',
      `Delete ${selectedTickets.length} ticket${selectedTickets.length !== 1 ? 's' : ''}? This cannot be undone.`,
      async () => {
        closeConfirm()
        setBulkProcessing(true)
        try {
          await Promise.all(selectedTickets.map(id => db.rmaTickets.delete(id)))
          db.notifications.create({
            type: 'ticket_deleted', title: 'Tickets Deleted',
            message: `${selectedTickets.length} ticket(s) were deleted by ${userEmail}`,
            entityType: 'ticket', entityId: null,
            createdBy: userEmail, targetRoles: ['admin', 'super_admin'], targetEmails: []
          }).catch(() => {})
          toast.success(`${selectedTickets.length} ticket(s) deleted`)
          db.auditLog.log(userEmail, 'ticket_bulk_deleted', `Deleted ${selectedTickets.length} tickets`).catch(() => {})
          setSelectedTickets([])
          loadData()
        } catch { toast.error('Failed to delete tickets') }
        finally { setBulkProcessing(false) }
      }
    )
  }

  const handleBulkTicketStatus = async () => {
    if (!bulkTicketStatus) return
    if (!(canDo('edit_all') || canDo('change_status'))) { toast.error('No permission to change status'); return }
    setBulkProcessing(true)
    try {
      await Promise.all(selectedTickets.map(id => db.rmaTickets.update(id, {
        ticket_status: bulkTicketStatus,
        updated_by: userEmail,
        updated_date: new Date().toISOString(),
      })))
      db.notifications.create({
        type: 'ticket_status_changed', title: 'Bulk Status Update',
        message: `${selectedTickets.length} ticket(s) status changed to "${bulkTicketStatus}" by ${userEmail}`,
        entityType: 'ticket', entityId: null,
        createdBy: userEmail, targetRoles: ['admin', 'super_admin'], targetEmails: []
      }).catch(() => {})
      toast.success(`Status updated to "${bulkTicketStatus}" for ${selectedTickets.length} ticket(s)`)
      db.auditLog.log(userEmail, 'ticket_bulk_status_changed', `Changed ${selectedTickets.length} tickets to "${bulkTicketStatus}"`).catch(() => {})
      setSelectedTickets([])
      setBulkTicketStatus('')
      loadData()
    } catch { toast.error('Failed to update status') }
    finally { setBulkProcessing(false) }
  }

  const handleBulkProductStatus = async () => {
    if (!bulkProductStatus) return
    if (!(canDo('edit_all') || canDo('edit_assigned'))) { toast.error('No permission to edit tickets'); return }
    setBulkProcessing(true)
    try {
      await Promise.all(selectedTickets.map(id => {
        const ticket = tickets.find(t => t.id === id)
        if (!ticket) return Promise.resolve()
        const updatedProducts = (ticket.products || []).map(p => ({ ...p, product_status: bulkProductStatus, status_date: new Date().toISOString() }))
        return db.rmaTickets.update(id, {
          products: updatedProducts,
          updated_by: userEmail,
          updated_date: new Date().toISOString(),
        })
      }))
      toast.success(`Product status updated to "${bulkProductStatus}" for ${selectedTickets.length} ticket(s)`)
      db.auditLog.log(userEmail, 'ticket_bulk_product_status_changed', `Changed product status to "${bulkProductStatus}" for ${selectedTickets.length} tickets`).catch(() => {})
      setSelectedTickets([])
      setBulkProductStatus('')
      loadData()
    } catch { toast.error('Failed to update product status') }
    finally { setBulkProcessing(false) }
  }

  const toggleSelectTicket = (id) => setSelectedTickets(prev => prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id])
  const toggleSelectAll = () => setSelectedTickets(selectedTickets.length === paginatedTickets.length ? [] : paginatedTickets.map(t => t.id))

  const handleCloseDetails = () => {
    const params = new URLSearchParams(window.location.search)
    params.delete('ticket')
    const qs = params.toString()
    window.history.replaceState({}, '', '/rma-tickets' + (qs ? `?${qs}` : ''))
    setShowDetailsModal(false)
  }

  const handleViewDetails = (ticket) => {
    window.history.pushState({ ticket: ticket.id }, '', `/rma-tickets?ticket=${ticket.id}`)
    setSelectedTicket(ticket)
    setShowDetailsModal(true)
    setTicketComments([])
    setNewComment('')
    setTimerRunning(false)
    setTimerStart(null)
    setSerialHistory([])
    setSerialHistorySerial('')
    setCommentsLoading(true)
    db.ticketComments.list(ticket.id).then(res => {
      if (!res.missing) setTicketComments(res.data)
    }).catch(() => {}).finally(() => setCommentsLoading(false))
    // Load time entries
    db.timeEntries.list(ticket.id).then(res => {
      if (res.missing) { setTimeEntriesMissing(true); setTimeEntries([]) }
      else { setTimeEntriesMissing(false); setTimeEntries(res.data) }
    }).catch(() => {})
    // Load parts used on this ticket
    db.ticketParts.list(ticket.id).then(res => {
      if (res.missing) { setTicketPartsMissing(true); setTicketParts([]) }
      else { setTicketPartsMissing(false); setTicketParts(res.data) }
    }).catch(() => {})
  }

  const handleAddComment = async (parentCommentId = null) => {
    if (!newComment.trim() && commentFiles.length === 0) return
    if (!selectedTicket) return
    setSubmittingComment(true)
    try {
      let attachments = []
      for (const file of commentFiles) {
        const result = await storage.uploadCommentAttachment(file, selectedTicket.id)
        if (result) attachments.push(result)
      }
      const comment = await db.ticketComments.create(
        selectedTicket.id,
        newComment.trim(),
        userEmail,
        userEmail,
        isInternalComment,
        parentCommentId,
        attachments
      )
      if (comment) {
        setTicketComments(prev => [...prev, comment])
        const targetEmails = []
        if (selectedTicket?.assigned_technician && selectedTicket.assigned_technician !== userEmail)
          targetEmails.push(selectedTicket.assigned_technician)
        if (selectedTicket?.created_by && selectedTicket.created_by !== userEmail && !targetEmails.includes(selectedTicket.created_by))
          targetEmails.push(selectedTicket.created_by)
        db.notifications.create({
          type: 'comment_added', title: 'New Comment',
          message: `${userEmail} commented on ticket ${selectedTicket.rma_number}`,
          entityType: 'ticket', entityId: selectedTicket.id, entityRef: selectedTicket.rma_number,
          createdBy: userEmail, targetRoles: ['admin', 'super_admin'], targetEmails
        }).catch(() => {})
      }
      setNewComment('')
      db.auditLog.log(userEmail, 'ticket_comment_added', `Added comment on ticket ${selectedTicket?.rma_number}`).catch(() => {})
      setCommentFiles([])
      setReplyingTo(null)
    } catch (err) {
      toast.error('Failed to post comment: ' + (err?.message || err?.code || 'unknown error'))
    } finally {
      setSubmittingComment(false)
    }
  }

  const handleDeleteComment = async (commentId) => {
    try {
      await db.ticketComments.delete(commentId)
      setTicketComments(prev => prev.filter(c => c.id !== commentId))
      db.auditLog.log(userEmail, 'ticket_comment_deleted', `Deleted comment ${commentId}`).catch(() => {})
    } catch {
      toast.error('Failed to delete comment')
    }
  }

  const handleExportPDF = async (ticket) => {
    const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;')
    let qrCodeUrl = ''
    try { qrCodeUrl = await QRCode.toDataURL(ticket.rma_number) } catch {}

    // Load PDF layout config and branding in parallel
    const PDF_DEFAULT = {
      paperSize: 'A4', orientation: 'portrait', font: 'Arial, sans-serif', fontSize: 11,
      primaryColor: '#4F46E5', headerStyle: 'colored', showLogo: false, logoPosition: 'right',
      showCompanyName: true, showRmaNumber: true, showDate: true,
      sections: { ticketInfo: true, generalDescription: true, products: true, accessories: true, attachments: true, signatureLine: false },
      sectionOrder: ['ticketInfo', 'generalDescription', 'products', 'accessories', 'attachments', 'signatureLine'],
      footerText: '', showGeneratedDate: true, showWatermark: false,
    }
    let pdfCfg = PDF_DEFAULT
    let brandingData = {}
    try {
      const [cfgResult, brd] = await Promise.all([db.rmaConfig.getAll(), brandingAPI.getBranding()])
      if (!cfgResult.missing) {
        const row = cfgResult.data.find(r => r.config_key === 'pdf_layout')
        if (row?.config_value) {
          const val = typeof row.config_value === 'string' ? JSON.parse(row.config_value) : row.config_value
          pdfCfg = {
            ...PDF_DEFAULT, ...val,
            sections: { ...PDF_DEFAULT.sections, ...(val.sections || {}) },
            sectionOrder: val.sectionOrder?.length ? val.sectionOrder : PDF_DEFAULT.sectionOrder,
          }
        }
      }
      if (brd) brandingData = brd
    } catch {}

    const color = pdfCfg.primaryColor || '#4F46E5'
    const font = pdfCfg.font || 'Arial, sans-serif'
    const fontSize = pdfCfg.fontSize || 11
    const sec = pdfCfg.sections || PDF_DEFAULT.sections
    const companyName = brandingData.company_name || 'myRMA'
    const logoUrl = pdfCfg.showLogo ? (brandingData.logo_url || null) : null

    const fmt = (d) => d ? new Date(d).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' }) : 'N/A'
    const fmtTS = (d) => {
      if (!d) return 'N/A'
      const dt = new Date(d)
      return dt.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' }) + ' at ' + dt.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' })
    }

    const productsHtml = (ticket.products || []).map((p, i) => `
      <div style="border:1px solid #E5E7EB;border-radius:6px;padding:12px;margin-bottom:12px">
        <h4 style="margin:0 0 8px;font-size:${fontSize + 1}px;color:#1F2937">Product ${i + 1}: ${esc(p.product_name) || '—'}</h4>
        <table style="width:100%;font-size:${fontSize}px;border-collapse:collapse">
          <tr><td style="color:#6B7280;padding:3px 8px;width:40%">Serial Number</td><td style="font-family:monospace"><strong>${esc(p.serial_number) || '—'}</strong></td></tr>
          <tr><td style="color:#6B7280;padding:3px 8px">Product Status</td><td><strong>${esc(p.product_status) || '—'}</strong></td></tr>
          <tr><td style="color:#6B7280;padding:3px 8px">Warranty Status</td><td><strong>${esc(p.warranty_status) || '—'}</strong></td></tr>
          <tr><td colspan="2" style="padding:6px 8px 0"><strong>Issue:</strong> ${esc(p.issue_description) || '—'}</td></tr>
        </table>
      </div>`).join('')

    const attachHtml = (ticket.attachments || []).length
      ? (ticket.attachments || []).map(a => `<li style="margin-bottom:4px">${esc(a.name)} <span style="color:#9CA3AF">(${(a.size / 1024).toFixed(1)} KB)</span></li>`).join('')
      : '<li style="color:#9CA3AF">No attachments</li>'

    const priorityColors = { Critical: '#FEE2E2;color:#991B1B', High: '#FFEDD5;color:#9A3412', Medium: '#DBEAFE;color:#1E40AF', Low: '#F3F4F6;color:#374151' }
    const pc = priorityColors[ticket.priority] || priorityColors.Medium

    const headerBorderStyle = pdfCfg.headerStyle === 'colored'
      ? `border-bottom:3px solid ${color};background:linear-gradient(135deg,${color}15 0%,transparent 100%)`
      : pdfCfg.headerStyle === 'minimal'
        ? 'border-bottom:1px solid #E5E7EB'
        : 'border-bottom:none'

    const logoHtml = logoUrl
      ? `<img src="${logoUrl}" style="max-height:60px;max-width:140px;object-fit:contain" />`
      : ''

    const headerLeft = pdfCfg.logoPosition === 'left'
      ? `<div style="display:flex;align-items:center;gap:12px">${logoHtml}<div>${pdfCfg.showCompanyName ? `<div style="font-size:${fontSize + 4}px;font-weight:bold;color:${color}">${esc(companyName)}</div>` : ''}${pdfCfg.showRmaNumber ? `<div style="font-size:${fontSize + 2}px;color:#6B7280;margin-top:2px">${esc(ticket.rma_number)}</div>` : ''}${pdfCfg.showDate ? `<div style="font-size:${fontSize - 1}px;color:#9CA3AF;margin-top:2px">${esc(fmtTS(ticket.created_date))}</div>` : ''}<div style="margin-top:6px"><span class="badge" style="background:#DBEAFE;color:#1E40AF">${esc(ticket.ticket_status)}</span><span class="badge" style="background:${pc}">${esc(ticket.priority)}</span></div></div></div>`
      : `<div>${pdfCfg.showCompanyName ? `<div style="font-size:${fontSize + 4}px;font-weight:bold;color:${color}">${esc(companyName)}</div>` : ''}${pdfCfg.showRmaNumber ? `<div style="font-size:${fontSize + 2}px;color:#6B7280;margin-top:2px">${esc(ticket.rma_number)}</div>` : ''}${pdfCfg.showDate ? `<div style="font-size:${fontSize - 1}px;color:#9CA3AF;margin-top:2px">${esc(fmtTS(ticket.created_date))}</div>` : ''}<div style="margin-top:6px"><span class="badge" style="background:#DBEAFE;color:#1E40AF">${esc(ticket.ticket_status)}</span><span class="badge" style="background:${pc}">${esc(ticket.priority)}</span></div></div>`

    const headerRight = pdfCfg.logoPosition === 'right'
      ? `<div style="display:flex;flex-direction:column;align-items:flex-end;gap:8px">${logoHtml}${qrCodeUrl ? `<div style="text-align:center"><img src="${qrCodeUrl}" width="80" height="80"/><div style="font-size:10px;color:#6B7280;margin-top:2px">Scan to view</div></div>` : ''}</div>`
      : qrCodeUrl ? `<div style="text-align:center"><img src="${qrCodeUrl}" width="80" height="80"/><div style="font-size:10px;color:#6B7280;margin-top:2px">Scan to view</div></div>` : ''

    const watermarkHtml = pdfCfg.showWatermark ? `<div style="position:fixed;top:50%;left:50%;transform:translate(-50%,-50%) rotate(-45deg);font-size:80px;font-weight:bold;color:${color};opacity:0.05;pointer-events:none;z-index:-1">DRAFT</div>` : ''

    const footerContent = [
      pdfCfg.showGeneratedDate ? `Generated: ${new Date().toLocaleString()}` : '',
      pdfCfg.footerText || companyName
    ].filter(Boolean)

    const w = window.open('', '_blank')
    w.document.write(`<!DOCTYPE html><html><head><title>RMA Ticket - ${ticket.rma_number}</title>
      <style>
        *{box-sizing:border-box;margin:0;padding:0}
        body{font-family:${font};font-size:${fontSize}px;color:#1F2937;padding:30px}
        .header{display:flex;justify-content:space-between;align-items:flex-start;${headerBorderStyle};padding-bottom:20px;margin-bottom:24px}
        .badge{display:inline-block;padding:3px 10px;border-radius:9999px;font-size:${fontSize - 1}px;font-weight:bold;margin-right:6px;margin-top:6px}
        .section{margin-bottom:20px}
        .section-title{font-size:${fontSize - 1}px;text-transform:uppercase;letter-spacing:0.05em;color:${color};border-bottom:2px solid ${color}33;padding-bottom:6px;margin-bottom:12px;font-weight:600}
        .grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px}
        .info-label{font-size:${fontSize - 2}px;color:#6B7280;margin-bottom:2px}
        .info-value{font-size:${fontSize}px;font-weight:bold}
        .desc-box{background:#F9FAFB;border:1px solid #E5E7EB;border-radius:6px;padding:12px;white-space:pre-wrap}
        .footer{margin-top:30px;border-top:1px solid #E5E7EB;padding-top:12px;display:flex;justify-content:space-between;color:#9CA3AF;font-size:${fontSize - 2}px}
        .sig-box{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin-top:40px}
        .sig-line{border-top:1px solid #374151;padding-top:6px;font-size:${fontSize - 1}px;color:#6B7280;text-align:center}
        @media print{body{padding:15px}}
      </style></head>
      <body>
      ${watermarkHtml}
      <div class="header">
        ${headerLeft}
        ${headerRight}
      </div>

      ${pdfCfg.sectionOrder.map(key => {
        if (!sec[key]) return ''
        if (key === 'ticketInfo') return `
        <div class="section">
          <div class="section-title">Ticket Information</div>
          <div class="grid">
            <div><div class="info-label">Customer</div><div class="info-value">${esc(ticket.customer_name) || '—'}</div></div>
            <div><div class="info-label">Assigned To</div><div class="info-value">${esc(ticket.assigned_technician) || 'Unassigned'}</div></div>
            <div><div class="info-label">Due Date</div><div class="info-value">${esc(fmt(ticket.due_date))}</div></div>
            <div><div class="info-label">Created</div><div class="info-value">${esc(fmtTS(ticket.created_date))}</div></div>
            <div><div class="info-label">Created By</div><div class="info-value">${esc(ticket.created_by) || '—'}</div></div>
          </div>
        </div>`
        if (key === 'generalDescription') return ticket.general_description ? `
        <div class="section">
          <div class="section-title">General RMA Description</div>
          <div class="desc-box">${esc(ticket.general_description)}</div>
        </div>` : ''
        if (key === 'products') return `
        <div class="section">
          <div class="section-title">Products (${(ticket.products || []).length})</div>
          ${productsHtml || '<p style="color:#9CA3AF">No products listed</p>'}
        </div>`
        if (key === 'accessories') return ticket.accessories_received ? `
        <div class="section">
          <div class="section-title">Accessories Received</div>
          <div class="desc-box">${esc(ticket.accessories_received)}</div>
        </div>` : ''
        if (key === 'attachments') return `
        <div class="section">
          <div class="section-title">Attachments</div>
          <ul style="padding-left:20px">${attachHtml}</ul>
        </div>`
        if (key === 'signatureLine') return `
        <div class="sig-box">
          <div><div class="sig-line">Customer Signature</div></div>
          <div><div class="sig-line">Technician Signature</div></div>
        </div>`
        return ''
      }).join('')}

      <div class="footer">
        <span>${esc(footerContent[0]) || ''}</span>
        <span>${esc(footerContent[1]) || ''}</span>
      </div>
      <script>window.onload=function(){setTimeout(function(){window.print()},300)}</script>
      </body></html>`)
    w.document.close()
    db.auditLog.log(userEmail, 'ticket_exported_pdf', `Exported ticket ${ticket.rma_number} to PDF`).catch(() => {})
  }

  const handleExport = () => {
    if (!canDo('export')) { toast.error('No permission to export'); return }
    const csv = [
      ['RMA Number', 'Customer', 'Status', 'Priority', 'Assigned To', 'Due Date', 'Created Date'],
      ...filteredTickets.map(t => [t.rma_number, t.customer_name, t.ticket_status, t.priority, t.assigned_technician || 'Unassigned', t.due_date || 'N/A', new Date(t.created_date).toLocaleDateString()])
    ].map(r => r.join(',')).join('\n')
    const a = document.createElement('a')
    a.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }))
    a.download = `rma-tickets-${Date.now()}.csv`; a.click()
    toast.success('Exported!')
    db.auditLog.log(userEmail, 'tickets_exported', `Exported ${filteredTickets.length} tickets to CSV`).catch(() => {})
  }

  const resetForm = () => {
    setFormData({
      customer_name: '', priority: 'Medium', ticket_status: 'New',
      assigned_technician: userEmail || '', due_date: DEFAULT_DUE(),
      general_description: '', accessories_received: '', attachments: [],
      products: [{ ...EMPTY_PRODUCT }]
    })
    setCustomerSearch(''); setProductSearches(['']); setShowProductDropdowns([false]); setPendingFiles([])
  }

  const handleAddNew = () => {
    if (!canDo('create')) { toast.error('No permission to create tickets'); return }
    setEditingTicket(null)
    resetForm()
    setPreviewRmaNumber(generateRmaNumber(tickets))
    setShowModal(true)
  }

  const addProduct = () => {
    setFormData({ ...formData, products: [...formData.products, { ...EMPTY_PRODUCT }] })
    setProductSearches(p => [...p, '']); setShowProductDropdowns(p => [...p, false])
  }

  const removeProduct = (i) => {
    setFormData({ ...formData, products: formData.products.filter((_, idx) => idx !== i) })
    setProductSearches(p => p.filter((_, idx) => idx !== i))
    setShowProductDropdowns(p => p.filter((_, idx) => idx !== i))
  }

  const updateProduct = (i, field, value) => {
    const p = [...formData.products]
    p[i] = { ...p[i], [field]: value }
    if (field === 'product_status') p[i].status_date = new Date().toISOString()
    setFormData({ ...formData, products: p })
  }

  const handleDeleteAttachment = async (att, i) => {
    try {
      if (att.path) await storage.deleteFile(att.path)
      setFormData({ ...formData, attachments: formData.attachments.filter((_, idx) => idx !== i) })
      toast.success('Attachment removed')
    } catch { toast.error('Failed to remove attachment') }
  }

  const handleFileSelect = (e) => {
    const files = Array.from(e.target.files)
    const total = (formData.attachments?.length || 0) + pendingFiles.length + files.length
    if (total > 10) { toast.error('Maximum 10 attachments per ticket'); return }
    setPendingFiles(prev => [...prev, ...files]); e.target.value = ''
  }

  const getStatusColor = (s) => ({ New: 'bg-pink-100 text-pink-800', 'In Progress': 'bg-blue-100 text-blue-800', 'On Hold': 'bg-yellow-100 text-yellow-800', Completed: 'bg-green-100 text-green-800', Cancelled: 'bg-gray-100 text-gray-800' }[s] || 'bg-gray-100 text-gray-800')
  const getPriorityColor = (p) => ({ Low: 'bg-gray-100 text-gray-800', Medium: 'bg-blue-100 text-blue-800', High: 'bg-orange-100 text-orange-800', Critical: 'bg-red-100 text-red-800' }[p] || 'bg-gray-100 text-gray-800')
  const fmt = (d) => d ? new Date(d).toLocaleDateString() : 'N/A'
  const SLABadge = ({ dueDate, status }) => {
    if (!dueDate || ['Completed', 'Cancelled'].includes(status)) return <span className="text-gray-400 text-xs">{dueDate ? fmt(dueDate) : '—'}</span>
    const days = Math.ceil((new Date(dueDate) - Date.now()) / 86400000)
    if (days < 0) return <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-semibold bg-red-100 text-red-700">Overdue {Math.abs(days)}d</span>
    if (days === 0) return <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-semibold bg-red-100 text-red-700">Due today</span>
    if (days <= 2) return <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-semibold bg-amber-100 text-amber-700">{days}d left</span>
    if (days <= 5) return <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-semibold bg-yellow-100 text-yellow-700">{days}d left</span>
    return <span className="text-xs text-gray-500">{fmt(dueDate)}</span>
  }
  const fmtDateTime = (d) => {
    if (!d) return 'N/A'
    const dt = new Date(d)
    return dt.toLocaleDateString() + ' ' + dt.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
  }
  const fmtBytes = (b) => b < 1024 ? `${b} B` : `${(b / 1024).toFixed(1)} KB`
  const isImage = (t) => t?.startsWith('image/')

  const inp = "w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none text-sm bg-white placeholder-gray-400 transition-colors"
  const lbl = "block text-sm font-medium text-gray-700 mb-1.5"

  if (loading) return <PageSkeleton cols={9} />

  return (
    <div className="space-y-6">

      {/* Header */}
      <PageHeader title="RMA Tickets" subtitle="Manage return merchandise authorization" />

      {/* Toolbar */}
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div className="flex items-center gap-2 flex-1 max-w-2xl">
          <div className="relative flex-1">
            <input ref={searchInputRef} type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Search by RMA number, customer, status, priority... (Press / to focus)"
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent" />
            <svg className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </div>
          <button onClick={() => setShowFilters(!showFilters)}
            className={`flex items-center gap-2 px-4 py-2 border rounded-lg text-sm transition-colors ${showFilters || filterStatus || filterPriority || filterAssigned || filterCustomer ? 'border-indigo-500 text-indigo-600 bg-indigo-50' : 'border-gray-300 text-gray-700 hover:bg-gray-50'}`}>
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2a1 1 0 01-.293.707L13 13.414V19a1 1 0 01-.553.894l-4 2A1 1 0 017 21v-7.586L3.293 6.707A1 1 0 013 6V4z" /></svg>
            Filters
            {(filterStatus || filterPriority || filterAssigned || filterCustomer) && (
              <span className="w-4 h-4 bg-indigo-600 text-white text-xs rounded-full flex items-center justify-center">
                {[filterStatus, filterPriority, filterAssigned, filterCustomer].filter(Boolean).length}
              </span>
            )}
          </button>
        </div>
        <div className="flex items-center gap-2">
          {canDo('export') && (
            <Button variant="secondary" onClick={handleExport}>
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
              Export
            </Button>
          )}
          {canDo('create') && (
            <Button onClick={handleAddNew}>
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
              Create Ticket
            </Button>
          )}
        </div>
      </div>

      {/* Filter panel */}
      {showFilters && (
        <div className="flex items-center gap-4 p-4 bg-gray-50 rounded-lg flex-wrap">
          <div className="flex items-center gap-2">
            <label className="text-sm font-medium text-gray-700">Status:</label>
            <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className="px-3 py-1.5 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600">
              <option value="">All</option>
              <option value="New">New</option>
              <option value="In Progress">In Progress</option>
              <option value="On Hold">On Hold</option>
              <option value="Completed">Completed</option>
              <option value="Cancelled">Cancelled</option>
            </select>
          </div>
          <div className="flex items-center gap-2">
            <label className="text-sm font-medium text-gray-700">Priority:</label>
            <select value={filterPriority} onChange={e => setFilterPriority(e.target.value)} className="px-3 py-1.5 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600">
              <option value="">All</option>
              <option value="Low">Low</option>
              <option value="Medium">Medium</option>
              <option value="High">High</option>
              <option value="Critical">Critical</option>
            </select>
          </div>
          <div className="flex items-center gap-2">
            <label className="text-sm font-medium text-gray-700">Assigned To:</label>
            <select value={filterAssigned} onChange={e => setFilterAssigned(e.target.value)} className="px-3 py-1.5 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600">
              <option value="">All</option>
              {[...new Set(tickets.map(t => t.assigned_technician).filter(Boolean))].sort().map(email => (
                <option key={email} value={email}>{email}</option>
              ))}
            </select>
          </div>
          <div className="flex items-center gap-2">
            <label className="text-sm font-medium text-gray-700">Customer:</label>
            <div className="relative filter-customer-dropdown">
              <div className="flex items-center">
                <input
                  type="text"
                  value={filterCustomerSearch}
                  onChange={e => { setFilterCustomerSearch(e.target.value); setShowFilterCustomerDropdown(true); if (!e.target.value) { setFilterCustomer('') } }}
                  onFocus={() => setShowFilterCustomerDropdown(true)}
                  placeholder={filterCustomer || 'All customers...'}
                  className={`w-52 px-3 py-1.5 border rounded-lg text-sm focus:ring-2 focus:ring-indigo-600 ${filterCustomer ? 'border-indigo-400 bg-indigo-50 pr-7' : 'border-gray-300'}`}
                />
                {filterCustomer && (
                  <button type="button" onMouseDown={e => { e.preventDefault(); setFilterCustomer(''); setFilterCustomerSearch('') }}
                    className="absolute right-2 text-gray-400 hover:text-gray-600">
                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                  </button>
                )}
              </div>
              {showFilterCustomerDropdown && (() => {
                const q = filterCustomerSearch.toLowerCase()
                const dbNames = customers.map(c => c.customer_type === 'B2B' && c.company_name ? c.company_name : c.contact_person).filter(Boolean)
                const ticketNames = tickets.map(t => t.customer_name).filter(Boolean)
                const allNames = [...new Set([...dbNames, ...ticketNames])].sort()
                const filtered = q ? allNames.filter(n => n.toLowerCase().includes(q)) : allNames
                return filtered.length > 0 ? (
                  <div className="absolute z-30 left-0 mt-1 w-64 bg-white border border-gray-200 rounded-lg shadow-xl max-h-52 overflow-y-auto">
                    {filtered.map(name => (
                      <button key={name} type="button"
                        onMouseDown={e => { e.preventDefault(); setFilterCustomer(name); setFilterCustomerSearch(''); setShowFilterCustomerDropdown(false) }}
                        className={`w-full px-3 py-2 text-left text-sm hover:bg-indigo-50 ${filterCustomer === name ? 'bg-indigo-50 font-medium text-indigo-700' : 'text-gray-700'}`}>
                        {name}
                      </button>
                    ))}
                  </div>
                ) : null
              })()}
            </div>
          </div>
          {(filterStatus || filterPriority || filterAssigned || filterCustomer) && (
            <button onClick={() => { setFilterStatus(''); setFilterPriority(''); setFilterAssigned(''); setFilterCustomer(''); setFilterCustomerSearch('') }}
              className="text-sm text-red-600 hover:underline">Clear all</button>
          )}
        </div>
      )}

      {/* Cap warning banner (H-4) */}
      {ticketsTotalCount !== null && ticketsTotalCount > tickets.length && (
        <div className="mb-2 px-3 py-2 bg-amber-50 border border-amber-200 rounded-lg text-amber-800 text-sm flex items-center gap-2">
          <span>⚠️</span>
          <span>Showing first <strong>{tickets.length}</strong> of <strong>{ticketsTotalCount}</strong> tickets. Use filters or search to find specific tickets.</span>
        </div>
      )}

      {/* Pagination top bar */}
      <div className="flex items-center justify-between text-sm text-gray-600">
        <div>Showing {filteredTickets.length === 0 ? 0 : startIndex + 1}–{endIndex} of {filteredTickets.length} tickets</div>
        <div className="flex items-center gap-2">
          <label className="text-sm text-gray-600">Items per page:</label>
          <select value={itemsPerPage} onChange={(e) => { setItemsPerPage(parseInt(e.target.value)); setCurrentPage(1) }}
            className="px-3 py-1 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600">
            <option value={10}>10</option>
            <option value={25}>25</option>
            <option value={50}>50</option>
            <option value={100}>100</option>
          </select>
        </div>
      </div>

      {/* Bulk action bar */}
      {selectedTickets.length > 0 && (
        <div className="flex items-center gap-3 px-4 py-3 bg-indigo-50 border border-indigo-200 rounded-xl flex-wrap">
          <div className="flex items-center gap-2 text-sm font-medium text-indigo-700">
            <span className="w-6 h-6 bg-indigo-600 text-white rounded-full flex items-center justify-center text-xs font-bold">{selectedTickets.length}</span>
            ticket{selectedTickets.length !== 1 ? 's' : ''} selected
          </div>
          <button onClick={() => setSelectedTickets([])} className="text-xs text-indigo-500 hover:text-indigo-700 underline">Clear</button>
          <div className="h-5 w-px bg-indigo-200 hidden sm:block" />

          {/* Change ticket status */}
          {(canDo('edit_all') || canDo('change_status')) && (
            <div className="flex items-center gap-1.5">
              <select value={bulkTicketStatus} onChange={e => setBulkTicketStatus(e.target.value)}
                className="px-2.5 py-1.5 border border-indigo-300 rounded-lg text-xs bg-white focus:ring-2 focus:ring-indigo-500 focus:border-transparent">
                <option value="">Ticket Status…</option>
                <option>New</option>
                <option>In Progress</option>
                <option>On Hold</option>
                <option>Completed</option>
                <option>Cancelled</option>
              </select>
              <button onClick={handleBulkTicketStatus} disabled={!bulkTicketStatus || bulkProcessing}
                className="px-3 py-1.5 bg-indigo-600 text-white rounded-lg text-xs font-medium hover:bg-indigo-700 disabled:opacity-40 transition-colors">
                Apply
              </button>
            </div>
          )}

          {/* Change product status */}
          {(canDo('edit_all') || canDo('edit_assigned')) && (
            <div className="flex items-center gap-1.5">
              <select value={bulkProductStatus} onChange={e => setBulkProductStatus(e.target.value)}
                className="px-2.5 py-1.5 border border-indigo-300 rounded-lg text-xs bg-white focus:ring-2 focus:ring-indigo-500 focus:border-transparent">
                <option value="">Product Status…</option>
                <option>Received</option>
                <option>Under Repair</option>
                <option>Repaired</option>
                <option>Can't Repair</option>
                <option>Replacement</option>
                <option>Credit Note</option>
              </select>
              <button onClick={handleBulkProductStatus} disabled={!bulkProductStatus || bulkProcessing}
                className="px-3 py-1.5 bg-indigo-600 text-white rounded-lg text-xs font-medium hover:bg-indigo-700 disabled:opacity-40 transition-colors">
                Apply
              </button>
            </div>
          )}

          {/* Delete */}
          {canDo('delete') && (
            <>
              <div className="h-5 w-px bg-indigo-200 hidden sm:block" />
              <button onClick={handleBulkDelete} disabled={bulkProcessing}
                className="flex items-center gap-1.5 px-3 py-1.5 bg-red-600 text-white rounded-lg text-xs font-medium hover:bg-red-700 disabled:opacity-40 transition-colors">
                {bulkProcessing
                  ? <div className="animate-spin w-3 h-3 border-2 border-white border-t-transparent rounded-full" />
                  : <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                }
                Delete Selected
              </button>
            </>
          )}
        </div>
      )}

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead className="bg-gray-50 border-y border-gray-200">
            <tr>
              <th className="px-4 py-3 w-10">
                <input type="checkbox"
                  checked={paginatedTickets.length > 0 && selectedTickets.length === paginatedTickets.length}
                  onChange={toggleSelectAll}
                  className="rounded border-gray-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer" />
              </th>
              <th className="px-3 py-3 text-left text-xs font-medium text-gray-400 uppercase w-10">#</th>
              <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase"><SortableHeader label="RMA Number" sortKey="rma_number" sortConfig={sortConfig} onSort={handleSort} /></th>
              <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase"><SortableHeader label="Customer" sortKey="customer_name" sortConfig={sortConfig} onSort={handleSort} /></th>
              <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase"><SortableHeader label="Status" sortKey="ticket_status" sortConfig={sortConfig} onSort={handleSort} /></th>
              <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase"><SortableHeader label="Priority" sortKey="priority" sortConfig={sortConfig} onSort={handleSort} /></th>
              <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase"><SortableHeader label="Assigned To" sortKey="assigned_technician" sortConfig={sortConfig} onSort={handleSort} /></th>
              <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase"><SortableHeader label="Created Date" sortKey="created_date" sortConfig={sortConfig} onSort={handleSort} /></th>
              <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
            </tr>
          </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {paginatedTickets.map((t, idx) => (
                  <tr key={t.id} className={`hover:bg-gray-50 transition-colors ${selectedTickets.includes(t.id) ? 'bg-indigo-50/60' : ''}`}>
                    <td className="px-4 py-3">
                      <input type="checkbox" checked={selectedTickets.includes(t.id)} onChange={() => toggleSelectTicket(t.id)}
                        className="rounded border-gray-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer" />
                    </td>
                    <td className="px-3 py-3 text-xs text-gray-400 tabular-nums">{startIndex + idx + 1}</td>
                    <td className="px-4 py-3">
                      <button onClick={() => handleViewDetails(t)} className="font-mono text-sm font-medium text-indigo-600 hover:text-indigo-800">{t.rma_number}</button>
                    </td>
                    <td className="px-4 py-3 text-sm text-gray-900">{t.customer_name}</td>
                    <td className="px-4 py-3"><span className={`px-2 py-1 text-xs font-medium rounded-full ${getStatusColor(t.ticket_status)}`}>{t.ticket_status}</span></td>
                    <td className="px-4 py-3"><span className={`px-2 py-1 text-xs font-medium rounded-full ${getPriorityColor(t.priority)}`}>{t.priority}</span></td>
                    <td className="px-4 py-3 text-sm text-gray-600">{t.assigned_technician || 'Unassigned'}</td>
                    <td className="px-4 py-3 text-sm text-gray-600">{fmt(t.created_date)}</td>
                    <td className="px-4 py-3 relative action-menu">
                      <button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === t.id ? null : t.id) }}
                        className="p-1.5 rounded-lg text-gray-400 hover:text-gray-700 hover:bg-gray-100 transition-colors">
                        <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><circle cx="12" cy="5" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="12" cy="19" r="1.5"/></svg>
                      </button>
                      {openMenuId === t.id && (
                        <div className="absolute right-0 top-9 z-30 w-44 bg-white rounded-xl shadow-lg border border-gray-200 py-1 overflow-hidden">
                          <button onClick={() => { handleViewDetails(t); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2.5">
                            <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/></svg>
                            View
                          </button>
                          {(canDo('edit_all') || canDo('edit_assigned')) && (
                            <button onClick={() => { handleEdit(t); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2.5">
                              <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                              Edit
                            </button>
                          )}
                          <button onClick={() => { handleExportPDF(t); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2.5">
                            <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
                            Export PDF
                          </button>
                          {canDo('delete') && (
                            <button onClick={() => { handleDelete(t.id); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50 flex items-center gap-2.5">
                              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                              Delete
                            </button>
                          )}
                        </div>
                      )}
                    </td>
                  </tr>
                ))}
                {paginatedTickets.length === 0 && (
                  <tr><td colSpan={9} className="px-4 py-20 text-center">
                    <div className="flex flex-col items-center gap-3">
                      <div className="w-14 h-14 bg-gray-100 rounded-2xl flex items-center justify-center">
                        <svg className="w-7 h-7 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M15 5v2m0 4v2m0 4v2M5 5a2 2 0 00-2 2v3a2 2 0 110 4v3a2 2 0 002 2h14a2 2 0 002-2v-3a2 2 0 110-4V7a2 2 0 00-2-2H5z" />
                        </svg>
                      </div>
                      <div>
                        <p className="font-semibold text-gray-700">No tickets found</p>
                        <p className="text-sm text-gray-400 mt-0.5">
                          {tickets.length > 0 ? 'Try adjusting your filters or search term' : 'Create your first RMA ticket to get started'}
                        </p>
                      </div>
                      {canDo('create') && tickets.length === 0 && (
                        <button onClick={handleAddNew} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm font-medium hover:bg-indigo-700 transition-colors">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                          Create First Ticket
                        </button>
                      )}
                    </div>
                  </td></tr>
                )}
              </tbody>
            </table>
      </div>

      {/* Pagination footer */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between pt-4 border-t border-gray-200">
          <div className="flex items-center gap-2">
            <button onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1}
              className="px-3 py-2 border border-gray-300 rounded text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed">Previous</button>
            <div className="flex items-center gap-1">{renderPageNumbers()}</div>
            <button onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages}
              className="px-3 py-2 border border-gray-300 rounded text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed">Next</button>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-sm text-gray-600">Jump to page:</span>
            <input type="number" min="1" max={totalPages} value={jumpToPage}
              onChange={(e) => setJumpToPage(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleJumpToPage()}
              placeholder={currentPage.toString()}
              className="w-20 px-3 py-1 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600" />
            <button onClick={handleJumpToPage} className="px-3 py-1 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700">Go</button>
          </div>
        </div>
      )}

      {/* ─── CREATE / EDIT MODAL ─── */}
      {showModal && (
        <div className="modal-overlay-bg fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 overflow-y-auto overscroll-contain">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl my-8">

            <div className="flex items-center justify-between px-6 py-5 border-b border-gray-200">
              <div>
                <h2 className="text-xl font-bold text-gray-900">{editingTicket ? 'Edit RMA Ticket' : 'Create New RMA Ticket'}</h2>
                <div className="flex items-center gap-3 mt-1">
                  <p className="text-xs text-gray-400"><span className="text-red-500">*</span> Required fields</p>
                  {!editingTicket && (
                    <span className="text-xs font-mono font-medium text-indigo-600 bg-indigo-50 border border-indigo-200 px-2 py-0.5 rounded">
                      {previewRmaNumber}
                    </span>
                  )}
                  {editingTicket && (
                    <span className="text-xs font-mono font-medium text-gray-500 bg-gray-100 border border-gray-200 px-2 py-0.5 rounded">
                      {editingTicket.rma_number}
                    </span>
                  )}
                </div>
              </div>
              <button onClick={() => { setShowModal(false); setEditingTicket(null); resetForm() }} className="w-8 h-8 flex items-center justify-center rounded-full text-gray-400 hover:bg-gray-100">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>

            <form onSubmit={handleSubmit}>
              <div className="px-6 py-5 space-y-5 max-h-[72vh] overflow-y-auto">

                {/* Row 1: Customer + Priority */}
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className={lbl}>Customer Name <span className="text-red-500">*</span></label>
                    <div className="relative customer-dropdown">
                      <input
                        type="text"
                        value={customerSearch}
                        onChange={(e) => { setCustomerSearch(e.target.value); setFormData({ ...formData, customer_name: e.target.value }); setShowCustomerDropdown(true) }}
                        onFocus={() => setShowCustomerDropdown(true)}
                        placeholder="Search customer..."
                        className={inp}
                        required
                      />
                      {showCustomerDropdown && filteredCustomersList.length > 0 && (
                        <div className="absolute z-30 w-full bg-white border border-gray-200 rounded-lg shadow-xl mt-1 max-h-64 overflow-y-auto">
                          {filteredCustomersList.map(c => {
                            const displayName = c.customer_type === 'B2B' && c.company_name ? c.company_name : c.contact_person
                            return (
                              <button key={c.id} type="button"
                                onMouseDown={(e) => { e.preventDefault(); setCustomerSearch(displayName); setFormData({ ...formData, customer_name: displayName }); setShowCustomerDropdown(false) }}
                                className="w-full px-4 py-2.5 text-left hover:bg-indigo-50 border-b border-gray-100 last:border-0"
                              >
                                <div className="text-sm font-medium text-gray-900">{displayName}</div>
                                {c.customer_type === 'B2B' && c.contact_person && c.company_name && (
                                  <div className="text-xs text-gray-500">{c.contact_person} · <span className="font-medium text-blue-600">B2B</span></div>
                                )}
                                {c.customer_type === 'B2C' && (
                                  <div className="text-xs text-gray-500"><span className="font-medium text-emerald-600">B2C</span>{c.mobile ? ` · ${c.mobile}` : ''}</div>
                                )}
                              </button>
                            )
                          })}
                        </div>
                      )}
                    </div>
                  </div>
                  <div>
                    <label className={lbl}>Priority <span className="text-red-500">*</span></label>
                    <select value={formData.priority} onChange={(e) => setFormData({ ...formData, priority: e.target.value })} className={inp}>
                      <option value="Low">Low</option>
                      <option value="Medium">Medium</option>
                      <option value="High">High</option>
                      <option value="Critical">Critical</option>
                    </select>
                  </div>
                </div>

                {/* Row 2: Status + Assigned To + Due Date */}
                <div className="grid grid-cols-3 gap-4">
                  <div>
                    <label className={lbl}>Ticket Status</label>
                    <select value={formData.ticket_status} onChange={(e) => setFormData({ ...formData, ticket_status: e.target.value })} className={inp}>
                      <option value="New">New</option>
                      <option value="In Progress">In Progress</option>
                      <option value="On Hold">On Hold</option>
                      <option value="Completed">Completed</option>
                      <option value="Cancelled">Cancelled</option>
                    </select>
                  </div>
                  <div>
                    <label className={lbl}>Assigned To</label>
                    {(userRole === 'admin' || userRole === 'super_admin') ? (
                      <select value={formData.assigned_technician}
                        onChange={(e) => setFormData({ ...formData, assigned_technician: e.target.value })}
                        className={inp}>
                        {users.map(u => (
                          <option key={u.user_email} value={u.user_email}>{u.user_email}</option>
                        ))}
                      </select>
                    ) : (
                      <div className={`${inp} bg-gray-50 text-gray-600 cursor-not-allowed`}>
                        {formData.assigned_technician || userEmail || '—'}
                      </div>
                    )}
                  </div>
                  <div>
                    <label className={lbl}>Due Date <span className="text-xs text-gray-400 font-normal ml-1">auto +7 days</span></label>
                    <input type="date" value={formData.due_date}
                      onChange={(e) => setFormData({ ...formData, due_date: e.target.value })} className={inp} />
                  </div>
                </div>

                {/* Products */}
                <div>
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="text-base font-semibold text-gray-900">Products</h3>
                    <button type="button" onClick={addProduct} className="text-sm text-indigo-600 hover:text-indigo-800 font-medium">+ Add Product</button>
                  </div>
                  {formData.products.map((product, idx) => (
                    <div key={idx} className="border border-gray-200 rounded-xl p-4 mb-4 bg-gray-50">
                      <div className="flex items-center justify-between mb-3">
                        <h4 className="font-medium text-gray-800 text-sm">Product {idx + 1}</h4>
                        {formData.products.length > 1 && (
                          <button type="button" onClick={() => removeProduct(idx)} className="text-red-500 hover:text-red-700 text-xs font-medium">Remove</button>
                        )}
                      </div>
                      <div className="grid grid-cols-2 gap-3">
                        {/* Product name combobox */}
                        <div>
                          <label className={lbl}>Product Name <span className="text-red-500">*</span></label>
                          <div className="relative product-dropdown">
                            <input type="text"
                              value={productSearches[idx] || ''}
                              onChange={(e) => {
                                const s = [...productSearches]; s[idx] = e.target.value; setProductSearches(s)
                                updateProduct(idx, 'product_name', e.target.value)
                                const d = [...showProductDropdowns]; d[idx] = true; setShowProductDropdowns(d)
                              }}
                              onFocus={() => { const d = [...showProductDropdowns]; d[idx] = true; setShowProductDropdowns(d) }}
                              placeholder="Search or type product..."
                              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent text-sm bg-white"
                              required
                            />
                            {showProductDropdowns[idx] && filteredProductsList(productSearches[idx]).length > 0 && (
                              <div className="absolute z-30 w-full bg-white border border-gray-200 rounded-lg shadow-xl mt-1 max-h-40 overflow-y-auto">
                                {filteredProductsList(productSearches[idx]).map(p => (
                                  <button key={p.id} type="button"
                                    onMouseDown={(e) => {
                                      e.preventDefault()
                                      const s = [...productSearches]; s[idx] = p.product_name; setProductSearches(s)
                                      updateProduct(idx, 'product_name', p.product_name)
                                      const d = [...showProductDropdowns]; d[idx] = false; setShowProductDropdowns(d)
                                    }}
                                    className="w-full px-3 py-2 text-left hover:bg-indigo-50 border-b border-gray-100 last:border-0"
                                  >
                                    <div className="text-sm font-medium text-gray-900">{p.product_name}</div>
                                    <div className="text-xs text-gray-500">{p.sku}{p.brand?.brand_name ? ` · ${p.brand.brand_name}` : ''}</div>
                                  </button>
                                ))}
                              </div>
                            )}
                          </div>
                        </div>
                        <div>
                          <label className={lbl}>Serial Number <span className="text-red-500">*</span></label>
                          <input type="text" value={product.serial_number} onChange={(e) => updateProduct(idx, 'serial_number', e.target.value)}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 text-sm bg-white" required />
                        </div>
                        <div>
                          <label className={lbl}>Product Status</label>
                          <select value={product.product_status} onChange={(e) => updateProduct(idx, 'product_status', e.target.value)}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 text-sm bg-white">
                            <option>Received</option>
                            <option>Under Repair</option>
                            <option>Repaired</option>
                            <option>Can't Repair</option>
                            <option>Replacement</option>
                            <option>Credit Note</option>
                          </select>
                        </div>
                        <div>
                          <label className={lbl}>Warranty Status</label>
                          <select value={product.warranty_status} onChange={(e) => updateProduct(idx, 'warranty_status', e.target.value)}
                            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 text-sm bg-white">
                            <option>In Warranty</option>
                            <option>Out of Warranty</option>
                            <option>Extended Warranty</option>
                          </select>
                        </div>
                      </div>
                      <div className="mt-3">
                        <label className={lbl}>Issue Description <span className="text-red-500">*</span></label>
                        <textarea value={product.issue_description} onChange={(e) => updateProduct(idx, 'issue_description', e.target.value)}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 text-sm bg-white" rows={3} required />
                      </div>
                    </div>
                  ))}
                </div>

                {/* General RMA Description */}
                <div>
                  <label className={lbl}>General RMA Description</label>
                  <textarea value={formData.general_description}
                    onChange={(e) => setFormData({ ...formData, general_description: e.target.value })}
                    placeholder="General description for the RMA ticket (optional)..."
                    className={inp} rows={3} />
                </div>

                {/* Accessories Received */}
                <div>
                  <label className={lbl}>Accessories Received</label>
                  <textarea value={formData.accessories_received}
                    onChange={(e) => setFormData({ ...formData, accessories_received: e.target.value })}
                    placeholder="List any accessories received with the device..."
                    className={inp} rows={3} />
                </div>

                {/* Shipping Information */}
                <div className="border border-gray-200 rounded-xl p-4 space-y-3 bg-gray-50/50">
                  <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider">Shipping Information</p>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className={lbl}>Carrier</label>
                      <select value={formData.carrier} onChange={e => setFormData(f => ({ ...f, carrier: e.target.value }))}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 text-sm bg-white">
                        {CARRIERS.map(c => <option key={c} value={c}>{c || '— Select carrier —'}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className={lbl}>Tracking Number</label>
                      <input type="text" value={formData.tracking_number} onChange={e => setFormData(f => ({ ...f, tracking_number: e.target.value }))}
                        className={inp} placeholder="e.g. 1Z999AA10123456784" />
                    </div>
                  </div>
                  <div>
                    <label className={lbl}>Shipping Label URL <span className="text-gray-400 font-normal">(optional)</span></label>
                    <input type="url" value={formData.shipping_label_url} onChange={e => setFormData(f => ({ ...f, shipping_label_url: e.target.value }))}
                      className={inp} placeholder="https://..." />
                  </div>
                  {formData.tracking_number && formData.carrier && (
                    <a href={`https://www.google.com/search?q=${encodeURIComponent(formData.carrier + ' tracking ' + formData.tracking_number)}`}
                      target="_blank" rel="noopener noreferrer"
                      className="inline-flex items-center gap-1 text-xs text-indigo-600 hover:text-indigo-800 font-medium">
                      <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" /></svg>
                      Track shipment
                    </a>
                  )}
                </div>

                {/* Attachments */}
                <div>
                  <label className={lbl}>
                    Attachments
                    <span className="text-xs text-gray-400 font-normal ml-2">({(formData.attachments?.length || 0) + pendingFiles.length}/10)</span>
                  </label>

                  {/* Uploaded attachments */}
                  {(formData.attachments || []).length > 0 && (
                    <div className="mb-3 space-y-2">
                      {formData.attachments.map((att, i) => (
                        <div key={i} className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg border border-gray-200">
                          {isImage(att.type)
                            ? <img src={att.url} alt={att.name} className="w-10 h-10 object-cover rounded flex-shrink-0" />
                            : <div className="w-10 h-10 bg-indigo-100 rounded flex items-center justify-center flex-shrink-0">
                                <svg className="w-5 h-5 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                              </div>
                          }
                          <div className="flex-1 min-w-0">
                            <a href={att.url} target="_blank" rel="noreferrer" className="text-sm font-medium text-indigo-600 hover:underline truncate block">{att.name}</a>
                            <p className="text-xs text-gray-400">{fmtBytes(att.size)}</p>
                          </div>
                          <button type="button" onClick={() => handleDeleteAttachment(att, i)} className="text-red-400 hover:text-red-600 p-1 flex-shrink-0">
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                          </button>
                        </div>
                      ))}
                    </div>
                  )}

                  {/* Pending files */}
                  {pendingFiles.length > 0 && (
                    <div className="mb-3 space-y-2">
                      {pendingFiles.map((f, i) => (
                        <div key={i} className="flex items-center gap-3 p-3 bg-amber-50 rounded-lg border border-amber-200">
                          <div className="w-10 h-10 bg-amber-100 rounded flex items-center justify-center flex-shrink-0">
                            <svg className="w-5 h-5 text-amber-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                          </div>
                          <div className="flex-1 min-w-0">
                            <p className="text-sm font-medium text-gray-900 truncate">{f.name}</p>
                            <p className="text-xs text-amber-600">{fmtBytes(f.size)} · Will upload on save</p>
                          </div>
                          <button type="button" onClick={() => setPendingFiles(p => p.filter((_, idx) => idx !== i))} className="text-red-400 hover:text-red-600 p-1 flex-shrink-0">
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                          </button>
                        </div>
                      ))}
                    </div>
                  )}

                  {/* Drop zone */}
                  {(formData.attachments?.length || 0) + pendingFiles.length < 10 && (
                    <label className="border-2 border-dashed border-gray-300 rounded-xl p-6 text-center cursor-pointer hover:border-indigo-400 transition-colors block">
                      <svg className="w-10 h-10 text-gray-400 mx-auto mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                      <p className="text-sm font-medium text-indigo-600">Click to upload or drag and drop</p>
                      <p className="text-xs text-gray-400 mt-1">Up to 10 files · Images, PDFs, documents</p>
                      <input ref={fileInputRef} type="file" multiple onChange={handleFileSelect} className="hidden" accept="image/*,.pdf,.doc,.docx,.xls,.xlsx,.txt" />
                    </label>
                  )}
                </div>

              </div>

              {/* Footer */}
              <div className="flex gap-3 px-6 py-4 border-t border-gray-200 bg-gray-50 rounded-b-2xl">
                <Button variant="secondary" type="button" className="flex-1 justify-center" onClick={() => { setShowModal(false); setEditingTicket(null); resetForm() }}>
                  Cancel
                </Button>
                <Button type="submit" loading={uploading} className="flex-1 justify-center">
                  {editingTicket ? 'Update Ticket' : 'Create Ticket'}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ─── DETAILS MODAL ─── */}
      {showDetailsModal && selectedTicket && (
        <div className="modal-overlay-bg fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 overflow-y-auto overscroll-contain">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl my-8">

            <div className="flex items-center justify-between px-6 py-5 border-b border-gray-200">
              <div>
                <h2 className="text-xl font-bold text-gray-900">Ticket Details</h2>
                <p className="text-sm font-mono text-indigo-600 mt-0.5">{selectedTicket.rma_number}</p>
              </div>
              <div className="flex items-center gap-2">
                <button onClick={() => handleExportPDF(selectedTicket)}
                  className="flex items-center gap-2 px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 text-sm font-medium">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                  Export PDF
                </button>
                <button onClick={handleCloseDetails} className="w-8 h-8 flex items-center justify-center rounded-full text-gray-400 hover:bg-gray-100">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            </div>

            <div className="px-6 py-5 space-y-6 max-h-[72vh] overflow-y-auto">

              {/* Info grid */}
              <div>
                <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Ticket Information</h3>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                  {[
                    { label: 'Customer', value: selectedTicket.customer_name },
                    { label: 'Status', value: <span className={`px-2 py-1 text-xs font-medium rounded-full ${getStatusColor(selectedTicket.ticket_status)}`}>{selectedTicket.ticket_status}</span> },
                    { label: 'Priority', value: <span className={`px-2 py-1 text-xs font-medium rounded-full ${getPriorityColor(selectedTicket.priority)}`}>{selectedTicket.priority}</span> },
                    { label: 'Assigned To', value: selectedTicket.assigned_technician || 'Unassigned' },
                    { label: 'Due Date', value: fmt(selectedTicket.due_date) },
                    { label: 'Created', value: fmtDateTime(selectedTicket.created_date) },
                    { label: 'Created By', value: selectedTicket.created_by || '—' },
                  ].map(({ label, value }) => (
                    <div key={label}>
                      <p className="text-xs text-gray-500 mb-1">{label}</p>
                      <div className="text-sm font-medium text-gray-900">{value}</div>
                    </div>
                  ))}
                </div>
              </div>

              {/* General description */}
              {selectedTicket.general_description && (
                <div>
                  <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">General RMA Description</h3>
                  <div className="bg-gray-50 rounded-xl p-4 text-sm text-gray-700 whitespace-pre-wrap">{selectedTicket.general_description}</div>
                </div>
              )}

              {/* Products */}
              <div>
                <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Products ({(selectedTicket.products || []).length})</h3>
                {(selectedTicket.products || []).map((p, i) => (
                  <div key={i} className="border border-gray-200 rounded-xl p-4 mb-3">
                    <h4 className="font-semibold text-gray-800 text-sm mb-3">Product {i + 1} — {p.product_name}</h4>
                    <div className="grid grid-cols-2 gap-3 text-sm">
                      <div><p className="text-xs text-gray-500">Serial Number</p>
                        <div className="flex items-center gap-2">
                          <p className="font-mono font-medium">{p.serial_number || '—'}</p>
                          {p.serial_number && (
                            <button onClick={async () => { const h = await db.serialHistory.getBySerial(p.serial_number); setSerialHistory(h); setSerialHistorySerial(p.serial_number) }}
                              className="text-xs text-indigo-500 hover:text-indigo-700 underline">History</button>
                          )}
                        </div>
                      </div>
                      <div><p className="text-xs text-gray-500">Product Status</p><p className="font-medium">{p.product_status}</p></div>
                      <div><p className="text-xs text-gray-500">Warranty</p>
                        <p className="font-medium">{p.warranty_status}
                        </p>
                      </div>
                      <div className="col-span-2"><p className="text-xs text-gray-500">Issue Description</p><p className="font-medium">{p.issue_description}</p></div>
                    </div>
                  </div>
                ))}
              </div>

              {/* Serial History Panel */}
              {serialHistory.length > 0 && (
                <div className="border border-indigo-200 rounded-xl p-4 bg-indigo-50/50">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="text-xs font-semibold text-indigo-700 uppercase tracking-wider">Serial History — {serialHistorySerial}</h3>
                    <button onClick={() => { setSerialHistory([]); setSerialHistorySerial('') }} className="text-xs text-indigo-500 hover:text-indigo-700">✕ Close</button>
                  </div>
                  <div className="space-y-2">
                    {serialHistory.map(t => (
                      <div key={t.id} className={`flex items-center justify-between p-2 bg-white rounded-lg border text-xs ${t.id === selectedTicket.id ? 'border-indigo-300' : 'border-gray-200'}`}>
                        <span className="font-mono font-medium text-indigo-700">{t.rma_number}</span>
                        <span className="text-gray-600">{t.customer_name}</span>
                        <span className={`px-2 py-0.5 rounded-full font-medium ${getStatusColor(t.ticket_status)}`}>{t.ticket_status}</span>
                        <span className="text-gray-400">{t.created_date ? new Date(t.created_date).toLocaleDateString() : '—'}</span>
                        {t.id !== selectedTicket.id && <button onClick={() => handleViewDetails(t)} className="text-indigo-500 hover:text-indigo-700 underline">Open</button>}
                        {t.id === selectedTicket.id && <span className="text-indigo-500 italic">Current</span>}
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* ── Time Tracking ── */}
              {!timeEntriesMissing && (
                <div className="border-t border-gray-200 pt-5">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider">Time Tracking</h3>
                    <span className="text-xs text-indigo-600 font-medium">
                      Total: {Math.floor(timeEntries.reduce((sum, e) => sum + (e.duration_min || 0), 0) / 60)}h {timeEntries.reduce((sum, e) => sum + (e.duration_min || 0), 0) % 60}m
                    </span>
                  </div>
                  <div className="space-y-3">
                    {/* Timer controls */}
                    <div className="flex items-center gap-3 flex-wrap">
                      {!timerRunning ? (
                        <button
                          onClick={() => { setTimerRunning(true); setTimerStart(Date.now()) }}
                          className="flex items-center gap-1.5 px-3 py-1.5 bg-green-600 text-white rounded-lg text-xs font-medium hover:bg-green-700 transition-colors">
                          <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                          Start Timer
                        </button>
                      ) : (
                        <button
                          onClick={async () => {
                            const mins = Math.max(1, Math.round((Date.now() - timerStart) / 60000))
                            setTimerRunning(false)
                            try {
                              const entry = await db.timeEntries.create({
                                ticket_id: selectedTicket.id,
                                user_email: userEmail,
                                started_at: new Date(timerStart).toISOString(),
                                ended_at: new Date().toISOString(),
                                duration_min: mins,
                                notes: timerNotes || null,
                              })
                              setTimeEntries(prev => [...prev, entry])
                              setTimerNotes('')
                              toast.success(`Logged ${Math.floor(mins / 60)}h ${mins % 60}m`)
                            } catch { toast.error('Failed to save time entry') }
                            setTimerStart(null)
                          }}
                          className="flex items-center gap-1.5 px-3 py-1.5 bg-red-600 text-white rounded-lg text-xs font-medium hover:bg-red-700 transition-colors">
                          <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 24 24"><rect x="6" y="6" width="12" height="12"/></svg>
                          Stop &amp; Save
                        </button>
                      )}
                      {timerRunning && (
                        <input value={timerNotes} onChange={e => setTimerNotes(e.target.value)}
                          placeholder="Timer notes (optional)"
                          className="flex-1 min-w-0 px-2 py-1.5 border border-gray-200 rounded-lg text-xs focus:ring-1 focus:ring-indigo-400 outline-none" />
                      )}
                      {!timerRunning && (
                        <button onClick={() => setAddingManual(v => !v)}
                          className="text-xs text-indigo-500 hover:text-indigo-700 underline transition-colors">
                          {addingManual ? 'Cancel' : '+ Manual entry'}
                        </button>
                      )}
                    </div>
                    {/* Manual entry form */}
                    {addingManual && !timerRunning && (
                      <div className="bg-gray-50 border border-gray-200 rounded-xl p-3">
                        <div className="flex items-center gap-2 flex-wrap">
                          <input type="number" min="0" max="99" value={manualHours} onChange={e => setManualHours(e.target.value)}
                            placeholder="0" className="w-16 px-2 py-1.5 border border-gray-200 rounded-lg text-xs text-center focus:ring-1 focus:ring-indigo-400 outline-none" />
                          <span className="text-xs text-gray-500 font-medium">h</span>
                          <input type="number" min="0" max="59" value={manualMins} onChange={e => setManualMins(e.target.value)}
                            placeholder="0" className="w-16 px-2 py-1.5 border border-gray-200 rounded-lg text-xs text-center focus:ring-1 focus:ring-indigo-400 outline-none" />
                          <span className="text-xs text-gray-500 font-medium">m</span>
                          <input value={manualNotes} onChange={e => setManualNotes(e.target.value)}
                            placeholder="Notes (optional)" className="flex-1 min-w-0 px-2 py-1.5 border border-gray-200 rounded-lg text-xs focus:ring-1 focus:ring-indigo-400 outline-none" />
                          <button
                            onClick={async () => {
                              const mins = parseInt(manualHours || 0) * 60 + parseInt(manualMins || 0)
                              if (!mins) { toast.error('Enter hours or minutes'); return }
                              try {
                                const now = new Date().toISOString()
                                const entry = await db.timeEntries.create({
                                  ticket_id: selectedTicket.id,
                                  user_email: userEmail,
                                  started_at: now,
                                  ended_at: now,
                                  duration_min: mins,
                                  notes: manualNotes || null,
                                })
                                setTimeEntries(prev => [...prev, entry])
                                setManualHours(''); setManualMins(''); setManualNotes('')
                                setAddingManual(false)
                                toast.success(`Logged ${Math.floor(mins / 60)}h ${mins % 60}m`)
                              } catch { toast.error('Failed to log time') }
                            }}
                            className="px-3 py-1.5 bg-indigo-600 text-white rounded-lg text-xs font-medium hover:bg-indigo-700 transition-colors">
                            Log
                          </button>
                        </div>
                      </div>
                    )}
                    {/* Time log list */}
                    {timeEntries.length > 0 ? (
                      <div className="space-y-1.5 max-h-44 overflow-y-auto">
                        {[...timeEntries].reverse().map(entry => (
                          <div key={entry.id} className="flex items-center gap-2 p-2 bg-gray-50 rounded-lg text-xs group">
                            <span className="text-gray-500 shrink-0">{entry.user_email}</span>
                            <span className="font-semibold text-gray-800 shrink-0">{Math.floor((entry.duration_min || 0) / 60)}h {(entry.duration_min || 0) % 60}m</span>
                            {entry.notes && <span className="text-gray-400 flex-1 truncate">{entry.notes}</span>}
                            {!entry.notes && <span className="flex-1" />}
                            <span className="text-gray-400 shrink-0">{entry.created_date ? new Date(entry.created_date).toLocaleDateString() : '—'}</span>
                            {(userRole === 'admin' || userRole === 'super_admin' || entry.user_email === userEmail) && (
                              <button onClick={async () => {
                                try { await db.timeEntries.delete(entry.id); setTimeEntries(prev => prev.filter(e => e.id !== entry.id)); toast.success('Entry deleted') }
                                catch { toast.error('Failed to delete') }
                              }} className="opacity-0 group-hover:opacity-100 text-gray-300 hover:text-red-500 transition-all shrink-0">×</button>
                            )}
                          </div>
                        ))}
                      </div>
                    ) : (
                      <p className="text-xs text-gray-400 italic">No time entries yet.</p>
                    )}
                  </div>
                </div>
              )}

              {/* ── Parts Used ── */}
              {!ticketPartsMissing && (
                <div className="border-t border-gray-200 pt-5">
                  <div className="flex items-center justify-between mb-3">
                    <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider">Parts Used ({ticketParts.length})</h3>
                    {ticketParts.length > 0 && (
                      <span className="text-xs text-indigo-600 font-medium">
                        Cost: ${ticketParts.reduce((sum, p) => sum + (p.quantity * p.unit_cost), 0).toFixed(2)}
                      </span>
                    )}
                  </div>
                  {ticketParts.length > 0 ? (
                    <div className="space-y-2">
                      {ticketParts.map(tp => (
                        <div key={tp.id} className="flex items-center gap-3 p-2 bg-gray-50 rounded-lg text-xs">
                          <span className="font-medium text-gray-800 flex-1">{tp.parts?.part_name || '—'}</span>
                          {tp.parts?.part_number && <span className="text-gray-400 font-mono">{tp.parts.part_number}</span>}
                          <span className="text-gray-500">×{tp.quantity}</span>
                          <span className="font-semibold text-gray-700">${(tp.quantity * tp.unit_cost).toFixed(2)}</span>
                          {tp.notes && <span className="text-gray-400 truncate max-w-[8rem]">{tp.notes}</span>}
                        </div>
                      ))}
                    </div>
                  ) : (
                    <p className="text-xs text-gray-400 italic">No parts recorded on this ticket.</p>
                  )}
                </div>
              )}

              {/* Accessories */}
              {selectedTicket.accessories_received && (
                <div>
                  <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Accessories Received</h3>
                  <div className="bg-gray-50 rounded-xl p-4 text-sm text-gray-700 whitespace-pre-wrap">{selectedTicket.accessories_received}</div>
                </div>
              )}

              {/* Attachments */}
              {selectedTicket.attachments?.length > 0 && (
                <div>
                  <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">Attachments ({selectedTicket.attachments.length})</h3>
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                    {selectedTicket.attachments.map((att, i) => (
                      <a key={i} href={att.url} target="_blank" rel="noreferrer"
                        className="flex flex-col items-center p-3 border border-gray-200 rounded-xl hover:bg-indigo-50 hover:border-indigo-300 transition-colors group">
                        {isImage(att.type)
                          ? <img src={att.url} alt={att.name} className="w-full h-24 object-cover rounded-lg mb-2" />
                          : <div className="w-full h-24 bg-gray-100 rounded-lg flex items-center justify-center mb-2">
                              <svg className="w-10 h-10 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                            </div>
                        }
                        <p className="text-xs font-medium text-gray-700 group-hover:text-indigo-600 truncate w-full text-center">{att.name}</p>
                        <p className="text-xs text-gray-400">{fmtBytes(att.size)}</p>
                      </a>
                    ))}
                  </div>
                </div>
              )}

              {/* ── Comments & Communication ── */}
              <div className="border-t border-gray-200 pt-5">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wider">Comments & Communication</h3>
                  <span className="text-xs text-gray-400">{ticketComments.length} comment{ticketComments.length !== 1 ? 's' : ''}</span>
                </div>

                {commentsLoading ? (
                  <div className="flex justify-center py-6">
                    <Spinner size="md" />
                  </div>
                ) : ticketComments.filter(c => !c.parent_comment_id).length === 0 ? (
                  <div className="text-center py-6 text-gray-400 text-sm">No comments yet. Start the conversation below.</div>
                ) : (
                  <div className="space-y-3 mb-4">
                    {ticketComments.filter(c => !c.parent_comment_id).map(comment => {
                      const replies = ticketComments.filter(r => r.parent_comment_id === comment.id)
                      const displayName = comment.author_name || comment.user_email || '?'
                      const initials = displayName[0].toUpperCase()
                      const ts = new Date(comment.created_date)
                      const dateStr = ts.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' })
                      const timeStr = ts.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' })
                      return (
                        <div key={comment.id}>
                          <div className={`flex gap-3 p-4 rounded-xl border ${comment.is_internal ? 'bg-amber-50 border-amber-200' : 'bg-gray-50 border-gray-200'}`}>
                            <div className={`w-9 h-9 rounded-full flex items-center justify-center text-white font-semibold text-sm flex-shrink-0 ${comment.is_internal ? 'bg-amber-500' : comment.is_customer_comment ? 'bg-green-500' : 'bg-indigo-500'}`}>
                              {initials}
                            </div>
                            <div className="flex-1 min-w-0">
                              <div className="flex items-center gap-2 flex-wrap mb-1">
                                <span className="text-sm font-semibold text-gray-900">{displayName}</span>
                                {comment.is_internal && <span className="px-2 py-0.5 rounded-full text-xs font-medium bg-amber-100 text-amber-700 border border-amber-200">Internal</span>}
                                {comment.is_customer_comment && <span className="px-2 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-700 border border-green-200">Customer</span>}
                                <span className="text-xs text-gray-400">{dateStr} · {timeStr}</span>
                              </div>
                              <p className="text-sm text-gray-700 whitespace-pre-wrap">{comment.comment_text}</p>
                              {comment.attachments?.length > 0 && (
                                <div className="mt-2 flex flex-wrap gap-2">
                                  {comment.attachments.map((att, i) => (
                                    <a key={i} href={att.url} target="_blank" rel="noopener noreferrer"
                                      className="inline-flex items-center gap-1 px-2 py-1 bg-white border border-gray-200 rounded-lg text-xs text-indigo-600 hover:text-indigo-800 hover:border-indigo-300 transition-colors">
                                      <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
                                      {att.name}
                                    </a>
                                  ))}
                                </div>
                              )}
                              <button onClick={() => { setReplyingTo(replyingTo === comment.id ? null : comment.id); setNewComment(''); setCommentFiles([]) }}
                                className="mt-2 text-xs text-gray-400 hover:text-indigo-600 transition-colors flex items-center gap-1">
                                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6" /></svg>
                                Reply{replies.length > 0 ? ` (${replies.length})` : ''}
                              </button>
                            </div>
                            {(userRole === 'admin' || userRole === 'super_admin') && (
                              <button onClick={() => handleDeleteComment(comment.id)}
                                className="text-gray-300 hover:text-red-500 flex-shrink-0 self-start p-1 transition-colors" title="Delete comment">
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                              </button>
                            )}
                          </div>

                          {replies.length > 0 && (
                            <div className="ml-8 mt-2 space-y-2">
                              {replies.map(reply => {
                                const rName = reply.author_name || reply.user_email || '?'
                                const rTs = new Date(reply.created_date)
                                return (
                                  <div key={reply.id} className={`flex gap-3 p-3 rounded-xl border ${reply.is_internal ? 'bg-amber-50 border-amber-200' : 'bg-white border-gray-200'}`}>
                                    <div className={`w-7 h-7 rounded-full flex items-center justify-center text-white font-semibold text-xs flex-shrink-0 ${reply.is_internal ? 'bg-amber-400' : reply.is_customer_comment ? 'bg-green-400' : 'bg-indigo-400'}`}>
                                      {rName[0].toUpperCase()}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                      <div className="flex items-center gap-2 flex-wrap mb-1">
                                        <span className="text-xs font-semibold text-gray-900">{rName}</span>
                                        {reply.is_internal && <span className="px-1.5 py-0.5 rounded-full text-xs font-medium bg-amber-100 text-amber-700 border border-amber-200">Internal</span>}
                                        {reply.is_customer_comment && <span className="px-1.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-700 border border-green-200">Customer</span>}
                                        <span className="text-xs text-gray-400">
                                          {rTs.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} · {rTs.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' })}
                                        </span>
                                      </div>
                                      <p className="text-sm text-gray-700 whitespace-pre-wrap">{reply.comment_text}</p>
                                      {reply.attachments?.length > 0 && (
                                        <div className="mt-2 flex flex-wrap gap-2">
                                          {reply.attachments.map((att, i) => (
                                            <a key={i} href={att.url} target="_blank" rel="noopener noreferrer"
                                              className="inline-flex items-center gap-1 px-2 py-1 bg-white border border-gray-200 rounded-lg text-xs text-indigo-600 hover:text-indigo-800 hover:border-indigo-300 transition-colors">
                                              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
                                              {att.name}
                                            </a>
                                          ))}
                                        </div>
                                      )}
                                    </div>
                                    {(userRole === 'admin' || userRole === 'super_admin') && (
                                      <button onClick={() => handleDeleteComment(reply.id)}
                                        className="text-gray-300 hover:text-red-500 flex-shrink-0 self-start p-1 transition-colors">
                                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                                      </button>
                                    )}
                                  </div>
                                )
                              })}
                            </div>
                          )}

                          {replyingTo === comment.id && (
                            <div className="ml-8 mt-2 bg-white border border-indigo-200 rounded-xl p-3 space-y-2">
                              <div className="flex items-center gap-1.5 mb-1">
                                <svg className="w-3 h-3 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6" /></svg>
                                <span className="text-xs text-indigo-600 font-medium">Replying to {displayName}</span>
                              </div>
                              <textarea
                                value={newComment}
                                onChange={e => setNewComment(e.target.value)}
                                onKeyDown={e => { if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) handleAddComment(comment.id) }}
                                rows={2}
                                placeholder="Write a reply... (Ctrl+Enter to submit)"
                                className="w-full text-sm text-gray-700 resize-none outline-none placeholder-gray-400"
                                autoFocus
                              />
                              {commentFiles.length > 0 && (
                                <div className="flex flex-wrap gap-1">
                                  {commentFiles.map((f, i) => (
                                    <span key={i} className="inline-flex items-center gap-1 px-2 py-0.5 bg-gray-100 rounded text-xs text-gray-600">
                                      {f.name}
                                      <button onClick={() => setCommentFiles(prev => prev.filter((_, j) => j !== i))} className="text-gray-400 hover:text-red-500">×</button>
                                    </span>
                                  ))}
                                </div>
                              )}
                              <div className="flex items-center justify-between gap-2">
                                <div className="flex items-center gap-3">
                                  <button onClick={() => commentFileInputRef.current?.click()} className="text-gray-400 hover:text-indigo-600 transition-colors" title="Attach file">
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
                                  </button>
                                  <label className="flex items-center gap-1.5 cursor-pointer select-none">
                                    <div onClick={() => setIsInternalComment(v => !v)}
                                      className={`relative w-8 h-4 rounded-full transition-colors ${isInternalComment ? 'bg-amber-500' : 'bg-gray-200'}`}>
                                      <div className={`absolute top-0.5 left-0.5 w-3 h-3 bg-white rounded-full shadow transition-transform ${isInternalComment ? 'translate-x-4' : ''}`} />
                                    </div>
                                    <span className="text-xs text-gray-500">Internal</span>
                                  </label>
                                </div>
                                <div className="flex items-center gap-2">
                                  <button onClick={() => { setReplyingTo(null); setNewComment(''); setCommentFiles([]) }} className="text-xs text-gray-400 hover:text-gray-600">Cancel</button>
                                  <button onClick={() => handleAddComment(comment.id)}
                                    disabled={!newComment.trim() || submittingComment}
                                    className="flex items-center gap-1 px-3 py-1.5 bg-indigo-600 text-white rounded-lg text-xs font-medium hover:bg-indigo-700 disabled:opacity-50 transition-colors">
                                    {submittingComment ? <Spinner size="sm" color="white" /> : 'Reply'}
                                  </button>
                                </div>
                              </div>
                            </div>
                          )}
                        </div>
                      )
                    })}
                  </div>
                )}

                {!replyingTo && (
                  <div className="bg-white border border-gray-200 rounded-xl p-3 space-y-3">
                    <textarea
                      value={newComment}
                      onChange={e => setNewComment(e.target.value)}
                      onKeyDown={e => { if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) handleAddComment() }}
                      rows={3}
                      placeholder="Write a comment... (Ctrl+Enter to submit)"
                      className="w-full text-sm text-gray-700 resize-none outline-none placeholder-gray-400"
                    />
                    {commentFiles.length > 0 && (
                      <div className="flex flex-wrap gap-1">
                        {commentFiles.map((f, i) => (
                          <span key={i} className="inline-flex items-center gap-1 px-2 py-0.5 bg-gray-100 rounded text-xs text-gray-600">
                            {f.name}
                            <button onClick={() => setCommentFiles(prev => prev.filter((_, j) => j !== i))} className="text-gray-400 hover:text-red-500">×</button>
                          </span>
                        ))}
                      </div>
                    )}
                    <div className="flex items-center justify-between gap-3">
                      <div className="flex items-center gap-3">
                        <button onClick={() => commentFileInputRef.current?.click()} className="text-gray-400 hover:text-indigo-600 transition-colors" title="Attach file">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" /></svg>
                        </button>
                        <label className="flex items-center gap-2 cursor-pointer select-none">
                          <div onClick={() => setIsInternalComment(v => !v)}
                            className={`relative w-9 h-5 rounded-full transition-colors ${isInternalComment ? 'bg-amber-500' : 'bg-gray-200'}`}>
                            <div className={`absolute top-0.5 left-0.5 w-4 h-4 bg-white rounded-full shadow transition-transform ${isInternalComment ? 'translate-x-4' : ''}`} />
                          </div>
                          <span className="text-xs text-gray-600">Internal only</span>
                        </label>
                      </div>
                      <button
                        onClick={() => handleAddComment()}
                        disabled={(!newComment.trim() && commentFiles.length === 0) || submittingComment}
                        className="flex items-center gap-1.5 px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm font-medium hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors">
                        {submittingComment
                          ? <Spinner size="sm" color="white" />
                          : <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                        }
                        Post
                      </button>
                    </div>
                  </div>
                )}
                <input type="file" multiple ref={commentFileInputRef} className="hidden"
                  onChange={e => { setCommentFiles(prev => [...prev, ...Array.from(e.target.files)]); e.target.value = '' }} />
              </div>

            </div>

            <div className="flex justify-end gap-3 px-6 py-4 border-t border-gray-200">
              {(canDo('edit_all') || canDo('edit_assigned')) && (
                <Button onClick={() => { handleCloseDetails(); handleEdit(selectedTicket) }}>
                  Edit Ticket
                </Button>
              )}
              <Button variant="secondary" onClick={handleCloseDetails}>
                Close
              </Button>
            </div>
          </div>
        </div>
      )}

      <ConfirmDialog
        open={confirmDialog.open}
        title={confirmDialog.title}
        message={confirmDialog.message}
        onConfirm={confirmDialog.onConfirm}
        onCancel={closeConfirm}
      />
    </div>
  )
}

import React, { useState, useEffect, useRef, useCallback } from 'react'
import { supabase, db, storage, branding as brandingAPI } from '../api/supabaseClient'

// ── Client-side brute-force protection ──────────────────────────────────────
// Tracks "not found" attempts in localStorage. After MAX_FAILS failures within
// WINDOW_MS the tracker is locked for LOCKOUT_MS. This is a UX-layer defence;
// real rate-limiting requires a server-side edge function.
const RL_KEY = 'tracker_rl'
const MAX_FAILS = 10
const WINDOW_MS  = 5  * 60 * 1000  // 5-minute sliding window
const LOCKOUT_MS = 15 * 60 * 1000  // 15-minute lockout

function getRLState() {
  try { return JSON.parse(localStorage.getItem(RL_KEY) || '{}') } catch { return {} }
}
function saveRLState(s) {
  try { localStorage.setItem(RL_KEY, JSON.stringify(s)) } catch {}
}
/** Returns { locked: true, secsLeft } or { locked: false } */
function checkRateLimit() {
  const s = getRLState()
  if (s.lockedUntil && Date.now() < s.lockedUntil) {
    return { locked: true, secsLeft: Math.ceil((s.lockedUntil - Date.now()) / 1000) }
  }
  return { locked: false }
}
/** Call when a "not found" response is received. Returns updated RL state. */
function recordFailure() {
  const now = Date.now()
  let s = getRLState()
  // Reset window if it has expired
  if (!s.windowStart || now - s.windowStart > WINDOW_MS) {
    s = { windowStart: now, count: 0 }
  }
  s.count = (s.count || 0) + 1
  if (s.count >= MAX_FAILS) s.lockedUntil = now + LOCKOUT_MS
  saveRLState(s)
  return s
}
/** Clears the lockout (call on successful lookup). */
function clearFailures() {
  try { localStorage.removeItem(RL_KEY) } catch {}
}

const PRODUCT_STATUS_COLORS = {
  'Received':     'bg-blue-100 text-blue-700',
  'Under Repair': 'bg-yellow-100 text-yellow-700',
  'Repaired':     'bg-green-100 text-green-700',
  "Can't Repair": 'bg-red-100 text-red-700',
  'Replacement':  'bg-indigo-100 text-indigo-700',
  'Credit Note':  'bg-orange-100 text-orange-700',
}

const STATUS_STEPS = ['New', 'In Progress', 'On Hold', 'Completed', 'Cancelled']
const STATUS_COLORS = {
  New: 'bg-pink-500',
  'In Progress': 'bg-blue-500',
  'On Hold': 'bg-yellow-500',
  Completed: 'bg-green-500',
  Cancelled: 'bg-gray-500',
}
const STATUS_STEP_COLORS = {
  New: { active: 'border-pink-500 bg-pink-500', done: 'border-green-500 bg-green-500', text: 'text-pink-600' },
  'In Progress': { active: 'border-blue-500 bg-blue-500', done: 'border-green-500 bg-green-500', text: 'text-blue-600' },
  'On Hold': { active: 'border-yellow-500 bg-yellow-500', done: 'border-green-500 bg-green-500', text: 'text-yellow-600' },
  Completed: { active: 'border-green-500 bg-green-500', done: 'border-green-500 bg-green-500', text: 'text-green-600' },
  Cancelled: { active: 'border-gray-500 bg-gray-500', done: 'border-gray-500 bg-gray-500', text: 'text-gray-600' },
}

const SCHEMA_SQL = `-- Run these in your Supabase SQL editor:
ALTER TABLE ticket_comments ADD COLUMN IF NOT EXISTS parent_comment_id UUID REFERENCES ticket_comments(id) ON DELETE SET NULL;
ALTER TABLE ticket_comments ADD COLUMN IF NOT EXISTS attachments JSONB DEFAULT '[]';
ALTER TABLE ticket_comments ADD COLUMN IF NOT EXISTS is_customer_comment BOOLEAN DEFAULT false;`

function fmtDate(iso) {
  if (!iso) return '—'
  return new Date(iso).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' })
}
function fmtDateTime(iso) {
  if (!iso) return '—'
  const d = new Date(iso)
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) + ' · ' +
    d.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' })
}
function fileSize(bytes) {
  if (!bytes) return ''
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

export default function RMATracker() {
  const [branding, setBranding] = useState(null)
  const [query, setQuery] = useState('')
  const [loading, setLoading] = useState(false)
  const [ticket, setTicket] = useState(null)
  const [notFound, setNotFound] = useState(false)
  const [comments, setComments] = useState([])
  const [schemaOk, setSchemaOk] = useState(true)
  // Rate-limit state
  const [rlLocked, setRlLocked] = useState(() => checkRateLimit().locked)
  const [rlSecsLeft, setRlSecsLeft] = useState(0)
  const lastSearchRef = useRef(0)  // timestamp of last search attempt

  // New comment state
  const [authorName, setAuthorName] = useState('')
  const [authorEmail, setAuthorEmail] = useState('')
  const [messageText, setMessageText] = useState('')
  const [replyingTo, setReplyingTo] = useState(null)
  const [commentFiles, setCommentFiles] = useState([])
  const [uploadingFiles, setUploadingFiles] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const fileInputRef = useRef(null)

  // Countdown ticker while rate-limit lockout is active
  useEffect(() => {
    const rl = checkRateLimit()
    if (!rl.locked) { setRlLocked(false); return }
    setRlLocked(true)
    setRlSecsLeft(rl.secsLeft)
    const id = setInterval(() => {
      const updated = checkRateLimit()
      if (!updated.locked) { setRlLocked(false); clearInterval(id) }
      else setRlSecsLeft(updated.secsLeft)
    }, 1000)
    return () => clearInterval(id)
  }, [rlLocked])

  useEffect(() => {
    brandingAPI.getBranding().then(setBranding).catch(() => {})
    // Pre-fill RMA from URL ?rma=...
    const params = new URLSearchParams(window.location.search)
    const rma = params.get('rma') || params.get('rma_number')
    if (rma) { setQuery(rma); handleSearch(rma) }
  }, [])

  const handleSearch = useCallback(async (overrideQuery) => {
    const q = (overrideQuery || query).trim()
    if (!q) return

    // Enforce rate limit
    const rl = checkRateLimit()
    if (rl.locked) { setRlLocked(true); setRlSecsLeft(rl.secsLeft); return }

    // Throttle: at least 800 ms between searches
    const now = Date.now()
    if (now - lastSearchRef.current < 800) return
    lastSearchRef.current = now

    setLoading(true)
    setNotFound(false)
    setTicket(null)
    setComments([])
    try {
      const found = await db.rmaTracker.getTicketByRmaNumber(q)
      if (!found) {
        setNotFound(true)
        const s = recordFailure()
        if (s.lockedUntil) { setRlLocked(true); setRlSecsLeft(Math.ceil((s.lockedUntil - Date.now()) / 1000)) }
        return
      }
      clearFailures()
      setTicket(found)
      const c = await db.rmaTracker.getPublicComments(found.id)
      setComments(c)
      // Check if schema has new columns
      if (c.length > 0 && !('parent_comment_id' in c[0])) setSchemaOk(false)
    } finally { setLoading(false) }
  }, [query])

  const handleFileChange = (e) => {
    const files = Array.from(e.target.files)
    setCommentFiles(prev => [...prev, ...files])
    e.target.value = ''
  }

  const removeFile = (idx) => setCommentFiles(prev => prev.filter((_, i) => i !== idx))

  const handleSubmitComment = async (e) => {
    e.preventDefault()
    if (!messageText.trim() || !authorName.trim() || !ticket) return
    setSubmitting(true)
    try {
      let attachments = []
      if (commentFiles.length > 0) {
        setUploadingFiles(true)
        attachments = await Promise.all(commentFiles.map(f => storage.uploadCommentAttachment(f, ticket.id)))
        setUploadingFiles(false)
      }
      const comment = await db.rmaTracker.addComment(
        ticket.id, authorName.trim(), authorEmail.trim() || null,
        messageText.trim(), replyingTo, attachments
      )
      if (comment) setComments(prev => [...prev, comment])
      setMessageText('')
      setCommentFiles([])
      setReplyingTo(null)
    } catch (err) {
      alert('Failed to send message. Please try again.')
    } finally { setSubmitting(false); setUploadingFiles(false) }
  }

  const stepIdx = STATUS_STEPS.findIndex(s => s.toLowerCase() === ticket?.ticket_status?.toLowerCase())
  const products = ticket?.products || []
  const topComments = comments.filter(c => !c.parent_comment_id)
  const getReplies = (id) => comments.filter(c => c.parent_comment_id === id)

  const primaryColor = branding?.primary_color || '#4F46E5'
  const companyName = branding?.company_name || 'myRMA'

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 shadow-sm">
        <div className="max-w-4xl mx-auto px-4 py-4 flex items-center gap-3">
          {branding?.logo_url
            ? <img src={branding.logo_url} alt={companyName} className="h-9 object-contain" />
            : <div className="w-9 h-9 rounded-lg flex items-center justify-center text-white font-bold text-sm" style={{ backgroundColor: primaryColor }}>
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
              </div>
          }
          <div>
            <div className="font-bold text-gray-900 text-lg leading-tight">{companyName}</div>
            <div className="text-xs text-gray-500">Service Request Tracker</div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full px-4 py-10 space-y-8">

        {/* Schema notice (dev-only — never shown to customers) */}
        {!schemaOk && import.meta.env.DEV && (
          <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 text-sm text-amber-800">
            <strong>Database migration required.</strong> Run this SQL in your Supabase editor to enable replies and attachments:
            <pre className="mt-2 text-xs bg-amber-100 rounded p-3 overflow-x-auto whitespace-pre">{SCHEMA_SQL}</pre>
          </div>
        )}

        {/* Search hero */}
        <div className="text-center space-y-2">
          <h1 className="text-3xl font-bold text-gray-900">Track Your Service Request</h1>
          <p className="text-gray-500">Enter your RMA number to check the current status and communicate with our team.</p>
        </div>

        <form onSubmit={e => { e.preventDefault(); handleSearch() }} className="flex gap-3 max-w-xl mx-auto">
          <input
            value={query}
            onChange={e => setQuery(e.target.value)}
            placeholder="e.g. RMA-15052025-0001"
            className="flex-1 px-4 py-3 border border-gray-300 rounded-xl text-sm focus:ring-2 focus:ring-indigo-600 focus:border-transparent shadow-sm"
            disabled={rlLocked}
          />
          <button type="submit" disabled={loading || !query.trim() || rlLocked}
            className="px-6 py-3 rounded-xl text-white text-sm font-semibold shadow-sm disabled:opacity-50 transition-colors hover:opacity-90"
            style={{ backgroundColor: primaryColor }}>
            {loading ? <div className="animate-spin w-5 h-5 border-2 border-white border-t-transparent rounded-full" /> : 'Track'}
          </button>
        </form>

        {/* Rate-limit lockout banner */}
        {rlLocked && (
          <div className="max-w-xl mx-auto bg-red-50 border border-red-200 rounded-xl p-4 text-sm text-red-700 text-center space-y-1">
            <p className="font-semibold">Too many failed lookups</p>
            <p>Please wait <span className="font-mono font-bold">{Math.floor(rlSecsLeft / 60)}:{String(rlSecsLeft % 60).padStart(2, '0')}</span> before trying again.</p>
          </div>
        )}

        {/* Not found */}
        {notFound && !rlLocked && (
          <div className="text-center py-10 space-y-2">
            <div className="text-5xl">🔍</div>
            <p className="text-gray-700 font-medium">No ticket found for <span className="font-mono text-indigo-600">"{query}"</span></p>
            <p className="text-gray-500 text-sm">Please double-check your RMA number and try again.</p>
          </div>
        )}

        {/* Ticket result */}
        {ticket && (
          <div className="space-y-6">
            {/* Status card */}
            <div className="bg-white rounded-2xl border border-gray-200 shadow-sm p-6 space-y-5">
              <div className="flex items-start justify-between flex-wrap gap-3">
                <div>
                  <div className="text-xs text-gray-400 uppercase tracking-wider font-medium mb-1">RMA Number</div>
                  <div className="text-2xl font-bold text-gray-900 font-mono">{ticket.rma_number}</div>
                </div>
                <span className={`px-4 py-1.5 rounded-full text-sm font-semibold text-white ${STATUS_COLORS[ticket.ticket_status] || 'bg-gray-400'}`}>
                  {ticket.ticket_status}
                </span>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-3 gap-4 text-sm">
                <div>
                  <div className="text-xs text-gray-400 uppercase tracking-wide mb-0.5">Received</div>
                  <div className="font-medium text-gray-800">{fmtDate(ticket.created_date)}</div>
                </div>
                {ticket.due_date && (
                  <div>
                    <div className="text-xs text-gray-400 uppercase tracking-wide mb-0.5">Estimated Completion</div>
                    <div className="font-medium text-gray-800">{fmtDate(ticket.due_date)}</div>
                  </div>
                )}
                {ticket.priority && (
                  <div>
                    <div className="text-xs text-gray-400 uppercase tracking-wide mb-0.5">Priority</div>
                    <div className="font-medium text-gray-800">{ticket.priority}</div>
                  </div>
                )}
              </div>

              {/* Status timeline */}
              <div>
                <div className="flex items-center justify-between mb-3">
                  <div className="text-xs text-gray-400 uppercase tracking-wide font-medium">Progress</div>
                  <button onClick={() => handleSearch(ticket.rma_number)}
                    className="flex items-center gap-1 text-xs text-gray-400 hover:text-indigo-600 transition-colors px-2 py-1 rounded-lg hover:bg-indigo-50">
                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg>
                    Refresh
                  </button>
                </div>
                <div className="flex items-center gap-0">
                  {STATUS_STEPS.map((step, i) => {
                    const done = i <= stepIdx
                    const active = i === stepIdx
                    const isLast = i === STATUS_STEPS.length - 1
                    const colors = STATUS_STEP_COLORS[step] || { active: 'border-indigo-600 bg-indigo-600', done: 'border-green-500 bg-green-500', text: 'text-indigo-600' }
                    return (
                      <React.Fragment key={step}>
                        <div className="flex flex-col items-center gap-1.5 flex-shrink-0">
                          <div className={`w-7 h-7 rounded-full flex items-center justify-center border-2 transition-all ${
                            active ? colors.active :
                            done ? colors.done :
                            'border-gray-200 bg-white'}`}>
                            {done && !active
                              ? <svg className="w-3.5 h-3.5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7"/></svg>
                              : active
                              ? <div className="w-2 h-2 bg-white rounded-full" />
                              : null
                            }
                          </div>
                          <span className={`text-[10px] font-medium leading-tight text-center max-w-[52px] ${active ? colors.text : done ? 'text-green-600' : 'text-gray-400'}`}>
                            {step}
                          </span>
                        </div>
                        {!isLast && (
                          <div className={`h-0.5 flex-1 mx-1 mb-4 ${i < stepIdx ? 'bg-green-400' : 'bg-gray-200'}`} />
                        )}
                      </React.Fragment>
                    )
                  })}
                </div>
              </div>
            </div>

            {/* General description */}
            {ticket.general_description && (
              <div className="bg-white rounded-2xl border border-gray-200 shadow-sm p-6">
                <h2 className="text-sm font-semibold text-gray-500 uppercase tracking-wider mb-3">Issue Description</h2>
                <p className="text-gray-700 text-sm leading-relaxed whitespace-pre-wrap">{ticket.general_description}</p>
              </div>
            )}

            {/* Products */}
            {products.length > 0 && (
              <div className="bg-white rounded-2xl border border-gray-200 shadow-sm p-6">
                <h2 className="text-sm font-semibold text-gray-500 uppercase tracking-wider mb-4">
                  Items ({products.length})
                </h2>
                <div className="space-y-3">
                  {products.map((p, i) => (
                    <div key={i} className="flex items-start gap-4 p-4 bg-gray-50 rounded-xl border border-gray-100">
                      <div className="w-9 h-9 bg-indigo-100 rounded-lg flex items-center justify-center flex-shrink-0">
                        <svg className="w-5 h-5 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 3H5a2 2 0 00-2 2v4m6-6h10a2 2 0 012 2v4M9 3v18m0 0h10a2 2 0 002-2V9M9 21H5a2 2 0 01-2-2V9m0 0h18"/></svg>
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="font-medium text-gray-900 text-sm">{p.product_name || `Item ${i + 1}`}</div>
                        {p.serial_number && <div className="text-xs text-gray-500 mt-0.5 font-mono">S/N: {p.serial_number}</div>}
                        {p.issue_description && <div className="text-xs text-gray-600 mt-1">{p.issue_description}</div>}
                        <div className="flex gap-2 mt-2 flex-wrap">
                          {p.product_status && (
                            <span className={`px-2 py-0.5 text-xs rounded-full font-medium ${PRODUCT_STATUS_COLORS[p.product_status] || 'bg-gray-100 text-gray-600'}`}>
                              {p.product_status}
                            </span>
                          )}
                          {p.warranty_status && (
                            <span className={`px-2 py-0.5 text-xs rounded-full font-medium ${p.warranty_status === 'In Warranty' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                              {p.warranty_status}
                            </span>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Messages */}
            <div className="bg-white rounded-2xl border border-gray-200 shadow-sm p-6">
              <h2 className="text-sm font-semibold text-gray-500 uppercase tracking-wider mb-5">
                Messages {comments.length > 0 && <span className="ml-1 text-gray-400">({comments.length})</span>}
              </h2>

              {/* Thread */}
              {comments.length === 0 ? (
                <div className="text-center py-6 text-gray-400 text-sm">No messages yet. Send a message below to contact our team.</div>
              ) : (
                <div className="space-y-4 mb-6">
                  {topComments.map(comment => (
                    <CommentThread
                      key={comment.id}
                      comment={comment}
                      replies={getReplies(comment.id)}
                      replyingTo={replyingTo}
                      onReply={() => setReplyingTo(replyingTo === comment.id ? null : comment.id)}
                    />
                  ))}
                </div>
              )}

              {/* Compose */}
              <div className="border border-gray-200 rounded-xl p-4 space-y-3 bg-gray-50">
                <div className="text-sm font-semibold text-gray-700">
                  {replyingTo ? (
                    <div className="flex items-center justify-between">
                      <span>Replying to message</span>
                      <button onClick={() => setReplyingTo(null)} className="text-xs text-indigo-600 hover:underline">Cancel reply</button>
                    </div>
                  ) : 'Send a Message'}
                </div>
                <form onSubmit={handleSubmitComment} className="space-y-3">
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <input value={authorName} onChange={e => setAuthorName(e.target.value)} required
                        placeholder="Your name *" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600 bg-white" />
                    </div>
                    <div>
                      <input type="email" value={authorEmail} onChange={e => setAuthorEmail(e.target.value)}
                        placeholder="Email (optional)" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600 bg-white" />
                    </div>
                  </div>
                  <textarea value={messageText} onChange={e => setMessageText(e.target.value)} required rows={3}
                    placeholder="Write your message..." className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600 resize-none bg-white" />

                  {/* File attachments */}
                  {commentFiles.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                      {commentFiles.map((f, i) => (
                        <div key={i} className="flex items-center gap-1.5 px-2 py-1 bg-white border border-gray-200 rounded-lg text-xs text-gray-700">
                          <svg className="w-3.5 h-3.5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13"/></svg>
                          <span className="max-w-[120px] truncate">{f.name}</span>
                          <span className="text-gray-400">({fileSize(f.size)})</span>
                          <button type="button" onClick={() => removeFile(i)} className="text-gray-400 hover:text-red-500 ml-0.5">✕</button>
                        </div>
                      ))}
                    </div>
                  )}

                  <div className="flex items-center justify-between">
                    <button type="button" onClick={() => fileInputRef.current?.click()}
                      className="flex items-center gap-1.5 text-xs text-gray-600 hover:text-indigo-600 px-3 py-1.5 border border-gray-300 rounded-lg hover:bg-white transition-colors">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13"/></svg>
                      Attach file
                    </button>
                    <input ref={fileInputRef} type="file" multiple className="hidden" onChange={handleFileChange} />
                    <button type="submit" disabled={submitting || !messageText.trim() || !authorName.trim()}
                      className="flex items-center gap-2 px-5 py-2 rounded-lg text-sm font-semibold text-white disabled:opacity-50 transition-opacity hover:opacity-90"
                      style={{ backgroundColor: primaryColor }}>
                      {submitting
                        ? <><div className="animate-spin w-4 h-4 border-2 border-white border-t-transparent rounded-full" />{uploadingFiles ? 'Uploading…' : 'Sending…'}</>
                        : <><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8"/></svg>Send Message</>
                      }
                    </button>
                  </div>
                </form>
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="border-t border-gray-200 mt-10 py-5 text-center text-xs text-gray-400">
        Powered by <span className="font-semibold text-gray-500">myRMA</span> — Secure service request tracking
      </footer>
    </div>
  )
}

function CommentThread({ comment, replies, replyingTo, onReply }) {
  const isTeam = !comment.is_customer_comment
  const displayName = comment.author_name || comment.user_email || 'Team'
  const initials = displayName[0]?.toUpperCase() || '?'
  const attachments = comment.attachments || []

  return (
    <div>
      <CommentBubble
        comment={comment}
        isTeam={isTeam}
        displayName={displayName}
        initials={initials}
        attachments={attachments}
        showReplyBtn
        isReplying={replyingTo === comment.id}
        onReply={onReply}
      />
      {replies.length > 0 && (
        <div className="ml-8 mt-2 space-y-2 pl-4 border-l-2 border-gray-100">
          {replies.map(reply => {
            const rIsTeam = !reply.is_customer_comment
            const rName = reply.author_name || reply.user_email || 'Team'
            return (
              <CommentBubble key={reply.id}
                comment={reply}
                isTeam={rIsTeam}
                displayName={rName}
                initials={rName[0]?.toUpperCase() || '?'}
                attachments={reply.attachments || []}
              />
            )
          })}
        </div>
      )}
    </div>
  )
}

function CommentBubble({ comment, isTeam, displayName, initials, attachments, showReplyBtn, isReplying, onReply }) {
  return (
    <div className={`flex gap-3 p-4 rounded-xl border ${isTeam ? 'bg-indigo-50 border-indigo-100' : 'bg-gray-50 border-gray-100'}`}>
      <div className={`w-9 h-9 rounded-full flex items-center justify-center text-white font-semibold text-sm flex-shrink-0 ${isTeam ? 'bg-indigo-500' : 'bg-gray-400'}`}>
        {initials}
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2 flex-wrap mb-1">
          <span className="text-sm font-semibold text-gray-900">{displayName}</span>
          {isTeam && <span className="px-2 py-0.5 text-xs font-medium bg-indigo-100 text-indigo-700 rounded-full">Support Team</span>}
          <span className="text-xs text-gray-400 ml-auto">{fmtDateTime(comment.created_date)}</span>
        </div>
        <p className="text-sm text-gray-700 whitespace-pre-wrap leading-relaxed">{comment.comment_text}</p>
        {attachments.length > 0 && (
          <div className="flex flex-wrap gap-2 mt-2">
            {attachments.map((att, i) => (
              <a key={i} href={att.url} target="_blank" rel="noopener noreferrer"
                className="flex items-center gap-1.5 px-2.5 py-1 bg-white border border-gray-200 rounded-lg text-xs text-indigo-600 hover:bg-indigo-50 transition-colors">
                <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13"/></svg>
                <span className="max-w-[140px] truncate">{att.name}</span>
              </a>
            ))}
          </div>
        )}
        {showReplyBtn && (
          <button onClick={onReply} className={`mt-2 text-xs font-medium transition-colors ${isReplying ? 'text-indigo-600' : 'text-gray-400 hover:text-indigo-500'}`}>
            {isReplying ? '↩ Cancel reply' : '↩ Reply'}
          </button>
        )}
      </div>
    </div>
  )
}

import React, { useState, useEffect, useCallback, useMemo } from 'react'
import { db } from '../api/supabaseClient'
import toast from 'react-hot-toast'
import { Spinner, PageHeader } from '../components/ui'
import { useAppearance } from '../contexts/AppearanceContext'

// ─── CSV Utility ──────────────────────────────────────────────────────────────
function downloadCSV(rows, columns, filename) {
  if (!rows.length) { toast('No data to export'); return }
  const headers = columns.map(c => c.label)
  const escape = v => { const s = String(v ?? '').replace(/"/g, '""'); return s.includes(',') || s.includes('\n') || s.includes('"') ? `"${s}"` : s }
  const csv = [headers.join(','), ...rows.map(r => columns.map(c => escape(r[c.key] ?? '')).join(','))].join('\r\n')
  const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' })
  const url = URL.createObjectURL(blob)
  const a = Object.assign(document.createElement('a'), { href: url, download: filename })
  document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url)
  toast.success(`Exported ${rows.length} rows`)
}

// ─── Date helpers ─────────────────────────────────────────────────────────────
function startOfDay(date) {
  const d = new Date(date); d.setHours(0, 0, 0, 0); return d
}
function endOfDay(date) {
  const d = new Date(date); d.setHours(23, 59, 59, 999); return d
}
function toYMD(date) {
  return new Date(date).toISOString().split('T')[0]
}
function resolutionHours(ticket) {
  if (ticket.ticket_status !== 'Completed' || !ticket.updated_date) return null
  const ms = new Date(ticket.updated_date) - new Date(ticket.created_date)
  return ms > 0 ? (ms / 3600000).toFixed(1) : null
}
function inRange(dateStr, from, to) {
  if (!dateStr) return false
  const d = new Date(dateStr)
  return d >= startOfDay(from) && d <= endOfDay(to)
}

// ─── KPI Card ─────────────────────────────────────────────────────────────────
function KpiCard({ label, value, icon, color = 'indigo', sub }) {
  const colors = {
    indigo: { bg: 'bg-indigo-50', icon: 'text-indigo-600', val: 'text-indigo-700' },
    green:  { bg: 'bg-green-50',  icon: 'text-green-600',  val: 'text-green-700'  },
    amber:  { bg: 'bg-amber-50',  icon: 'text-amber-600',  val: 'text-amber-700'  },
    red:    { bg: 'bg-red-50',    icon: 'text-red-600',    val: 'text-red-700'    },
    blue:   { bg: 'bg-blue-50',   icon: 'text-blue-600',   val: 'text-blue-700'   },
    purple: { bg: 'bg-purple-50', icon: 'text-purple-600', val: 'text-purple-700' },
  }
  const c = colors[color] || colors.indigo
  return (
    <div className="bg-white rounded-xl border border-gray-200 p-5 flex items-start gap-4">
      <div className={`w-10 h-10 rounded-xl ${c.bg} flex items-center justify-center flex-shrink-0`}>
        <svg className={`w-5 h-5 ${c.icon}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={icon} />
        </svg>
      </div>
      <div className="min-w-0">
        <p className={`text-2xl font-bold ${c.val} leading-none`}>{value}</p>
        <p className="text-sm text-gray-500 mt-1">{label}</p>
        {sub && <p className="text-xs text-gray-400 mt-0.5">{sub}</p>}
      </div>
    </div>
  )
}

// ─── Migration Banner ─────────────────────────────────────────────────────────
function MigrationBanner({ table, children }) {
  return (
    <div className="flex items-start gap-3 px-4 py-3 bg-amber-50 border border-amber-200 rounded-xl">
      <svg className="w-5 h-5 text-amber-600 flex-shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
      <div className="text-sm text-amber-800">
        <span className="font-semibold">The <code className="font-mono bg-amber-100 px-1 rounded">{table}</code> table has not been set up.</span>{' '}
        {children || 'Run the required SQL migration in Supabase to enable this feature.'}
      </div>
    </div>
  )
}

// ─── Status Badge ─────────────────────────────────────────────────────────────
function StatusBadge({ status }) {
  const map = {
    'New':         'bg-blue-100 text-blue-700',
    'In Progress': 'bg-yellow-100 text-yellow-700',
    'On Hold':     'bg-orange-100 text-orange-700',
    'Completed':   'bg-green-100 text-green-700',
    'Cancelled':   'bg-gray-100 text-gray-500',
  }
  return <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${map[status] || 'bg-gray-100 text-gray-600'}`}>{status || '—'}</span>
}

function PriorityBadge({ priority }) {
  const map = {
    'Critical': 'bg-red-100 text-red-700',
    'High':     'bg-orange-100 text-orange-700',
    'Medium':   'bg-yellow-100 text-yellow-700',
    'Low':      'bg-gray-100 text-gray-600',
  }
  return <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${map[priority] || 'bg-gray-100 text-gray-600'}`}>{priority || '—'}</span>
}

// ─── Tickets Tab ──────────────────────────────────────────────────────────────
function TicketsTab({ tickets, onNavigateToTicket, formatDate }) {
  const [filterStatus, setFilterStatus]       = useState('')
  const [filterPriority, setFilterPriority]   = useState('')
  const [filterTechnician, setFilterTechnician] = useState('')

  const statuses    = useMemo(() => [...new Set(tickets.map(t => t.ticket_status).filter(Boolean))].sort(), [tickets])
  const priorities  = useMemo(() => [...new Set(tickets.map(t => t.priority).filter(Boolean))].sort(), [tickets])
  const technicians = useMemo(() => [...new Set(tickets.map(t => t.assigned_technician).filter(Boolean))].sort(), [tickets])

  const filtered = useMemo(() => {
    let list = [...tickets]
    if (filterStatus)     list = list.filter(t => t.ticket_status === filterStatus)
    if (filterPriority)   list = list.filter(t => t.priority === filterPriority)
    if (filterTechnician) list = list.filter(t => t.assigned_technician === filterTechnician)
    return list
  }, [tickets, filterStatus, filterPriority, filterTechnician])

  const total       = filtered.length
  const completed   = filtered.filter(t => t.ticket_status === 'Completed')
  const overdue     = filtered.filter(t => t.due_date && new Date(t.due_date) < new Date() && t.ticket_status !== 'Completed' && t.ticket_status !== 'Cancelled')
  const resolveTimes = completed.map(t => resolutionHours(t)).filter(v => v !== null).map(Number)
  const avgResolve   = resolveTimes.length ? (resolveTimes.reduce((s, v) => s + v, 0) / resolveTimes.length).toFixed(1) : '—'

  const completedWithDue = completed.filter(t => t.due_date)
  const slaMet = completedWithDue.filter(t => !t.due_date || new Date(t.updated_date) <= new Date(t.due_date))
  const slaPct = completedWithDue.length ? Math.round(slaMet.length / completedWithDue.length * 100) : '—'

  const handleExport = () => {
    const columns = [
      { key: 'rma_number', label: 'RMA #' },
      { key: 'customer_name', label: 'Customer' },
      { key: 'ticket_status', label: 'Status' },
      { key: 'priority', label: 'Priority' },
      { key: 'assigned_technician', label: 'Technician' },
      { key: 'created_date', label: 'Created' },
      { key: 'due_date', label: 'Due' },
      { key: 'resolved_date', label: 'Resolved' },
      { key: 'resolution_hrs', label: 'Resolution (hrs)' },
    ]
    const rows = filtered.map(t => ({
      rma_number: t.rma_number || '',
      customer_name: t.customer_name || '',
      ticket_status: t.ticket_status || '',
      priority: t.priority || '',
      assigned_technician: t.assigned_technician || '',
      created_date: formatDate(t.created_date),
      due_date: formatDate(t.due_date),
      resolved_date: t.ticket_status === 'Completed' ? formatDate(t.updated_date) : '',
      resolution_hrs: resolutionHours(t) ?? 'Open',
    }))
    downloadCSV(rows, columns, `tickets-report-${toYMD(new Date())}.csv`)
  }

  const sel = 'px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent bg-white'

  return (
    <div className="space-y-5">
      {/* KPIs */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <KpiCard label="Total Tickets" value={total} color="indigo" icon="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
        <KpiCard label="Avg Resolution Time" value={avgResolve === '—' ? '—' : `${avgResolve}h`} color="blue" icon="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
        <KpiCard label="SLA Compliance" value={slaPct === '—' ? '—' : `${slaPct}%`} color="green" icon="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
        <KpiCard label="Overdue Rate" value={total ? `${Math.round(overdue.length / total * 100)}%` : '—'} color="red" icon="M12 9v2m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" sub={`${overdue.length} overdue`} />
      </div>

      {/* Filters + Export */}
      <div className="flex items-center gap-3 flex-wrap">
        <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className={sel}>
          <option value="">All Statuses</option>
          {statuses.map(s => <option key={s} value={s}>{s}</option>)}
        </select>
        <select value={filterPriority} onChange={e => setFilterPriority(e.target.value)} className={sel}>
          <option value="">All Priorities</option>
          {priorities.map(p => <option key={p} value={p}>{p}</option>)}
        </select>
        <select value={filterTechnician} onChange={e => setFilterTechnician(e.target.value)} className={sel}>
          <option value="">All Technicians</option>
          {technicians.map(t => <option key={t} value={t}>{t}</option>)}
        </select>
        <span className="text-sm text-gray-400">{filtered.length} ticket{filtered.length !== 1 ? 's' : ''}</span>
        <button onClick={handleExport} className="ml-auto flex items-center gap-1.5 px-3 py-2 border border-gray-200 rounded-lg text-sm text-gray-600 hover:bg-gray-50 transition-colors">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
          Export CSV
        </button>
      </div>

      {/* Table */}
      {filtered.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-xl border border-gray-200">
          <p className="text-sm text-gray-400">No tickets match the selected filters</p>
        </div>
      ) : (
        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b border-gray-200">
                <tr>
                  {['RMA #', 'Customer', 'Status', 'Priority', 'Technician', 'Created', 'Due', 'Resolved', 'Resolution'].map(h => (
                    <th key={h} className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider whitespace-nowrap">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {filtered.map(t => {
                  const hrs = resolutionHours(t)
                  return (
                    <tr key={t.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-4 py-3">
                        <button
                          onClick={() => onNavigateToTicket?.(t.id)}
                          className="font-mono text-indigo-600 hover:text-indigo-800 hover:underline text-xs font-medium">
                          {t.rma_number || t.id?.slice(0, 8)}
                        </button>
                      </td>
                      <td className="px-4 py-3 text-gray-700 max-w-[160px] truncate">{t.customer_name || '—'}</td>
                      <td className="px-4 py-3"><StatusBadge status={t.ticket_status} /></td>
                      <td className="px-4 py-3"><PriorityBadge priority={t.priority} /></td>
                      <td className="px-4 py-3 text-gray-500 text-xs max-w-[120px] truncate">{t.assigned_technician || '—'}</td>
                      <td className="px-4 py-3 text-gray-500 text-xs whitespace-nowrap">{formatDate(t.created_date)}</td>
                      <td className="px-4 py-3 text-xs whitespace-nowrap">
                        {t.due_date
                          ? <span className={new Date(t.due_date) < new Date() && t.ticket_status !== 'Completed' ? 'text-red-600 font-medium' : 'text-gray-500'}>{formatDate(t.due_date)}</span>
                          : <span className="text-gray-300">—</span>}
                      </td>
                      <td className="px-4 py-3 text-gray-500 text-xs whitespace-nowrap">
                        {t.ticket_status === 'Completed' ? formatDate(t.updated_date) : <span className="text-gray-300">—</span>}
                      </td>
                      <td className="px-4 py-3 text-xs">
                        {hrs !== null
                          ? <span className="px-2 py-0.5 rounded-full bg-indigo-100 text-indigo-700 font-medium">{hrs}h</span>
                          : <span className="text-gray-400">Open</span>}
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  )
}

// ─── Customers Tab ────────────────────────────────────────────────────────────
function CustomersTab({ customers, tickets, formatDate }) {
  const customerStats = useMemo(() => {
    const map = {}
    for (const t of tickets) {
      if (!t.customer_id && !t.customer_name) continue
      const key = t.customer_id || t.customer_name
      if (!map[key]) map[key] = { total: 0, open: 0, lastActivity: null, customerId: t.customer_id, customerName: t.customer_name }
      map[key].total++
      if (t.ticket_status !== 'Completed' && t.ticket_status !== 'Cancelled') map[key].open++
      if (!map[key].lastActivity || t.created_date > map[key].lastActivity) map[key].lastActivity = t.created_date
    }
    return map
  }, [tickets])

  const enriched = useMemo(() => customers.map(c => {
    const stats = customerStats[c.id] || { total: 0, open: 0, lastActivity: null }
    return { ...c, totalTickets: stats.total, openTickets: stats.open, lastActivity: stats.lastActivity }
  }).sort((a, b) => b.totalTickets - a.totalTickets), [customers, customerStats])

  const totalActive  = customers.filter(c => c.customer_status === 'Active').length
  const avgTickets   = customers.length ? (tickets.length / customers.length).toFixed(1) : '—'
  const topReturning = enriched.filter(c => c.totalTickets > 1).length

  const handleExport = () => {
    const columns = [
      { key: 'name', label: 'Customer Name' },
      { key: 'company', label: 'Company' },
      { key: 'total', label: 'Total Tickets' },
      { key: 'open', label: 'Open Tickets' },
      { key: 'last', label: 'Last Activity' },
    ]
    const rows = enriched.map(c => ({
      name: c.contact_person || c.company_name || '',
      company: c.company_name || '',
      total: c.totalTickets,
      open: c.openTickets,
      last: formatDate(c.lastActivity),
    }))
    downloadCSV(rows, columns, `customers-report-${toYMD(new Date())}.csv`)
  }

  return (
    <div className="space-y-5">
      <div className="grid grid-cols-2 lg:grid-cols-3 gap-4">
        <KpiCard label="Active Customers" value={totalActive} color="indigo" icon="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z" />
        <KpiCard label="Avg Tickets / Customer" value={avgTickets} color="blue" icon="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
        <KpiCard label="Returning Customers" value={topReturning} color="green" icon="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
      </div>

      <div className="flex justify-end">
        <button onClick={handleExport} className="flex items-center gap-1.5 px-3 py-2 border border-gray-200 rounded-lg text-sm text-gray-600 hover:bg-gray-50 transition-colors">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
          Export CSV
        </button>
      </div>

      {enriched.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-xl border border-gray-200">
          <p className="text-sm text-gray-400">No customer data in range</p>
        </div>
      ) : (
        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b border-gray-200">
                <tr>
                  {['Customer Name', 'Company', 'Total Tickets', 'Open Tickets', 'Last Activity'].map(h => (
                    <th key={h} className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {enriched.map(c => (
                  <tr key={c.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-4 py-3 font-medium text-gray-900">{c.contact_person || '—'}</td>
                    <td className="px-4 py-3 text-gray-500">{c.company_name || '—'}</td>
                    <td className="px-4 py-3">
                      <span className="px-2 py-0.5 rounded-full text-xs font-semibold bg-indigo-100 text-indigo-700">{c.totalTickets}</span>
                    </td>
                    <td className="px-4 py-3">
                      {c.openTickets > 0
                        ? <span className="px-2 py-0.5 rounded-full text-xs font-semibold bg-amber-100 text-amber-700">{c.openTickets}</span>
                        : <span className="text-gray-300 text-xs">—</span>}
                    </td>
                    <td className="px-4 py-3 text-gray-500 text-xs">{c.lastActivity ? formatDate(c.lastActivity) : '—'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  )
}

// ─── Technicians Tab ──────────────────────────────────────────────────────────
function TechniciansTab({ tickets, timeEntries, timeEntriesMissing, formatDate }) {
  const stats = useMemo(() => {
    const map = {}
    for (const t of tickets) {
      const tech = t.assigned_technician
      if (!tech) continue
      if (!map[tech]) map[tech] = { email: tech, assigned: 0, completed: 0, resolveTimes: [], hoursLogged: 0 }
      map[tech].assigned++
      if (t.ticket_status === 'Completed') {
        map[tech].completed++
        const hrs = resolutionHours(t)
        if (hrs !== null) map[tech].resolveTimes.push(Number(hrs))
      }
    }
    if (!timeEntriesMissing) {
      for (const e of timeEntries) {
        const tech = e.user_email || e.technician_email
        if (tech && map[tech]) map[tech].hoursLogged += (e.duration_min || 0) / 60
      }
    }
    return Object.values(map).sort((a, b) => b.assigned - a.assigned)
  }, [tickets, timeEntries, timeEntriesMissing])

  const activeTechs = stats.length
  const avgAssigned = activeTechs ? (tickets.length / activeTechs).toFixed(1) : '—'
  const totalHours  = timeEntriesMissing ? null : stats.reduce((s, t) => s + t.hoursLogged, 0).toFixed(1)

  const handleExport = () => {
    const columns = [
      { key: 'email', label: 'Technician' },
      { key: 'assigned', label: 'Assigned Tickets' },
      { key: 'completed', label: 'Completed Tickets' },
      { key: 'avgResolve', label: 'Avg Resolution (hrs)' },
      { key: 'hoursLogged', label: 'Hours Logged' },
    ]
    const rows = stats.map(t => ({
      email: t.email,
      assigned: t.assigned,
      completed: t.completed,
      avgResolve: t.resolveTimes.length ? (t.resolveTimes.reduce((s, v) => s + v, 0) / t.resolveTimes.length).toFixed(1) : '—',
      hoursLogged: timeEntriesMissing ? 'N/A' : t.hoursLogged.toFixed(1),
    }))
    downloadCSV(rows, columns, `technicians-report-${toYMD(new Date())}.csv`)
  }

  return (
    <div className="space-y-5">
      <div className="grid grid-cols-2 lg:grid-cols-3 gap-4">
        <KpiCard label="Active Technicians" value={activeTechs} color="purple" icon="M16 7a4 4 0 11-8 0 4 4 0 018 0M12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
        <KpiCard label="Avg Tickets Assigned" value={avgAssigned} color="blue" icon="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
        <KpiCard
          label="Total Hours Logged"
          value={totalHours !== null ? `${totalHours}h` : 'N/A'}
          color="green"
          icon="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"
          sub={timeEntriesMissing ? 'time_entries table not set up' : undefined}
        />
      </div>

      {timeEntriesMissing && <MigrationBanner table="time_entries">Time tracking data is unavailable until the migration is run.</MigrationBanner>}

      <div className="flex justify-end">
        <button onClick={handleExport} className="flex items-center gap-1.5 px-3 py-2 border border-gray-200 rounded-lg text-sm text-gray-600 hover:bg-gray-50 transition-colors">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
          Export CSV
        </button>
      </div>

      {stats.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-xl border border-gray-200">
          <p className="text-sm text-gray-400">No assigned tickets in range</p>
        </div>
      ) : (
        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b border-gray-200">
                <tr>
                  {['Technician', 'Assigned', 'Completed', 'Avg Resolution (hrs)', 'Hours Logged'].map(h => (
                    <th key={h} className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider whitespace-nowrap">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {stats.map(t => {
                  const avgRes = t.resolveTimes.length
                    ? (t.resolveTimes.reduce((s, v) => s + v, 0) / t.resolveTimes.length).toFixed(1)
                    : null
                  return (
                    <tr key={t.email} className="hover:bg-gray-50 transition-colors">
                      <td className="px-4 py-3 font-medium text-gray-900 text-xs">{t.email}</td>
                      <td className="px-4 py-3">
                        <span className="px-2 py-0.5 rounded-full text-xs font-semibold bg-indigo-100 text-indigo-700">{t.assigned}</span>
                      </td>
                      <td className="px-4 py-3">
                        <span className="px-2 py-0.5 rounded-full text-xs font-semibold bg-green-100 text-green-700">{t.completed}</span>
                      </td>
                      <td className="px-4 py-3">
                        {avgRes !== null
                          ? <span className="px-2 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-700">{avgRes}h</span>
                          : <span className="text-gray-300 text-xs">—</span>}
                      </td>
                      <td className="px-4 py-3 text-gray-500 text-xs">
                        {timeEntriesMissing ? 'N/A' : `${t.hoursLogged.toFixed(1)}h`}
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  )
}

// ─── Financial Tab ────────────────────────────────────────────────────────────
function FinancialTab({ invoices, invoicesMissing, formatDate }) {
  if (invoicesMissing) return (
    <div className="space-y-4">
      <MigrationBanner table="invoices">Invoice data is unavailable. Set up the invoices table to enable financial reporting.</MigrationBanner>
    </div>
  )

  const INV_STATUS_CLS = {
    paid:     'bg-green-100 text-green-700',
    pending:  'bg-yellow-100 text-yellow-700',
    overdue:  'bg-red-100 text-red-700',
    draft:    'bg-gray-100 text-gray-600',
    voided:   'bg-gray-100 text-gray-400',
  }

  const totalInvoiced = invoices.reduce((s, i) => s + (i.total_amount || i.amount || 0), 0)
  const totalPaid     = invoices.filter(i => i.status === 'paid').reduce((s, i) => s + (i.total_amount || i.amount || 0), 0)
  const totalPending  = invoices.filter(i => i.status === 'pending' || i.status === 'overdue').reduce((s, i) => s + (i.total_amount || i.amount || 0), 0)
  const quotesVal     = invoices.filter(i => i.type === 'quote' || i.invoice_type === 'quote').reduce((s, i) => s + (i.total_amount || i.amount || 0), 0)

  const fmt$ = v => `$${Number(v).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',')}`

  const handleExport = () => {
    const columns = [
      { key: 'invoice_number', label: 'Invoice #' },
      { key: 'customer_name', label: 'Customer' },
      { key: 'type', label: 'Type' },
      { key: 'status', label: 'Status' },
      { key: 'amount', label: 'Total' },
      { key: 'due_date', label: 'Due Date' },
    ]
    const rows = invoices.map(i => ({
      invoice_number: i.invoice_number || '',
      customer_name: i.customer_name || '',
      type: i.type || i.invoice_type || '',
      status: i.status || '',
      amount: i.total_amount || i.amount || 0,
      due_date: formatDate(i.due_date),
    }))
    downloadCSV(rows, columns, `financial-report-${toYMD(new Date())}.csv`)
  }

  return (
    <div className="space-y-5">
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <KpiCard label="Total Invoiced" value={fmt$(totalInvoiced)} color="indigo" icon="M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z" />
        <KpiCard label="Total Paid" value={fmt$(totalPaid)} color="green" icon="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
        <KpiCard label="Pending / Overdue" value={fmt$(totalPending)} color="amber" icon="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
        <KpiCard label="Quotes Value" value={fmt$(quotesVal)} color="blue" icon="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
      </div>

      <div className="flex justify-end">
        <button onClick={handleExport} className="flex items-center gap-1.5 px-3 py-2 border border-gray-200 rounded-lg text-sm text-gray-600 hover:bg-gray-50 transition-colors">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>
          Export CSV
        </button>
      </div>

      {invoices.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-xl border border-gray-200">
          <p className="text-sm text-gray-400">No invoices in the selected date range</p>
        </div>
      ) : (
        <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b border-gray-200">
                <tr>
                  {['Invoice #', 'Customer', 'Type', 'Status', 'Total', 'Due Date'].map(h => (
                    <th key={h} className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase tracking-wider whitespace-nowrap">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {invoices.map(inv => (
                  <tr key={inv.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-4 py-3 font-mono text-xs font-medium text-gray-900">{inv.invoice_number || '—'}</td>
                    <td className="px-4 py-3 text-gray-700 max-w-[150px] truncate">{inv.customer_name || '—'}</td>
                    <td className="px-4 py-3 text-gray-500 capitalize text-xs">{inv.type || inv.invoice_type || '—'}</td>
                    <td className="px-4 py-3">
                      <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${INV_STATUS_CLS[inv.status] || 'bg-gray-100 text-gray-600'}`}>
                        {inv.status || '—'}
                      </span>
                    </td>
                    <td className="px-4 py-3 font-semibold text-gray-900 tabular-nums">{fmt$(inv.total_amount || inv.amount || 0)}</td>
                    <td className="px-4 py-3 text-gray-500 text-xs whitespace-nowrap">
                      {inv.due_date
                        ? <span className={new Date(inv.due_date) < new Date() && inv.status !== 'paid' ? 'text-red-600 font-medium' : ''}>{formatDate(inv.due_date)}</span>
                        : '—'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  )
}

// ─── Main Component ───────────────────────────────────────────────────────────
export default function Reports({ currentUserRole, currentUserEmail, currentUserPermissions, onNavigateToTicket }) {
  const { formatDate, formatDateTime } = useAppearance()

  const canDo = (action) => {
    if (currentUserRole === 'super_admin' || currentUserRole === 'admin') return true
    return currentUserPermissions?.reports?.[action] === true
  }

  const isAdminOrManager = currentUserRole === 'super_admin' || currentUserRole === 'admin' || currentUserRole === 'manager'
  const isViewer         = currentUserRole === 'viewer'
  const isTechnician     = currentUserRole === 'technician'

  // Date range state
  const today = toYMD(new Date())
  const [fromDate, setFromDate] = useState(() => {
    const d = new Date(); d.setDate(d.getDate() - 30); return toYMD(d)
  })
  const [toDate, setToDate] = useState(today)

  // Tab state — viewers/technicians can only see Tickets
  const allTabs = [
    { id: 'tickets', label: 'Tickets' },
    ...(isAdminOrManager ? [
      { id: 'customers', label: 'Customers' },
      { id: 'technicians', label: 'Technicians' },
      { id: 'financial', label: 'Financial' },
    ] : []),
  ]
  const [activeTab, setActiveTab] = useState('tickets')

  // Data state
  const [tickets, setTickets]               = useState([])
  const [customers, setCustomers]           = useState([])
  const [timeEntries, setTimeEntries]       = useState([])
  const [timeEntriesMissing, setTeam]       = useState(false)
  const [invoices, setInvoices]             = useState([])
  const [invoicesMissing, setInvMissing]    = useState(false)
  const [loading, setLoading]               = useState(true)

  const load = useCallback(async () => {
    setLoading(true)
    try {
      const [tkRes, custRes, teRes, invRes] = await Promise.all([
        db.rmaTickets.list(),
        db.customers.list(),
        isAdminOrManager ? db.timeEntries.listAll() : Promise.resolve({ missing: false, data: [] }),
        isAdminOrManager ? db.invoices.list() : Promise.resolve({ missing: false, data: [] }),
      ])
      setTickets(tkRes || [])
      setCustomers(custRes || [])
      if (teRes.missing) { setTeam(true); setTimeEntries([]) }
      else { setTeam(false); setTimeEntries(teRes.data || []) }
      if (invRes.missing) { setInvMissing(true); setInvoices([]) }
      else { setInvMissing(false); setInvoices(invRes.data || []) }
    } catch { toast.error('Failed to load report data') }
    finally { setLoading(false) }
  }, [isAdminOrManager])

  useEffect(() => { load() }, [load])

  // Apply date range filter
  const filteredTickets = useMemo(() =>
    tickets.filter(t => inRange(t.created_date, fromDate, toDate)),
    [tickets, fromDate, toDate]
  )
  const filteredCustomers = useMemo(() =>
    customers.filter(c => inRange(c.created_date, fromDate, toDate)),
    [customers, fromDate, toDate]
  )
  const filteredInvoices = useMemo(() =>
    invoices.filter(i => inRange(i.created_date, fromDate, toDate)),
    [invoices, fromDate, toDate]
  )

  // Preset date ranges
  const applyPreset = (days) => {
    const d = new Date(); d.setDate(d.getDate() - days)
    setFromDate(toYMD(d)); setToDate(today)
  }
  const applyThisYear = () => {
    setFromDate(`${new Date().getFullYear()}-01-01`); setToDate(today)
  }

  const inputCls = 'px-3 py-1.5 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent'
  const presetCls = (active) => `px-3 py-1.5 text-xs rounded-lg border transition-colors ${active ? 'bg-indigo-600 text-white border-indigo-600' : 'border-gray-200 text-gray-600 hover:bg-gray-50'}`

  const isPreset7   = fromDate === toYMD((() => { const d = new Date(); d.setDate(d.getDate() - 7); return d })())
  const isPreset30  = fromDate === toYMD((() => { const d = new Date(); d.setDate(d.getDate() - 30); return d })())
  const isPreset90  = fromDate === toYMD((() => { const d = new Date(); d.setDate(d.getDate() - 90); return d })())
  const isThisYear  = fromDate === `${new Date().getFullYear()}-01-01`

  return (
    <div className="space-y-6">
      {/* Header */}
      <PageHeader title="Reports & Analytics" subtitle="Analyse ticket performance, customer trends, and financials">
        <button onClick={load} className="flex items-center gap-1.5 px-3 py-2 border border-gray-200 rounded-lg text-sm text-gray-600 hover:bg-gray-50 transition-colors">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"/></svg>
          Refresh
        </button>
      </PageHeader>

      {/* Date Range Bar */}
      <div className="flex items-center gap-3 flex-wrap bg-white rounded-xl border border-gray-200 px-4 py-3">
        <svg className="w-4 h-4 text-gray-400 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"/></svg>
        <input type="date" value={fromDate} onChange={e => setFromDate(e.target.value)} max={toDate} className={inputCls} />
        <span className="text-gray-400 text-sm">to</span>
        <input type="date" value={toDate} onChange={e => setToDate(e.target.value)} min={fromDate} max={today} className={inputCls} />
        <div className="flex items-center gap-1.5 flex-wrap ml-2">
          <button onClick={() => applyPreset(7)}  className={presetCls(isPreset7 && toDate === today)}>Last 7 days</button>
          <button onClick={() => applyPreset(30)} className={presetCls(isPreset30 && toDate === today)}>Last 30 days</button>
          <button onClick={() => applyPreset(90)} className={presetCls(isPreset90 && toDate === today)}>Last 90 days</button>
          <button onClick={applyThisYear}         className={presetCls(isThisYear && toDate === today)}>This year</button>
        </div>
      </div>

      {/* Tabs */}
      <div className="border-b border-gray-200">
        <div className="flex gap-1 overflow-x-auto">
          {allTabs.map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id)}
              className={`px-4 py-2.5 text-sm font-medium border-b-2 whitespace-nowrap transition-colors ${activeTab === tab.id ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* Content */}
      {loading ? (
        <div className="flex items-center justify-center py-20">
          <Spinner size="lg" />
        </div>
      ) : (
        <>
          {activeTab === 'tickets' && (
            <TicketsTab
              tickets={filteredTickets}
              onNavigateToTicket={onNavigateToTicket}
              formatDate={formatDate}
            />
          )}
          {activeTab === 'customers' && isAdminOrManager && (
            <CustomersTab
              customers={filteredCustomers}
              tickets={filteredTickets}
              formatDate={formatDate}
            />
          )}
          {activeTab === 'technicians' && isAdminOrManager && (
            <TechniciansTab
              tickets={filteredTickets}
              timeEntries={timeEntries}
              timeEntriesMissing={timeEntriesMissing}
              formatDate={formatDate}
            />
          )}
          {activeTab === 'financial' && isAdminOrManager && (
            <FinancialTab
              invoices={filteredInvoices}
              invoicesMissing={invoicesMissing}
              formatDate={formatDate}
            />
          )}
        </>
      )}
    </div>
  )
}

import React, { useState } from 'react'
import { auth } from '../api/supabaseClient'

export default function ResetPassword({ onDone }) {
  const [password, setPassword] = useState('')
  const [confirm, setConfirm] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [showConfirm, setShowConfirm] = useState(false)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const [success, setSuccess] = useState(false)

  const EyeIcon = ({ visible }) => visible ? (
    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268 2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21" />
    </svg>
  ) : (
    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
    </svg>
  )

  const handleSubmit = async (e) => {
    e.preventDefault()
    setError('')

    if (password.length < 8) {
      setError('Password must be at least 8 characters')
      return
    }
    if (!/[A-Z]/.test(password) || !/[a-z]/.test(password) || !/[0-9]/.test(password)) {
      setError('Password must include uppercase, lowercase, and a number')
      return
    }
    if (password !== confirm) {
      setError('Passwords do not match')
      return
    }

    setLoading(true)
    try {
      await auth.updatePassword(password)
      setSuccess(true)
      setTimeout(onDone, 2000)
    } catch (err) {
      setError(err.message || 'Failed to update password')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-50 to-blue-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-md p-8">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-indigo-600 rounded-xl flex items-center justify-center mx-auto mb-4">
            <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
          </div>
          <h1 className="text-3xl font-bold text-gray-900">myRMA</h1>
          <p className="text-gray-600 mt-2">Set a new password</p>
          <p className="text-xs text-gray-400 mt-3">You're here because someone requested a password reset for your account. If that wasn't you, you can safely close this page — your current password will remain unchanged until you submit a new one.</p>
        </div>

        {success ? (
          <div className="text-center space-y-4">
            <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto">
              <svg className="w-8 h-8 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <p className="text-gray-800 font-medium">Password updated!</p>
            <p className="text-sm text-gray-500">Redirecting you to login...</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">New Password</label>
              <div className="relative">
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full px-4 py-3 pr-12 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent"
                  placeholder="••••••••"
                  required
                  autoFocus
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(v => !v)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                  tabIndex={-1}
                >
                  <EyeIcon visible={showPassword} />
                </button>
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Confirm Password</label>
              <div className="relative">
                <input
                  type={showConfirm ? 'text' : 'password'}
                  value={confirm}
                  onChange={(e) => setConfirm(e.target.value)}
                  className="w-full px-4 py-3 pr-12 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent"
                  placeholder="••••••••"
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowConfirm(v => !v)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                  tabIndex={-1}
                >
                  <EyeIcon visible={showConfirm} />
                </button>
              </div>
            </div>

            {error && (
              <div className="bg-red-50 text-red-600 px-4 py-3 rounded-lg text-sm">
                {error}
              </div>
            )}

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-indigo-600 text-white py-3 rounded-lg font-medium hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              {loading ? 'Updating...' : 'Update Password'}
            </button>
          </form>
        )}
      </div>
    </div>
  )
}

import React, { useState, useEffect, useMemo } from 'react'
import { db } from '../api/supabaseClient'
import toast from 'react-hot-toast'
import { Button, Spinner, PageHeader } from '../components/ui'
import EmptyState from '../components/EmptyState'
import { useAppearance } from '../contexts/AppearanceContext'

// ─── Constants ────────────────────────────────────────────────────────────────

const PRIORITY_CLS = {
  Critical: 'bg-red-100 text-red-700 border border-red-200',
  High:     'bg-orange-100 text-orange-700',
  Medium:   'bg-yellow-100 text-yellow-700',
  Low:      'bg-green-100 text-green-700',
}

const STATUS_CLS = {
  'New':         'bg-pink-100 text-pink-700',
  'In Progress': 'bg-blue-100 text-blue-700',
  'On Hold':     'bg-yellow-100 text-yellow-700',
  'Completed':   'bg-green-100 text-green-700',
  'Cancelled':   'bg-gray-100 text-gray-600',
}

const DAY_NAMES = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']

// ─── Helpers ──────────────────────────────────────────────────────────────────

/** Returns the Monday of the week containing `date` */
function getMonday(date) {
  const d = new Date(date)
  const day = d.getDay() // 0=Sun
  const diff = day === 0 ? -6 : 1 - day
  d.setDate(d.getDate() + diff)
  d.setHours(0, 0, 0, 0)
  return d
}

/** Returns array of 7 Date objects starting from monday */
function weekDays(monday) {
  return Array.from({ length: 7 }, (_, i) => {
    const d = new Date(monday)
    d.setDate(d.getDate() + i)
    return d
  })
}

function isoDate(date) {
  return date.toISOString().split('T')[0]
}

function sameDay(a, b) {
  return isoDate(a) === isoDate(b)
}

function shortDate(date) {
  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
}

// ─── Ticket Card ─────────────────────────────────────────────────────────────

function TicketCard({ ticket, isOverdue, onNavigateToTicket }) {
  return (
    <div
      onClick={() => onNavigateToTicket?.(ticket.id)}
      className={`rounded-lg border bg-white p-2.5 cursor-pointer hover:shadow-md transition-shadow text-xs ${
        isOverdue ? 'border-l-4 border-l-red-500 border-t-gray-200 border-r-gray-200 border-b-gray-200' : 'border-gray-200'
      }`}
    >
      <p className="font-semibold text-gray-800 truncate mb-1">{ticket.rma_number}</p>
      <p className="text-gray-500 truncate mb-1.5">{ticket.customer_name || '—'}</p>
      <div className="flex flex-wrap gap-1">
        {ticket.priority && (
          <span className={`px-1.5 py-0.5 rounded text-[10px] font-medium ${PRIORITY_CLS[ticket.priority] || 'bg-gray-100 text-gray-600'}`}>
            {ticket.priority}
          </span>
        )}
        {ticket.ticket_status && (
          <span className={`px-1.5 py-0.5 rounded text-[10px] font-medium ${STATUS_CLS[ticket.ticket_status] || 'bg-gray-100 text-gray-600'}`}>
            {ticket.ticket_status}
          </span>
        )}
      </div>
      {ticket.assigned_technician && (
        <p className="text-gray-400 mt-1 truncate">{ticket.assigned_technician}</p>
      )}
    </div>
  )
}

// ─── Main Component ───────────────────────────────────────────────────────────

export default function TechCalendar({
  currentUserRole,
  currentUserEmail,
  currentUserPermissions,
  onNavigateToTicket,
}) {
  const { formatDate } = useAppearance()

  const canDo = (s, a) =>
    ['super_admin', 'admin'].includes(currentUserRole) ||
    currentUserPermissions?.[s]?.[a]

  const isAdminOrManager =
    ['super_admin', 'admin', 'manager'].includes(currentUserRole)

  const [tickets, setTickets] = useState([])
  const [loading, setLoading] = useState(true)
  const [mondayDate, setMondayDate] = useState(() => getMonday(new Date()))
  const [selectedTech, setSelectedTech] = useState('')

  // ─── Load data ──────────────────────────────────────────────────────────────
  useEffect(() => {
    setLoading(true)
    db.rmaTickets.list()
      .then(data => setTickets(data))
      .catch(err => {
        console.error(err)
        toast.error('Failed to load tickets')
      })
      .finally(() => setLoading(false))
  }, [])

  // ─── Derived data ────────────────────────────────────────────────────────────
  const technicians = useMemo(() => {
    const set = new Set()
    tickets.forEach(t => { if (t.assigned_technician) set.add(t.assigned_technician) })
    return Array.from(set).sort()
  }, [tickets])

  const effectiveTech = isAdminOrManager ? selectedTech : currentUserEmail

  const filteredTickets = useMemo(() => {
    if (!effectiveTech) return tickets
    return tickets.filter(t => t.assigned_technician === effectiveTech)
  }, [tickets, effectiveTech])

  const today = new Date()
  today.setHours(0, 0, 0, 0)

  const days = weekDays(mondayDate)

  const ticketsByDay = useMemo(() => {
    const map = {}
    days.forEach(d => { map[isoDate(d)] = [] })
    filteredTickets.forEach(t => {
      if (!t.due_date) return
      const key = t.due_date.split('T')[0]
      if (map[key]) map[key].push(t)
    })
    return map
  }, [filteredTickets, days])

  const unscheduled = useMemo(() =>
    filteredTickets.filter(t =>
      !t.due_date &&
      t.ticket_status !== 'Completed' &&
      t.ticket_status !== 'Cancelled'
    )
  , [filteredTickets])

  // ─── Navigation ──────────────────────────────────────────────────────────────
  const goToPrev = () => {
    const d = new Date(mondayDate)
    d.setDate(d.getDate() - 7)
    setMondayDate(d)
  }
  const goToNext = () => {
    const d = new Date(mondayDate)
    d.setDate(d.getDate() + 7)
    setMondayDate(d)
  }
  const goToToday = () => setMondayDate(getMonday(new Date()))

  const sunday = days[6]
  const weekLabel = `${shortDate(mondayDate)} – ${shortDate(sunday)}`

  // ─── Render ──────────────────────────────────────────────────────────────────
  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[320px]">
        <Spinner size="lg" />
      </div>
    )
  }

  return (
    <div className="p-6 max-w-full">
      {/* Header */}
      <PageHeader
        title="Tech Calendar"
        subtitle="Weekly view of tickets by technician and due date"
      />

      {/* Controls */}
      <div className="flex flex-wrap items-center gap-3 mb-6">
        {/* Week navigation */}
        <div className="flex items-center gap-2">
          <button
            onClick={goToPrev}
            className="p-2 rounded-lg border border-gray-200 hover:bg-gray-50 transition-colors"
            aria-label="Previous week"
          >
            <svg className="w-4 h-4 text-gray-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
          </button>
          <span className="text-sm font-semibold text-gray-800 min-w-[160px] text-center">{weekLabel}</span>
          <button
            onClick={goToNext}
            className="p-2 rounded-lg border border-gray-200 hover:bg-gray-50 transition-colors"
            aria-label="Next week"
          >
            <svg className="w-4 h-4 text-gray-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
            </svg>
          </button>
          <Button variant="secondary" size="sm" onClick={goToToday}>Today</Button>
        </div>

        {/* Technician filter — admin/manager only */}
        {isAdminOrManager && (
          <div className="ml-auto flex items-center gap-2">
            <label className="text-sm text-gray-500">Technician:</label>
            <select
              value={selectedTech}
              onChange={e => setSelectedTech(e.target.value)}
              className="px-3 py-1.5 border border-gray-300 rounded-lg text-sm bg-white focus:outline-none focus:ring-2 focus:ring-indigo-500"
            >
              <option value="">All Technicians</option>
              {technicians.map(t => (
                <option key={t} value={t}>{t}</option>
              ))}
            </select>
          </div>
        )}
      </div>

      {/* Calendar Grid */}
      <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden mb-6">
        {/* Day header row */}
        <div className="grid grid-cols-7 border-b border-gray-200">
          {days.map((d, i) => {
            const isToday = sameDay(d, new Date())
            return (
              <div
                key={i}
                className={`px-3 py-3 text-center border-r last:border-r-0 border-gray-100 ${
                  isToday ? 'bg-indigo-50' : 'bg-gray-50'
                }`}
              >
                <p className={`text-xs font-semibold uppercase tracking-wide ${isToday ? 'text-indigo-600' : 'text-gray-500'}`}>
                  {DAY_NAMES[i]}
                </p>
                <p className={`text-lg font-bold mt-0.5 ${isToday ? 'text-indigo-700' : 'text-gray-800'}`}>
                  {d.getDate()}
                </p>
                <p className="text-[10px] text-gray-400">{d.toLocaleDateString('en-US', { month: 'short' })}</p>
              </div>
            )
          })}
        </div>

        {/* Day columns */}
        <div className="grid grid-cols-7 min-h-[400px]">
          {days.map((d, i) => {
            const key = isoDate(d)
            const dayTickets = ticketsByDay[key] || []
            const isToday = sameDay(d, new Date())
            return (
              <div
                key={i}
                className={`border-r last:border-r-0 border-gray-100 p-2 flex flex-col gap-2 ${
                  isToday ? 'bg-indigo-50/30' : ''
                }`}
              >
                {dayTickets.length === 0 && (
                  <p className="text-[10px] text-gray-300 text-center mt-4">—</p>
                )}
                {dayTickets.map(ticket => {
                  const dueDate = ticket.due_date ? new Date(ticket.due_date) : null
                  dueDate && dueDate.setHours(0, 0, 0, 0)
                  const isOverdue = dueDate && dueDate < today && ticket.ticket_status !== 'Completed' && ticket.ticket_status !== 'Cancelled'
                  return (
                    <TicketCard
                      key={ticket.id}
                      ticket={ticket}
                      isOverdue={isOverdue}
                      onNavigateToTicket={onNavigateToTicket}
                    />
                  )
                })}
              </div>
            )
          })}
        </div>
      </div>

      {/* Unscheduled Panel */}
      <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-4">
        <h3 className="text-sm font-semibold text-gray-700 mb-3 flex items-center gap-2">
          <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
          </svg>
          Unscheduled Tickets
          {unscheduled.length > 0 && (
            <span className="ml-1 px-2 py-0.5 rounded-full bg-gray-100 text-gray-600 text-xs font-medium">
              {unscheduled.length}
            </span>
          )}
        </h3>
        {unscheduled.length === 0 ? (
          <EmptyState
            title="No unscheduled tickets"
            description="All active tickets have a due date assigned."
            className="py-8"
          />
        ) : (
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-2">
            {unscheduled.map(ticket => (
              <TicketCard
                key={ticket.id}
                ticket={ticket}
                isOverdue={false}
                onNavigateToTicket={onNavigateToTicket}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { db, auth } from '../api/supabaseClient'
import toast from 'react-hot-toast'
import ConfirmDialog from '../components/ConfirmDialog'
import { Spinner, Button } from '../components/ui'
import { useURLTab } from '../hooks/useURLTab'

function validatePasswordStrength(pw) {
  if (!pw || pw.length < 8) return 'Password must be at least 8 characters'
  if (!/[A-Z]/.test(pw)) return 'Password must contain an uppercase letter'
  if (!/[a-z]/.test(pw)) return 'Password must contain a lowercase letter'
  if (!/[0-9]/.test(pw)) return 'Password must contain a number'
  return null
}

export default function UserManagement({ currentUserRole, currentUserEmail }) {
  const [activeTab, setActiveTab] = useURLTab('umtab', 'users')
  const [users, setUsers] = useState([])
  const [customRoles, setCustomRoles] = useState([])
  const [loading, setLoading] = useState(true)
  const [confirmDialog, setConfirmDialog] = useState({ open: false, title: '', message: '', onConfirm: null })
  const openConfirm = (title, message, onConfirm) => setConfirmDialog({ open: true, title, message, onConfirm })
  const closeConfirm = () => setConfirmDialog(d => ({ ...d, open: false }))

  const [showAddUserModal, setShowAddUserModal] = useState(false)
  const [showCreateRoleModal, setShowCreateRoleModal] = useState(false)
  const [showPermissionsModal, setShowPermissionsModal] = useState(false)
  const [showUserControlModal, setShowUserControlModal] = useState(false)
  const [showActivityModal, setShowActivityModal] = useState(false)
  const [showPasswordModal, setShowPasswordModal] = useState(false)
  const [openMenuId, setOpenMenuId] = useState(null)
  const [selectedUser, setSelectedUser] = useState(null)
  const [userActivity, setUserActivity] = useState([])
  
  const [newUserEmail, setNewUserEmail] = useState('')
  const [newUserRole, setNewUserRole] = useState('technician')
  const [newUserPassword, setNewUserPassword] = useState('')
  
  const [newRoleName, setNewRoleName] = useState('')
  const [newRoleDescription, setNewRoleDescription] = useState('')
  const [newRolePermissions, setNewRolePermissions] = useState(getDefaultPermissions())

  const [controlAction, setControlAction] = useState('')
  const [controlReason, setControlReason] = useState('')
  const [controlNotes, setControlNotes] = useState('')
  const [controlExpiration, setControlExpiration] = useState('')

  const [resetPassword, setResetPassword] = useState('')

  useEffect(() => {
    const handler = (e) => { if (!e.target.closest('.action-menu')) setOpenMenuId(null) }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  useEffect(() => {
    loadData()
  }, [])

  const loadData = async () => {
    try {
      const [usersData, rolesData] = await Promise.all([
        db.userRoles.listAllRoles(),
        db.userRoles.getCustomRoles()
      ])
      setUsers(usersData)
      setCustomRoles(rolesData)
    } catch (error) {
      console.error('Error loading data:', error)
      toast.error('Failed to load data')
    } finally {
      setLoading(false)
    }
  }

  const handleAddUser = async (e) => {
    e.preventDefault()
    
    if (!newUserEmail || !newUserPassword || !newUserRole) {
      toast.error('Please fill all fields')
      return
    }

    const pwError = validatePasswordStrength(newUserPassword)
    if (pwError) { toast.error(pwError); return }

    try {
      // Create the Supabase Auth account first (requires service-role key)
      await auth.adminCreateUser(newUserEmail, newUserPassword)
      // Then record the role in user_roles
      await db.userRoles.createRole(newUserEmail, newUserRole)
      db.userActivity.create(currentUserEmail, 'user_created', `Created user ${newUserEmail} with role ${newUserRole}`).catch(() => {})
      db.notifications.create({
        type: 'user_created', title: 'New User Added',
        message: `${newUserEmail} was added with role: ${newUserRole}`,
        entityType: 'user', createdBy: currentUserEmail,
        targetRoles: ['super_admin'], targetEmails: []
      }).catch(() => {})
      toast.success(`User created! ${newUserEmail} can now log in.`)
      db.auditLog.log(currentUserEmail, 'user_created', `Created user ${newUserEmail} with role ${newUserRole}`).catch(() => {})
      setNewUserEmail('')
      setNewUserRole('technician')
      setNewUserPassword('')
      setShowAddUserModal(false)
      loadData()
    } catch (error) {
      console.error('Error adding user:', error)
      toast.error(error.message || 'Failed to add user')
    }
  }

  const handleUpdateRole = async (email, newRole) => {
    try {
      await db.userRoles.updateRole(email, newRole)
      db.userActivity.create(currentUserEmail, 'user_role_changed', `Changed role of ${email} to ${newRole}`).catch(() => {})
      db.notifications.create({
        type: 'user_role_changed', title: 'Role Updated',
        message: `${email}'s role was changed to ${newRole}`,
        entityType: 'user', createdBy: currentUserEmail,
        targetRoles: ['super_admin'], targetEmails: [email]
      }).catch(() => {})
      toast.success('Role updated successfully!')
      db.auditLog.log(currentUserEmail, 'user_role_changed', `Changed role of ${email} to ${newRole}`).catch(() => {})
      loadData()
    } catch (error) {
      console.error('Error updating role:', error)
      toast.error('Failed to update role')
    }
  }

  const handleCreateCustomRole = async (e) => {
    e.preventDefault()
    try {
      await db.userRoles.createCustomRole(
        newRoleName,
        newRoleDescription,
        newRolePermissions,
        currentUserEmail
      )
      toast.success('Custom role created successfully!')
      db.auditLog.log(currentUserEmail, 'custom_role_created', `Created custom role ${newRoleName}`).catch(() => {})
      setNewRoleName('')
      setNewRoleDescription('')
      setNewRolePermissions(getDefaultPermissions())
      setShowCreateRoleModal(false)
      loadData()
    } catch (error) {
      console.error('Error creating role:', error)
      toast.error('Failed to create custom role')
    }
  }

  const handleEditPermissions = (user) => {
    setSelectedUser(user)
    setShowPermissionsModal(true)
  }

  const handleSavePermissions = async () => {
    try {
      await db.userRoles.updateUserPermissions(selectedUser.user_email, selectedUser.permissions)
      toast.success('Permissions updated successfully!')
      setShowPermissionsModal(false)
      setSelectedUser(null)
      loadData()
    } catch (error) {
      console.error('Error updating permissions:', error)
      toast.error('Failed to update permissions')
    }
  }

  const handleDeleteCustomRole = (roleId) => {
    openConfirm(
      'Delete Custom Role',
      'Delete this custom role? Users assigned to it will lose their custom permissions.',
      async () => {
        closeConfirm()
        try {
          await db.userRoles.deleteCustomRole(roleId)
          toast.success('Custom role deleted successfully!')
          db.auditLog.log(currentUserEmail, 'custom_role_deleted', `Deleted custom role ${roleId}`).catch(() => {})
          loadData()
        } catch (error) {
          console.error('Error deleting role:', error)
          toast.error('Failed to delete custom role')
        }
      }
    )
  }

  const handleOpenUserControl = (user) => {
    setSelectedUser(user)
    setControlAction('')
    setControlReason('')
    setControlNotes(user.notes || '')
    setControlExpiration(user.expiration_date || '')
    setShowUserControlModal(true)
  }

  const handleUserControlAction = async () => {
    if (!controlAction) {
      toast.error('Please select an action')
      return
    }

    try {
      switch (controlAction) {
        case 'suspend':
          if (!controlReason) {
            toast.error('Please provide a reason for suspension')
            return
          }
          await db.userRoles.updateUserStatus(selectedUser.user_email, 'suspended', controlReason, currentUserEmail)
          db.userActivity.create(currentUserEmail, 'user_suspended', `Suspended ${selectedUser.user_email}: ${controlReason}`).catch(() => {})
          db.notifications.create({
            type: 'user_suspended', title: 'Account Suspended',
            message: `Your account was suspended. Reason: ${controlReason}`,
            entityType: 'user', createdBy: currentUserEmail,
            targetRoles: ['super_admin'], targetEmails: [selectedUser.user_email]
          }).catch(() => {})
          toast.success('User suspended successfully')
          db.auditLog.log(currentUserEmail, 'user_suspended', `Suspended ${selectedUser.user_email}: ${controlReason}`).catch(() => {})
          break

        case 'activate':
          await db.userRoles.updateUserStatus(selectedUser.user_email, 'active', null, null)
          db.userActivity.create(currentUserEmail, 'user_activated', `Activated ${selectedUser.user_email}`).catch(() => {})
          db.notifications.create({
            type: 'user_activated', title: 'Account Activated',
            message: `Your account has been reactivated`,
            entityType: 'user', createdBy: currentUserEmail,
            targetRoles: ['super_admin'], targetEmails: [selectedUser.user_email]
          }).catch(() => {})
          toast.success('User activated successfully')
          db.auditLog.log(currentUserEmail, 'user_activated', `Activated ${selectedUser.user_email}`).catch(() => {})
          break

        case 'lock':
          await db.userRoles.updateUserStatus(selectedUser.user_email, 'locked', controlReason, currentUserEmail)
          db.userActivity.create(currentUserEmail, 'user_locked', `Locked ${selectedUser.user_email}${controlReason ? `: ${controlReason}` : ''}`).catch(() => {})
          toast.success('User locked successfully')
          break

        case 'deactivate':
          await db.userRoles.updateUserStatus(selectedUser.user_email, 'deactivated', controlReason, currentUserEmail)
          db.userActivity.create(currentUserEmail, 'user_deactivated', `Deactivated ${selectedUser.user_email}`).catch(() => {})
          toast.success('User deactivated successfully')
          break

        case 'update_notes':
          await db.userRoles.updateUserNotes(selectedUser.user_email, controlNotes)
          toast.success('Notes updated successfully')
          break

        case 'set_expiration':
          if (!controlExpiration) {
            toast.error('Please set an expiration date')
            return
          }
          await db.userRoles.setUserExpiration(selectedUser.user_email, controlExpiration)
          toast.success('Expiration date set successfully')
          break

        case 'delete':
          openConfirm(
            'Delete User',
            `Permanently delete ${selectedUser.user_email}? This action cannot be undone.`,
            async () => {
              closeConfirm()
              try {
                const deletedEmail = selectedUser.user_email
                await db.userRoles.deleteUser(deletedEmail)
                db.userActivity.create(currentUserEmail, 'user_deleted', `Deleted user ${deletedEmail}`).catch(() => {})
                db.notifications.create({
                  type: 'user_deleted', title: 'User Deleted',
                  message: `${deletedEmail} was removed from the system`,
                  entityType: 'user', createdBy: currentUserEmail,
                  targetRoles: ['super_admin'], targetEmails: []
                }).catch(() => {})
                toast.success('User deleted successfully')
                db.auditLog.log(currentUserEmail, 'user_deleted', `Deleted user ${deletedEmail}`).catch(() => {})
                setShowUserControlModal(false)
                setSelectedUser(null)
                loadData()
              } catch (error) {
                toast.error('Failed to delete user')
              }
            }
          )
          return

        default:
          break
      }

      setShowUserControlModal(false)
      setSelectedUser(null)
      loadData()
    } catch (error) {
      console.error('Error performing user action:', error)
      toast.error('Failed to perform action')
    }
  }

  const handleViewActivity = async (user) => {
    setSelectedUser(user)
    try {
      const activity = await db.userActivity.list(user.user_email)
      setUserActivity(activity)
      setShowActivityModal(true)
    } catch (error) {
      console.error('Error loading activity:', error)
      toast.error('Failed to load user activity')
    }
  }

  const handleOpenPasswordReset = (user) => {
    setSelectedUser(user)
    setResetPassword('')
    setShowPasswordModal(true)
  }

  const handleResetPassword = async () => {
    try {
      if (currentUserRole === 'super_admin') {
        // Direct password set via Edge Function (super_admin only)
        if (resetPassword.length < 6) { toast.error('Password must be at least 6 characters'); return }
        await auth.adminSetPassword(selectedUser.user_email, resetPassword)
        toast.success(`Password updated for ${selectedUser.user_email}`)
        db.auditLog.log(currentUserEmail, 'user_password_reset', `Directly reset password for ${selectedUser.user_email}`).catch(() => {})
      } else {
        // Admin: send a reset email link instead
        await auth.resetPassword(selectedUser.user_email)
        toast.success(`Password reset email sent to ${selectedUser.user_email}`)
        db.auditLog.log(currentUserEmail, 'user_password_reset', `Sent password reset email to ${selectedUser.user_email}`).catch(() => {})
      }
      setShowPasswordModal(false)
      setSelectedUser(null)
      setResetPassword('')
    } catch (error) {
      console.error('Error resetting password:', error)
      toast.error('Failed to reset password: ' + (error?.message || 'unknown error'))
    }
  }

  if (currentUserRole !== 'admin' && currentUserRole !== 'super_admin') {
    return (
      <div className="text-center py-12">
        <svg className="w-16 h-16 text-red-600 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
        </svg>
        <h2 className="text-2xl font-bold text-gray-900 mb-2">Access Denied</h2>
        <p className="text-gray-600">Only administrators can access user management.</p>
      </div>
    )
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Spinner size="lg" />
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">User Management</h1>
          <p className="text-sm text-gray-500 mt-0.5">Manage users, roles, and permissions</p>
        </div>
        <button
          onClick={() => setShowAddUserModal(true)}
          className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium transition-colors"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
          </svg>
          Add User
        </button>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-gray-200">
        <div className="border-b border-gray-200">
          <nav className="flex gap-8 px-6">
            <button
              onClick={() => setActiveTab('users')}
              className={'py-4 border-b-2 font-medium transition-colors ' + (activeTab === 'users' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-gray-500 hover:text-gray-700')}
            >
              Users
            </button>
            <button
              onClick={() => setActiveTab('roles')}
              className={'py-4 border-b-2 font-medium transition-colors ' + (activeTab === 'roles' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-gray-500 hover:text-gray-700')}
            >
              Role Templates
            </button>
            <button
              onClick={() => setActiveTab('custom')}
              className={'py-4 border-b-2 font-medium transition-colors ' + (activeTab === 'custom' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-gray-500 hover:text-gray-700')}
            >
              Custom Roles
            </button>
          </nav>
        </div>

        <div className="p-6">
          {activeTab === 'users' && (
            <UsersTab
              users={users}
              currentUserRole={currentUserRole}
              currentUserEmail={currentUserEmail}
              onUpdateRole={handleUpdateRole}
              onEditPermissions={handleEditPermissions}
              onUserControl={handleOpenUserControl}
              onViewActivity={handleViewActivity}
              onResetPassword={handleOpenPasswordReset}
              openMenuId={openMenuId}
              setOpenMenuId={setOpenMenuId}
            />
          )}
          
          {activeTab === 'roles' && <RoleTemplatesTab currentUserRole={currentUserRole} currentUserEmail={currentUserEmail} />}
          
          {activeTab === 'custom' && (
            <CustomRolesTab 
              customRoles={customRoles}
              onCreateRole={() => setShowCreateRoleModal(true)}
              onDeleteRole={handleDeleteCustomRole}
            />
          )}
        </div>
      </div>

      {showAddUserModal && (
        <AddUserModal
          email={newUserEmail}
          password={newUserPassword}
          role={newUserRole}
          onEmailChange={setNewUserEmail}
          onPasswordChange={setNewUserPassword}
          onRoleChange={setNewUserRole}
          onSubmit={handleAddUser}
          onClose={() => {
            setShowAddUserModal(false)
            setNewUserEmail('')
            setNewUserPassword('')
            setNewUserRole('technician')
          }}
        />
      )}

      {showCreateRoleModal && (
        <CreateRoleModal
          roleName={newRoleName}
          roleDescription={newRoleDescription}
          permissions={newRolePermissions}
          onRoleNameChange={setNewRoleName}
          onRoleDescriptionChange={setNewRoleDescription}
          onPermissionsChange={setNewRolePermissions}
          onSubmit={handleCreateCustomRole}
          onClose={() => setShowCreateRoleModal(false)}
        />
      )}

      {showPermissionsModal && selectedUser && (
        <PermissionsModal
          user={selectedUser}
          onUserChange={setSelectedUser}
          onSave={handleSavePermissions}
          onClose={() => {
            setShowPermissionsModal(false)
            setSelectedUser(null)
          }}
        />
      )}

      {showUserControlModal && selectedUser && (
        <UserControlModal
          user={selectedUser}
          action={controlAction}
          reason={controlReason}
          notes={controlNotes}
          expiration={controlExpiration}
          onActionChange={setControlAction}
          onReasonChange={setControlReason}
          onNotesChange={setControlNotes}
          onExpirationChange={setControlExpiration}
          onSubmit={handleUserControlAction}
          onClose={() => {
            setShowUserControlModal(false)
            setSelectedUser(null)
          }}
        />
      )}

      {showActivityModal && selectedUser && (
        <ActivityModal
          user={selectedUser}
          activity={userActivity}
          onClose={() => {
            setShowActivityModal(false)
            setSelectedUser(null)
            setUserActivity([])
          }}
        />
      )}

      {showPasswordModal && selectedUser && (
        <PasswordResetModal
          user={selectedUser}
          isSuperAdmin={currentUserRole === 'super_admin'}
          password={resetPassword}
          onPasswordChange={setResetPassword}
          onSubmit={handleResetPassword}
          onClose={() => {
            setShowPasswordModal(false)
            setSelectedUser(null)
            setResetPassword('')
          }}
        />
      )}

      <ConfirmDialog
        open={confirmDialog.open}
        title={confirmDialog.title}
        message={confirmDialog.message}
        onConfirm={confirmDialog.onConfirm}
        onCancel={closeConfirm}
      />
    </div>
  )
}

function UsersTab({ users, currentUserRole, currentUserEmail, onUpdateRole, onEditPermissions, onUserControl, onViewActivity, onResetPassword, openMenuId, setOpenMenuId }) {
  const isSuperAdmin = currentUserRole === 'super_admin'
  return (
    <div className="overflow-x-auto">
      <table className="w-full">
        <thead className="bg-gray-50">
          <tr>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">User</th>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Status</th>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Role</th>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Change Role</th>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Permissions</th>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">Actions</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-200">
          {users.map((user) => (
            <tr key={user.id} className="hover:bg-gray-50">
              <td className="px-6 py-4 whitespace-nowrap">
                <div className="flex items-center">
                  <div className="w-10 h-10 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center font-semibold">
                    {user.user_email.charAt(0).toUpperCase()}
                  </div>
                  <div className="ml-3">
                    <p className="text-sm font-medium text-gray-900">{user.user_email}</p>
                    {user.last_login && (
                      <p className="text-xs text-gray-500">
                        Last login: {new Date(user.last_login).toLocaleDateString()}
                      </p>
                    )}
                  </div>
                </div>
              </td>
              <td className="px-6 py-4 whitespace-nowrap">
                <StatusBadge status={user.status || 'active'} />
              </td>
              <td className="px-6 py-4 whitespace-nowrap">
                <RoleBadge role={user.role} />
              </td>
              <td className="px-6 py-4 whitespace-nowrap">
                {user.user_email === currentUserEmail ? (
                  <span className="text-sm text-gray-400 italic">current user</span>
                ) : (
                  <select
                    value={user.role}
                    onChange={(e) => onUpdateRole(user.user_email, e.target.value)}
                    className="px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent text-sm"
                  >
                    {isSuperAdmin && <option value="super_admin">Super Admin</option>}
                    <option value="admin">Admin</option>
                    <option value="manager">Manager</option>
                    <option value="technician">Technician</option>
                    <option value="viewer">Viewer</option>
                  </select>
                )}
              </td>
              <td className="px-6 py-4 whitespace-nowrap">
                {isSuperAdmin ? (
                  <button
                    onClick={() => onEditPermissions(user)}
                    className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg border text-xs font-medium transition-colors hover:bg-indigo-50 hover:border-indigo-300 hover:text-indigo-700 border-gray-200 text-gray-600"
                  >
                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"/></svg>
                    {user.permissions ? 'Custom' : 'Role Default'}
                  </button>
                ) : (
                  <span className="px-3 py-1.5 rounded-lg border border-gray-200 text-xs font-medium text-gray-500">
                    {user.permissions ? 'Custom' : 'Role Default'}
                  </span>
                )}
              </td>
              <td className="px-6 py-4 relative action-menu">
                <button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === user.id ? null : user.id) }}
                  className="p-1.5 rounded-lg text-gray-400 hover:text-gray-700 hover:bg-gray-100 transition-colors">
                  <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><circle cx="12" cy="5" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="12" cy="19" r="1.5"/></svg>
                </button>
                {openMenuId === user.id && (
                  <div className="absolute right-0 top-9 z-30 w-48 bg-white rounded-xl shadow-lg border border-gray-200 py-1 overflow-hidden">
                    <button onClick={() => { onUserControl(user); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2.5">
                      <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
                      Controls
                    </button>
                    <button onClick={() => { onResetPassword(user); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2.5">
                      <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z"/></svg>
                      Reset Password
                    </button>
                    <button onClick={() => { onViewActivity(user); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2.5">
                      <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"/></svg>
                      Activity
                    </button>
                  </div>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

function AddUserModal({ email, password, role, onEmailChange, onPasswordChange, onRoleChange, onSubmit, onClose }) {
  const [showPassword, setShowPassword] = useState(false)

  const generatePassword = () => {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789!@#$%^&*'
    let pass = ''
    for (let i = 0; i < 12; i++) {
      pass += chars.charAt(Math.floor(Math.random() * chars.length))
    }
    onPasswordChange(pass)
    setShowPassword(true)
    toast.success('Password generated! Make sure to copy it!')
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-md p-6">
        <h2 className="text-2xl font-bold text-gray-900 mb-4">Add New User</h2>
        <form onSubmit={onSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Email *</label>
            <input
              type="email"
              value={email}
              onChange={(e) => onEmailChange(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent"
              placeholder="user@example.com"
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Password *</label>
            <div className="relative">
              <input
                type={showPassword ? "text" : "password"}
                value={password}
                onChange={(e) => onPasswordChange(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent pr-10"
                placeholder="Min 6 characters"
                required
                minLength={6}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500"
              >
                {showPassword ? '🙈' : '👁️'}
              </button>
            </div>
            <button
              type="button"
              onClick={generatePassword}
              className="mt-2 text-sm text-indigo-600 hover:text-indigo-800 font-medium"
            >
              🎲 Generate Strong Password
            </button>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Role *</label>
            <select
              value={role}
              onChange={(e) => onRoleChange(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent"
            >
              <option value="technician">🔧 Technician</option>
              <option value="manager">👔 Manager</option>
              <option value="admin">👑 Admin</option>
              <option value="viewer">👁️ Viewer</option>
            </select>
          </div>

          <div className="flex gap-3 pt-4">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700"
            >
              Create User
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

function PasswordResetModal({ user, isSuperAdmin, password, onPasswordChange, onSubmit, onClose }) {
  const [showPassword, setShowPassword] = useState(false)

  const generatePassword = () => {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789!@#$%^&*'
    let pass = ''
    for (let i = 0; i < 12; i++) pass += chars.charAt(Math.floor(Math.random() * chars.length))
    onPasswordChange(pass)
    setShowPassword(true)
    toast.success('Password generated! Copy it before closing.')
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-md p-6">
        <h2 className="text-xl font-bold text-gray-900 mb-1">Reset Password</h2>
        <p className="text-sm text-gray-500 mb-4">User: <strong className="text-gray-800">{user.user_email}</strong></p>

        {isSuperAdmin ? (
          /* Super-admin: set password directly via Edge Function */
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1.5">New Password</label>
              <div className="relative">
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={e => onPasswordChange(e.target.value)}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600 focus:border-transparent pr-10 text-sm"
                  placeholder="Min 6 characters"
                  minLength={6}
                  autoFocus
                />
                <button type="button" onClick={() => setShowPassword(v => !v)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600">
                  {showPassword ? '🙈' : '👁️'}
                </button>
              </div>
              <button type="button" onClick={generatePassword}
                className="mt-2 text-sm text-indigo-600 hover:text-indigo-800 font-medium">
                🎲 Generate Strong Password
              </button>
            </div>
            <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-3">
              <p className="text-sm text-yellow-800">⚠️ The user will be able to log in immediately with this new password.</p>
            </div>
            <div className="flex gap-3 pt-1">
              <button onClick={onClose}
                className="flex-1 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors">
                Cancel
              </button>
              <button onClick={onSubmit} disabled={password.length < 6}
                className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors font-medium">
                Set Password
              </button>
            </div>
          </div>
        ) : (
          /* Admin: send a reset email link */
          <div className="space-y-4">
            <div className="bg-blue-50 border border-blue-200 rounded-lg p-3">
              <p className="text-sm text-blue-800">
                A password reset link will be emailed to the user. The link expires after 1 hour.
              </p>
            </div>
            <div className="flex gap-3">
              <button onClick={onClose}
                className="flex-1 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors">
                Cancel
              </button>
              <button onClick={onSubmit}
                className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-medium">
                Send Reset Email
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

function UserControlModal({ user, action, reason, notes, expiration, onActionChange, onReasonChange, onNotesChange, onExpirationChange, onSubmit, onClose }) {
  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 overflow-y-auto">
      <div className="bg-white rounded-xl shadow-xl w-full max-w-2xl p-6 m-4">
        <h2 className="text-2xl font-bold text-gray-900 mb-4">User Controls: {user.user_email}</h2>
        
        <div className="space-y-4">
          <div className="bg-gray-50 p-4 rounded-lg">
            <p className="text-sm text-gray-600 mb-2">Current Status:</p>
            <StatusBadge status={user.status || 'active'} />
            {user.suspended_reason && (
              <div className="mt-2 text-sm text-gray-600">
                <p><strong>Reason:</strong> {user.suspended_reason}</p>
                <p><strong>Suspended by:</strong> {user.suspended_by}</p>
              </div>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Action</label>
            <select
              value={action}
              onChange={(e) => onActionChange(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600"
            >
              <option value="">Select action...</option>
              <option value="activate">✅ Activate User</option>
              <option value="suspend">⏸️ Suspend User</option>
              <option value="lock">🔒 Lock Account</option>
              <option value="deactivate">❌ Deactivate User</option>
              <option value="update_notes">📝 Update Notes</option>
              <option value="set_expiration">⏳ Set Expiration Date</option>
              <option value="delete">🗑️ Delete User (Permanent)</option>
            </select>
          </div>

          {(action === 'suspend' || action === 'lock' || action === 'deactivate') && (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Reason *</label>
              <textarea
                value={reason}
                onChange={(e) => onReasonChange(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600"
                rows="3"
                placeholder="Provide a reason for this action..."
                required
              />
            </div>
          )}

          {action === 'update_notes' && (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Notes</label>
              <textarea
                value={notes}
                onChange={(e) => onNotesChange(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600"
                rows="4"
                placeholder="Add notes about this user..."
              />
            </div>
          )}

          {action === 'set_expiration' && (
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">Expiration Date</label>
              <input
                type="datetime-local"
                value={expiration}
                onChange={(e) => onExpirationChange(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-600"
              />
              <p className="text-xs text-gray-500 mt-1">User access will expire on this date</p>
            </div>
          )}

          {action === 'delete' && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-4">
              <p className="text-red-800 font-medium">⚠️ Warning: This action cannot be undone!</p>
              <p className="text-sm text-red-600 mt-1">All user data and permissions will be permanently deleted.</p>
            </div>
          )}
        </div>

        <div className="flex gap-3 pt-6 border-t mt-6">
          <button
            onClick={onClose}
            className="flex-1 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
          >
            Cancel
          </button>
          <button
            onClick={onSubmit}
            disabled={!action}
            className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Execute Action
