const EMPTY_FORM = { title: '', message: '', type: 'info', is_active: true, starts_at: '', ends_at: '' }

const TYPE_STYLES = {
  info:    { badge: 'bg-blue-100 text-blue-800',   bar: 'bg-blue-50 border-blue-200 text-blue-900',   icon: 'ℹ️' },
  warning: { badge: 'bg-yellow-100 text-yellow-800', bar: 'bg-yellow-50 border-yellow-200 text-yellow-900', icon: '⚠️' },
  success: { badge: 'bg-green-100 text-green-800',  bar: 'bg-green-50 border-green-200 text-green-900',  icon: '✅' },
  error:   { badge: 'bg-red-100 text-red-800',     bar: 'bg-red-50 border-red-200 text-red-900',     icon: '🚨' },
}

export default function Announcements({ currentUserEmail }) {
  const [announcements, setAnnouncements] = useState([])
  const [loading, setLoading] = useState(true)
  const [missing, setMissing] = useState(false)
  const [showModal, setShowModal] = useState(false)
  const [editing, setEditing] = useState(null)
  const [form, setForm] = useState(EMPTY_FORM)
  const [saving, setSaving] = useState(false)
  const [openMenuId, setOpenMenuId] = useState(null)

  useEffect(() => { load() }, [])
  useEffect(() => {
    const handler = (e) => { if (!e.target.closest('.action-menu')) setOpenMenuId(null) }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  const load = async () => {
    setLoading(true)
    const result = await db.announcements.list()
    setMissing(result.missing)
    setAnnouncements(result.data)
    setLoading(false)
  }

  const openCreate = () => { setEditing(null); setForm(EMPTY_FORM); setShowModal(true) }
  const openEdit = (a) => { setEditing(a); setForm({ title: a.title, message: a.message, type: a.type, is_active: a.is_active, starts_at: a.starts_at?.slice(0,16) || '', ends_at: a.ends_at?.slice(0,16) || '' }); setShowModal(true) }

  const handleSave = async (e) => {
    e.preventDefault()
    if (!form.title.trim() || !form.message.trim()) { toast.error('Title and message are required'); return }
    setSaving(true)
    try {
      const payload = { ...form, starts_at: form.starts_at || null, ends_at: form.ends_at || null, updated_date: new Date().toISOString() }
      if (editing) {
        await db.announcements.update(editing.id, payload)
        toast.success('Announcement updated')
        db.auditLog.log(currentUserEmail, 'announcement_updated', `Updated announcement "${form.title}"`).catch(() => {})
      } else {
        await db.announcements.create({ ...payload, created_by: currentUserEmail, created_date: new Date().toISOString() })
        toast.success('Announcement created')
        db.auditLog.log(currentUserEmail, 'announcement_created', `Created announcement "${form.title}"`).catch(() => {})
      }
      setShowModal(false)
      load()
    } catch (err) { toast.error(err.message) } finally { setSaving(false) }
  }

  const handleDelete = async (id) => {
    if (!confirm('Delete this announcement?')) return
    try {
      await db.announcements.delete(id)
      toast.success('Deleted')
      db.auditLog.log(currentUserEmail, 'announcement_deleted', `Deleted announcement ${id}`).catch(() => {})
      load()
    }
    catch (err) { toast.error(err.message) }
  }

  const handleToggle = async (a) => {
    try {
      await db.announcements.update(a.id, { is_active: !a.is_active })
      db.auditLog.log(currentUserEmail, 'announcement_status_changed', `${!a.is_active ? 'Activated' : 'Deactivated'} announcement "${a.title}"`).catch(() => {})
      load()
    }
    catch (err) { toast.error(err.message) }
  }

  const fmt = (d) => d ? new Date(d).toLocaleString() : '—'
  const inp = 'w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600 focus:border-transparent'

  if (loading) return <div className="flex justify-center py-16"><div className="animate-spin w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full" /></div>

  if (missing) return <MigrationNotice feature="Announcements" sql={ANNOUNCEMENTS_SQL} />

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold text-gray-900">Announcements</h2>
          <p className="text-sm text-gray-500 mt-0.5">Post banners visible to all logged-in users</p>
        </div>
        <button onClick={openCreate} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
          New Announcement
        </button>
      </div>

      {/* Live preview of active announcements */}
      {announcements.filter(a => a.is_active).length > 0 && (
        <div className="space-y-2">
          <p className="text-xs font-medium text-gray-500 uppercase tracking-wider">Live Preview</p>
          {announcements.filter(a => a.is_active).map(a => {
            const s = TYPE_STYLES[a.type] || TYPE_STYLES.info
            return (
              <div key={a.id} className={`flex items-start gap-3 px-4 py-3 border rounded-lg text-sm ${s.bar}`}>
                <span className="text-base leading-none mt-0.5">{s.icon}</span>
                <div><span className="font-semibold">{a.title}:</span> {a.message}</div>
              </div>
            )
          })}
        </div>
      )}

      {/* Table */}
      <div className="bg-white rounded-xl border border-gray-200 overflow-hidden shadow-sm">
        <table className="w-full">
          <thead className="bg-gray-50 border-b border-gray-200">
            <tr>
              {['Title', 'Type', 'Active', 'Starts', 'Ends', 'Actions'].map(h => (
                <th key={h} className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase">{h}</th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {announcements.length === 0 && (
              <tr><td colSpan={6} className="px-4 py-12 text-center text-gray-400">No announcements yet</td></tr>
            )}
            {announcements.map(a => {
              const s = TYPE_STYLES[a.type] || TYPE_STYLES.info
              return (
                <tr key={a.id} className="hover:bg-gray-50">
                  <td className="px-4 py-3">
                    <div className="font-medium text-sm text-gray-900">{a.title}</div>
                    <div className="text-xs text-gray-500 truncate max-w-xs">{a.message}</div>
                  </td>
                  <td className="px-4 py-3"><span className={`px-2 py-1 rounded-full text-xs font-medium ${s.badge}`}>{s.icon} {a.type}</span></td>
                  <td className="px-4 py-3">
                    <button onClick={() => handleToggle(a)} className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${a.is_active ? 'bg-indigo-600' : 'bg-gray-300'}`}>
                      <span className={`inline-block h-3.5 w-3.5 transform rounded-full bg-white transition-transform ${a.is_active ? 'translate-x-4' : 'translate-x-1'}`} />
                    </button>
                  </td>
                  <td className="px-4 py-3 text-xs text-gray-500">{fmt(a.starts_at)}</td>
                  <td className="px-4 py-3 text-xs text-gray-500">{fmt(a.ends_at)}</td>
                  <td className="px-4 py-3 relative action-menu">
                    <button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === a.id ? null : a.id) }}
                      className="p-1.5 rounded-lg text-gray-400 hover:text-gray-700 hover:bg-gray-100 transition-colors">
                      <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><circle cx="12" cy="5" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="12" cy="19" r="1.5"/></svg>
                    </button>
                    {openMenuId === a.id && (
                      <div className="absolute right-0 top-9 z-30 w-40 bg-white rounded-xl shadow-lg border border-gray-200 py-1 overflow-hidden">
                        <button onClick={() => { openEdit(a); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2.5">
                          <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                          Edit
                        </button>
                        <button onClick={() => { handleDelete(a.id); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50 flex items-center gap-2.5">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                          Delete
                        </button>
                      </div>
                    )}
                  </td>
                </tr>
              )
            })}
          </tbody>
        </table>
      </div>

      {/* Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg">
            <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200">
              <h3 className="text-lg font-bold text-gray-900">{editing ? 'Edit Announcement' : 'New Announcement'}</h3>
              <button onClick={() => setShowModal(false)} className="text-gray-400 hover:text-gray-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
            <form onSubmit={handleSave} className="px-6 py-5 space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Title <span className="text-red-500">*</span></label>
                <input value={form.title} onChange={e => setForm({...form, title: e.target.value})} className={inp} placeholder="e.g. Scheduled Maintenance" required />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Message <span className="text-red-500">*</span></label>
                <textarea value={form.message} onChange={e => setForm({...form, message: e.target.value})} className={inp} rows={3} placeholder="Message visible to all users..." required />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">Type</label>
                  <select value={form.type} onChange={e => setForm({...form, type: e.target.value})} className={inp}>
                    <option value="info">ℹ️ Info</option>
                    <option value="warning">⚠️ Warning</option>
                    <option value="success">✅ Success</option>
                    <option value="error">🚨 Alert</option>
                  </select>
                </div>
                <div className="flex items-end pb-1">
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input type="checkbox" checked={form.is_active} onChange={e => setForm({...form, is_active: e.target.checked})} className="w-4 h-4 text-indigo-600 rounded" />
                    <span className="text-sm font-medium text-gray-700">Active now</span>
                  </label>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">Start date <span className="text-xs text-gray-400">(optional)</span></label>
                  <input type="datetime-local" value={form.starts_at} onChange={e => setForm({...form, starts_at: e.target.value})} className={inp} />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">End date <span className="text-xs text-gray-400">(optional)</span></label>
                  <input type="datetime-local" value={form.ends_at} onChange={e => setForm({...form, ends_at: e.target.value})} className={inp} />
                </div>
              </div>
              <div className="flex justify-end gap-3 pt-2">
                <button type="button" onClick={() => setShowModal(false)} className="px-4 py-2 text-sm text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50">Cancel</button>
                <button type="submit" disabled={saving} className="px-4 py-2 text-sm font-medium bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50">
                  {saving ? 'Saving...' : editing ? 'Save Changes' : 'Create'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

export function MigrationNotice({ feature, sql }) {
  const [copied, setCopied] = useState(false)
  const copy = () => { navigator.clipboard.writeText(sql); setCopied(true); setTimeout(() => setCopied(false), 2000) }
  return (
    <div className="bg-amber-50 border border-amber-200 rounded-xl p-6 space-y-4">
      <div className="flex items-start gap-3">
        <span className="text-2xl">⚙️</span>
        <div>
          <h3 className="font-semibold text-amber-900">{feature} — Database setup required</h3>
          <p className="text-sm text-amber-700 mt-1">Run the following SQL in your <strong>Supabase SQL Editor</strong> to enable this feature.</p>
        </div>
      </div>
      <div className="relative">
        <pre className="bg-gray-900 text-green-400 text-xs rounded-lg p-4 overflow-x-auto whitespace-pre-wrap">{sql}</pre>
        <button onClick={copy} className="absolute top-2 right-2 px-2 py-1 bg-gray-700 text-gray-300 text-xs rounded hover:bg-gray-600">
          {copied ? '✓ Copied' : 'Copy'}
        </button>
      </div>
    </div>
  )
}

const ANNOUNCEMENTS_SQL = `CREATE TABLE IF NOT EXISTS announcements (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  title TEXT NOT NULL,
  message TEXT NOT NULL,
  type TEXT DEFAULT 'info' CHECK (type IN ('info','warning','success','error')),
  is_active BOOLEAN DEFAULT true,
  starts_at TIMESTAMPTZ,
  ends_at TIMESTAMPTZ,
  created_by TEXT,
  created_date TIMESTAMPTZ DEFAULT NOW(),
  updated_date TIMESTAMPTZ DEFAULT NOW()
);`

import React, { useState, useEffect } from 'react'
import { db } from '../../api/supabaseClient'
import toast from 'react-hot-toast'

export default function AuditLog() {
  const [logs, setLogs] = useState([])
  const [filtered, setFiltered] = useState([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState('')
  const [filterUser, setFilterUser] = useState('')
  const [filterAction, setFilterAction] = useState('')
  const [filterFrom, setFilterFrom] = useState('')
  const [filterTo, setFilterTo] = useState('')

  useEffect(() => { load() }, [])
  useEffect(() => { applyFilters() }, [logs, search, filterUser, filterAction, filterFrom, filterTo])

  const load = async () => {
    setLoading(true)
    try {
      const data = await db.auditLog.listAll(500)
      setLogs(data)
    } catch { toast.error('Failed to load audit log') }
    finally { setLoading(false) }
  }

  const applyFilters = () => {
    let f = [...logs]
    if (search) { const q = search.toLowerCase(); f = f.filter(l => l.user_email?.toLowerCase().includes(q) || l.action_type?.toLowerCase().includes(q) || l.action_details?.toLowerCase().includes(q)) }
    if (filterUser) f = f.filter(l => l.user_email === filterUser)
    if (filterAction) f = f.filter(l => l.action_type === filterAction)
    if (filterFrom) f = f.filter(l => new Date(l.created_date) >= new Date(filterFrom))
    if (filterTo) f = f.filter(l => new Date(l.created_date) <= new Date(filterTo + 'T23:59:59'))
    setFiltered(f)
  }

  const handleExport = () => {
    const csv = ['Date,User,Action,Details',
      ...filtered.map(l => [new Date(l.created_date).toLocaleString(), l.user_email || '', l.action_type || '', `"${(l.action_details || '').replace(/"/g, '""')}"`].join(','))
    ].join('\n')
    const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }))
    a.download = `audit-log-${new Date().toISOString().split('T')[0]}.csv`
    document.body.appendChild(a); a.click(); document.body.removeChild(a)
    toast.success(`Exported ${filtered.length} records`)
  }

  const uniqueUsers = [...new Set(logs.map(l => l.user_email).filter(Boolean))].sort()
  const uniqueActions = [...new Set(logs.map(l => l.action_type).filter(Boolean))].sort()
  const clearFilters = () => { setSearch(''); setFilterUser(''); setFilterAction(''); setFilterFrom(''); setFilterTo('') }
  const hasFilters = search || filterUser || filterAction || filterFrom || filterTo
  const inp = 'px-3 py-1.5 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600 focus:border-transparent'

  if (loading) return <div className="flex justify-center py-16"><div className="animate-spin w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full" /></div>

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold text-gray-900">Audit Log</h2>
          <p className="text-sm text-gray-500 mt-0.5">All user activity across the system — {logs.length} records</p>
        </div>
        <button onClick={handleExport} className="flex items-center gap-2 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 text-sm font-medium">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
          Export CSV
        </button>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-3 items-center">
        <div className="relative flex-1 min-w-48">
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search user, action, details..."
            className={`w-full pl-9 pr-3 py-1.5 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600 focus:border-transparent`} />
          <svg className="w-4 h-4 text-gray-400 absolute left-2.5 top-1/2 -translate-y-1/2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>
        <select value={filterUser} onChange={e => setFilterUser(e.target.value)} className={inp}>
          <option value="">All users</option>
          {uniqueUsers.map(u => <option key={u} value={u}>{u}</option>)}
        </select>
        <select value={filterAction} onChange={e => setFilterAction(e.target.value)} className={inp}>
          <option value="">All actions</option>
          {uniqueActions.map(a => <option key={a} value={a}>{a}</option>)}
        </select>
        <input type="date" value={filterFrom} onChange={e => setFilterFrom(e.target.value)} className={inp} title="From date" />
        <input type="date" value={filterTo} onChange={e => setFilterTo(e.target.value)} className={inp} title="To date" />
        {hasFilters && <button onClick={clearFilters} className="text-sm text-red-600 hover:underline">Clear</button>}
      </div>

      <div className="text-xs text-gray-500">Showing {filtered.length} of {logs.length} records</div>

      {/* Table */}
      <div className="bg-white rounded-xl border border-gray-200 overflow-hidden shadow-sm">
        <div className="overflow-x-auto max-h-[600px] overflow-y-auto">
          <table className="w-full">
            <thead className="bg-gray-50 border-b border-gray-200 sticky top-0">
              <tr>
                {['Date & Time', 'User', 'Action', 'Details'].map(h => (
                  <th key={h} className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filtered.length === 0 && (
                <tr><td colSpan={4} className="px-4 py-12 text-center text-gray-400">No log entries match your filters</td></tr>
              )}
              {filtered.map((l, i) => (
                <tr key={l.id || i} className="hover:bg-gray-50 text-sm">
                  <td className="px-4 py-3 text-gray-500 whitespace-nowrap text-xs">{new Date(l.created_date).toLocaleString()}</td>
                  <td className="px-4 py-3 text-gray-700 font-medium">{l.user_email}</td>
                  <td className="px-4 py-3">
                    <span className="px-2 py-0.5 bg-indigo-50 text-indigo-700 rounded text-xs font-mono">{l.action_type}</span>
                  </td>
                  <td className="px-4 py-3 text-gray-600 max-w-sm truncate">{l.action_details || '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { db } from '../../api/supabaseClient'
import toast from 'react-hot-toast'
import { MigrationNotice } from './Announcements'

const FIELD_TYPES = ['text', 'number', 'date', 'select', 'textarea', 'checkbox']
const APPLIES_TO = ['ticket', 'customer']
const EMPTY_FORM = { field_name: '', field_label: '', field_type: 'text', applies_to: 'ticket', is_required: false, is_active: true, field_options: [] }

const TYPE_ICONS = { text: '📝', number: '🔢', date: '📅', select: '📋', textarea: '🗒️', checkbox: '☑️' }

export default function CustomFields({ currentUserEmail }) {
  const [fields, setFields] = useState([])
  const [loading, setLoading] = useState(true)
  const [missing, setMissing] = useState(false)
  const [showModal, setShowModal] = useState(false)
  const [editing, setEditing] = useState(null)
  const [form, setForm] = useState(EMPTY_FORM)
  const [saving, setSaving] = useState(false)
  const [newOption, setNewOption] = useState('')
  const [openMenuId, setOpenMenuId] = useState(null)
  const [filterAppliesTo, setFilterAppliesTo] = useState('')

  useEffect(() => { load() }, [])
  useEffect(() => {
    const handler = (e) => { if (!e.target.closest('.action-menu')) setOpenMenuId(null) }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  const load = async () => {
    setLoading(true)
    const result = await db.customFields.list()
    setMissing(result.missing)
    setFields(result.data)
    setLoading(false)
  }

  const openCreate = () => { setEditing(null); setForm(EMPTY_FORM); setNewOption(''); setShowModal(true) }
  const openEdit = (f) => {
    setEditing(f)
    setForm({ field_name: f.field_name, field_label: f.field_label, field_type: f.field_type, applies_to: f.applies_to, is_required: f.is_required, is_active: f.is_active, field_options: f.field_options || [] })
    setNewOption(''); setShowModal(true)
  }

  const handleSave = async (e) => {
    e.preventDefault()
    if (!form.field_label.trim()) { toast.error('Label is required'); return }
    if (!form.field_name.trim()) { toast.error('Field name is required'); return }
    if (!/^[a-z_][a-z0-9_]*$/.test(form.field_name)) { toast.error('Field name: lowercase letters, numbers, underscores only'); return }
    if (form.field_type === 'select' && form.field_options.length === 0) { toast.error('Add at least one option for select fields'); return }
    setSaving(true)
    try {
      const payload = { ...form, field_options: form.field_type === 'select' ? form.field_options : null }
      if (editing) {
        await db.customFields.update(editing.id, payload)
        toast.success('Field updated')
      } else {
        await db.customFields.create({ ...payload, created_by: currentUserEmail, created_date: new Date().toISOString() })
        toast.success('Custom field created')
      }
      setShowModal(false); load()
    } catch (err) { toast.error(err.message) } finally { setSaving(false) }
  }

  const handleDelete = async (id) => {
    if (!confirm('Delete this custom field? Data stored in this field will not be deleted from existing records.')) return
    try { await db.customFields.delete(id); toast.success('Deleted'); load() }
    catch (err) { toast.error(err.message) }
  }

  const handleToggle = async (f) => {
    try { await db.customFields.update(f.id, { is_active: !f.is_active }); load() }
    catch (err) { toast.error(err.message) }
  }

  const addOption = () => {
    if (!newOption.trim()) return
    setForm(f => ({ ...f, field_options: [...f.field_options, newOption.trim()] }))
    setNewOption('')
  }
  const removeOption = (i) => setForm(f => ({ ...f, field_options: f.field_options.filter((_, idx) => idx !== i) }))

  const inp = 'w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600'
  const displayed = filterAppliesTo ? fields.filter(f => f.applies_to === filterAppliesTo) : fields

  if (loading) return <div className="flex justify-center py-16"><div className="animate-spin w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full" /></div>
  if (missing) return <MigrationNotice feature="Custom Fields" sql={CUSTOM_FIELDS_SQL} />

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold text-gray-900">Custom Fields</h2>
          <p className="text-sm text-gray-500 mt-0.5">Add extra fields to tickets and customers</p>
        </div>
        <button onClick={openCreate} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
          Add Field
        </button>
      </div>

      <div className="flex items-center gap-3">
        <span className="text-sm text-gray-600">Filter:</span>
        {['', 'ticket', 'customer'].map(v => (
          <button key={v} onClick={() => setFilterAppliesTo(v)}
            className={`px-3 py-1 rounded-full text-sm font-medium transition-colors ${filterAppliesTo === v ? 'bg-indigo-600 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}>
            {v === '' ? 'All' : v === 'ticket' ? '🎫 Tickets' : '👤 Customers'}
          </button>
        ))}
      </div>

      <div className="bg-white rounded-xl border border-gray-200 overflow-hidden shadow-sm">
        <table className="w-full">
          <thead className="bg-gray-50 border-b border-gray-200">
            <tr>
              {['Field Label', 'Name (key)', 'Type', 'Applies To', 'Required', 'Active', 'Actions'].map(h => (
                <th key={h} className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase">{h}</th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {displayed.length === 0 && (
              <tr><td colSpan={7} className="px-4 py-12 text-center text-gray-400">No custom fields defined yet</td></tr>
            )}
            {displayed.map(f => (
              <tr key={f.id} className={`hover:bg-gray-50 ${!f.is_active ? 'opacity-50' : ''}`}>
                <td className="px-4 py-3 font-medium text-sm text-gray-900">{f.field_label}</td>
                <td className="px-4 py-3 font-mono text-xs text-gray-500">{f.field_name}</td>
                <td className="px-4 py-3 text-sm text-gray-600">{TYPE_ICONS[f.field_type]} {f.field_type}</td>
                <td className="px-4 py-3"><span className={`px-2 py-0.5 rounded text-xs font-medium ${f.applies_to === 'ticket' ? 'bg-indigo-100 text-indigo-700' : 'bg-emerald-100 text-emerald-700'}`}>{f.applies_to}</span></td>
                <td className="px-4 py-3 text-sm text-gray-600">{f.is_required ? '✓ Yes' : 'No'}</td>
                <td className="px-4 py-3">
                  <button onClick={() => handleToggle(f)} className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${f.is_active ? 'bg-indigo-600' : 'bg-gray-300'}`}>
                    <span className={`inline-block h-3.5 w-3.5 transform rounded-full bg-white transition-transform ${f.is_active ? 'translate-x-4' : 'translate-x-1'}`} />
                  </button>
                </td>
                <td className="px-4 py-3 relative action-menu">
                  <button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === f.id ? null : f.id) }}
                    className="p-1.5 rounded-lg text-gray-400 hover:text-gray-700 hover:bg-gray-100 transition-colors">
                    <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><circle cx="12" cy="5" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="12" cy="19" r="1.5"/></svg>
                  </button>
                  {openMenuId === f.id && (
                    <div className="absolute right-0 top-9 z-30 w-40 bg-white rounded-xl shadow-lg border border-gray-200 py-1 overflow-hidden">
                      <button onClick={() => { openEdit(f); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2.5">
                        <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                        Edit
                      </button>
                      <button onClick={() => { handleDelete(f.id); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50 flex items-center gap-2.5">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                        Delete
                      </button>
                    </div>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 overflow-y-auto">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg my-8">
            <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200">
              <h3 className="text-lg font-bold text-gray-900">{editing ? 'Edit Field' : 'New Custom Field'}</h3>
              <button onClick={() => setShowModal(false)} className="text-gray-400 hover:text-gray-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
            <form onSubmit={handleSave} className="px-6 py-5 space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Label <span className="text-red-500">*</span></label>
                <input value={form.field_label} onChange={e => setForm({...form, field_label: e.target.value, field_name: editing ? form.field_name : e.target.value.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'')})}
                  className={inp} placeholder="e.g. Customer PO Number" required />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Field key <span className="text-red-500">*</span> <span className="text-xs text-gray-400">(lowercase, no spaces)</span></label>
                <input value={form.field_name} onChange={e => setForm({...form, field_name: e.target.value})} className={`${inp} font-mono`} placeholder="e.g. customer_po_number" disabled={!!editing} required />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">Type</label>
                  <select value={form.field_type} onChange={e => setForm({...form, field_type: e.target.value})} className={inp}>
                    {FIELD_TYPES.map(t => <option key={t} value={t}>{TYPE_ICONS[t]} {t}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">Applies to</label>
                  <select value={form.applies_to} onChange={e => setForm({...form, applies_to: e.target.value})} className={inp}>
                    {APPLIES_TO.map(t => <option key={t} value={t}>{t === 'ticket' ? '🎫 Ticket' : '👤 Customer'}</option>)}
                  </select>
                </div>
              </div>
              <div className="flex items-center gap-4">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input type="checkbox" checked={form.is_required} onChange={e => setForm({...form, is_required: e.target.checked})} className="w-4 h-4 text-indigo-600 rounded" />
                  <span className="text-sm font-medium text-gray-700">Required field</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input type="checkbox" checked={form.is_active} onChange={e => setForm({...form, is_active: e.target.checked})} className="w-4 h-4 text-indigo-600 rounded" />
                  <span className="text-sm font-medium text-gray-700">Active</span>
                </label>
              </div>
              {form.field_type === 'select' && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1.5">Options</label>
                  <div className="flex gap-2 mb-2">
                    <input value={newOption} onChange={e => setNewOption(e.target.value)} onKeyPress={e => e.key === 'Enter' && (e.preventDefault(), addOption())}
                      className={`${inp} flex-1`} placeholder="Add option..." />
                    <button type="button" onClick={addOption} className="px-3 py-2 bg-gray-100 hover:bg-gray-200 rounded-lg text-sm">Add</button>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {form.field_options.map((o, i) => (
                      <span key={i} className="flex items-center gap-1 px-2 py-1 bg-gray-100 rounded text-sm">
                        {o}
                        <button type="button" onClick={() => removeOption(i)} className="text-gray-400 hover:text-red-500 ml-1">×</button>
                      </span>
                    ))}
                  </div>
                </div>
              )}
              <div className="flex justify-end gap-3 pt-2">
                <button type="button" onClick={() => setShowModal(false)} className="px-4 py-2 text-sm text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50">Cancel</button>
                <button type="submit" disabled={saving} className="px-4 py-2 text-sm font-medium bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50">
                  {saving ? 'Saving...' : editing ? 'Save Changes' : 'Create Field'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

const CUSTOM_FIELDS_SQL = `CREATE TABLE IF NOT EXISTS custom_field_definitions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  field_name TEXT NOT NULL,
  field_label TEXT NOT NULL,
  field_type TEXT NOT NULL CHECK (field_type IN ('text','number','date','select','textarea','checkbox')),
  applies_to TEXT NOT NULL CHECK (applies_to IN ('ticket','customer')),
  is_required BOOLEAN DEFAULT false,
  is_active BOOLEAN DEFAULT true,
  field_options JSONB,
  sort_order INTEGER DEFAULT 0,
  created_by TEXT,
  created_date TIMESTAMPTZ DEFAULT NOW()
);`

import React, { useState, useEffect } from 'react'
import { db } from '../../api/supabaseClient'
import toast from 'react-hot-toast'

export default function DataCleanup() {
  const [tickets, setTickets] = useState([])
  const [customers, setCustomers] = useState([])
  const [loading, setLoading] = useState(true)
  const [working, setWorking] = useState(false)
  const [completedDays, setCompletedDays] = useState(90)
  const [cancelledDays, setCancelledDays] = useState(30)
  const [preview, setPreview] = useState(null)

  useEffect(() => { load() }, [])

  const load = async () => {
    setLoading(true)
    try {
      const [t, c] = await Promise.all([db.rmaTickets.list(), db.customers.list()])
      setTickets(t); setCustomers(c)
    } catch { toast.error('Failed to load data') }
    finally { setLoading(false) }
  }

  const cutoff = (days) => { const d = new Date(); d.setDate(d.getDate() - days); return d }

  const staleCompleted = tickets.filter(t => t.ticket_status === 'Completed' && t.updated_date && new Date(t.updated_date) < cutoff(completedDays))
  const staleCancelled = tickets.filter(t => t.ticket_status === 'Cancelled' && t.updated_date && new Date(t.updated_date) < cutoff(cancelledDays))

  const ticketIds = [...new Set(tickets.map(t => t.customer_name).filter(Boolean))]
  const orphanCustomers = customers.filter(c => {
    const name = c.customer_type === 'B2B' && c.company_name ? c.company_name : c.contact_person
    return !ticketIds.includes(name)
  })

  const nameCounts = customers.reduce((acc, c) => {
    const name = (c.company_name || c.contact_person || '').toLowerCase().trim()
    if (name) acc[name] = (acc[name] || []).concat(c)
    return acc
  }, {})
  const duplicateGroups = Object.values(nameCounts).filter(g => g.length > 1)

  const handleDeleteTickets = async (list, label) => {
    if (!list.length) return
    if (!confirm(`Delete ${list.length} ${label} tickets? This cannot be undone.`)) return
    setWorking(true)
    try {
      await db.rmaTickets.bulkDelete ? db.rmaTickets.bulkDelete(list.map(t => t.id)) : Promise.all(list.map(t => db.rmaTickets.delete(t.id)))
      toast.success(`Deleted ${list.length} ${label} tickets`)
      load()
    } catch (err) { toast.error(err.message) } finally { setWorking(false) }
  }

  const StatCard = ({ label, count, sub, color, action, actionLabel, disabled }) => (
    <div className={`bg-white rounded-xl border p-5 shadow-sm ${color === 'red' ? 'border-red-200' : color === 'amber' ? 'border-amber-200' : 'border-gray-200'}`}>
      <div className="flex items-start justify-between">
        <div>
          <div className={`text-3xl font-bold ${color === 'red' ? 'text-red-600' : color === 'amber' ? 'text-amber-600' : 'text-gray-900'}`}>{count}</div>
          <div className="text-sm font-medium text-gray-700 mt-1">{label}</div>
          <div className="text-xs text-gray-500 mt-0.5">{sub}</div>
        </div>
      </div>
      {action && (
        <button onClick={action} disabled={disabled || count === 0 || working}
          className={`mt-4 w-full py-1.5 text-sm font-medium rounded-lg border transition-colors disabled:opacity-40 disabled:cursor-not-allowed ${
            color === 'red' ? 'border-red-300 text-red-700 hover:bg-red-50' : 'border-gray-300 text-gray-700 hover:bg-gray-50'
          }`}>
          {working ? 'Working...' : actionLabel}
        </button>
      )}
    </div>
  )

  if (loading) return <div className="flex justify-center py-16"><div className="animate-spin w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full" /></div>

  return (
    <div className="space-y-8">
      <div>
        <h2 className="text-lg font-semibold text-gray-900">Data Cleanup</h2>
        <p className="text-sm text-gray-500 mt-0.5">Remove stale records and identify data quality issues</p>
      </div>

      {/* Ticket cleanup */}
      <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm space-y-5">
        <h3 className="text-base font-semibold text-gray-900">Ticket Cleanup</h3>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1.5">Completed tickets older than (days)</label>
            <div className="flex items-center gap-2">
              <input type="number" min={1} value={completedDays} onChange={e => setCompletedDays(parseInt(e.target.value) || 90)}
                className="w-24 px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600" />
              <span className="text-sm text-gray-500">days — <strong>{staleCompleted.length}</strong> tickets found</span>
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1.5">Cancelled tickets older than (days)</label>
            <div className="flex items-center gap-2">
              <input type="number" min={1} value={cancelledDays} onChange={e => setCancelledDays(parseInt(e.target.value) || 30)}
                className="w-24 px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600" />
              <span className="text-sm text-gray-500">days — <strong>{staleCancelled.length}</strong> tickets found</span>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="p-4 bg-gray-50 rounded-lg">
            <div className="flex items-center justify-between mb-2">
              <div>
                <span className="text-2xl font-bold text-gray-900">{staleCompleted.length}</span>
                <p className="text-sm text-gray-600">Stale completed tickets</p>
                <p className="text-xs text-gray-400">Completed &gt;{completedDays} days ago</p>
              </div>
              <span className="text-3xl">✅</span>
            </div>
            <button onClick={() => handleDeleteTickets(staleCompleted, 'completed')} disabled={staleCompleted.length === 0 || working}
              className="w-full py-1.5 text-sm font-medium rounded-lg border border-red-300 text-red-700 hover:bg-red-50 disabled:opacity-40 disabled:cursor-not-allowed">
              Delete {staleCompleted.length} tickets
            </button>
          </div>
          <div className="p-4 bg-gray-50 rounded-lg">
            <div className="flex items-center justify-between mb-2">
              <div>
                <span className="text-2xl font-bold text-gray-900">{staleCancelled.length}</span>
                <p className="text-sm text-gray-600">Stale cancelled tickets</p>
                <p className="text-xs text-gray-400">Cancelled &gt;{cancelledDays} days ago</p>
              </div>
              <span className="text-3xl">❌</span>
            </div>
            <button onClick={() => handleDeleteTickets(staleCancelled, 'cancelled')} disabled={staleCancelled.length === 0 || working}
              className="w-full py-1.5 text-sm font-medium rounded-lg border border-red-300 text-red-700 hover:bg-red-50 disabled:opacity-40 disabled:cursor-not-allowed">
              Delete {staleCancelled.length} tickets
            </button>
          </div>
        </div>
      </div>

      {/* Customer quality */}
      <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm space-y-5">
        <h3 className="text-base font-semibold text-gray-900">Customer Data Quality</h3>
        <div className="grid grid-cols-2 gap-4">
          <div className="p-4 bg-gray-50 rounded-lg">
            <div className="flex items-center justify-between mb-2">
              <div>
                <span className="text-2xl font-bold text-gray-900">{orphanCustomers.length}</span>
                <p className="text-sm text-gray-600">Customers with no tickets</p>
                <p className="text-xs text-gray-400">Have never submitted an RMA</p>
              </div>
              <span className="text-3xl">👤</span>
            </div>
            <button onClick={() => setPreview({ type: 'orphans', items: orphanCustomers })}
              disabled={orphanCustomers.length === 0}
              className="w-full py-1.5 text-sm font-medium rounded-lg border border-gray-300 text-gray-700 hover:bg-gray-100 disabled:opacity-40 disabled:cursor-not-allowed">
              Review list
            </button>
          </div>
          <div className="p-4 bg-gray-50 rounded-lg">
            <div className="flex items-center justify-between mb-2">
              <div>
                <span className="text-2xl font-bold text-amber-600">{duplicateGroups.length}</span>
                <p className="text-sm text-gray-600">Potential duplicate groups</p>
                <p className="text-xs text-gray-400">Same company or contact name</p>
              </div>
              <span className="text-3xl">⚠️</span>
            </div>
            <button onClick={() => setPreview({ type: 'duplicates', items: duplicateGroups })}
              disabled={duplicateGroups.length === 0}
              className="w-full py-1.5 text-sm font-medium rounded-lg border border-amber-300 text-amber-700 hover:bg-amber-50 disabled:opacity-40 disabled:cursor-not-allowed">
              Review duplicates
            </button>
          </div>
        </div>
      </div>

      {/* Preview panel */}
      {preview && (
        <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-base font-semibold text-gray-900">
              {preview.type === 'orphans' ? `Customers with no tickets (${preview.items.length})` : `Duplicate groups (${preview.items.length})`}
            </h3>
            <button onClick={() => setPreview(null)} className="text-gray-400 hover:text-gray-600">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          </div>
          <div className="max-h-64 overflow-y-auto space-y-1">
            {preview.type === 'orphans' && preview.items.map(c => (
              <div key={c.id} className="flex items-center justify-between py-1.5 px-3 rounded hover:bg-gray-50 text-sm">
                <span className="text-gray-800">{c.company_name || c.contact_person}</span>
                <span className="text-xs text-gray-400">{c.customer_type} · {c.customer_status}</span>
              </div>
            ))}
            {preview.type === 'duplicates' && preview.items.map((group, i) => (
              <div key={i} className="mb-3 p-3 bg-amber-50 rounded-lg">
                <p className="text-xs font-semibold text-amber-800 mb-1.5">{group.length} records with same name:</p>
                {group.map(c => (
                  <div key={c.id} className="text-xs text-gray-700 py-0.5">{c.company_name || c.contact_person} · {c.email || c.mobile || 'no contact'} · created {new Date(c.created_date).toLocaleDateString()}</div>
                ))}
              </div>
            ))}
          </div>
          <p className="text-xs text-gray-400 mt-3">To merge or delete records, go to the Customers page and edit them directly.</p>
        </div>
      )}
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { db } from '../../api/supabaseClient'
import toast from 'react-hot-toast'
import { MigrationNotice } from './Announcements'

const WEBHOOK_EVENTS = ['ticket.created', 'ticket.updated', 'ticket.status_changed', 'ticket.deleted', 'customer.created', 'customer.updated']

const EMPTY_FORM = { name: '', url: '', events: [], is_active: true, secret_key: '' }

export default function Integrations({ currentUserEmail }) {
  const [webhooks, setWebhooks] = useState([])
  const [loading, setLoading] = useState(true)
  const [missing, setMissing] = useState(false)
  const [showModal, setShowModal] = useState(false)
  const [editing, setEditing] = useState(null)
  const [form, setForm] = useState(EMPTY_FORM)
  const [saving, setSaving] = useState(false)
  const [testing, setTesting] = useState(null)
  const [openMenuId, setOpenMenuId] = useState(null)

  useEffect(() => { load() }, [])
  useEffect(() => {
    const handler = (e) => { if (!e.target.closest('.action-menu')) setOpenMenuId(null) }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  const load = async () => {
    setLoading(true)
    const result = await db.webhooks.list()
    setMissing(result.missing)
    setWebhooks(result.data)
    setLoading(false)
  }

  const openCreate = () => { setEditing(null); setForm(EMPTY_FORM); setShowModal(true) }
  const openEdit = (w) => { setEditing(w); setForm({ name: w.name, url: w.url, events: w.events || [], is_active: w.is_active, secret_key: w.secret_key || '' }); setShowModal(true) }

  const handleSave = async (e) => {
    e.preventDefault()
    if (!form.name.trim()) { toast.error('Name is required'); return }
    if (!form.url.trim() || !form.url.startsWith('http')) { toast.error('Valid URL is required'); return }
    if (form.events.length === 0) { toast.error('Select at least one event'); return }
    setSaving(true)
    try {
      const payload = { ...form, updated_date: new Date().toISOString() }
      if (editing) {
        await db.webhooks.update(editing.id, payload)
        toast.success('Webhook updated')
      } else {
        await db.webhooks.create({ ...payload, created_by: currentUserEmail, created_date: new Date().toISOString() })
        toast.success('Webhook created')
      }
      setShowModal(false); load()
    } catch (err) { toast.error(err.message) } finally { setSaving(false) }
  }

  const handleDelete = async (id) => {
    if (!confirm('Delete this webhook?')) return
    try { await db.webhooks.delete(id); toast.success('Deleted'); load() }
    catch (err) { toast.error(err.message) }
  }

  const handleToggle = async (w) => {
    try { await db.webhooks.update(w.id, { is_active: !w.is_active }); load() }
    catch (err) { toast.error(err.message) }
  }

  const handleTest = async (w) => {
    setTesting(w.id)
    try {
      const payload = { event: 'webhook.test', timestamp: new Date().toISOString(), data: { message: 'Test webhook from myRMA Control Panel' } }
      await fetch(w.url, { method: 'POST', headers: { 'Content-Type': 'application/json', ...(w.secret_key ? { 'X-Webhook-Secret': w.secret_key } : {}) }, body: JSON.stringify(payload) })
      toast.success('Test payload sent')
    } catch { toast.error('Failed to reach webhook URL — check CORS or the URL') }
    finally { setTesting(null) }
  }

  const toggleEvent = (ev) => setForm(f => ({ ...f, events: f.events.includes(ev) ? f.events.filter(e => e !== ev) : [...f.events, ev] }))
  const inp = 'w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600'

  if (loading) return <div className="flex justify-center py-16"><div className="animate-spin w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full" /></div>
  if (missing) return <MigrationNotice feature="Integrations / Webhooks" sql={WEBHOOKS_SQL} />

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold text-gray-900">Integrations</h2>
          <p className="text-sm text-gray-500 mt-0.5">Configure outbound webhooks for ticket and customer events</p>
        </div>
        <button onClick={openCreate} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
          Add Webhook
        </button>
      </div>

      {/* Info box */}
      <div className="flex items-start gap-3 p-4 bg-blue-50 border border-blue-200 rounded-lg text-sm text-blue-800">
        <svg className="w-5 h-5 text-blue-500 flex-shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
        <div>Webhooks send a POST request with a JSON payload to your URL when events occur. Use them to connect Slack, Teams, Zapier, or custom systems. The optional secret key is sent as <code className="bg-blue-100 px-1 rounded">X-Webhook-Secret</code> header.</div>
      </div>

      {/* Webhooks table */}
      <div className="bg-white rounded-xl border border-gray-200 overflow-hidden shadow-sm">
        <table className="w-full">
          <thead className="bg-gray-50 border-b border-gray-200">
            <tr>
              {['Name', 'URL', 'Events', 'Active', 'Actions'].map(h => (
                <th key={h} className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase">{h}</th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {webhooks.length === 0 && (
              <tr><td colSpan={5} className="px-4 py-12 text-center text-gray-400">No webhooks configured yet</td></tr>
            )}
            {webhooks.map(w => (
              <tr key={w.id} className="hover:bg-gray-50">
                <td className="px-4 py-3 font-medium text-sm text-gray-900">{w.name}</td>
                <td className="px-4 py-3 text-sm text-gray-500 max-w-xs truncate font-mono text-xs">{w.url}</td>
                <td className="px-4 py-3">
                  <div className="flex flex-wrap gap-1">
                    {(w.events || []).map(ev => <span key={ev} className="px-1.5 py-0.5 bg-gray-100 text-gray-600 text-xs rounded font-mono">{ev}</span>)}
                  </div>
                </td>
                <td className="px-4 py-3">
                  <button onClick={() => handleToggle(w)} className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${w.is_active ? 'bg-indigo-600' : 'bg-gray-300'}`}>
                    <span className={`inline-block h-3.5 w-3.5 transform rounded-full bg-white transition-transform ${w.is_active ? 'translate-x-4' : 'translate-x-1'}`} />
                  </button>
                </td>
                <td className="px-4 py-3 relative action-menu">
                  <button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === w.id ? null : w.id) }}
                    className="p-1.5 rounded-lg text-gray-400 hover:text-gray-700 hover:bg-gray-100 transition-colors">
                    <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><circle cx="12" cy="5" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="12" cy="19" r="1.5"/></svg>
                  </button>
                  {openMenuId === w.id && (
                    <div className="absolute right-0 top-9 z-30 w-44 bg-white rounded-xl shadow-lg border border-gray-200 py-1 overflow-hidden">
                      <button onClick={() => { handleTest(w); setOpenMenuId(null) }} disabled={testing === w.id || !w.is_active}
                        className="w-full px-4 py-2 text-left text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2.5 disabled:opacity-40">
                        <svg className="w-4 h-4 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z"/></svg>
                        {testing === w.id ? 'Sending...' : 'Test Webhook'}
                      </button>
                      <button onClick={() => { openEdit(w); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-gray-700 hover:bg-gray-50 flex items-center gap-2.5">
                        <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                        Edit
                      </button>
                      <button onClick={() => { handleDelete(w.id); setOpenMenuId(null) }} className="w-full px-4 py-2 text-left text-sm text-red-600 hover:bg-red-50 flex items-center gap-2.5">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
                        Delete
                      </button>
                    </div>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg">
            <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200">
              <h3 className="text-lg font-bold text-gray-900">{editing ? 'Edit Webhook' : 'Add Webhook'}</h3>
              <button onClick={() => setShowModal(false)} className="text-gray-400 hover:text-gray-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
            <form onSubmit={handleSave} className="px-6 py-5 space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Name <span className="text-red-500">*</span></label>
                <input value={form.name} onChange={e => setForm({...form, name: e.target.value})} className={inp} placeholder="e.g. Slack Notifications" required />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Endpoint URL <span className="text-red-500">*</span></label>
                <input type="url" value={form.url} onChange={e => setForm({...form, url: e.target.value})} className={inp} placeholder="https://hooks.example.com/..." required />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1.5">Secret Key <span className="text-xs text-gray-400">(optional)</span></label>
                <input value={form.secret_key} onChange={e => setForm({...form, secret_key: e.target.value})} className={inp} placeholder="Sent as X-Webhook-Secret header" />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Events <span className="text-red-500">*</span></label>
                <div className="grid grid-cols-2 gap-2">
                  {WEBHOOK_EVENTS.map(ev => (
                    <label key={ev} className="flex items-center gap-2 cursor-pointer">
                      <input type="checkbox" checked={form.events.includes(ev)} onChange={() => toggleEvent(ev)} className="w-4 h-4 text-indigo-600 rounded" />
                      <span className="text-sm font-mono text-gray-700">{ev}</span>
                    </label>
                  ))}
                </div>
              </div>
              <label className="flex items-center gap-2 cursor-pointer">
                <input type="checkbox" checked={form.is_active} onChange={e => setForm({...form, is_active: e.target.checked})} className="w-4 h-4 text-indigo-600 rounded" />
                <span className="text-sm font-medium text-gray-700">Active</span>
              </label>
              <div className="flex justify-end gap-3 pt-2">
                <button type="button" onClick={() => setShowModal(false)} className="px-4 py-2 text-sm text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50">Cancel</button>
                <button type="submit" disabled={saving} className="px-4 py-2 text-sm font-medium bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50">
                  {saving ? 'Saving...' : editing ? 'Save Changes' : 'Create Webhook'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

const WEBHOOKS_SQL = `CREATE TABLE IF NOT EXISTS webhooks (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  url TEXT NOT NULL,
  events JSONB NOT NULL DEFAULT '[]',
  is_active BOOLEAN DEFAULT true,
  secret_key TEXT,
  last_triggered_at TIMESTAMPTZ,
  created_by TEXT,
  created_date TIMESTAMPTZ DEFAULT NOW(),
  updated_date TIMESTAMPTZ DEFAULT NOW()
);`

import React, { useState, useEffect } from 'react'
import { db, branding as brandingAPI } from '../../api/supabaseClient'
import toast from 'react-hot-toast'

const DEFAULT_SECTION_ORDER = ['ticketInfo', 'generalDescription', 'products', 'accessories', 'attachments', 'signatureLine']

const DEFAULT = {
  paperSize: 'A4',
  orientation: 'portrait',
  font: 'Arial, sans-serif',
  fontSize: 11,
  primaryColor: '#4F46E5',
  headerStyle: 'colored',
  showLogo: false,
  logoPosition: 'right',
  showCompanyName: true,
  showRmaNumber: true,
  showDate: true,
  sections: {
    ticketInfo: true,
    generalDescription: true,
    products: true,
    accessories: true,
    attachments: true,
    signatureLine: false,
  },
  sectionOrder: DEFAULT_SECTION_ORDER,
  footerText: '',
  showGeneratedDate: true,
  showWatermark: false,
}

const FONTS = [
  { label: 'Calibri', value: 'Calibri, Candara, sans-serif' },
  { label: 'Arial', value: 'Arial, sans-serif' },
  { label: 'Helvetica', value: 'Helvetica, sans-serif' },
  { label: 'Georgia', value: 'Georgia, serif' },
  { label: 'Times New Roman', value: "'Times New Roman', serif" },
  { label: 'Courier New', value: "'Courier New', monospace" },
]

const SECTIONS_META = [
  { key: 'ticketInfo', label: 'Ticket Information', desc: 'Customer, assigned to, dates, status, priority' },
  { key: 'generalDescription', label: 'General Description', desc: 'RMA description / reason for return' },
  { key: 'products', label: 'Products', desc: 'Product list with serial numbers and issue details' },
  { key: 'accessories', label: 'Accessories Received', desc: 'Items received alongside the products' },
  { key: 'attachments', label: 'Attachments', desc: 'List of uploaded files' },
  { key: 'signatureLine', label: 'Signature Line', desc: 'Customer / technician signature space' },
]

export default function PDFLayout({ currentUserEmail }) {
  const [config, setConfig] = useState(DEFAULT)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [logoUrl, setLogoUrl] = useState(null)

  useEffect(() => {
    load()
  }, [])

  const load = async () => {
    try {
      const [cfgResult, brandingData] = await Promise.all([db.rmaConfig.getAll(), brandingAPI.getBranding()])
      if (brandingData?.logo_url) setLogoUrl(brandingData.logo_url)

      let savedConfig = null
      if (!cfgResult.missing) {
        const row = cfgResult.data.find(r => r.config_key === 'pdf_layout')
        if (row?.config_value) {
          try {
            savedConfig = typeof row.config_value === 'string' ? JSON.parse(row.config_value) : row.config_value
          } catch { savedConfig = null }
        }
      }

      if (savedConfig) {
        setConfig({
          ...DEFAULT,
          ...savedConfig,
          sections: { ...DEFAULT.sections, ...(savedConfig.sections || {}) },
          sectionOrder: savedConfig.sectionOrder?.length ? savedConfig.sectionOrder : DEFAULT_SECTION_ORDER,
        })
      } else if (brandingData?.primary_color) {
        setConfig(c => ({ ...c, primaryColor: brandingData.primary_color }))
      }
    } catch {}
    finally { setLoading(false) }
  }

  const save = async () => {
    setSaving(true)
    try {
      await db.rmaConfig.set('pdf_layout', config, currentUserEmail)
      toast.success('PDF layout saved')
    } catch (err) { toast.error(err.message) }
    finally { setSaving(false) }
  }

  const set = (key, val) => setConfig(c => ({ ...c, [key]: val }))
  const setSection = (key, val) => setConfig(c => ({ ...c, sections: { ...c.sections, [key]: val } }))

  const inp = 'w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600'
  const Toggle = ({ checked, onChange }) => (
    <button type="button" onClick={() => onChange(!checked)}
      className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${checked ? 'bg-indigo-600' : 'bg-gray-300'}`}>
      <span className={`inline-block h-3.5 w-3.5 transform rounded-full bg-white transition-transform ${checked ? 'translate-x-4' : 'translate-x-1'}`} />
    </button>
  )

  if (loading) return <div className="flex justify-center py-16"><div className="animate-spin w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full" /></div>

  const previewColor = config.primaryColor || '#4F46E5'
  const previewFont = config.font || 'Arial, sans-serif'
  const previewFontSize = config.fontSize || 11
  const isLandscape = config.orientation === 'landscape'

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold text-gray-900">PDF Layout</h2>
          <p className="text-sm text-gray-500 mt-0.5">Customize how RMA tickets look when printed or exported to PDF</p>
        </div>
        <button onClick={save} disabled={saving} className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium disabled:opacity-50">
          {saving ? 'Saving...' : 'Save Layout'}
        </button>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">

        {/* ─── Settings Panel ─── */}
        <div className="space-y-5">

          {/* Page Setup */}
          <div className="bg-white rounded-xl border border-gray-200 p-5 shadow-sm">
            <h3 className="text-sm font-semibold text-gray-900 mb-4 flex items-center gap-2">
              <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
              Page Setup
            </h3>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-gray-600 mb-1.5">Paper Size</label>
                <select value={config.paperSize} onChange={e => set('paperSize', e.target.value)} className={inp}>
                  <option value="A4">A4 (210 × 297 mm)</option>
                  <option value="Letter">US Letter (8.5 × 11 in)</option>
                  <option value="A5">A5 (148 × 210 mm)</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-600 mb-1.5">Orientation</label>
                <div className="flex gap-2">
                  {['portrait', 'landscape'].map(o => (
                    <button key={o} type="button" onClick={() => set('orientation', o)}
                      className={`flex-1 py-2 rounded-lg border text-sm font-medium capitalize transition-colors ${config.orientation === o ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-gray-200 text-gray-600 hover:border-gray-300'}`}>
                      {o}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {/* Typography */}
          <div className="bg-white rounded-xl border border-gray-200 p-5 shadow-sm">
            <h3 className="text-sm font-semibold text-gray-900 mb-4 flex items-center gap-2">
              <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h8m-8 6h16" /></svg>
              Typography
            </h3>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-gray-600 mb-1.5">Font Family</label>
                <select value={config.font} onChange={e => set('font', e.target.value)} className={inp}>
                  {FONTS.map(f => <option key={f.value} value={f.value}>{f.label}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-600 mb-1.5">Font Size</label>
                <div className="flex gap-2">
                  {[9, 10, 11, 12].map(s => (
                    <button key={s} type="button" onClick={() => set('fontSize', s)}
                      className={`flex-1 py-2 rounded-lg border text-sm font-medium transition-colors ${config.fontSize === s ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-gray-200 text-gray-600 hover:border-gray-300'}`}>
                      {s}pt
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {/* Branding & Header */}
          <div className="bg-white rounded-xl border border-gray-200 p-5 shadow-sm">
            <h3 className="text-sm font-semibold text-gray-900 mb-4 flex items-center gap-2">
              <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21a4 4 0 01-4-4V5a2 2 0 012-2h4a2 2 0 012 2v12a4 4 0 01-4 4zm0 0h12a2 2 0 002-2v-4a2 2 0 00-2-2h-2.343M11 7.343l1.657-1.657a2 2 0 012.828 0l2.829 2.829a2 2 0 010 2.828l-8.486 8.485M7 17h.01" /></svg>
              Branding & Header
            </h3>
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-gray-600 mb-1.5">Header Style</label>
                <div className="flex gap-2">
                  {[{ v: 'colored', l: 'Colored' }, { v: 'minimal', l: 'Minimal' }, { v: 'none', l: 'None' }].map(({ v, l }) => (
                    <button key={v} type="button" onClick={() => set('headerStyle', v)}
                      className={`flex-1 py-2 rounded-lg border text-sm font-medium transition-colors ${config.headerStyle === v ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-gray-200 text-gray-600 hover:border-gray-300'}`}>
                      {l}
                    </button>
                  ))}
                </div>
              </div>
              <div className="flex items-center gap-4">
                <div className="flex-1">
                  <label className="block text-xs font-medium text-gray-600 mb-1.5">Primary Color</label>
                  <div className="flex items-center gap-2">
                    <input type="color" value={config.primaryColor} onChange={e => set('primaryColor', e.target.value)} className="w-10 h-9 rounded border border-gray-300 cursor-pointer p-0.5" />
                    <input type="text" value={config.primaryColor} onChange={e => set('primaryColor', e.target.value)} className={`${inp} font-mono flex-1`} />
                  </div>
                </div>
              </div>
              <div className="space-y-3">
                {[
                  { key: 'showLogo', label: 'Show Company Logo', sub: logoUrl ? 'Using logo from Appearance settings' : 'No logo set — upload one in Appearance' },
                  { key: 'showCompanyName', label: 'Show Company Name' },
                  { key: 'showRmaNumber', label: 'Show RMA Number in Header' },
                  { key: 'showDate', label: 'Show Print Date' },
                ].map(({ key, label, sub }) => (
                  <div key={key} className="flex items-center justify-between">
                    <div>
                      <p className="text-sm text-gray-700">{label}</p>
                      {sub && <p className="text-xs text-gray-400">{sub}</p>}
                    </div>
                    <Toggle checked={!!config[key]} onChange={v => set(key, v)} />
                  </div>
                ))}
                {config.showLogo && (
                  <div>
                    <label className="block text-xs font-medium text-gray-600 mb-1.5">Logo Position</label>
                    <div className="flex gap-2">
                      {['left', 'right'].map(p => (
                        <button key={p} type="button" onClick={() => set('logoPosition', p)}
                          className={`flex-1 py-1.5 rounded-lg border text-sm font-medium capitalize transition-colors ${config.logoPosition === p ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-gray-200 text-gray-600 hover:border-gray-300'}`}>
                          {p}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Content Sections */}
          <div className="bg-white rounded-xl border border-gray-200 p-5 shadow-sm">
            <h3 className="text-sm font-semibold text-gray-900 mb-1 flex items-center gap-2">
              <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 10h16M4 14h16M4 18h16" /></svg>
              Content Sections
            </h3>
            <p className="text-xs text-gray-400 mb-4">Toggle sections on/off and drag the arrows to reorder them in the PDF</p>
            <div className="space-y-2">
              {(config.sectionOrder || DEFAULT_SECTION_ORDER).map((key, idx, arr) => {
                const meta = SECTIONS_META.find(s => s.key === key)
                if (!meta) return null
                const moveUp = () => {
                  if (idx === 0) return
                  const next = [...arr]
                  ;[next[idx - 1], next[idx]] = [next[idx], next[idx - 1]]
                  setConfig(c => ({ ...c, sectionOrder: next }))
                }
                const moveDown = () => {
                  if (idx === arr.length - 1) return
                  const next = [...arr]
                  ;[next[idx], next[idx + 1]] = [next[idx + 1], next[idx]]
                  setConfig(c => ({ ...c, sectionOrder: next }))
                }
                return (
                  <div key={key} className={`flex items-center gap-3 p-3 rounded-lg border transition-colors ${config.sections[key] ? 'bg-gray-50 border-gray-200' : 'bg-white border-gray-100 opacity-50'}`}>
                    <div className="flex flex-col gap-0.5">
                      <button type="button" onClick={moveUp} disabled={idx === 0}
                        className="p-0.5 text-gray-400 hover:text-gray-700 disabled:opacity-20 disabled:cursor-not-allowed transition-colors">
                        <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M5 15l7-7 7 7" /></svg>
                      </button>
                      <button type="button" onClick={moveDown} disabled={idx === arr.length - 1}
                        className="p-0.5 text-gray-400 hover:text-gray-700 disabled:opacity-20 disabled:cursor-not-allowed transition-colors">
                        <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 9l-7 7-7-7" /></svg>
                      </button>
                    </div>
                    <span className="text-xs font-bold text-gray-300 w-4 text-center">{idx + 1}</span>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm text-gray-700 font-medium">{meta.label}</p>
                      <p className="text-xs text-gray-400">{meta.desc}</p>
                    </div>
                    <Toggle checked={!!config.sections[key]} onChange={v => setSection(key, v)} />
                  </div>
                )
              })}
            </div>
          </div>

          {/* Footer */}
          <div className="bg-white rounded-xl border border-gray-200 p-5 shadow-sm">
            <h3 className="text-sm font-semibold text-gray-900 mb-4 flex items-center gap-2">
              <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 10h18M3 14h18" /></svg>
              Footer
            </h3>
            <div className="space-y-3">
              <div>
                <label className="block text-xs font-medium text-gray-600 mb-1.5">Custom Footer Text</label>
                <input value={config.footerText} onChange={e => set('footerText', e.target.value)} className={inp} placeholder="e.g. Confidential — For internal use only" />
              </div>
              <div className="flex items-center justify-between">
                <p className="text-sm text-gray-700">Show Generated Date</p>
                <Toggle checked={!!config.showGeneratedDate} onChange={v => set('showGeneratedDate', v)} />
              </div>
            </div>
          </div>
        </div>

        {/* ─── Live Preview ─── */}
        <div className="sticky top-0">
          <div className="bg-gray-100 rounded-xl p-6 border border-gray-200">
            <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-4">Preview</p>
            <div className={`bg-white shadow-xl mx-auto overflow-hidden ${isLandscape ? 'max-w-full' : 'max-w-xs'}`}
              style={{ aspectRatio: isLandscape ? '1.414/1' : '1/1.414', fontFamily: previewFont, fontSize: `${previewFontSize * 0.7}px`, color: '#1F2937' }}>
              <div style={{ padding: '12px', height: '100%', display: 'flex', flexDirection: 'column' }}>
                {/* Header */}
                {config.headerStyle !== 'none' && (
                  <div style={{
                    borderBottom: config.headerStyle === 'colored' ? `2px solid ${previewColor}` : '1px solid #E5E7EB',
                    paddingBottom: '8px', marginBottom: '10px',
                    display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start'
                  }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                      {config.showLogo && logoUrl && config.logoPosition === 'left' && (
                        <img src={logoUrl} alt="logo" style={{ height: '24px', objectFit: 'contain' }} />
                      )}
                      <div>
                        {config.showCompanyName && <div style={{ fontWeight: 'bold', color: previewColor, fontSize: `${previewFontSize * 0.8}px` }}>Company Name</div>}
                        <div style={{ fontWeight: '600', fontSize: `${previewFontSize * 0.75}px` }}>RMA Ticket</div>
                        {config.showRmaNumber && <div style={{ color: '#6B7280', fontSize: `${previewFontSize * 0.65}px` }}>RMA-18052026-0001</div>}
                      </div>
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                      {config.showDate && <div style={{ fontSize: `${previewFontSize * 0.6}px`, color: '#6B7280' }}>18/05/2026</div>}
                      {config.showLogo && logoUrl && config.logoPosition === 'right' && (
                        <img src={logoUrl} alt="logo" style={{ height: '24px', objectFit: 'contain', marginLeft: '6px' }} />
                      )}
                    </div>
                  </div>
                )}

                {/* Content sections */}
                <div style={{ flex: 1, overflow: 'hidden' }}>
                  {config.sections.ticketInfo && (
                    <div style={{ marginBottom: '8px' }}>
                      <div style={{ fontSize: `${previewFontSize * 0.6}px`, textTransform: 'uppercase', color: '#6B7280', borderBottom: '1px solid #E5E7EB', paddingBottom: '3px', marginBottom: '5px', letterSpacing: '0.05em' }}>Ticket Information</div>
                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '4px' }}>
                        {['Customer', 'Assigned To', 'Due Date'].map(l => (
                          <div key={l}><div style={{ fontSize: `${previewFontSize * 0.55}px`, color: '#9CA3AF' }}>{l}</div><div style={{ fontSize: `${previewFontSize * 0.65}px`, background: '#F3F4F6', borderRadius: '2px', height: '5px', marginTop: '2px' }} /></div>
                        ))}
                      </div>
                    </div>
                  )}
                  {config.sections.generalDescription && (
                    <div style={{ marginBottom: '8px' }}>
                      <div style={{ fontSize: `${previewFontSize * 0.6}px`, textTransform: 'uppercase', color: '#6B7280', borderBottom: '1px solid #E5E7EB', paddingBottom: '3px', marginBottom: '5px', letterSpacing: '0.05em' }}>General Description</div>
                      <div style={{ background: '#F9FAFB', border: '1px solid #E5E7EB', borderRadius: '3px', height: '18px' }} />
                    </div>
                  )}
                  {config.sections.products && (
                    <div style={{ marginBottom: '8px' }}>
                      <div style={{ fontSize: `${previewFontSize * 0.6}px`, textTransform: 'uppercase', color: '#6B7280', borderBottom: '1px solid #E5E7EB', paddingBottom: '3px', marginBottom: '5px', letterSpacing: '0.05em' }}>Products</div>
                      <div style={{ border: '1px solid #E5E7EB', borderRadius: '3px', padding: '4px', height: '22px' }} />
                    </div>
                  )}
                  {config.sections.signatureLine && (
                    <div style={{ marginTop: 'auto', display: 'flex', gap: '12px' }}>
                      {['Customer Signature', 'Technician Signature'].map(l => (
                        <div key={l} style={{ flex: 1 }}>
                          <div style={{ borderTop: '1px solid #374151', paddingTop: '3px', fontSize: `${previewFontSize * 0.55}px`, color: '#6B7280' }}>{l}</div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>

                {/* Footer */}
                <div style={{ borderTop: '1px solid #E5E7EB', paddingTop: '5px', marginTop: '8px', display: 'flex', justifyContent: 'space-between', color: '#9CA3AF', fontSize: `${previewFontSize * 0.55}px` }}>
                  <span>{config.footerText || 'myRMA'}</span>
                  {config.showGeneratedDate && <span>Generated: 18/05/2026</span>}
                </div>
              </div>
            </div>
            <p className="text-center text-xs text-gray-400 mt-3">{config.paperSize} · {config.orientation} · {config.fontSize}pt</p>
          </div>
        </div>
      </div>
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { db } from '../../api/supabaseClient'
import toast from 'react-hot-toast'
import { MigrationNotice } from './Announcements'

const DEFAULT_SLA = { Low: { response: 72, resolution: 168 }, Medium: { response: 24, resolution: 72 }, High: { response: 4, resolution: 24 }, Critical: { response: 1, resolution: 4 } }
const DEFAULT_RULES = []
const DEFAULT_SETTINGS = { default_priority: 'Medium', default_status: 'New', auto_due_days: 7 }
const PRIORITY_COLORS = { Low: 'bg-gray-100 text-gray-700', Medium: 'bg-blue-100 text-blue-700', High: 'bg-orange-100 text-orange-700', Critical: 'bg-red-100 text-red-700' }

export default function RMAConfig({ currentUserEmail }) {
  const [loading, setLoading] = useState(true)
  const [missing, setMissing] = useState(false)
  const [saving, setSaving] = useState(false)
  const [sla, setSla] = useState(DEFAULT_SLA)
  const [rules, setRules] = useState(DEFAULT_RULES)
  const [settings, setSettings] = useState(DEFAULT_SETTINGS)
  const [users, setUsers] = useState([])

  useEffect(() => { load() }, [])

  const load = async () => {
    setLoading(true)
    try {
      const [cfgResult, usersData] = await Promise.all([db.rmaConfig.getAll(), db.userRoles.listAllRoles()])
      if (cfgResult.missing) { setMissing(true); setLoading(false); return }
      setUsers(usersData)
      const byKey = Object.fromEntries(cfgResult.data.map(r => [r.config_key, r.config_value]))
      if (byKey.sla_rules) setSla(byKey.sla_rules)
      if (byKey.auto_assignment_rules) setRules(byKey.auto_assignment_rules)
      if (byKey.default_settings) setSettings(byKey.default_settings)
    } catch { toast.error('Failed to load config') }
    finally { setLoading(false) }
  }

  const save = async () => {
    setSaving(true)
    try {
      await Promise.all([
        db.rmaConfig.set('sla_rules', sla, currentUserEmail),
        db.rmaConfig.set('auto_assignment_rules', rules, currentUserEmail),
        db.rmaConfig.set('default_settings', settings, currentUserEmail),
      ])
      toast.success('Configuration saved')
      db.auditLog.log(currentUserEmail, 'rma_config_updated', 'Updated RMA configuration (SLA rules, assignment rules, default settings)').catch(() => {})
    } catch (err) { toast.error(err.message) } finally { setSaving(false) }
  }

  const addRule = () => setRules([...rules, { condition_field: 'priority', condition_value: 'Critical', assign_to: '' }])
  const removeRule = (i) => setRules(rules.filter((_, idx) => idx !== i))
  const updateRule = (i, key, val) => setRules(rules.map((r, idx) => idx === i ? { ...r, [key]: val } : r))

  const inp = 'w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600'
  const sel = 'px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600'

  if (loading) return <div className="flex justify-center py-16"><div className="animate-spin w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full" /></div>
  if (missing) return <MigrationNotice feature="RMA Configuration" sql={RMA_CONFIG_SQL} />

  return (
    <div className="space-y-8">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold text-gray-900">RMA Configuration</h2>
          <p className="text-sm text-gray-500 mt-0.5">SLA rules, auto-assignment, and ticket defaults</p>
        </div>
        <button onClick={save} disabled={saving} className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 text-sm font-medium disabled:opacity-50">
          {saving ? 'Saving...' : 'Save All Changes'}
        </button>
      </div>

      {/* Default Settings */}
      <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm">
        <h3 className="text-base font-semibold text-gray-900 mb-4">Default Ticket Settings</h3>
        <div className="grid grid-cols-3 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1.5">Default Priority</label>
            <select value={settings.default_priority} onChange={e => setSettings({...settings, default_priority: e.target.value})} className={sel}>
              {['Low','Medium','High','Critical'].map(p => <option key={p}>{p}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1.5">Default Status</label>
            <select value={settings.default_status} onChange={e => setSettings({...settings, default_status: e.target.value})} className={sel}>
              {['New','In Progress','On Hold','Completed','Cancelled'].map(s => <option key={s}>{s}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1.5">Auto Due Date (days)</label>
            <input type="number" min={1} max={365} value={settings.auto_due_days}
              onChange={e => setSettings({...settings, auto_due_days: parseInt(e.target.value) || 7})} className={inp} />
          </div>
        </div>
      </div>

      {/* SLA Rules */}
      <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm">
        <h3 className="text-base font-semibold text-gray-900 mb-1">SLA Rules by Priority</h3>
        <p className="text-sm text-gray-500 mb-4">Define response and resolution time targets in hours.</p>
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-50">
              <tr>
                {['Priority', 'Response Target (hrs)', 'Resolution Target (hrs)'].map(h => (
                  <th key={h} className="px-4 py-3 text-left text-xs font-semibold text-gray-500 uppercase">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {Object.keys(sla).map(priority => (
                <tr key={priority} className="hover:bg-gray-50">
                  <td className="px-4 py-3">
                    <span className={`px-2 py-1 rounded-full text-xs font-semibold ${PRIORITY_COLORS[priority]}`}>{priority}</span>
                  </td>
                  <td className="px-4 py-3">
                    <input type="number" min={1} value={sla[priority].response}
                      onChange={e => setSla({...sla, [priority]: {...sla[priority], response: parseInt(e.target.value) || 1}})}
                      className="w-28 px-3 py-1.5 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600" />
                  </td>
                  <td className="px-4 py-3">
                    <input type="number" min={1} value={sla[priority].resolution}
                      onChange={e => setSla({...sla, [priority]: {...sla[priority], resolution: parseInt(e.target.value) || 1}})}
                      className="w-28 px-3 py-1.5 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-600" />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Auto-Assignment Rules */}
      <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h3 className="text-base font-semibold text-gray-900">Auto-Assignment Rules</h3>
            <p className="text-sm text-gray-500 mt-0.5">Automatically assign tickets based on conditions.</p>
          </div>
          <button onClick={addRule} className="flex items-center gap-1.5 px-3 py-1.5 border border-gray-300 rounded-lg text-sm hover:bg-gray-50">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
            Add Rule
          </button>
        </div>
        {rules.length === 0 && (
          <div className="text-center py-8 text-gray-400 border-2 border-dashed border-gray-200 rounded-lg">
            No auto-assignment rules. Click "Add Rule" to create one.
          </div>
        )}
        <div className="space-y-3">
          {rules.map((rule, i) => (
            <div key={i} className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg">
              <span className="text-sm text-gray-500 whitespace-nowrap">When</span>
              <select value={rule.condition_field} onChange={e => updateRule(i, 'condition_field', e.target.value)} className={`${sel} flex-1`}>
                <option value="priority">Priority</option>
                <option value="customer_name">Customer Name</option>
              </select>
              <span className="text-sm text-gray-500">is</span>
              {rule.condition_field === 'priority' ? (
                <select value={rule.condition_value} onChange={e => updateRule(i, 'condition_value', e.target.value)} className={`${sel} flex-1`}>
                  {['Low','Medium','High','Critical'].map(p => <option key={p}>{p}</option>)}
                </select>
              ) : (
                <input value={rule.condition_value} onChange={e => updateRule(i, 'condition_value', e.target.value)} placeholder="Customer name..." className={`${inp} flex-1`} />
              )}
              <span className="text-sm text-gray-500 whitespace-nowrap">→ assign to</span>
              <select value={rule.assign_to} onChange={e => updateRule(i, 'assign_to', e.target.value)} className={`${sel} flex-1`}>
                <option value="">Select user...</option>
                {users.map(u => <option key={u.user_email} value={u.user_email}>{u.user_email}</option>)}
              </select>
              <button onClick={() => removeRule(i)} className="text-red-400 hover:text-red-600 flex-shrink-0">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

const RMA_CONFIG_SQL = `CREATE TABLE IF NOT EXISTS rma_config (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  config_key TEXT UNIQUE NOT NULL,
  config_value JSONB NOT NULL,
  updated_by TEXT,
  updated_date TIMESTAMPTZ DEFAULT NOW()
);`
